def card_p(doll):
    """The card's overall as 0 (55, the weakest) .. 1 (125, the best); special cards go a bit past."""
    return clamp((getattr(doll, "rating", OVR_FLOOR) - OVR_FLOOR) / 70.0, 0.0, 1.2)


def rating_k(doll, rng):
    lo, hi = rng
    return lo + (hi - lo) * card_p(doll)


def stat01(value):
    """A stat as 0..1 across the 50-160 range - what the physics actually reads."""
    return clamp((value - STAT_FLOOR) / float(STAT_CEIL - STAT_FLOOR), 0.0, 1.0)

