# ==========================================================
# SMALL HELPERS
# ==========================================================
def clamp(v, lo, hi):
    return lo if v < lo else hi if v > hi else v


def lerp_rgb(a, b, t):
    t = max(0.0, min(1.0, t))
    return tuple(int(round(a[i] + (b[i] - a[i]) * t)) for i in range(3))


def lerp(a, b, t):
    return a + (b - a) * t


def approach(current, target, rate, dt):
    return current + (target - current) * (1.0 - math.exp(-rate * dt))


def rot(v, a):
    """Rotate a vector by angle a. Positive a turns clockwise on screen."""
    c, s = math.cos(a), math.sin(a)
    return Vector2(v[0] * c - v[1] * s, v[0] * s + v[1] * c)


def perp(v):
    return Vector2(-v.y, v.x)


def closest_on_segment(p, a, b):
    ab = b - a
    l2 = ab.length_squared()
    if l2 < 1e-9:
        return Vector2(a)
    t = clamp((p - a).dot(ab) / l2, 0.0, 1.0)
    return a + ab * t


SPRITES_DIR = os.path.join(SCRIPT_DIR, "sprites")   # all the art lives here


def _search_dirs():
    dirs = [SPRITES_DIR] if os.path.isdir(SPRITES_DIR) else []
    for d in (SCRIPT_DIR, os.getcwd()):
        d = os.path.abspath(d)
        if d not in dirs:
            dirs.append(d)
        try:                                   # also one level of subfolders
            for sub in sorted(os.listdir(d)):
                full = os.path.join(d, sub)
                if os.path.isdir(full) and full not in dirs:
                    dirs.append(full)
        except Exception:
            pass
    return dirs


def find_file(names, exts):
    """Find a file next to the script (or in the current folder, or one
    subfolder down). Case-insensitive; spaces/dashes count as underscores;
    also matches names with a prefix (e.g. 1abd5885-ballkick1.mp3)."""
    norm = lambda t: t.lower().replace(" ", "_").replace("-", "_")
    listing = []
    for d in _search_dirs():
        try:
            listing.append((d, os.listdir(d)))
        except Exception:
            continue
    for exact in (True, False):              # an exact name anywhere beats a prefixed one
        for d, files in listing:
            for base in names:
                for ext in exts:
                    want = norm(base + ext)
                    for fn in files:
                        low = norm(fn)
                        if low == want if exact else low.endswith("_" + want):
                            return os.path.join(d, fn)
    return None


def load_raw(*base_names):
    """Load an image from the sprites folder (or next to the script)."""
    for base in base_names:
        path = find_file((base,), (".png", ".jpg", ".jpeg"))
        if path is None:
            continue
        try:
            return pygame.image.load(path).convert_alpha()
        except Exception:
            continue
    return None


def load_fit(size, *names):
    """Aspect-fit load (for the head and ball)."""
    img = load_raw(*names)
    if img is None:
        return None
    w, h = img.get_size()
    if w <= 0 or h <= 0:
        return None
    s = min(size[0] / w, size[1] / h)
    return pygame.transform.smoothscale(img, (max(1, int(w * s)), max(1, int(h * s))))


def load_exact(size, *names):
    """Scaled once to the piece's fixed size - pieces never stretch at runtime."""
    img = load_raw(*names)
    if img is None:
        return None
    return pygame.transform.smoothscale(img, (int(size[0]), int(size[1])))


MISSING_SPRITES = []

# what a file name needs to contain for each Argentina piece (any match works,
# capitals/spaces don't matter). Exact names like ARG_torso.png win first.
TEAM_ALIASES = {"ARG": ("arg", "argentin"), "BRA": ("bra", "brazil", "brasil")}
_TORSO = ("torso", "body", "shirt", "jersey", "chest", "kit")
_ARM, _LEG = ("arm",), ("leg", "short", "pant")
# name -> (keywords the file name must contain, team it belongs to, words it must NOT contain)
SPRITE_RULES = {
    "ARG_torso": (_TORSO, "ARG", ()),
    "ARG_arm": (_ARM, "ARG", ("black",)),
    "ARG_leg": (_LEG, "ARG", ("black",)),
    "giuliano": (("giuliano", "simeone"), None, ()),
    "lautaro": (("lautaro", "martinez"), None, ()),
    "messi": (("messi",), None, ()),
    "BRA_torso": (_TORSO, "BRA", ()),
    "BRA_arm": (_ARM, "BRA", ("black",)),
    "BRA_leg": (_LEG, "BRA", ("black",)),
    "blackarm": (("blackarm", "black_arm", "black arm", "black-arm"), None, ()),
    "blackleg": (("blackleg", "black_leg", "black leg", "black-leg"), None, ()),
    "igor": (("igor",), None, ()),
    "bruno": (("bruno",), None, ()),
    "vinicius": (("vinicius", "vinícius", "vini"), None, ()),
}


def find_sprite(name):
    """Exact name first (e.g. BRA_torso.png), then any PNG whose name contains
    a keyword for this piece. A kit piece prefers files naming its team and
    never takes one naming another team. Flags and ball.png are skipped."""
    path = find_file((name,), (".png",))
    if path is not None:
        return path
    keys, team, bad = SPRITE_RULES.get(name, ((), None, ()))
    skip = {t.lower() + ".png" for t in TEAMS} | {"ball.png"}
    best = None
    for d in _search_dirs():
        try:
            files = sorted(os.listdir(d))
        except Exception:
            continue
        for fn in files:
            low = fn.lower()
            if not low.endswith(".png") or low in skip:
                continue
            stem = low[:-4]
            if not any(k in stem for k in keys) or any(b in stem for b in bad):
                continue
            score = 1
            if team is not None:
                if any(a in stem for a in TEAM_ALIASES.get(team, ())):
                    score = 0
                elif any(a in stem for t, al in TEAM_ALIASES.items() if t != team for a in al):
                    continue                     # belongs to a different team
            if best is None or score < best[0]:
                best = (score, os.path.join(d, fn))
        if best is not None:
            return best[1]
    return None


def load_pixel(name, size, fit=False, quiet=False, trim=True):
    """Load a pixel-art sprite from the script folder, trimmed to its visible
    part and scaled with hard pixels (no smoothing). fit=True keeps its shape
    inside `size`; otherwise it fills `size` exactly. trim=False keeps the file's
    own frame, so a set of sprites drawn on one canvas keeps a common scale and
    baseline. None if missing."""
    path = find_sprite(name)
    if path is None and quiet:
        return None
    if path is None:
        print("[ragdoll_football] missing sprite: %s.png (looked in %s)" % (name, SPRITES_DIR))
        MISSING_SPRITES.append(name + ".png")
        return None
    try:
        img = pygame.image.load(path).convert_alpha()
        if trim:
            box = img.get_bounding_rect()
            if box.w > 0 and box.h > 0:
                img = img.subsurface(box).copy()
        w, h = size
        if fit:
            k = min(w / img.get_width(), h / img.get_height())
            w, h = img.get_width() * k, img.get_height() * k
        out = pygame.transform.scale(img, (max(1, int(w)), max(1, int(h))))
        print("[ragdoll_football] loaded sprite:", path)
        return out
    except Exception as exc:
        print("[ragdoll_football] could not load %s: %s" % (path, exc))
        MISSING_SPRITES.append(os.path.basename(path) + " (unreadable)")
        return None


def ordinal(n):
    return "%d%s" % (n, "TH" if 10 <= n % 100 <= 20 else {1: "ST", 2: "ND", 3: "RD"}.get(n % 10, "TH"))


def load_teams():
    """Load the 12 team flags (ARG.png, BRA.png, ...) from the script's folder.
    The team name is the file name without '.png'."""
    teams = []
    for code in TEAMS:
        path = find_file((code,), (".png",)) or \
            os.path.join(SCRIPT_DIR, "flags", code + ".png")    # old layout
        if not os.path.exists(path):
            continue
        try:
            img = pygame.image.load(path).convert_alpha()
        except Exception:
            continue
        teams.append({"name": code, "flag": img})
    return teams


_FLAG_CACHE = {}


def fit_flag(img, w, h):
    """Flag scaled to fit a w x h box (cached)."""
    key = (id(img), int(w), int(h))
    if key not in _FLAG_CACHE:
        iw, ih = img.get_size()
        k = min(w / max(1, iw), h / max(1, ih))
        _FLAG_CACHE[key] = pygame.transform.smoothscale(
            img, (max(1, int(iw * k)), max(1, int(ih * k))))
    return _FLAG_CACHE[key]


def capsule(surface, color, a, b, radius):
    d = b - a
    length = d.length()
    if length > 0.5:
        n = d / length
        p = Vector2(-n.y, n.x) * radius
        pts = [a + p, b + p, b - p, a - p]
        pygame.draw.polygon(surface, color, [(q.x, q.y) for q in pts])
    r = max(1, int(radius))
    pygame.draw.circle(surface, color, (int(a.x), int(a.y)), r)
    pygame.draw.circle(surface, color, (int(b.x), int(b.y)), r)


def rot_rect(center, w, h, angle):
    hw, hh = w * 0.5, h * 0.5
    return [center + rot((x, y), angle) for x, y in ((-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh))]


def poly(surface, color, pts):
    pygame.draw.polygon(surface, color, [(p.x, p.y) for p in pts])


class CachedFont:
    """A pygame font that keeps the surfaces it has already rendered. Re-rendering
    the same HUD and menu text 60 times a second is most of the browser's work."""

    def __init__(self, font, limit=1200):
        self._font = font
        self._cache = {}
        self._limit = limit

    def render(self, text, antialias=True, color=(255, 255, 255), *rest):
        if rest:                                   # background colour: rare, don't cache
            return self._font.render(text, antialias, color, *rest)
        key = (text, tuple(color)[:4], bool(antialias))
        img = self._cache.get(key)
        if img is None:
            if len(self._cache) >= self._limit:
                self._cache.clear()
            img = self._font.render(text, antialias, color)
            self._cache[key] = img
        return img

    def __getattr__(self, name):                   # size(), get_height(), metrics()...
        return getattr(self._font, name)


def _budget(cache, size, mpx):
    """Keep a surface cache under a pixel budget - memory matters more than hit rate here."""
    total = getattr(cache, "px", 0) + int(size[0]) * int(size[1])
    if total > mpx * 1000000:
        cache.clear()
        total = int(size[0]) * int(size[1])
    try:
        cache.px = total
    except AttributeError:
        pass


class _Cache(dict):
    px = 0


_TINT_CACHE = _Cache()


def tint(size, colour):
    """A reusable translucent rectangle (veils, HUD pads). Never drawn on, only blitted."""
    key = (int(size[0]), int(size[1]), tuple(colour))
    surf = _TINT_CACHE.get(key)
    if surf is None:
        _budget(_TINT_CACHE, size, 8)
        surf = pygame.Surface((int(size[0]), int(size[1])), pygame.SRCALPHA)
        surf.fill(colour)
        _TINT_CACHE[key] = surf
    return surf


# ---------------------------------------------------------------- frame budget
# Everything below exists for one reason: a browser frame can't afford to allocate
# megapixels of surface 60 times a second. Anything that used to be built per frame
# is either cached by shape, or drawn into a surface we keep and reuse.

_SCRATCH = _Cache()


def scratch(size, slot=0):
    """A transparent surface to draw one frame's effect into, kept and reused.

    Two effects alive at the same time need different slots."""
    size = (max(1, int(size[0])), max(1, int(size[1])))
    key = (size, slot)
    surf = _SCRATCH.get(key)
    if surf is None:
        _budget(_SCRATCH, size, 10)
        surf = pygame.Surface(size, pygame.SRCALPHA)
        _SCRATCH[key] = surf
    else:
        surf.fill((0, 0, 0, 0))
    return surf


def opaque(img, under=(8, 10, 18)):
    """A full-screen picture with no per-pixel alpha: blitting it is a straight copy instead of a
    blend of two million pixels (5 Nov optimising pass - the browser paid for every one)."""
    if img is None:
        return None
    out = pygame.Surface(img.get_size()).convert()
    out.fill(under)
    out.blit(img, (0, 0))
    return out


_TINTED = {}


def tinted(img, colour, key):
    """img with a translucent colour washed over it, made once (it used to be washed every frame)."""
    hit = _TINTED.get(key)
    if hit is not None and hit[0] is img:
        return hit[1]
    out = opaque(img)
    wash(out, colour)
    _TINTED[key] = (img, out)
    return out


def wash(target, colour, rect=None, slot=0):
    """A flat translucent wash over the target.

    A veil used to mean building a surface the size of the screen, filling it and blitting it
    on top: three passes over two megapixels. The same result comes out of multiplying what is
    already there and adding the colour back, which is one pass over the pixels already in
    the frame - no surface, nothing to allocate, nothing to read. The browser feels this."""
    col = tuple(colour)
    alpha = col[3] if len(col) > 3 else 255
    alpha = max(0, min(255, int(alpha)))
    if alpha <= 3:
        return
    r = rect if rect is not None else target.get_rect()
    keep = 255 - alpha
    if alpha >= 252:                                   # solid: a plain fill is cheapest
        target.fill(col[:3], r)
        return
    try:
        target.fill((keep, keep, keep), r, special_flags=pygame.BLEND_RGB_MULT)
        add = tuple(int(c * alpha / 255.0) for c in col[:3])
        if max(add) > 0:
            target.fill(add, r, special_flags=pygame.BLEND_RGB_ADD)
        return
    except Exception:
        pass                                           # old pygame: the old way still works
    surf = scratch((r.w, r.h), slot)
    surf.fill(col)
    target.blit(surf, (r.x, r.y))


_GLOW_CACHE = _Cache()


def glow_blob(size, colour, alpha=60):
    """The soft ellipse behind cards and packs, cached by shape (sizes and alpha
    are rounded, so a pulsing aura reuses a handful of surfaces instead of one a frame)."""
    w = max(8, int(size[0]) // 16 * 16)
    h = max(8, int(size[1]) // 16 * 16)
    a = max(0, min(255, int(alpha) // 10 * 10))
    key = (w, h, tuple(colour)[:3], a)
    surf = _GLOW_CACHE.get(key)
    if surf is None:
        _budget(_GLOW_CACHE, (w, h), 4)
        surf = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.ellipse(surf, tuple(colour)[:3] + (a,), surf.get_rect())
        _GLOW_CACHE[key] = surf
    return surf


_SHINE_CACHE = _Cache()


def shine_sweep(size):
    """The diagonal gloss across a card face - same shape for every card of that size."""
    w, h = max(1, int(size[0])), max(1, int(size[1]))
    surf = _SHINE_CACHE.get((w, h))
    if surf is None:
        _budget(_SHINE_CACHE, (w, h), 3)
        surf = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.polygon(surf, (255, 255, 255, 34),
                            [(w * 0.55, 0), (w * 0.78, 0), (w * 0.25, h), (0, h)])
        _SHINE_CACHE[(w, h)] = surf
    return surf


_SCALE_BUF = {}


_SCALE_DEST_OK = None           # does this pygame take a destination surface? asked once


def scale_into(img, size, key):
    """pygame.transform.scale that writes into a surface we keep, instead of making one."""
    global _SCALE_DEST_OK
    size = (max(1, int(size[0])), max(1, int(size[1])))
    if _SCALE_DEST_OK is False:
        return pygame.transform.scale(img, size)
    dest = _SCALE_BUF.get(key)
    if dest is None or dest.get_size() != size:
        dest = pygame.Surface(size)
        _SCALE_BUF[key] = dest
    try:
        pygame.transform.scale(img, size, dest)
        _SCALE_DEST_OK = True
        return dest
    except Exception:                       # older pygame: no destination argument
        _SCALE_DEST_OK = False
        _SCALE_BUF.clear()
        return pygame.transform.scale(img, size)


_FIT_CACHE = _Cache()


def scaled(img, size):
    """pygame.transform.scale, cached per (image, size) - for art that is rescaled every frame."""
    size = (max(1, int(size[0])), max(1, int(size[1])))
    key = (id(img), size)
    out = _FIT_CACHE.get(key)
    if out is None:
        _budget(_FIT_CACHE, size, 6)
        out = pygame.transform.scale(img, size)
        _FIT_CACHE[key] = out
    return out


def smooth_scaled(img, size):
    """scaled(), but averaging. For pixel art shrunk well below the size it was drawn at, where
    plain scaling throws whole rows away - and a row of a small face is an eye."""
    size = (max(1, int(size[0])), max(1, int(size[1])))
    key = (id(img), size, "smooth")
    out = _FIT_CACHE.get(key)
    if out is None:
        _budget(_FIT_CACHE, size, 6)
        try:
            out = pygame.transform.smoothscale(img, size)
        except Exception:                   # a surface smoothscale will not take: scale it plainly
            out = pygame.transform.scale(img, size)
        _FIT_CACHE[key] = out
    return out


_SMALL_TEXT = {}


def scaled_text(img, k):
    """A rendered label, smaller - kept, because labels are cached and so is this."""
    key = (id(img), round(k, 3))
    out = _SMALL_TEXT.get(key)
    if out is None:
        if len(_SMALL_TEXT) > 300:
            _SMALL_TEXT.clear()
        size = (max(1, int(img.get_width() * k)), max(1, int(img.get_height() * k)))
        try:
            out = pygame.transform.smoothscale(img, size)
        except Exception:
            out = pygame.transform.scale(img, size)
        _SMALL_TEXT[key] = (out, img)                  # hold the source so its id can't be reused
        return out
    return out[0]


_ROT_CACHE = {}


def rotated(img, degrees):
    """pygame.transform.rotate, cached in 2-degree steps (the browser can't
    afford to re-rotate every sprite 60 times a second)."""
    try:
        step = round(degrees / ROT_STEP) * ROT_STEP % 360.0
        key = (id(img), step)
        out = _ROT_CACHE.get(key)
        if out is None:
            if len(_ROT_CACHE) > 4000:
                _ROT_CACHE.clear()
            out = pygame.transform.rotate(img, step)
            _ROT_CACHE[key] = out
        return out
    except Exception:
        return pygame.transform.rotate(img, degrees)


def blit_rot(surface, img, center, angle):
    r = rotated(img, -math.degrees(angle))
    surface.blit(r, r.get_rect(center=(int(center.x), int(center.y))))


# ==========================================================
# SOUND (synthesised at boot, no files needed)
# ==========================================================
class SFX:
    def __init__(self):
        self.enabled = False
        self.muted = False
        self.has_music = False
        self.bank = {}
        try:
            if pygame.mixer.get_init() is None:
                pygame.mixer.init(44100, -16, 2, MIXER_BUFFER)
            try:
                pygame.mixer.set_num_channels(8 if WEB_BUILD else 16)
            except Exception:
                pass
            self.bank["kick"] = self._tone(200, 0.10, vol=0.55, sweep=0.30, noise=0.45)
            self.bank["tap"] = self._tone(420, 0.06, vol=0.28, sweep=0.55, noise=0.30)
            kick = self._load("ballkick1", "ballkick", "kick")
            if kick is not None:
                self.bank["kick"] = kick
                self.bank["tap"] = kick
            self.bank["whistle"] = self._tone(1850, 0.30, vol=0.30, sweep=1.04, wave="square")
            self.bank["shock"] = self._load("shock") or self._tone(90, 0.35, vol=0.6, sweep=0.5, noise=0.6)
            self.bank["whoosh"] = self._tone(900, 0.22, vol=0.25, sweep=0.35, noise=0.85)
            self.bank["buff"] = self._tone(520, 0.4, vol=0.3, sweep=1.6, wave="square")
            cheer = self._load("cheering", "cheer")
            if cheer is not None:
                self.bank["cheer"] = cheer
            self.enabled = True
        except Exception:
            self.enabled = False

    @staticmethod
    def _load(*names):
        path = find_file(names, (".ogg", ".mp3", ".wav"))
        if path is None:
            return None
        try:
            return pygame.mixer.Sound(path)
        except Exception:
            return None

    # music slots: drop menumusic1.mp3 / playingmusic1.mp3 / creditsmusic1.mp3 next to the script
    TRACKS = {"menu": ("menu1", "menumusic1", "menumusic", "menu_music"),
              "match": ("playingmusic1", "playingmusic", "matchmusic1", "music"),
              "match2": ("playingmusic2",),
              "credits": ("creditsmusic1", "creditsmusic", "credits_music"),
              "impossible": ("impossiblemodeselect", "impossible"),
              "pack": ("openingpack", "packopening")}
    ONCE = ("pack",)                        # played once, not looped
    VOLUME = {"pack": 0.55, "impossible": 0.3}

    def track_path(self, slot):
        path = find_file(self.TRACKS[slot], (".ogg", ".mp3", ".wav"))
        if path is None and slot in ("menu", "credits", "match2", "impossible"):
            path = find_file(self.TRACKS["match"], (".ogg", ".mp3", ".wav"))
        return path

    def has_track(self, slot):
        return find_file(self.TRACKS[slot], (".ogg", ".mp3", ".wav")) is not None

    def play_track(self, slot, start=0.0, force=False):
        """Ask for a background track. The swap itself happens after the next frame is drawn.

        Loading and decoding a music file takes long enough to be felt, and it was always
        asked for at the worst possible moment - the frame you open a pack, or walk into
        the shop. Queueing it means the new screen is already on-screen when it happens."""
        self.want = slot
        if not self.enabled or self.muted:
            return
        self.pending_track = (slot, start, force)

    def pump(self):
        """Called once a frame, after drawing: do any music swap that is waiting."""
        job = getattr(self, "pending_track", None)
        if job is None:
            return
        self.pending_track = None
        self.swap_track(*job)

    def swap_track(self, slot, start=0.0, force=False):
        """Swap the background track. No-op if that file is already playing."""
        if not self.enabled or self.muted:
            self.want = slot
            return
        path = self.track_path(slot)
        if path is None or (path == getattr(self, "now_playing", None) and not force):
            return
        try:
            pygame.mixer.music.load(path)
            pygame.mixer.music.set_volume(self.VOLUME.get(slot, 0.20))
            loops = 0 if slot in self.ONCE else -1
            try:
                pygame.mixer.music.play(loops, start)
            except Exception:
                pygame.mixer.music.play(loops)
            self.now_playing = path
            self.want = slot
            self.has_music = True
        except Exception:
            pass

    def start_music(self):
        self.now_playing = None
        self.want = "menu"
        self.swap_track("menu")

    def toggle_mute(self):
        self.muted = not self.muted
        if not self.muted:
            self.swap_track(getattr(self, "want", "menu"))
        if self.has_music:
            try:
                if self.muted:
                    pygame.mixer.music.pause()
                else:
                    pygame.mixer.music.unpause()
            except Exception:
                pass

    @staticmethod
    def _tone(freq, dur, vol=0.35, sweep=1.0, noise=0.0, wave="sine"):
        rate = 44100
        n = max(2, int(rate * dur))
        buf = array.array("h")
        phase = 0.0
        for i in range(n):
            frac = i / n
            f = freq * (sweep ** frac)
            phase += 2.0 * math.pi * f / rate
            s = math.sin(phase)
            if wave == "square":
                s = 1.0 if s >= 0.0 else -1.0
            if noise > 0.0:
                s = s * (1.0 - noise) + random.uniform(-1.0, 1.0) * noise
            env = (1.0 - frac) ** 1.5
            val = int(clamp(s * env * vol, -1.0, 1.0) * 31000)
            buf.append(val)
            buf.append(val)
        return pygame.mixer.Sound(buffer=buf.tobytes())

    def play(self, name, volume=1.0):
        if not self.enabled or self.muted or name not in SOUNDS_ON:
            return
        snd = self.bank.get(name)
        if snd is None:
            return
        try:
            snd.set_volume(clamp(volume, 0.0, 1.0))
            snd.play()
        except Exception:
            pass


# ==========================================================
# PARTICLES
# ==========================================================
class Particles:
    def __init__(self):
        self.items = []

    def burst(self, pos, count, kind="dust", direction=None, spread=1.0, speed=300.0,
              color=(220, 220, 220)):
        if not PARTICLES_ON:
            return
        for _ in range(count):
            if direction is None:
                ang = random.uniform(0, math.tau)
                vel = Vector2(math.cos(ang), math.sin(ang)) * random.uniform(0.3, 1.0) * speed
            else:
                base = math.atan2(direction.y, direction.x)
                ang = base + random.uniform(-spread, spread)
                vel = Vector2(math.cos(ang), math.sin(ang)) * random.uniform(0.4, 1.0) * speed
            self.items.append({
                "pos": Vector2(pos), "vel": vel, "kind": kind,
                "life": random.uniform(0.28, 0.7), "age": 0.0,
                "size": random.uniform(3.0, 8.0), "color": color,
                "spin": random.uniform(-14.0, 14.0), "rot": random.uniform(0, math.tau),
            })
        cap = 240 if WEB_BUILD else 900
        if len(self.items) > cap:
            del self.items[:len(self.items) - cap]

    def update(self, dt):
        alive = []
        for p in self.items:
            p["age"] += dt
            if p["age"] >= p["life"]:
                continue
            if p["kind"] == "dust":
                p["vel"] *= (1.0 - 3.2 * dt)
                p["vel"].y -= 40.0 * dt
            elif p["kind"] == "spark":
                p["vel"].y += 1400.0 * dt
                p["vel"] *= (1.0 - 1.5 * dt)
            else:  # confetti
                p["vel"].y += 700.0 * dt
                p["vel"].x += math.sin(p["age"] * 7.0 + p["rot"]) * 240.0 * dt
                p["vel"] *= (1.0 - 0.8 * dt)
            p["pos"] += p["vel"] * dt
            p["rot"] += p["spin"] * dt
            alive.append(p)
        self.items = alive

    def draw(self, surface):
        for p in self.items:
            t = 1.0 - p["age"] / p["life"]
            if p["kind"] == "confetti":
                s = p["size"] * 1.6
                c = math.cos(p["rot"]) * s
                pts = [(p["pos"].x - s, p["pos"].y - c), (p["pos"].x + s, p["pos"].y - c * 0.4),
                       (p["pos"].x + s, p["pos"].y + c), (p["pos"].x - s, p["pos"].y + c * 0.4)]
                pygame.draw.polygon(surface, p["color"], pts)
            else:
                r = max(1, int(p["size"] * t))
                pygame.draw.circle(surface, p["color"], (int(p["pos"].x), int(p["pos"].y)), r)


# ==========================================================
# BALL
# ==========================================================
class Ball:
    def __init__(self):
        self.pos = Vector2(WIDTH * 0.5, 240)
        self.vel = Vector2()
        self.radius = BALL_RADIUS
        self.spin = 0.0
        self.angle = 0.0
        self.squash = 0.0
        self.squash_dir = Vector2(0, -1)
        self.frozen = True
        self.trail = []
        self.extra_g = 0.0         # Perfect Shot: extra pull so it dips sharply
        self.extra_g_t = 0.0
        self.ghost_t = 0.0
        self.home_ghost_t = 0.0         # while > 0 the CPU can't touch it (it's over his head)
        self.home_ghost_t = 0.0    # while > 0 the player's own body doesn't knock it (flicks)
        self.carrier, self.carrier_t = None, 0.0   # who is dribbling it (shielding)
        self.zip_t = 0.0           # BULLET PASS / TIKI TAKA: less drag for a moment
        self.bend, self.bend_t, self.bend_goal = 0.0, 0.0, None   # a spun shot curling to goal
        self.art = self._build_art()

    def _build_art(self):
        raw = load_raw("ball", "football")
        if raw is not None:                       # pixel art: scale hard, never smooth it
            d = self.radius * 2
            k = min(d / raw.get_width(), d / raw.get_height())
            return pygame.transform.scale(raw, (max(2, int(raw.get_width() * k)),
                                                max(2, int(raw.get_height() * k))))
        d = self.radius * 2
        surf = pygame.Surface((d, d), pygame.SRCALPHA)
        c = self.radius
        pygame.draw.circle(surf, INK, (c, c), self.radius)
        pygame.draw.circle(surf, WHITE, (c, c), self.radius - 4)
        pygame.draw.circle(surf, (40, 44, 60), (c, c), int(self.radius * 0.30))
        for i in range(5):
            a = math.tau * i / 5.0 - math.pi / 2.0
            px = c + math.cos(a) * self.radius * 0.66
            py = c + math.sin(a) * self.radius * 0.66
            pygame.draw.circle(surf, (40, 44, 60), (int(px), int(py)), int(self.radius * 0.17))
        return surf

    def reset(self, x, y, frozen=True):
        self.pos.update(x, y)
        self.vel.update(0, 0)
        self.spin = 0.0
        self.squash = 0.0
        self.frozen = frozen
        self.trail.clear()
        self.extra_g_t = 0.0
        self.ghost_t = 0.0

    def step(self, h, segments, sfx, particles):
        if self.frozen:
            return
        h *= BALL_TIME                       # everything about the ball happens in its own, slower time
        # 29 Oct: with no air drag any more, "zip" (BULLET PASS, TIKI TAKA, POWER SHOT) can't mean
        # "keeps its pace" in the air - every ball does now. It means "stays on a line" instead:
        # while it lasts the ball falls slower, so it flies flatter and further
        zip_air = self.zip_t > 0.0 and self.pos.y < GROUND_Y - self.radius - 2
        self.vel.y += BALL_GRAVITY * TWIST["grav"] * (ZIP_GRAVITY if zip_air else 1.0) * h
        if TWIST["wind"] and self.pos.y < GROUND_Y - self.radius - 2:
            self.vel.x += TWIST["wind"] * h                             # WINDY
        if self.extra_g_t > 0.0:
            self.vel.y += self.extra_g * h
            self.extra_g_t -= h
        self.ghost_t = max(0.0, self.ghost_t - h)
        self.home_ghost_t = max(0.0, self.home_ghost_t - h)
        self.carrier_t = max(0.0, self.carrier_t - h)
        self.zip_t = max(0.0, self.zip_t - h)
        if self.bend_t > 0.0 and self.bend_goal is not None and self.vel.length_squared() > 1.0:
            # SHOT: a spun hit curls toward goal through its flight (it bends, never homes)
            self.bend_t -= h
            want = self.bend_goal - self.pos
            if self.vel.dot(want) > 0.0:
                cur = math.atan2(self.vel.y, self.vel.x)
                diff = (math.atan2(want.y, want.x) - cur + math.pi) % math.tau - math.pi
                step = self.bend / BEND_TIME * h
                turn = clamp(diff, -step, step)
                sp = self.vel.length()
                self.vel = Vector2(math.cos(cur + turn), math.sin(cur + turn)) * sp
        self.vel *= (1.0 - BALL_AIR_DRAG * (0.3 if self.zip_t > 0.0 else 1.0) * h)
        if self.pos.y < GROUND_Y - self.radius - 2 and self.vel.length_squared() > 1.0 and self.extra_g_t <= 0.0 \
                and self.spin * self.vel.x > 0.0:
            # topspin dips it (Magnus): the push is across its path, on the downward side. Spin the
            # other way (backspin) does nothing - the ball never floats up.
            side = Vector2(-self.vel.y, self.vel.x).normalize()
            self.vel += side * min(abs(self.spin) * BALL_DIP, BALL_DIP_MAX) * math.copysign(1.0, self.spin) * h
        if self.vel.length() > BALL_SPEED_CAP:
            self.vel.scale_to_length(BALL_SPEED_CAP)
        self.pos += self.vel * h

        floor = GROUND_Y - self.radius
        if self.pos.y > floor:
            impact = abs(self.vel.y)
            self.pos.y = floor
            if impact > 60.0:
                self.vel.y = -impact * BALL_RESTITUTION
                self.impact(Vector2(0, -1), impact)
                if impact > 300.0:
                    sfx.play("bounce", clamp(impact / 1600.0, 0.15, 0.8))
                    particles.burst(Vector2(self.pos.x, GROUND_Y), 6, "dust",
                                    Vector2(0, -1), 1.1, impact * 0.35, (176, 200, 168))
            else:
                self.vel.y = 0.0
            self.vel.x -= self.vel.x * BALL_GROUND_FRICTION * TWIST["roll"] * (0.3 if self.zip_t > 0.0 else 1.0) * h
            self.spin = approach(self.spin, math.degrees(self.vel.x / self.radius), 14.0, h)

        if self.pos.y < self.radius:
            self.pos.y = self.radius
            self.vel.y = abs(self.vel.y) * BALL_RESTITUTION
        if self.pos.x < self.radius:
            self.pos.x = self.radius
            self.vel.x = abs(self.vel.x) * BALL_RESTITUTION
        elif self.pos.x > WIDTH - self.radius:
            self.pos.x = WIDTH - self.radius
            self.vel.x = -abs(self.vel.x) * BALL_RESTITUTION

        for a, b, thick in segments:
            self._collide_segment(a, b, thick, sfx, particles)

        self.angle -= self.spin * h
        self.spin *= (1.0 - BALL_AIR_SPIN_DECAY * h)

    def _collide_segment(self, a, b, thick, sfx, particles):
        cp = closest_on_segment(self.pos, a, b)
        d = self.pos - cp
        dist = d.length()
        min_dist = self.radius + thick * 0.5
        if dist >= min_dist:
            return
        n = d / dist if dist > 1e-6 else Vector2(0, -1)
        self.pos = cp + n * min_dist
        vn = self.vel.dot(n)
        if vn < 0:
            self.vel -= n * vn * (1.0 + BALL_RESTITUTION)
            self.spin += self.vel.dot(Vector2(-n.y, n.x)) * 0.02
            self.impact(n, abs(vn))
            if abs(vn) > 200.0:
                sfx.play("post", clamp(abs(vn) / 1400.0, 0.2, 0.9))
                particles.burst(cp, 8, "spark", n, 0.9, abs(vn) * 0.5, YELLOW)

    def impact(self, normal, strength):
        pass                                   # 1 Nov: the ball never squashes - always a circle

    def push_trail(self):
        if self.vel.length() > 420.0 and not self.frozen:
            self.trail.append(Vector2(self.pos))
            if len(self.trail) > 14:
                self.trail.pop(0)
        elif self.trail:
            self.trail.pop(0)

    def draw(self, surface):
        for i, p in enumerate(self.trail if BALL_TRAIL_ON else ()):
            t = (i + 1) / (len(self.trail) + 1)
            r = int(self.radius * t * 0.8)
            if r > 1:
                ghost = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
                pygame.draw.circle(ghost, (255, 255, 255, int(70 * t)), (r, r), r)
                surface.blit(ghost, (int(p.x - r), int(p.y - r)))

        img = self.art                         # always the round ball, only ever turned (1 Nov)
        try:
            r = rotated(img, self.angle % 360.0)
        except Exception:
            r = img
        surface.blit(r, r.get_rect(center=(int(self.pos.x), int(self.pos.y))))


# ==========================================================
# PLAYER: a tumbling rigid body (torso + head) with gravity-hung limbs
# ==========================================================
class Spring:
    """Small damped spring - only used for the head's slight lag."""
    __slots__ = ("a", "av", "stiff", "damp", "limit")

    def __init__(self, stiff, damp, limit):
        self.a = 0.0
        self.av = 0.0
        self.stiff = stiff
        self.damp = damp
        self.limit = limit

    def step(self, target, h):
        self.av += (self.stiff * (target - self.a) - self.damp * self.av) * h
        self.a += self.av * h
        if abs(self.a) > self.limit:
            self.a = math.copysign(self.limit, self.a)
            self.av *= -0.25

    def reset(self):
        self.a = 0.0
        self.av = 0.0


def wrap(a):
    return (a + math.pi) % math.tau - math.pi


def cross(a, b):
    return a.x * b.y - a.y * b.x


def pendulum_acc(theta, force, length):
    """Angular acceleration of a hanging piece (theta 0 = pointing straight
    down, positive = tip swings left) under a force per unit mass."""
    return (-math.cos(theta) * force.x - math.sin(theta) * force.y) / length


class Limb:
    """One rigid arm or leg pinned to the torso.

    Its angle is a WORLD angle, so gravity always pulls it toward the floor
    no matter how the torso is turned: if the body falls over to the right,
    the upper (left) arm swings round to hang down, and the lower (right)
    arm ends up tucked under the torso, out of sight. It can't pass through
    the floor - it lies flat on it instead. Legs have a wide joint range,
    so they drop into the splits when the hips reach the ground.
    """

    def __init__(self, side, pivot, length, radius, limit, joint_damp, splay=0.0):
        self.side = side                  # -1 = left piece, +1 = right piece
        self.splay = splay                # rests this far out from straight down
        self.local = Vector2(pivot)
        self.length = length
        self.radius = radius
        self.limit = limit                # max angle vs torso (None = free)
        self.joint_damp = joint_damp
        self.a = 0.0
        self.av = 0.0
        self.on_floor = False

    def reset(self, body_angle):
        self.a = body_angle - self.side * max(0.08, self.splay)
        self.av = 0.0

    def pivot(self, body):
        return body.pos + rot(self.local, body.angle)

    def step(self, body, force, h, segments=()):
        acc = pendulum_acc(self.a + self.side * self.splay, force, self.length * 0.6)   # settles splayed out
        acc -= self.joint_damp * (self.av - body.av) + LIMB_ABS_DAMP * self.av
        self.av += acc * h
        self.a = wrap(self.a + self.av * h)

        if self.limit is not None:
            rel = wrap(self.a - body.angle)
            if abs(rel) > self.limit:
                self.a = wrap(body.angle + math.copysign(self.limit, rel))
                self.av = body.av + (self.av - body.av) * -0.2

        # the floor: the limb lies on it instead of poking through
        self.on_floor = False
        piv = self.pivot(body)
        floor = GROUND_Y - self.radius
        if piv.y + self.length * math.cos(self.a) > floor:
            c = clamp((floor - piv.y) / self.length, -1.0, 1.0)
            base = math.acos(c)
            s = math.sin(self.a)
            prefer = math.copysign(1.0, s) if abs(s) > 0.02 else -self.side

            def cost(cand):
                over = 0.0
                if self.limit is not None:       # never fold past the joint
                    over = max(0.0, abs(wrap(cand - body.angle)) - self.limit)
                return (over, abs(wrap(cand - self.a)), 0 if cand * prefer > 0 else 1)

            self.a = min((base, -base), key=cost)
            self.av *= 0.35
            self.on_floor = True

        # the goal frame: rotate the limb out of the crossbar/roof
        for a, b, thick in segments:
            min_d = self.radius + thick * 0.5
            tip = piv + rot((0, self.length), self.a)
            if (tip - closest_on_segment(tip, a, b)).length() >= min_d:
                continue
            for _ in range(8):
                best = None
                for da in (0.07, -0.07):
                    t2 = piv + rot((0, self.length), self.a + da)
                    dd = (t2 - closest_on_segment(t2, a, b)).length()
                    if best is None or dd > best[0]:
                        best = (dd, da)
                self.a = wrap(self.a + best[1])
                if best[0] >= min_d:
                    break
            self.av *= 0.3


class Player:
    # collision circles in torso space: head, two top corners, rounded hips.
    # The rounded bottom means it can never balance - it always falls over.
    HEAD_LOCAL = Vector2(0, -(TORSO_H / 2 + NECK_GAP + HEAD_R))
    HIP_LOCAL = Vector2(0, TORSO_H / 2 - HIP_ROUND)
    SHAPE = (
        (HEAD_LOCAL, float(HEAD_R)),
        (Vector2(-(TORSO_W / 2 - 5), -TORSO_H / 2 + 5), 5.0),
        (Vector2(TORSO_W / 2 - 5, -TORSO_H / 2 + 5), 5.0),
        (HIP_LOCAL, float(HIP_ROUND)),
    )

    def __init__(self, x, facing, kit):
        self.facing = facing
        self.kit = kit
        self.pos = Vector2()
        self.vel = Vector2()
        self.last_vel = Vector2()
        self.angle = 0.0          # torso rotation, positive = clockwise
        self.av = 0.0

        self.head = Spring(150.0, 13.0, 0.30)
        arm_len = ARM_L - ARM_W / 2
        self.arm_l = Limb(-1, (-SHOULDER_X, SHOULDER_Y), arm_len, ARM_W / 2, None, ARM_JOINT_DAMP, ARM_SPLAY)
        self.arm_r = Limb(1, (SHOULDER_X, SHOULDER_Y), arm_len, ARM_W / 2, None, ARM_JOINT_DAMP, ARM_SPLAY)
        self.leg_l = Limb(-1, (-HIP_X, HIP_Y), LEG_L, BOOT_R, LEG_LIMIT, LEG_JOINT_DAMP, LEG_SPLAY)
        self.leg_r = Limb(1, (HIP_X, HIP_Y), LEG_L, BOOT_R, LEG_LIMIT, LEG_JOINT_DAMP, LEG_SPLAY)
        self.slide_t = 0.0         # > 0 right after diving into the floor: it skids
        self.chain_t = 0.0         # > 0 right after a throw: the next one can be a chained boost
        self.aim_dir = Vector2(facing, 0)   # where this player last threw - where blocks go
        self.limbs = (self.leg_l, self.leg_r, self.arm_l, self.arm_r)

        self.throw_timer = 0.0
        self.grounded = True
        self._segments = ()
        self.rating = 100          # card overall
        self.sho = 100             # the old two names, kept: shot accuracy and physical
        self.str = 100
        self.stat = dict(self.NEUTRAL_STATS)
        # the six stats as 0..1 - what the physics actually reads every step
        self.s_speed = self.s_shot = self.s_pass = self.s_drib = self.s_def = self.s_phys = 0.45
        self.is_gk = False
        self.range_mult = self.power_mult = self.hit_mult = 1.0   # ability boosts
        self.control = self.aim_bonus = 0.0
        self.traits = ()           # the small details
        self.abilities = ()        # [(playstyle, level)] from the card
        self.ps_on, self.ps_flash, self.ps_pop = {}, {}, None   # PlayStyles: owned / lit / name popping
        self.ab = {}               # ability effects rolled up: key -> size
        self.ctx = {}              # match context the abilities look at
        self.bump_t = 0.0          # a moment after being clattered (ESCAPE)
        self.ghost = False         # passes through the other player (dribble moves)
        self.default_sprites = {
            "head": load_fit((HEAD_R * 2, HEAD_R * 2), "head"),
            "torso": load_exact((TORSO_W, TORSO_H), "torso"),
            "arm": load_exact((ARM_W, ARM_L), "arm", "arms"),
            "leg": load_exact((LEG_W, LEG_L), "leg", "legs"),
        }
        self.sprites = self.default_sprites
        self.reset_to(x)

    def set_look(self, sprites=None):
        """Swap in a team kit / head (any missing piece uses the default)."""
        look = dict(self.default_sprites)
        for k, v in (sprites or {}).items():
            if v is not None:
                look[k] = v
        self.sprites = look

    def reset_to(self, x):
        # dropped in upright on its hips; it slumps over on its own
        self.pos.update(x, GROUND_Y - TORSO_H / 2 - 2)
        self.vel.update(0, 0)
        self.last_vel.update(0, 0)
        self.angle = random.uniform(-0.05, 0.05)
        self.av = 0.0
        self.head.reset()
        for limb in self.limbs:
            limb.reset(self.angle)
        self.throw_timer = 0.0
        self.grounded = True

    @property
    def on_ground(self):
        return self.grounded

    NEUTRAL_STATS = {k: 100 for k in STAT_KEYS}

    def set_stats(self, card):
        self.rating = card["rating"] if card else 100
        st = dict(self.NEUTRAL_STATS)
        if card and card.get("stats"):
            st.update(card["stats"])
        self.stat = st
        # the 0..1 versions, worked out once - the physics reads these every step
        self.s_speed = stat01(st["speed"])
        self.s_shot = stat01(st["shot"])
        self.s_pass = stat01(st["pass"])
        self.s_drib = stat01(st["drib"])
        self.s_def = stat01(st["def"])
        self.s_phys = stat01(st["phys"])
        self.is_gk = bool(card and card.get("pos") == "GK")
        self.sho, self.str = st["shot"], st["phys"]          # the old two names
        self.set_abilities(card.get("ps", ()) if card else (),
                           card.get("traits", ()) if card else ())

    def set_abilities(self, styles=(), traits=()):
        """Traits are always on. PlayStyles fire by themselves when their moment comes."""
        self.abilities = tuple(styles)
        self.traits = tuple(traits)
        self.ps_on = {}                                   # key -> strength (1.0 / 1.5)
        for ps, level in self.abilities:
            if ps["group"] == "gk" and not getattr(self, "is_gk", False):
                continue                                  # keeper ones only work on a keeper
            self.ps_on[ps["key"]] = PS_LEVEL_SCALE[max(1, min(PS_MAX_LEVEL, int(level))) - 1]
        self.ps_flash = {}                                # key -> seconds its badge stays lit
        self.ps_cool = {}                                 # key -> seconds before it can fire again
        self.ps_pop = None                                # (key, seconds): the badge over his head
        self.rebuild_ab()

    def rebuild_ab(self):
        """Roll the traits into one effect bag."""
        self.ab = {}
        for t in self.traits:
            for key, v in t["fx"].items():
                self.ab[key] = self.ab.get(key, 0.0) + v

    def ps(self, key):
        """This PlayStyle's strength (1.0 silver, 1.5 gold), or 0 if he doesn't have it."""
        return self.ps_on.get(key, 0.0) if hasattr(self, "ps_on") else 0.0

    def ps_ready(self, key):
        """Its strength if he has it AND it's off cooldown, else 0."""
        if self.__dict__.setdefault("ps_cool", {}).get(key, 0.0) > 0.0:
            return 0.0
        return self.ps(key)

    def ps_fire(self, key):
        """It just fired: light the badge, float the name, start its cooldown. Returns the strength."""
        L = self.ps(key)
        if L:
            self.__dict__.setdefault("ps_cool", {})[key] = PS_COOL.get(key, 5.0)
            if self.ps_flash.get(key, 0.0) < PS_FLASH * 0.6:
                self.ps_pop = (key, PS_POP)                       # the badge floats over his head
            self.ps_flash[key] = PS_FLASH
            self.ps_fired = (getattr(self, "ps_fired", (None, 0))[1] + 1, key)[::-1]   # (key, count) for the game
        return L

    # the old fired PlayStyles are gone; these stay so nothing that asks them breaks
    def style_usable(self, i):
        return i < len(self.abilities) and self.abilities[i][0]["key"] in getattr(self, "ps_on", {})

    def style_ready(self, i):
        return False

    def style_live(self, i):
        return i < len(self.abilities) and self.ps_flash.get(self.abilities[i][0]["key"], 0.0) > 0.0

    def fire_style(self, i):
        return False

    def tick_styles(self, dt):
        cool = self.__dict__.setdefault("ps_cool", {})
        for k in list(cool):
            cool[k] -= dt
            if cool[k] <= 0.0:
                del cool[k]
        self.trick_t = max(0.0, getattr(self, "trick_t", 0.0) - dt)
        for k in list(self.ps_flash):
            self.ps_flash[k] -= dt
            if self.ps_flash[k] <= 0.0:
                del self.ps_flash[k]
        if self.ps_pop is not None:
            name, t = self.ps_pop
            self.ps_pop = (name, t - dt) if t - dt > 0.0 else None
        self.cap_t = max(0.0, getattr(self, "cap_t", 0.0) - dt)

    def a(self, key):
        return self.ab.get(key, 0.0)

    def body_r(self):
        """DEFENDING, plus WALL / INTERCEPTOR / REFLEXES, make you a wider obstacle."""
        own = 1.0 if self.ctx.get("own_half") else 0.0
        third = 1.0 if self.ctx.get("own_third") else 0.0
        defend = 0.16 * self.s_def * own * self.gk_mult()    # a defender covers his own goal
        return BODY_R * (1.0 + defend + self.a("body") + self.a("body_own") * own
                         + self.a("reach_own") * third)

    def gk_mult(self):
        """A keeper's DEFENDING counts double in his own box."""
        if not self.is_gk:
            return 1.0
        own_x = GOAL_DEPTH * 0.5 if self.facing > 0 else WIDTH - GOAL_DEPTH * 0.5
        return 2.0 if abs(self.pos.x - own_x) < GK_BOX else 1.0

    def hit01(self):
        """How hard this card strikes the ball, 0..1: 50% PHYS, 30% SHOT, 10% SPEED, 10% PASS."""
        return (HIT_MIX["phys"] * self.s_phys + HIT_MIX["shot"] * self.s_shot
                + HIT_MIX["speed"] * self.s_speed + HIT_MIX["pass"] * self.s_pass)

    def duel01(self):
        """Body duels: 70% PHYS, 30% DEF."""
        return DUEL_MIX["phys"] * self.s_phys + DUEL_MIX["def"] * self.s_def

    def speed_k(self):
        lo, hi = SPEED_RANGE
        return lo + (hi - lo) * self.s_speed

    def drag_k(self):
        """Fast players lose less speed to the air and the floor."""
        lo, hi = SPEED_DRAG
        return lo + (hi - lo) * self.s_speed

    def power_bonus(self):
        c = self.ctx
        return (self.a("power") + self.a("press") * (1.0 if c.get("near_opp") else 0.0)
                + self.a("sweep") * (1.0 if c.get("own_third") else 0.0)
                + self.a("burst") * (1.0 if self.bump_t > 0.0 else 0.0)
                + self.a("clutch") * (1.0 if c.get("clutch") else 0.0))

    def strength01(self):
        """PHYSICAL: a longer drag, a harder fling, and you don't get shoved about."""
        return self.s_phys

    def drag_range(self):
        """Stronger players can pull the arrow further..."""
        sweep = self.a("sweep") if self.ctx.get("own_third") else 0.0
        return THROW_DRAG_RANGE * (0.85 + 0.35 * self.strength01()) * self.range_mult * (1.0 + self.a("range") + sweep)

    def max_power(self):
        """...for a harder fling."""
        speed = self.speed_k()                              # SPEED: how hard a throw launches you
        return (THROW_MAX * speed * (0.94 + 0.12 * self.strength01())
                * self.power_mult * (1.0 + self.power_bonus()))

    def speed_cap(self):
        """SPEED: the ceiling on how fast this card can be travelling."""
        boost = getattr(self, "cap_k", 1.0) if getattr(self, "cap_t", 0.0) > 0.0 else 1.0   # ACCELERATOR
        return PLAYER_SPEED_CAP * self.speed_k() * boost

    def throw_keep(self):
        """DRIBBLING / PIVOT: how much of your old speed survives a new throw.

        A low-dribbling card carries its momentum into the new throw, so turning round
        takes two of them; a high one changes direction almost on the spot."""
        kill = TURN_KILL * self.s_drib + self.a("turn")
        return THROW_KEEP * clamp(1.0 - kill, 0.0, 1.0)

    def aim_wobble(self, t):
        """Low shooting = shaky aim (radians); 130+ shooting is rock steady."""
        still = 1.0 - clamp(self.vel.length() / 500.0, 0.0, 1.0)     # DEAD BALL
        steady = self.aim_bonus * 4 + self.a("aim") * 2.2 + self.a("aim_still") * 2.0 * still
        c = self.ctx
        if self.ps("penalty") and c.get("dead_ball"):
            steady += 0.6 * self.ps("penalty")                          # PENALTY EXPERT
        if self.ps("clinical") and c.get("near_goal") and c.get("ball_close"):
            steady += 0.35 * self.ps("clinical")                        # CLINICAL FINISHER
        if self.ps("power") and self.vel.length() > PS_RUNUP:
            steady += 0.35 * self.ps("power")                           # POWER SHOT
        amp = (1.0 - self.s_shot) * AIM_WOBBLE * clamp(1.0 - steady, 0.0, 1.0)
        return amp * (0.7 * math.sin(t * 7.0) + 0.3 * math.sin(t * 13.3 + 1.7))

    # ---- rigid body helpers --------------------------------
    def to_world(self, local):
        return self.pos + rot(local, self.angle)

    def point_vel(self, p):
        return self.vel + perp(p - self.pos) * self.av

    def inv_eff(self, p, n):
        rn = cross(p - self.pos, n)
        return 1.0 / PLAYER_MASS + rn * rn / PLAYER_INERTIA

    def apply_impulse(self, p, j):
        self.vel += j / PLAYER_MASS
        self.av += cross(p - self.pos, j) / PLAYER_INERTIA

    # ---- control ------------------------------------------
    def can_throw(self):
        return self.throw_timer <= 0.0

    def throw(self, direction, power, sfx=None, particles=None):
        if direction.length_squared() < 1e-6 or not self.can_throw():
            return False
        n = direction.normalize()
        was_grounded = self.grounded
        if self.chain_t > 0.0 and self.vel.length() > 600.0:
            power *= 1.0 + CHAIN_BOOST * self.s_speed       # SPEED: a quick second throw on the move
        ball = getattr(self, "ball_ref", None)
        keep = self.throw_keep()
        knock, wait_k = 0.0, 1.0
        if ball is not None and getattr(self, "ps_on", None):
            to_ball = ball.pos - self.pos
            gap = to_ball.length()
            at_ball = gap > 1.0 and n.dot(to_ball / gap) > 0.6
            carrying = getattr(ball, "carrier", None) is self and ball.carrier_t > 0.0 and gap < CARRY_DIST
            loose = getattr(ball, "carrier", None) is None or ball.carrier_t <= 0.0
            opp = getattr(self, "opp_ref", None)
            if gap > 380.0 and at_ball and loose and self.ps_ready("accelerator"):   # ACCELERATOR
                L = self.ps_fire("accelerator")
                power *= 1.0 + 0.75 * L                       # (was 0.24, 0.40)
                self.cap_t, self.cap_k = 2.0, 1.0 + 0.55 * L   # (was 0.20, 0.32)
            if carrying and n.x * self.facing > 0.2 and self.ps_ready("rapid"):       # RAPID
                L = self.ps_fire("rapid")
                power *= 1.0 + 0.55 * L                       # (was 0.18, 0.30)
                knock = 1050.0 * L                             # (was 420, 640)
            if carrying and self.ctx.get("near_opp") and self.ps_ready("trickster"):  # TRICKSTER
                L = self.ps_fire("trickster")
                keep *= clamp(1.0 - 0.92 * L, 0.02, 1.0)       # turns on the spot...
                self.trick_t = 0.65                            # ...through him
                ball.carrier, ball.carrier_t = self, CARRY_TIME
                if opp is not None:
                    opp.throw_timer = max(opp.throw_timer, PS_STUN * L)   # ...and he's frozen
            if self.ctx.get("clutch") and self.ps_ready("relentless"):               # RELENTLESS
                L = self.ps_fire("relentless")
                power *= 1.0 + 0.55 * L                       # (was 0.15, 0.28)
                wait_k *= clamp(1.0 - 0.75 * L, 0.1, 1.0)    # (was 0.40, 0.55)
            own_x = GOAL_DEPTH if self.facing > 0 else WIDTH - GOAL_DEPTH
            if self.is_gk and abs(ball.pos.x - own_x) < GK_BOX and n.dot(to_ball) > 0.0 \
                    and self.ps_ready("rushout"):                  # RUSH OUT
                L = self.ps_fire("rushout")
                power *= 1.0 + 0.85 * L                       # (was 0.30, 0.45)
                self.cap_t, self.cap_k = 1.4, 1.0 + 0.45 * L
                wait_k *= clamp(1.0 - 0.80 * L, 0.05, 1.0)
        self.vel = self.vel * keep + n * power
        if knock > 0.0:
            ball.vel += n * knock
        self.aim_dir = Vector2(n)
        if was_grounded and n.y > -0.25:
            self.vel.y = min(self.vel.y, -THROW_GROUND_HOP)
        # a flick of spin so the body tumbles: flung right, it tips back left
        self.av = self.av * 0.3 - n.x * power * THROW_SPIN
        self.grounded = False
        lo, hi = THROW_WAIT                                 # DRIBBLING: throw again sooner
        wait = max(THROW_COOLDOWN, lo + (hi - lo) * self.s_drib)
        self.throw_timer = wait * wait_k * clamp(1.0 - self.a("quick"), 0.2, 1.0)
        self.chain_t = CHAIN_WINDOW + self.throw_timer
        if sfx:
            sfx.play("throw", clamp(power / THROW_MAX, 0.2, 0.6))
        if particles and was_grounded:
            particles.burst(Vector2(self.pos.x, GROUND_Y), 9, "dust",
                            -n, 0.8, power * 0.25, (186, 208, 178))
        return True

    # ---- simulation ---------------------------------------
    def _contacts(self, segments):
        """(contact point, normal, penetration) for every touching circle."""
        out = []
        for local, r in self.SHAPE:
            c = self.to_world(local)
            pen = c.y + r - GROUND_Y
            if pen > 0.0:
                out.append((c + Vector2(0, r), Vector2(0, -1), pen))
            pen = r - c.x
            if pen > 0.0:
                out.append((c - Vector2(r, 0), Vector2(1, 0), pen))
            pen = c.x + r - WIDTH
            if pen > 0.0:
                out.append((c + Vector2(r, 0), Vector2(-1, 0), pen))
            pen = r - c.y
            if pen > 0.0:
                out.append((c - Vector2(0, r), Vector2(0, 1), pen))
            for a, b, thick in segments:
                cp = closest_on_segment(c, a, b)
                d = c - cp
                dist = d.length()
                pen = r + thick * 0.5 - dist
                if pen > 0.0:
                    n = d / dist if dist > 1e-6 else Vector2(0, -1)
                    out.append((c - n * r, n, pen))
        return out

    def step(self, h, segments, sfx, particles):
        self._segments = segments
        self.throw_timer = max(0.0, self.throw_timer - h)
        self.bump_t = max(0.0, self.bump_t - h)
        self.chain_t = max(0.0, self.chain_t - h)
        self.slide_t = max(0.0, self.slide_t - h)
        if self.abilities:
            self.tick_styles(h)
        else:
            self.cap_t = 0.0
        was_grounded = self.grounded

        self.vel.y += PLAYER_GRAVITY * TWIST["grav"] * clamp(1.0 - self.a("float"), 0.5, 1.0) * h          # FEATHER
        self.vel *= (1.0 - PLAYER_AIR_DRAG * self.drag_k() * clamp(1.0 - self.a("glide"), 0.3, 1.0) * h)   # GLIDE
        cap = self.speed_cap()
        if self.vel.length() > cap:
            self.vel.scale_to_length(cap)
        self.av = clamp(self.av * (1.0 - AIR_ANGULAR_DAMP * h), -22.0, 22.0)
        self.pos += self.vel * h
        self.angle = wrap(self.angle + self.av * h)

        contacts = self._contacts(segments)
        self.grounded = any(n.y < -0.5 for _, n, _ in contacts)
        v_in = Vector2(self.vel)                    # how it came in, for the slide
        grip = GROUND_MU * (SLIDE_GRIP if self.slide_t > 0.0 else 1.0)
        grip *= clamp(1.0 - 3.0 * self.a("glide"), 0.3, 1.0) * TWIST["grip"]     # GLIDE (and RAIN): a landing skids on
        impact = 0.0
        for it in range(4):
            for p, n, _ in contacts:
                vn = self.point_vel(p).dot(n)
                if vn >= 0.0:
                    continue
                impact = max(impact, -vn)
                e = GROUND_RESTITUTION * (1.0 + self.a("spring")) if (it == 0 and vn < -250.0) else 0.0
                jn = -(1.0 + e) * vn / self.inv_eff(p, n)
                self.apply_impulse(p, n * jn)
                t = perp(n)
                vt = self.point_vel(p).dot(t)
                jt = clamp(-vt / self.inv_eff(p, t), -grip * jn, grip * jn)
                self.apply_impulse(p, t * jt)

        for _ in range(3):                         # push out of the floor/walls
            for _, n, pen in self._contacts(segments):
                self.pos += n * (pen * 0.8)

        if self.grounded and not was_grounded and v_in.y > 300.0 and abs(v_in.x) > 150.0:
            # THE SLIDE (26 Oct): a dive into the floor used to lose everything - the hard hit
            # made a huge normal force, and the floor's grip ate all the sideways speed in one
            # step. Now the speed comes back, by the angle: a shallow dive skids a long way,
            # one straight down barely moves. The grip stays loose for a moment so it skids.
            steep = math.atan2(v_in.y, abs(v_in.x)) / (math.pi * 0.5)
            keep = SLIDE_KEEP[0] + (SLIDE_KEEP[1] - SLIDE_KEEP[0]) * steep
            want = keep * abs(v_in.x)
            if abs(self.vel.x) < want:
                self.vel.x = math.copysign(want, v_in.x)
            self.slide_t = SLIDE_TIME
        if self.grounded and self.slide_t > 0.0 and abs(self.vel.x) > 500.0 and particles \
                and random.random() < 0.35:
            particles.burst(Vector2(self.pos.x, GROUND_Y), 1, "dust", Vector2(-math.copysign(1, self.vel.x), -0.6),
                            0.7, abs(self.vel.x) * 0.15, (192, 212, 184))
        if self.grounded:
            # Landing used to stop you dead. Now the floor only scrapes: a fast landing skids
            # on, bleeding speed, and a slow one comes to rest instead of drifting forever.
            sliding = self.slide_t > 0.0                 # the floor drags less mid-slide
            # GLIDE (29 Oct): air drag is gone, so it carries your momentum through the landing instead
            glide = clamp(1.0 - 3.0 * self.a("glide"), 0.3, 1.0) * TWIST["grip"]
            self.vel.x *= math.exp(-GROUND_DRAG * self.drag_k() * (SLIDE_DRAG if sliding else 1.0) * glide * h)
            scrape = SLIDE_SCRAPE * clamp(1.0 - self.a("slide"), 0.25, 1.0) * (0.5 if sliding else 1.0) * glide * h
            if abs(self.vel.x) > scrape:
                self.vel.x -= math.copysign(scrape, self.vel.x)
            else:
                self.vel.x = 0.0
            upright = abs(self.angle) < 0.9
            if upright:
                # it can't stand: tip over toward whichever side it leans
                lean = self.angle if abs(self.angle) > 1e-3 else -self.facing * 1e-3
                self.av += math.copysign(TOPPLE_PUSH, lean) * h
            else:
                self.av *= math.exp(-GROUND_ANGULAR_DAMP * (1.0 + self.a("settle")) * h)
                if self.vel.length() < 14.0 and abs(self.av) < 0.25:
                    self.vel.update(0, 0)          # lying still stays still
                    self.av = 0.0
            if not was_grounded and impact > 350.0:
                self._on_land(impact, sfx, particles)

        self._animate(h)

    def _on_land(self, impact, sfx, particles):
        if impact > 800.0:
            if sfx:
                sfx.play("land", clamp(impact / 2600.0, 0.15, 0.6))
            if particles:
                particles.burst(Vector2(self.pos.x, GROUND_Y), int(clamp(impact / 240.0, 4, 14)),
                                "dust", Vector2(0, -1), 1.3, impact * 0.22, (192, 212, 184))

    def _animate(self, h):
        dv = self.vel - self.last_vel
        self.last_vel.update(self.vel)
        # acceleration from anything other than gravity (throws, floor, hits)
        push = dv / h - Vector2(0, PLAYER_GRAVITY)
        # limbs always feel gravity, plus a little lag from being shoved
        force = Vector2(0, PLAYER_GRAVITY) - push * LIMB_LAG
        if force.length() > LIMB_FORCE_CAP:
            force.scale_to_length(LIMB_FORCE_CAP)
        for limb in self.limbs:
            limb.step(self, force, h, self._segments)
        self.head.av -= clamp(dv.x, -2200.0, 2200.0) * 0.0018
        self.head.step(0.0, h)

    # ---- geometry -----------------------------------------
    def frame(self):
        f = {"ta": self.angle}
        f["neck"] = self.to_world((0, -TORSO_H / 2))
        f["head_a"] = self.angle + self.head.a
        f["head"] = f["neck"] + rot((0, -(NECK_GAP + HEAD_R)), f["head_a"])
        f["arms"] = []
        for limb in (self.arm_l, self.arm_r):
            piv = limb.pivot(self)
            f["arms"].append((piv, piv + rot((0, limb.length), limb.a), limb.a))
        f["legs"] = []
        for limb in (self.leg_l, self.leg_r):
            piv = limb.pivot(self)
            f["legs"].append((piv, piv + rot((0, limb.length), limb.a), limb.a))
        return f

    def body_segment(self):
        """The body collides with ball/opponent as one capsule (head to hips)."""
        return self.to_world(self.HEAD_LOCAL), self.to_world(self.HIP_LOCAL)

    def lowest_y(self):
        return max(self.to_world(l).y + r for l, r in self.SHAPE)

    # ---- rendering ----------------------------------------
    def draw(self, surface, debug=False):
        kit = self.kit
        s = self.sprites
        f = self.frame()
        ta = f["ta"]

        # legs and arms are all drawn behind the torso, so a limb tucked
        # under the body disappears behind it
        for piv, end, ang in f["legs"]:
            if s["leg"] is not None:
                blit_rot(surface, s["leg"], piv + rot((0, LEG_L / 2), ang), ang)
                continue
            knee = piv + rot((0, LEG_L * 0.45), ang)
            toe = end + rot((self.facing * 9, 1), ang)
            capsule(surface, kit["skin"], knee, end, LEG_W / 2 - 1)
            capsule(surface, kit["shorts"], piv, knee, LEG_W / 2)
            capsule(surface, kit["boot"], end, toe, BOOT_R)

        for piv, end, ang in f["arms"]:
            if s["arm"] is not None:
                blit_rot(surface, s["arm"], piv + rot((0, ARM_L / 2), ang), ang)
                continue
            elbow = piv + rot((0, ARM_L * 0.48), ang)
            capsule(surface, kit["skin"], elbow, end, ARM_W / 2 - 1)
            capsule(surface, kit["shirt_dark"], piv, elbow, ARM_W / 2)

        # torso: one rigid piece with a rounded bottom
        if s["torso"] is not None:
            blit_rot(surface, s["torso"], self.pos, ta)
        else:
            hip = self.to_world(self.HIP_LOCAL)
            upper_h = TORSO_H - HIP_ROUND
            upper_c = self.to_world((0, -TORSO_H / 2 + upper_h / 2))
            hr = TORSO_W / 2
            poly(surface, kit["shirt"], rot_rect(upper_c, TORSO_W, upper_h, ta))
            pygame.draw.circle(surface, kit["shorts"], (int(hip.x), int(hip.y)), int(hr))
            poly(surface, kit["shorts"], rot_rect(self.to_world((0, TORSO_H / 2 - HIP_ROUND - 4)),
                                                  TORSO_W, 8, ta))
            poly(surface, kit["shirt_dark"],
                 rot_rect(self.to_world((0, -TORSO_H / 2 + 4)), TORSO_W, 8, ta))

        # head
        hp, ha = f["head"], f["head_a"]
        if s["head"] is not None:
            blit_rot(surface, s["head"], hp, ha)
        else:
            pygame.draw.circle(surface, kit["skin"], (int(hp.x), int(hp.y)), HEAD_R)

        if debug:
            for local, r in self.SHAPE:
                c = self.to_world(local)
                pygame.draw.circle(surface, (255, 0, 160), (int(c.x), int(c.y)), int(r), 1)
            top, bot = self.body_segment()
            pygame.draw.line(surface, (255, 0, 160), top, bot, 1)


# ==========================================================
# CONTACTS
# ==========================================================
def closest_between_segments(p1, q1, p2, q2):
    """Closest points between segments p1-q1 and p2-q2."""
    d1, d2, r = q1 - p1, q2 - p2, p1 - p2
    a, e, f = d1.dot(d1), d2.dot(d2), d2.dot(r)
    if a < 1e-9 and e < 1e-9:
        return Vector2(p1), Vector2(p2)
    if a < 1e-9:
        s, t = 0.0, clamp(f / e, 0.0, 1.0)
    else:
        c = d1.dot(r)
        if e < 1e-9:
            s, t = clamp(-c / a, 0.0, 1.0), 0.0
        else:
            b = d1.dot(d2)
            denom = a * e - b * b
            s = clamp((b * f - c * e) / denom, 0.0, 1.0) if denom > 1e-9 else 0.0
            t = (b * s + f) / e
            if t < 0.0:
                t, s = 0.0, clamp(-c / a, 0.0, 1.0)
            elif t > 1.0:
                t, s = 1.0, clamp((b - c) / a, 0.0, 1.0)
    return p1 + d1 * s, p2 + d2 * t


def ability_hit(doll, ball, vn):
    """How much harder this particular hit is, from the doll's attacking abilities."""
    if not getattr(doll, "ab", None):
        return 1.0
    facing = getattr(doll, "facing", 1)
    goal_x = WIDTH - GOAL_DEPTH * 0.5 if facing > 0 else GOAL_DEPTH * 0.5
    dist = abs(ball.pos.x - goal_x)
    their_half = (ball.pos.x > WIDTH * 0.5) if facing > 0 else (ball.pos.x < WIDTH * 0.5)
    m = 1.0 + _ab(doll, "hit")
    m += _ab(doll, "hit_att") if their_half else _ab(doll, "hit_own")
    if dist < 560.0:
        m += _ab(doll, "hit_box")
    if dist > 1000.0:
        m += _ab(doll, "hit_far")
    if ball.pos.y < doll.pos.y - 30.0:
        m += _ab(doll, "hit_high")
    if abs(vn) > 700.0:
        m += _ab(doll, "hit_fast")
    # VOLLEY / ACROBAT: you're off the floor and so is the ball
    if not getattr(doll, "grounded", True) and ball.pos.y < GROUND_Y - ball.radius - 40.0:
        m += _ab(doll, "hit_air")
    if getattr(doll, "ctx", {}).get("clutch"):
        m += _ab(doll, "clutch")
    return m


def ball_vs_player(ball, doll, sfx, particles, on_hit):
    """Ball against the body capsule and the four limb tips (hands + feet).
    Only the deepest contact is resolved each step."""
    if ball.frozen:
        return False
    best = None
    top, bot = doll.body_segment()
    cp = closest_on_segment(ball.pos, top, bot)
    d = ball.pos - cp
    body_r = doll.body_r() if hasattr(doll, "body_r") else BODY_R
    pen = ball.radius + body_r - d.length()
    if pen > 0.0:
        best = (pen, cp, body_r, None)
    for limb in doll.limbs:
        piv = limb.pivot(doll)
        tip = piv + rot((0, limb.length), limb.a)
        r = limb.radius + 2.0
        pen = ball.radius + r - (ball.pos - tip).length()
        if pen > 0.0 and (best is None or pen > best[0]):
            best = (pen, tip, r, (limb, piv))
    if best is None:
        return False

    pen, centre, r, limb_hit = best
    d = ball.pos - centre
    dist = d.length()
    n = d / dist if dist > 1e-6 else Vector2(0, -1)
    ball.pos += n * pen
    contact = centre + n * r
    if limb_hit is None:
        pv = doll.point_vel(contact)
        inv = doll.inv_eff(contact, n)
    else:
        limb, piv = limb_hit
        # a swinging limb adds its own speed to the hit
        pv = doll.point_vel(piv) + perp(contact - piv) * clamp(limb.av, -20.0, 20.0)
        inv = doll.inv_eff(piv, n) + LIMB_HIT_SOFTNESS
    rel = ball.vel - pv
    vn = rel.dot(n)
    if vn >= 0.0:
        return True

    # ---- what kind of moment this is (the PlayStyles look at it)
    has_ps = bool(getattr(doll, "ps_on", None))
    sp_in = ball.vel.length()
    drive = max(0.0, pv.dot(n))
    run_up = pv.length()
    facing = getattr(doll, "facing", 1)
    goal = Vector2(WIDTH - GOAL_DEPTH * 0.5 if facing > 0 else GOAL_DEPTH * 0.5, GROUND_Y - GOAL_HEIGHT * 0.5)
    to_goal = (goal - ball.pos).length()
    their_half = (ball.pos.x - WIDTH * 0.5) * facing > 0.0
    head_hit = limb_hit is None and hasattr(doll, "HEAD_LOCAL") and \
        (contact - doll.to_world(doll.HEAD_LOCAL)).length() < HEAD_R + 10.0
    ctx = getattr(doll, "ctx", {})
    fired = []                                                    # (key, strength) that fire on this hit

    def ps_try(key, cond):
        if has_ps and cond and doll.ps_ready(key):              # off cooldown, and its moment
            fired.append(key)
            return doll.ps_fire(key)
        return 0.0
    at_goal = n.dot((goal - ball.pos) / max(1.0, to_goal))     # 1 = struck straight at their goal
    ps_mult = 1.0
    L_head = ps_try("header", head_hit and drive > 120.0)
    ps_mult += 1.10 * L_head                                   # PRECISION HEADER
    L_pen = ps_try("penalty", sp_in < PS_DEAD and drive > 180.0 and at_goal > 0.25)
    ps_mult += 1.20 * L_pen                                    # PENALTY EXPERT
    L_cli = ps_try("clinical", to_goal < PS_NEAR_GOAL and drive > 450.0 and at_goal > 0.4)
    ps_mult += 0.95 * L_cli                                    # CLINICAL FINISHER
    L_pow = ps_try("power", their_half and run_up > PS_RUNUP and drive > 550.0 and at_goal > 0.3)
    ps_mult += 1.25 * L_pow                                    # POWER SHOT
    L_whip = ps_try("whipped", to_goal > PS_FAR and drive > 400.0 and n.y < -0.25 and n.x * facing > 0.0)
    ps_mult += 0.75 * L_whip                                   # WHIPPED CROSS
    L_bul = ps_try("bullet", to_goal > 650.0 and 400.0 < drive < 1800.0 and abs(n.y) < 0.35
                   and n.x * facing > 0.3)
    ps_mult += 0.90 * L_bul                                    # BULLET PASS
    L_chip = ps_try("chip", their_half and 450.0 < to_goal < 1900.0 and drive > 280.0 and n.y < -0.40
                    and ctx.get("opp_off_line"))

    # momentum exchange: a fast player hits hard, a still one barely nudges it
    rest = BALL_PLAYER_RESTITUTION * (1.0 + _ab(doll, "rebound"))          # BLOCKER
    j = -(1.0 + rest) * vn / (1.0 / BALL_MASS + inv)
    # the card's overall (28 Oct): x2.6 from the weakest card to the best, around the old middle
    j *= BALL_HIT_BASE * rating_k(doll, RATING_HIT)
    # HIT POWER: 50% PHYSICAL, 30% SHOT, 10% SPEED, 10% PASSING
    lo, hi = HIT_RANGE
    j *= lo + (hi - lo) * (doll.hit01() if hasattr(doll, "hit01") else 0.5)
    # SHIELDING: an opponent knocks a ball you are carrying away less (DRIB + PHYS);
    # a good defender cuts through it - that is a steal
    carrier = getattr(ball, "carrier", None)
    stealing = False
    if carrier is not None and carrier is not doll and ball.carrier_t > 0.0 \
            and (ball.pos - carrier.pos).length() < CARRY_DIST:
        shield = SHIELD_MAX * (0.6 * getattr(carrier, "s_drib", 0.5) + 0.4 * getattr(carrier, "s_phys", 0.5))
        if getattr(carrier, "ps_on", None) and carrier.ps_ready("bruiser"):
            shield *= 1.0 + 2.6 * carrier.ps_fire("bruiser")          # BRUISER: a far stronger shield
        shield *= 1.0 - 0.7 * getattr(doll, "s_def", 0.0)
        L_ant = ps_try("anticipate", True)
        if L_ant:                                                    # ANTICIPATE: a clean steal...
            shield = 0.0
            carrier.throw_timer = max(getattr(carrier, "throw_timer", 0.0), PS_STUN * L_ant)   # ...he's stunned
        j *= 1.0 - clamp(shield, 0.0, 0.8)
        stealing = True
    j *= getattr(doll, "hit_mult", 1.0) * ability_hit(doll, ball, vn) * ps_mult
    ball.vel += n * (j / BALL_MASS)
    # the ball goes where the body part is going: it takes on the sideways sweep of the
    # torso / arm / leg that touched it instead of only bouncing off along the normal
    carry = BALL_CARRY * (1.0 + (_ab(doll, "limb_sweep") if limb_hit is not None else 0.0))
    vt_ball = ball.vel - n * ball.vel.dot(n)
    vt_body = pv - n * pv.dot(n)
    ball.vel += (vt_body - vt_ball) * carry
    # PASSING (26 Oct): touch, never cushioning - the ball keeps its speed. A soft touch
    # sends it the way you are moving; a low passer's soft touch is heavy and springs off;
    # on a real hit, good passing lines the ball up with your run.
    drive = max(0.0, pv.dot(n))
    soft = clamp(1.0 - drive / CONTROL_FADE, 0.0, 1.0) ** 1.6
    s_pass = getattr(doll, "s_pass", 0.0)
    touch = (TOUCH_PASS * s_pass + getattr(doll, "control", 0.0) + _ab(doll, "control")
             + (0.3 * getattr(doll, "s_def", 0.0) if stealing else 0.0))       # FIRST TOUCH / SILKY
    L_tiki = ps_try("tikitaka", soft > 0.35 and sp_in > 350.0 and doll.vel.length() > 150.0)
    touch += 1.0 * L_tiki                                                       # TIKI TAKA: first time
    L_trick = ps_try("trickster", soft > 0.4 and ctx.get("near_opp") and getattr(ball, "carrier", None) is doll)
    touch += 0.30 * L_trick                                                     # TRICKSTER
    if "anticipate" in fired:
        touch = max(touch, 0.6 + 0.2 * doll.ps("anticipate"))                   # the steal goes your way
        soft = max(soft, 0.8)
    sp0 = ball.vel.length()
    move = doll.vel.length()
    if move > 80.0 and sp0 > 1.0:
        k_soft = clamp(touch, 0.0, 0.95) * soft                  # a soft touch: goes where you move
        k = k_soft + CLEAN_HIT * s_pass * (1.0 - soft)            # a real hit: lines up with your run
        if k > 0.0:
            new = ball.vel / sp0 * (1.0 - k) + doll.vel / move * k
            if new.length_squared() > 1e-4:
                # never slower than it was; a soft touch also takes on your speed
                ball.vel = new.normalize() * (sp0 + max(0.0, move - sp0) * k_soft)
    heavy = HEAVY_TOUCH * (1.0 - s_pass) * soft
    if heavy > 0.0:
        ball.vel += n * max(abs(vn), 200.0) * heavy                          # a heavy touch
    if L_tiki and doll.vel.length() > 1.0:                                    # ...it's yours, at your pace
        ball.vel = doll.vel.normalize() * max(doll.vel.length() * (1.0 + 0.55 * L_tiki), 420.0)
        ball.zip_t = max(ball.zip_t, 0.8)
        doll.throw_timer = 0.0                                                # ...and you go again at once
    if L_trick and doll.vel.length() > 1.0:                                   # TRICKSTER: stays at your feet
        ball.vel = ball.vel * (1.0 - 0.25 * L_trick) + doll.vel * (0.25 * L_trick)
    if soft > 0.3:
        ball.carrier, ball.carrier_t = doll, CARRY_TIME                       # you're carrying it
    # DEFENDING: a shot coming at your own goal loses its sting on you. SAFE HANDS is
    # the keeper version of the same thing - it catches rather than deflects.
    own = getattr(doll, "ctx", {}).get("own_half")
    if own and abs(vn) > 500.0:
        gk = doll.gk_mult() if hasattr(doll, "gk_mult") else 1.0
        s_def = getattr(doll, "s_def", 0.0) * gk
        kill = BLOCK_KILL * s_def + _ab(doll, "catch")
        if kill > 0.0:
            ball.vel *= clamp(1.0 - kill, 0.18, 1.0)
        # ...and the block goes where the defender is aiming (his last throw)
        aim = getattr(doll, "aim_dir", None)
        k = clamp(BLOCK_AIM * s_def, 0.0, 0.85)
        L_def = ps_try("deflector", getattr(doll, "is_gk", False))
        if L_def:                                                    # DEFLECTOR: killed, up and wide
            ball.vel *= clamp(1.0 - 0.75 * L_def, 0.15, 1.0)
            aim = Vector2(0.55 * facing, -0.85).normalize()
            k = clamp(0.80 * L_def, k, 0.95)
        sp = ball.vel.length()
        if aim is not None and k > 0.0 and sp > 1.0:
            new = ball.vel / sp * (1.0 - k) + aim * k
            if new.length_squared() > 1e-4:
                ball.vel = new.normalize() * sp
    # aim_bonus (Ren's Perfect Shot) is a scripted move with its own aim: it still turns the
    # ball at once. Everything from stats, traits and PlayStyles now bends a SPUN hit (below).
    speed = ball.vel.length()
    goal = Vector2(WIDTH - GOAL_DEPTH * 0.5 if doll.facing > 0 else GOAL_DEPTH * 0.5,
                   GROUND_Y - GOAL_HEIGHT * 0.5)
    want = goal - ball.pos
    ball.bend, ball.bend_t = 0.0, 0.0
    pull = 0.0
    if L_head:
        if their_half:
            pull += 0.60 * L_head                                 # PRECISION HEADER: on target
        else:                                                     # ...or cleared up and away
            away = Vector2(0.6 * facing, -0.8).normalize()
            ball.vel = (ball.vel.normalize() * 0.3 + away * 0.7).normalize() * max(speed, 1.0)
    pull += 0.55 * L_pen + 0.60 * L_cli                           # PENALTY EXPERT / CLINICAL
    if pull > 0.0 and speed > 300.0 and want.length_squared() > 1.0 and ball.vel.dot(want) > 0.0:
        cur = math.atan2(ball.vel.y, ball.vel.x)
        diff = (math.atan2(want.y, want.x) - cur + math.pi) % math.tau - math.pi
        turn = clamp(diff, -pull, pull)
        ball.vel = Vector2(math.cos(cur + turn), math.sin(cur + turn)) * speed
    if speed > 300.0 and getattr(doll, "aim_bonus", 0.0) > 0.0 and want.length_squared() > 1.0 \
            and ball.vel.dot(want) > 0.0:
        cur = math.atan2(ball.vel.y, ball.vel.x)
        diff = (math.atan2(want.y, want.x) - cur + math.pi) % math.tau - math.pi
        turn = clamp(diff, -doll.aim_bonus, doll.aim_bonus)
        ball.vel = Vector2(math.cos(cur + turn), math.sin(cur + turn)) * speed
    strength = abs(vn)
    if n.y > -0.35 and strength > 500.0:
        lift = (0.12 + _ab(doll, "lift") * 0.45) * clamp(1.0 - _ab(doll, "flat"), 0.4, 1.0)
        if L_bul:
            lift *= 0.10                                             # BULLET PASS: stays flat
        if L_pow:
            lift *= 0.20                                             # POWER SHOT: low and driven
        ball.vel.y -= strength * lift                                # LOB lifts, LOW DRIVEN flattens
    if L_bul:
        ball.vel.y = max(ball.vel.y, -abs(ball.vel.x) * 0.08)
        ball.zip_t = max(ball.zip_t, 2.6)                            # ...and keeps its pace
    if L_pow:
        ball.zip_t = max(ball.zip_t, 2.2)
    if L_chip:                                                       # CHIP SHOT: a real lob that drops in
        aim_pt = Vector2(goal.x, GROUND_Y - GOAL_HEIGHT * 0.42)
        dx, dy = aim_pt.x - ball.pos.x, aim_pt.y - ball.pos.y
        T = clamp(abs(dx) / 760.0, 0.75, 1.7)                      # flight time (ball time)
        vx = dx / T * 1.04                                           # (a touch more for the air drag)
        vy = (dy - 0.5 * BALL_GRAVITY * T * T) / T
        miss = (1.5 - L_chip) * random.uniform(-0.05, 0.05)        # silver: within a few %, gold: perfect
        ball.vel = Vector2(vx * (1.0 + miss), vy)
        if ball.vel.length() > BALL_SPEED_CAP:
            ball.vel.scale_to_length(BALL_SPEED_CAP)
        ball.extra_g_t = 0.0
    elif strength < 420.0 and _ab(doll, "lift") > 0.0:
        ball.vel.y -= strength * _ab(doll, "lift") * 1.1             # PLAY MAKER pops it up for himself
    dspin = rel.dot(perp(n)) * 0.035 * (1.0 + _ab(doll, "curve"))           # SPIN
    ball.spin += dspin
    # 1 Nov: and TOPSPIN - the ball rolls forward off every hit, more the harder it's struck, and
    # dips in flight (Ball.step). A chip has none, so the lob still drops where it was aimed.
    if not L_chip and abs(ball.vel.x) > 1.0:
        top = math.degrees(min(abs(ball.vel.x), BALL_SPEED_CAP) / ball.radius) * BALL_TOPSPIN   # (a pop straight up barely turns)
        ball.spin = math.copysign(max(abs(ball.spin), top), ball.vel.x) if ball.spin * ball.vel.x >= 0.0 \
            else math.copysign(top, ball.vel.x)
    # SHOT: only a hit that puts spin on the ball bends toward goal - noticeably at the top
    b0, b1 = BEND_SPIN
    spin_k = clamp((abs(dspin) - b0) / (b1 - b0), 0.0, 1.0)
    fin_spin = clamp((abs(dspin) - b0 * 0.6) / (b1 - b0 * 0.6), 0.0, 1.0)    # FINESSE reads less spin
    sp_out = ball.vel.length()
    heading = ball.vel.dot(want) / max(1.0, sp_out * want.length()) if want.length_squared() > 1.0 else 0.0
    L_fin = ps_try("finesse", 420.0 < to_goal < 1700.0 and fin_spin >= 0.15
                   and sp_out > 350.0 and heading > 0.45)
    if L_fin:                                                        # FINESSE EXPERT: the curler
        corner = Vector2(goal.x, GROUND_Y - GOAL_HEIGHT * 0.80)      # into the top corner
        ball.bend = min(BEND_MAX + 0.55 * L_fin, 0.45 + 0.26 * L_fin + getattr(doll, "s_shot", 0.5) * BEND_SHOT * 0.5)
        ball.bend_t, ball.bend_goal = BEND_TIME * 1.15, corner
        ball.vel *= 1.0 + 0.65 * L_fin
    elif spin_k > 0.0 and sp_out > 300.0 and want.length_squared() > 1.0 and ball.vel.dot(want) > 0.0:
        ball.bend = min(BEND_MAX, getattr(doll, "s_shot", 0.5) * BEND_SHOT + _ab(doll, "aim")) * spin_k
        ball.bend_t, ball.bend_goal = BEND_TIME, goal
    if L_whip and ball.bend <= 0.0:                                  # WHIPPED CROSS: curls into the box
        ball.bend, ball.bend_t = 0.75 * L_whip, BEND_TIME * 1.5
        ball.bend_goal = Vector2(goal.x - facing * 320.0, GROUND_Y - 260.0)
    ball.impact(n, strength)
    if limb_hit is None:
        doll.apply_impulse(contact, -n * j)
    else:
        limb, piv = limb_hit
        doll.apply_impulse(piv, -n * j * 0.6)
        limb.av = clamp(limb.av - cross(contact - piv, n * j) * 0.004, -20.0, 20.0)

    if strength > 900.0:
        sfx.play("kick", clamp(strength / 2200.0, 0.45, 1.0))
        on_hit(strength)
    elif strength > 200.0:
        sfx.play("tap", clamp(strength / 1200.0, 0.15, 0.5))
    return True


def player_vs_player(a, b, sfx, ball=None):
    if getattr(a, "ghost", False) or getattr(b, "ghost", False):
        return
    if getattr(a, "trick_t", 0.0) > 0.0 or getattr(b, "trick_t", 0.0) > 0.0:
        return                                                    # TRICKSTER: straight through him
    pa, pb = closest_between_segments(*a.body_segment(), *b.body_segment())
    d = pa - pb
    dist = d.length()
    ra = a.body_r() if hasattr(a, "body_r") else BODY_R
    rb = b.body_r() if hasattr(b, "body_r") else BODY_R
    pen = ra + rb - dist
    if pen <= 0.0:
        return
    n = d / dist if dist > 1e-6 else Vector2(1 if a.pos.x >= b.pos.x else -1, 0)
    a.pos += n * (pen * 0.5)
    b.pos -= n * (pen * 0.5)
    c = (pa + pb) * 0.5
    vn = (a.point_vel(c) - b.point_vel(c)).dot(n)
    if vn >= 0.0:
        return
    j = -(1.0 + 0.35) * vn / (a.inv_eff(c, n) + b.inv_eff(c, n))
    # duels: 70% PHYSICAL + 30% DEFENDING, and the faster one has the edge. The stronger
    # player barely moves, the weaker one gets knocked further.
    def duel(p):
        base = p.duel01() if hasattr(p, "duel01") else 0.45
        k = (0.15 + 1.25 * base) * rating_k(p, RATING_DUEL) \
            * (1.0 + DUEL_SPEED * clamp(p.vel.length() / 2000.0, 0.0, 1.0))
        if abs(vn) > 400.0 and getattr(p, "ps_on", None) and p.ps_ready("bruiser"):
            k *= 1.0 + 3.0 * p.ps_fire("bruiser")                    # BRUISER: wins it by a mile
        return k
    sa, sb = duel(a), duel(b)
    # GUARDIAN: barge into the player carrying the ball and you win it
    if ball is not None and abs(vn) > 250.0:
        for tackler, holder in ((a, b), (b, a)):
            if getattr(ball, "carrier", None) is holder and ball.carrier_t > 0.0 \
                    and (ball.pos - holder.pos).length() < CARRY_DIST \
                    and getattr(tackler, "ps_on", None) and tackler.ps_ready("guardian"):
                L = tackler.ps_fire("guardian")
                holder.throw_timer = max(getattr(holder, "throw_timer", 0.0), PS_STUN * L)   # he's stunned
                pop = tackler.pos - ball.pos
                if pop.length_squared() > 1.0:
                    ball.vel = pop.normalize() * (380.0 + 240.0 * L) + tackler.vel * 0.3 + Vector2(0, -200.0)
                ball.carrier, ball.carrier_t = tackler, CARRY_TIME
                break
    # TANK throws people further, ANCHOR keeps you standing
    ka = (1.0 + _ab(b, "mass")) * clamp(1.0 - _ab(a, "anchor"), 0.4, 1.0)
    kb = (1.0 + _ab(a, "mass")) * clamp(1.0 - _ab(b, "anchor"), 0.4, 1.0)
    a.apply_impulse(c, n * j * (2.0 * sb / (sa + sb)) * ka)
    b.apply_impulse(c, -n * j * (2.0 * sa / (sa + sb)) * kb)
    if abs(vn) > 300.0:                           # ESCAPE: a burst of power after contact
        a.bump_t = b.bump_t = 0.9
    if abs(vn) > 500.0:
        sfx.play("bump", clamp(abs(vn) / 2000.0, 0.2, 0.7))


# ==========================================================
# CPU BRAIN - uses exactly the same throw the human gets
# ==========================================================
class Brain:
    """CPU player. Uses exactly the same throw the human gets."""

    def __init__(self, doll, attack_dir, skill=0.75, opponent=None):
        self.doll = doll
        self.attack_dir = attack_dir          # -1 = attacks the left goal
        self.skill = skill
        self.opponent = opponent
        self.bonus = 0.0                      # set by the game when the CPU is losing
        self.impossible = False               # no hesitation, twice as quick
        self.slow = 1.0                       # > 1: everything around Ren slows down
        self.think_timer = 0.0
        self.was_grounded = True
        # its own dice, so pressing buttons doesn't shift everything else's randomness
        self.ps_rng = random.Random(7391)

    def fire_styles(self, ball):
        """PlayStyles fire by themselves now - nothing for the CPU to press."""
        return

    def update(self, dt, ball):
        doll = self.doll
        # sometimes it lies there a moment after landing, "thinking"
        landed = doll.on_ground and not self.was_grounded
        self.was_grounded = doll.on_ground
        if landed and not self.impossible and random.random() < CPU_THINK_CHANCE:
            self.think_timer = max(self.think_timer, random.uniform(0.4, 0.9))

        self.fire_styles(ball)
        self.think_timer -= dt
        if self.think_timer > 0.0 or not doll.can_throw():
            return
        self.think_timer = CPU_REACTION * random.uniform(0.8, 1.25)   # human-like
        # 28 Oct: a better card reads the game quicker (the CPU's version of a quick thrower)
        self.think_timer *= lerp(CPU_READ[0], CPU_READ[1], min(1.0, card_p(doll)))
        if self.impossible:
            self.think_timer *= 0.45
        self.think_timer *= self.slow
        skill = min(1.0 if self.impossible else 0.98, self.skill + self.bonus)

        horizon = clamp(doll.pos.distance_to(ball.pos) / 1500.0, 0.10, 0.45)
        bt = horizon * BALL_TIME                       # the ball moves in its own, slower time
        pred = Vector2(ball.pos.x + ball.vel.x * bt,
                       ball.pos.y + ball.vel.y * bt + 0.5 * BALL_GRAVITY * bt ** 2)
        pred.y = min(pred.y, GROUND_Y - BALL_RADIUS)
        pred.x = clamp(pred.x, 60, WIDTH - 60)

        goal = Vector2(GOAL_DEPTH * 0.5 if self.attack_dir < 0 else WIDTH - GOAL_DEPTH * 0.5,
                       GROUND_Y - GOAL_HEIGHT * 0.45)
        to_goal = goal - pred
        to_goal = to_goal.normalize() if to_goal.length_squared() > 1.0 else Vector2(self.attack_dir, 0)
        strike = pred - to_goal * (BALL_RADIUS + 40)   # line up behind the ball

        here = doll.pos
        dist = here.distance_to(pred)
        own_goal_x = WIDTH - GOAL_DEPTH if self.attack_dir < 0 else GOAL_DEPTH
        threat = abs(ball.pos.x - own_goal_x) < 480
        err = lerp(150.0, 36.0, skill) * lerp(CPU_AIM[0], CPU_AIM[1], min(1.0, card_p(doll)))
        noise = Vector2(random.uniform(-err, err), random.uniform(-err * 0.6, err * 0.4))

        if not doll.on_ground:
            if dist < 260.0 and random.random() < skill * 0.7:
                self._go(pred + noise * 0.5, 0.95, skill)
            return

        # sometimes body-check the human if they're closer to the ball
        opp = self.opponent
        if (opp is not None and random.random() < CPU_TACKLE_CHANCE
                and opp.pos.distance_to(ball.pos) < dist and here.distance_to(opp.pos) < 450.0):
            self._go(opp.pos + opp.vel * 0.15 + Vector2(0, -60), 0.85, skill)
            return

        if dist < 620.0 or threat:
            # on the wrong side of the ball: a normal hit would send it toward
            # our own goal, so pop it up into the air instead (or hop over it)
            wrong_side = (here.x - ball.pos.x) * self.attack_dir > 0.0
            # 28 Oct: chasing a ball that is rolling back at its own goal, it used to catch it from
            # behind at full speed and ram it in - and the faster the card, the more own goals
            # (10 of Henderson's 15 against Messi). Now it gets GOAL-SIDE: high over the ball and
            # down in front of it.
            toward_own = ball.vel.x * self.attack_dir < -150.0
            if wrong_side and toward_own:
                lead = 260.0 + min(420.0, abs(ball.vel.x) * BALL_TIME * 0.3)
                over = Vector2(pred.x - self.attack_dir * lead, min(pred.y, here.y) - 400.0)
                self._go(over + noise * 0.3, 0.9, skill)
                return
            if wrong_side:
                if pred.y < GROUND_Y - BALL_RADIUS - 60.0:
                    self._go(pred + Vector2(0, BALL_RADIUS + 12) + noise * 0.3, 0.9, skill)
                else:
                    over = Vector2(ball.pos.x - self.attack_dir * 150.0, here.y - 300.0)
                    self._go(over + noise * 0.3, 0.8, skill)
                return
            arc = min(240.0, dist * 0.4)
            self._go(strike + noise + Vector2(0, -arc), clamp(dist / 620.0, 0.45, 1.0), skill)
            return

        guard = clamp(pred.x - self.attack_dir * 340, 220, WIDTH - 220)
        dx = guard - here.x
        if abs(dx) > 120.0:
            self._go(Vector2(here.x + math.copysign(min(abs(dx), 380.0), dx), here.y - 180), 0.5, skill)

    # 28 Oct: the CPU used to throw at a share of ITS OWN max power, so a faster card just flew
    # further past the ball and the card made no difference (Messi v Henderson, CPU v CPU, 49-48).
    # Now it throws as hard as the distance needs, like a person pulling the arrow - and its card
    # only sets how hard it CAN throw. Long throws are where the best cards pull away.
    CPU_REF_POWER = 2500.0

    def _go(self, target, power_scale, skill):
        d = target - self.doll.pos
        if d.length_squared() < 4.0:
            return
        want = lerp(THROW_MIN, self.CPU_REF_POWER, clamp(power_scale, 0.0, 1.0)) * lerp(0.8, 1.0, skill)
        if power_scale >= 0.95:                    # a flat-out sprint or strike: everything it has
            want = max(want, self.doll.max_power() * lerp(0.85, 1.0, skill))
        power = min(want, self.doll.max_power())
        if self.impossible:
            power *= 1.08
        self.doll.throw(d, power)


