def today_number():
    """A whole number that goes up by one at local midnight - the World's Game slot turns on it."""
    try:
        import datetime
        return datetime.date.today().toordinal()
    except Exception:
        return int(time.time() // 86400)


def seconds_to_midnight():
    try:
        t = time.localtime()
        return max(0, 86400 - (t.tm_hour * 3600 + t.tm_min * 60 + t.tm_sec))
    except Exception:
        return 0

# ---- levels / XP
XP_REWARD = {"win": 100, "draw": 50, "loss": 20}
XP_PER_GOAL = 10
