PS_NONE_IN_B = 3               # one pool B card in every this many has no PlayStyle at all


def ps_count(card, pool):
    """How many PlayStyles this card gets: two for pool A, one for most of pool B, none else."""
    if pool == "A":
        return 2
    if pool != "B":
        return 0
    rng = random.Random("nostyle:" + str(card.get("id", card["name"])))
    return 0 if rng.randrange(PS_NONE_IN_B) == 0 else 1


def ps_level(card, index, pool=None):
    """31 Oct, Hubi's rule: a pool A card has one level 2 PlayStyle and one level 1 - except the
    World Cup pack's pool A, which keeps both at level 2. Pool B only ever has level 1."""
    pool = pool or pool_of(card)
    if pool == "A":
        if card.get("pack") == 0:                  # the World Cup pack
            return 2
        return 2 if index == 0 else 1
    return 1


def card_playstyles(card, pool):
    """[(playstyle, level)] for a card - fixed per card, never random between runs."""
    n = ps_count(card, pool)
    if not n:
        return ()
    keys = [k for k in PS_SIGNATURE.get(card.get("id"), ()) if k in PS_BY_KEY][:n]
    groups = PS_POS.get(card["pos"], ("mid", "att"))
    rng = random.Random("ps:" + str(card.get("id", card["name"])))
    i = 0
    while len(keys) < n:
        pool_keys = [k for k in PS_GROUPS[groups[i % len(groups)]] if k not in keys]
        if not pool_keys:
            pool_keys = [k for k in PS_BY_KEY if k not in keys]
        keys.append(pool_keys[rng.randrange(len(pool_keys))])
        i += 1
    return tuple((PS_BY_KEY[k], ps_level(card, j, pool)) for j, k in enumerate(keys))


# ---- traits: the small details, no level, several per card ----------------------
TRAIT_COUNT = {"A": 4, "B": 3, "C": 2}


def card_trait_keys(card, pool="C", extra=0):
    """A card's traits. Hand-picked for the big names, otherwise drawn from its
    position's categories - fixed per card, never random between runs."""
    n = TRAIT_COUNT.get(pool, 2) + extra
    keys = [k for k in ABILITY_SIGNATURE.get(card.get("id"), ()) if k in ABILITY_BY_KEY][:n]
    order = ABILITY_POS.get(card["pos"], ("drb", "att", "def", "drb"))
    rng = random.Random("trait:" + str(card.get("id", card["name"])))
    i = 0
    while len(keys) < n:
        cat = order[i % len(order)] if i < len(order) else "fin"
        bag = [k for k in ABILITY_POOLS.get(cat, ()) if k not in keys]
        if not bag:
            bag = [k for k in ABILITY_BY_KEY if k not in keys]
        if not bag:
            break
        keys.append(bag[rng.randrange(len(bag))])
        i += 1
    return tuple(keys)


def card_traits(card, pool="C", extra=0):
    """The trait dicts for a card, in the order they are shown."""
    return tuple(ABILITY_BY_KEY[k] for k in card_trait_keys(card, pool, extra))


def card_flavour(card):
    """A skill move and a celebration - shown on the card, never touches the physics."""
    rng = random.Random("flavour:" + str(card.get("id", card["name"])))
    moves = [f for f in FLAVOUR_TRAITS if f[2] == "Skill Move"]
    cheers = [f for f in FLAVOUR_TRAITS if f[2] == "Celebration"]
    return (moves[rng.randrange(len(moves))], cheers[rng.randrange(len(cheers))])


def ability_list(card):
    """Kept for the places that still ask for 'a card's abilities': its PlayStyles."""
    return tuple(card.get("ps", ()))


def pool_of(card):
    """A = icons and the big ratings, B = the middle, C = the rest - unless the card's
    pack fixes its pool (Limit Breakers: Hubi's lists, not ratings, decide)."""
    if card.get("fixed_pool"):
        return card["fixed_pool"]
    if card.get("design") in ("icon", "samba") or card["rating"] >= PACK_TIER_A:
        return "A"
    return "B" if card["rating"] >= PACK_TIER_B else "C"


def finish_card(card):
    """Hang the six stats, the PlayStyles, the traits and the flavour on a card.

    Done once when the card tables are read, never per frame. A pool B card that drew no
    PlayStyle gets the trade Hubi asked for instead: every stat up, and an extra trait."""
    pool = pool_of(card)
    card["pool"] = pool
    card["ps"] = card_playstyles(card, pool)
    if card.get("id") in BOX_CARDS:                     # Game Box players: a level 3 and a level 2 (1 Nov)
        card["ps"] = tuple((ps, BOX_PS_LEVELS[j] if j < len(BOX_PS_LEVELS) else lv)
                           for j, (ps, lv) in enumerate(card["ps"]))
    traded = pool == "B" and not card["ps"]
    card["stats"] = card_stats(card, NO_STYLE_BONUS if traded else 0)
    card["traits"] = card_traits(card, pool, extra=1 if traded else 0)
    card["flavour"] = card_flavour(card)
    card["sho"] = card["stats"]["shot"]            # the old two names still work
    card["str"] = card["stats"]["phys"]
    return card


def _ab(doll, key):
    return getattr(doll, "ab", {}).get(key, 0.0)

