def lb_raw(shown):
    """The table number whose overall shows as `shown` (the inverse of ovr())."""
    lo, hi = OVR_RAW
    raw = int(round(lo + (shown - OVR_FLOOR) * (hi - lo) / float(OVR_CEIL - OVR_FLOOR)))
    for r in (raw, raw - 1, raw + 1):
        if ovr(r) == shown:
            return r
    return raw

