def card_stats(card, bonus=0):
    """The six stats for a card. Same card, same numbers, every time."""
    lo, hi = STAT_BASE
    k = clamp((card["rating"] - OVR_FLOOR) / float(OVR_CEIL - OVR_FLOOR), 0.0, 1.2)
    base = lo + (hi - lo) * k
    offs = STAT_POS.get(card["pos"], STAT_DEFAULT)
    rng = random.Random("stats:" + str(card.get("id", card["name"])))
    out = {}
    for key, off in zip(STAT_KEYS, offs):
        # a little per-card character, so two strikers on the same overall aren't twins
        wobble = rng.randrange(-6, 7)
        out[key] = int(clamp(round(base + off + wobble + bonus), STAT_FLOOR, STAT_CEIL))
    return out


def star_stats(pos, ovr):
    """(shooting, strength) for a Star Signing from his position."""
    if pos == "GK":
        return ovr - 55, ovr + 4
    if pos in ("CB", "LB", "RB"):
        return ovr - 26, ovr + 4
    if pos == "CDM":
        return ovr - 10, ovr + 2
    if pos in ("CM", "CAM"):
        return ovr - 1, ovr - 8
    return min(155, ovr + 3), ovr - 14


def sign_cap(rating):
    """The most a card of this OVR can cost in Star Signings (SIGN_CAP), or None above / below the band."""
    if not SIGN_CAP[0][0] <= rating <= SIGN_CAP[-1][0]:
        return None
    for (r0, v0), (r1, v1) in zip(SIGN_CAP, SIGN_CAP[1:]):
        if rating <= r1:
            return int(round(v0 * (v1 / float(v0)) ** ((rating - r0) / float(r1 - r0)) / 100.0)) * 100


def star_points_for(rating):
    """Star Points for one copy of a card with this OVR."""
    pts = SP_CURVE
    if rating <= pts[0][0]:
        return pts[0][1]
    for (r0, v0), (r1, v1) in zip(pts, pts[1:]):
        if rating <= r1:
            v = v0 + (v1 - v0) * (rating - r0) / float(r1 - r0)
            return int(round(v / 10.0)) * 10
    return pts[-1][1]

