class NetLink:
    """Talks to the page through window.aswc* hooks."""

    def __init__(self):
        self.on = False
        self.w = js_window()
        if self.w is not None:
            try:
                self.w.aswcNetPoll                     # does the page provide the hooks?
                self.on = True
            except Exception:
                self.on = False

    def poll(self):
        if not self.on:
            return []
        try:
            raw = self.w.aswcNetPoll()
            return json.loads(raw) if raw else []
        except Exception:
            return []

    def send(self, msg):
        if not self.on:
            return
        try:
            self.w.aswcNetSend(json.dumps(msg))
        except Exception:
            pass

    def chat(self, text):
        if not self.on:
            return
        try:
            self.w.aswcChatSend(text)
        except Exception:
            pass

    def result(self, home, away):
        if not self.on:
            return
        try:
            self.w.aswcMatchResult(json.dumps({"home": home, "away": away}))
        except Exception:
            pass

    def connected_hint(self):
        """False only when the page says the peer connection has dropped."""
        if not self.on:
            return True
        try:
            return bool(self.w.aswcNetUp())
        except Exception:
            return True


def read_save_text():
    if WEB_BUILD:
        w = js_window()
        try:
            return w.localStorage.getItem(SAVE_KEY)
        except Exception:
            return None
    try:
        with open(SAVE_PATH, "r", encoding="utf-8") as fh:
            return fh.read()
    except Exception:
        return None


def write_save_text(text):
    if WEB_BUILD:
        w = js_window()
        try:
            w.localStorage.setItem(SAVE_KEY, text)
        except Exception:
            pass
        try:
            w.aswcSave(text)               # the page pushes it to the player's cloud save
        except Exception:
            pass                           # signed out / offline: localStorage still has it
        return
    tmp = SAVE_PATH + ".tmp"
    with open(tmp, "w", encoding="utf-8") as fh:
        fh.write(text)
    os.replace(tmp, SAVE_PATH)
