    def draw_twist_hud(self, surface):
        key = getattr(self, "match_twist", "normal")
        if not ((self.mode == "club" and LADDER) or self.mode == "gauntlet") or key == "normal":
            return
        if key == "rain":
            rain = self.__dict__.get("_rain")
            if rain is None:
                rain = pygame.Surface((WIDTH, HEIGHT * 2), pygame.SRCALPHA)
                rnd = random.Random(5)
                for _ in range(520):
                    x, y = rnd.uniform(0, WIDTH), rnd.uniform(0, HEIGHT * 2)
                    pygame.draw.line(rain, (190, 210, 255, rnd.randint(40, 90)), (x, y), (x - 9, y + 30), 3)
                self._rain = rain
            off = int(pygame.time.get_ticks() * 0.9) % HEIGHT
            surface.blit(rain, (0, off - HEIGHT))
        r = pygame.Rect(WIDTH // 2 - 170, 118, 340, 50)
        veil = pygame.Surface(r.size, pygame.SRCALPHA)
        pygame.draw.rect(veil, (8, 12, 30, 190), veil.get_rect(), border_radius=25)
        surface.blit(veil, r.topleft)
        pygame.draw.rect(surface, TWIST_COL.get(key, WHITE), r, 3, border_radius=25)
        self.draw_twist_icon(surface, key, (r.x + 34, r.centery), 14)
        name = TWIST_NAME[key]
        if key == "wind":
            name += "  >>" if TWIST.get("wind", 0) > 0 else "  <<"
        self.home_text(surface, name, (r.x + 64, r.centery), 24, WHITE, shadow=False, max_w=r.w - 80)

    # ==================================================================================
    # THE GAUNTLET (30 Oct). Hubi: "play against harder teams then harder until you're playing
    # statistically the best team in any situation with a hard cpu" - its own tab in PLAY.
    # Ten opponents in a row, one loss ends the run. Rungs 1-3 are about skill (weak to middling
    # teams, a MEDIUM brain), 4-6 add a matchday twist and a HARD brain, 7-9 add pressure (the
    # top clubs, boosts, starting 1-0 down), and rung 10 is THE MACHINE: the three cards that win
    # most under its twist, measured in CPU v CPU play (testing/machine_sim.py -> MACHINE), with
    # the Impossible brain. Every card in your five plays exactly 4 halves (25% a half) - 20 halves,
    # 10 matches - so the only choice is the ORDER: spend your best early, or save them for it.
    # All ten opponents are drawn when the run starts, so you can plan the whole climb.
    # ==================================================================================
    def gt(self):
        G = self.save.get("gauntlet")
        if not isinstance(G, dict):
            G = {"run": None, "best": 0, "runs": 0, "wins": 0, "last": None}
            self.save["gauntlet"] = G
        return G

    def gt_run(self):
        run = self.gt().get("run")
        return run if isinstance(run, dict) and run.get("opps") else None

    def gt_rung(self):
        run = self.gt_run()
        return min(GT_LEN - 1, run["rung"]) if run else 0

    def gt_teams(self):
        """[(strength, (kind, code))] for every club and nation: the average of its best three."""
        hit = self.__dict__.get("_gt_teams")
        if hit is not None:
            return hit
        groups = {}
        for c in self.cards.values():
            if c["kind"] in ("club", "wc"):
                groups.setdefault((c["kind"], c["team"]), []).append(c["rating"])
        out = []
        for spec, rs in groups.items():
            rs.sort(reverse=True)
            out.append((sum(rs[:3]) / float(min(3, len(rs))), spec))
        out.sort(key=lambda x: -x[0])
        self._gt_teams = out
        return out

    def gt_machine_ids(self, twist):
        """THE MACHINE's three for this twist: measured, or (no measurements) the top three by rating."""
        ids = [i for i in (MACHINE.get(twist) or {}).get("ids", ()) if i in self.cards]
        if len(ids) < 3:
            best = sorted((c for c in self.cards.values() if c["kind"] != "rookie"), key=lambda c: -c["rating"])
            ids += [c["id"] for c in best if c["id"] not in ids][:3 - len(ids)]
        return ids[:3]

    def gt_machine_stat(self, twist, cid):
        """(score, shot px/s, reach px, throws a second) for one of THE MACHINE's three, or None."""
        M = MACHINE.get(twist) or {}
        ids = list(M.get("ids", ()))
        if cid not in ids:
            return None
        i = ids.index(cid)
        try:
            return M["score"][i], M["shot"][i], M["reach"][i], M["rate"][i]
        except (KeyError, IndexError):
            return None

    def gt_new_run(self):
        squad = [k for k in self.save.get("squad", ()) if k in self.cards]
        if len(squad) < SQUAD_SIZE:
            self.toast("PICK %d PLAYERS IN TEAM FIRST" % SQUAD_SIZE, (255, 150, 150), 2.0)
            return False
        teams = self.gt_teams()
        used, opps = set(), [None] * GT_LEN
        for k in range(GT_LEN - 2, -1, -1):                 # top first: the last rungs need the big clubs
            lo, hi = GT_RUNGS[k][1]
            cands = [s for st, s in teams if lo <= st <= hi and s not in used]
            if not cands:
                mid = (lo + hi) / 2.0
                free = sorted((abs(st - mid), s) for st, s in teams if s not in used)
                cands = [free[0][1]] if free else [teams[0][1]]
            pick = random.choice(cands)
            used.add(pick)
            opps[k] = list(pick)
        opps[-1] = ["machine", ""]
        twists = []
        for k, row in enumerate(GT_RUNGS):
            if k == GT_LEN - 1:
                twists.append(random.choice(("normal",) + GT_PLAYABLE_TWISTS))
            else:
                twists.append(random.choice(GT_PLAYABLE_TWISTS) if row[3] else "normal")
        G = self.gt()
        G["run"] = {"squad": squad[:SQUAD_SIZE], "stam": {k: 100 for k in squad[:SQUAD_SIZE]}, "rung": 0,
                    "opps": opps, "twists": twists, "results": []}
        G["runs"] = int(G.get("runs", 0)) + 1
        self.gt_modal = None
        self.write_save()
        return True

    # ---- who's on each rung -------------------------------------------------------------
    def gt_spec(self, k):
        run = self.gt_run()
        return tuple(run["opps"][k]) if run else None

    def gt_twist(self, k):
        run = self.gt_run()
        return run["twists"][k] if run else "normal"

    def gt_team_cards(self, k):
        spec = self.gt_spec(k)
        if spec is None:
            return []
        if spec[0] == "machine":
            return [self.cards[i] for i in self.gt_machine_ids(self.gt_twist(k))]
        return sorted((c for c in self.cards.values() if c["kind"] == spec[0] and c["team"] == spec[1]),
                      key=lambda c: -c["rating"])

    def gt_team_name(self, k):
        spec = self.gt_spec(k)
        if spec is None:
            return "?"
        if spec[0] == "machine":
            return "THE MACHINE"
        if spec[0] == "club":
            for c in self.clubs:
                if c["code"] == spec[1]:
                    return c["name"].upper()
        return NATION_NAMES.get(spec[1], spec[1]).upper()

    def gt_team_badge(self, k):
        spec = self.gt_spec(k)
        if spec is None:
            return None
        if spec[0] == "machine":
            return self.gt_machine_badge(120)
        if spec[0] == "club":
            for c in self.clubs:
                if c["code"] == spec[1]:
                    return c["badge"]
            return None
        for t in self.teams:
            if t["name"] == spec[1]:
                return t["flag"]
        return None

    def gt_strength(self, k):
        spec = self.gt_spec(k)
        if spec is None:
            return 0
        if spec[0] == "machine":
            cs = self.gt_team_cards(k)
            return int(round(sum(c["rating"] for c in cs) / float(max(1, len(cs)))))
        for st, s in self.gt_teams():
            if tuple(s) == spec:
                return int(round(st))
        return 0

    def gt_machine_badge(self, size):
        cache = self.__dict__.setdefault("_gt_badge", {})
        if size in cache:
            return cache[size]
        s = pygame.Surface((size, size), pygame.SRCALPHA)
        c = size // 2
        hexa = [(c + int(math.cos(math.pi / 6 + k * math.pi / 3) * size * 0.47),
                 c + int(math.sin(math.pi / 6 + k * math.pi / 3) * size * 0.47)) for k in range(6)]
        pygame.draw.polygon(s, (22, 14, 18), hexa)
        pygame.draw.polygon(s, (230, 40, 50), hexa, max(3, size // 20))
        inner = [(c + int((x - c) * 0.74), c + int((y - c) * 0.74)) for x, y in hexa]
        pygame.draw.polygon(s, (90, 16, 22), inner, max(3, size // 30))
        pygame.draw.ellipse(s, (255, 70, 60), (c - size * 0.26, c - size * 0.10, size * 0.52, size * 0.20))
        pygame.draw.circle(s, (255, 230, 200), (c, c), max(3, size // 14))
        pygame.draw.circle(s, (40, 6, 8), (c, c), max(2, size // 26))
        cache[size] = s
        return s

    # ---- the run, as the match code sees it -----------------------------------------------
    def gt_cpu_level(self):
        """How clever the CPU's half-time sub is: 1 = for the score, 2 = counters you, 3 = Impossible."""
        k = self.gt_rung()
        return 1 if k < 3 else (IMPOSSIBLE if k == GT_LEN - 1 else 2)

    def gt_stam(self):
        run = self.gt_run()
        return run["stam"] if run else {}

    def gt_halves_left(self, cid, stam=None):
        """Halves this card can still play in the run (RELENTLESS cards get more out of their 100%)."""
        cost = self.half_cost(self.cards[cid], GT_HALF) if cid in self.cards else GT_HALF
        s = self.gt_stam().get(cid, 0) if stam is None else stam
        return int(math.ceil(s / float(cost) - 1e-6)) if s > 0 else 0

    def gt_pick_cpu(self):
        pool = self.gt_team_cards(self.gt_rung())
        if not pool:
            return None
        k = self.gt_rung()
        if k == GT_LEN - 1:
            return pool[0]                                   # the measured best goes first
        if k >= 3:
            return max(pool, key=lambda c: c["rating"])
        return random.choice(pool)

    def enter_gauntlet(self):
        self.mode = "gauntlet"
        self.drop_impossible()
        self.clear_twist()
        self.state = GAUNTLET
        self.paused = False
        self.dragging = False
        self.slowmo = 1.0
        self.shake = 0.0
        self.gt_reveal = None
        self.gt_hover = None
        if not hasattr(self, "gt_modal"):
            self.gt_modal = None

    def gt_start_match(self):
        run = self.gt_run()
        if run is None:
            return
        k = run["rung"]
        row = GT_RUNGS[k]
        self.match_twist = run["twists"][k]
        self.brain.skill = row[2]
        self.brain.impossible = k == GT_LEN - 1
        self.played_this_match = set()
        self.my_card = None
        if k == GT_LEN - 1 and getattr(self, "gt_reveal", None) is None:
            self.gt_reveal = pygame.time.get_ticks() * 0.001   # THE MACHINE gets an entrance first
            self.sfx.play("shock", 1.0)
            return
        self.gt_reveal = None
        self.go_lineup(1)

    def gt_boost(self):
        return GT_RUNGS[self.gt_rung()][4]

    def gt_kickoff_extra(self):
        """After new_match: rungs 7, 9 and THE MACHINE start 1-0 down."""
        if GT_RUNGS[self.gt_rung()][5]:
            self.score_away = 1
            self.match_low = -1
            self.first_goal = "away"

    def gt_pay(self, result, goals):
        k = self.gt_rung()
        return (GT_RUNGS[k][6] if result == "win" else REWARD["loss"]) + REWARD_PER_GOAL * goals

    def gt_finish(self, my_goals, their_goals):
        G = self.gt()
        run = self.gt_run()
        self.clear_twist()
        self.drop_impossible()
        self.slowmo = 1.0
        if run is None:
            self.enter_gauntlet()
            return
        k = run["rung"]
        name = self.gt_team_name(k)
        run["results"].append([my_goals, their_goals])
        if my_goals > their_goals:
            run["rung"] = k + 1
            G["best"] = max(int(G.get("best", 0)), k + 1)
            if k + 1 >= GT_LEN:                              # THE MACHINE is beaten
                G["wins"] = int(G.get("wins", 0)) + 1
                self.add_trophy("gauntlet")
                self.archive_event("machine")                # the Signature Archive (1 Nov)
                self.award_xp(XP_TROPHY)
                card = self.lg_reward_card("A")
                self.send_mail("YOU BEAT THE MACHINE",
                               "Ten in a row, and the last one was the best team the numbers could find. "
                               "Here's %d coins%s." % (GT_WIN_COINS, " and a pool A card" if card else ""),
                               {"coins": GT_WIN_COINS, "cards": [card["id"]] if card else []})
                self.mail_list()[0]["from"] = "THE GAUNTLET"
                G["last"] = {"rung": GT_LEN, "won": True}
                G["run"] = None
                self.gt_modal = {"kind": "won", "score": [my_goals, their_goals], "name": name}
            else:
                self.gt_modal = {"kind": "cleared", "rung": k, "score": [my_goals, their_goals], "name": name,
                                 "coins": getattr(self, "last_earned", 0)}
        else:
            G["last"] = {"rung": k, "won": False, "name": name, "score": [my_goals, their_goals]}
            G["run"] = None
            self.gt_modal = {"kind": "lost", "rung": k, "score": [my_goals, their_goals], "name": name,
                             "best": int(G.get("best", 0))}
        self.write_save()
        self.enter_gauntlet()

    # ---- clicks --------------------------------------------------------------------------
    def gt_layout(self):
        stairs = pygame.Rect(40, 132, WIDTH - 80, 508)
        steps = []
        base = stairs.bottom - 22
        for k in range(GT_LEN):
            h = 360 if k == GT_LEN - 1 else 92 + k * 26
            steps.append(pygame.Rect(70 + k * 178, base - h, 166, h))
        scout = pygame.Rect(40, 660, 1000, 390)
        squad = pygame.Rect(1060, 660, 820, 390)
        play = pygame.Rect(scout.right - 30 - 380, scout.bottom - 30 - 104, 380, 104)
        cards = [pygame.Rect(squad.x + 30 + i * 158, squad.y + 78, 136, 185) for i in range(SQUAD_SIZE)]
        quit_ = pygame.Rect(squad.right - 30 - 200, squad.y + 20, 200, 44)
        return {"stairs": stairs, "steps": steps, "scout": scout, "squad": squad, "play": play,
                "cards": cards, "quit": quit_}

    def gt_click(self, pos):
        p = (pos.x, pos.y) if hasattr(pos, "x") else tuple(pos)
        if getattr(self, "gt_reveal", None) is not None:
            if pygame.time.get_ticks() * 0.001 - self.gt_reveal < 3.4:
                self.gt_reveal = pygame.time.get_ticks() * 0.001 - 3.4   # skip to the end of the entrance
            else:
                self.gt_reveal = None
                self.played_this_match = set()
                self.my_card = None
                self.go_lineup(1)
            return
        if getattr(self, "gt_modal", None) is not None:
            self.gt_modal = None
            return
        L = self.gt_layout()
        run = self.gt_run()
        if L["play"].collidepoint(p):
            if run is None:
                if not self.gt_new_run():
                    return
                self.toast("THE GAUNTLET:  10 TO GO", (255, 120, 110), 2.0)
                return
            self.gt_start_match()
            return
        if run is not None and L["quit"].collidepoint(p):
            if getattr(self, "gt_quit_armed", False):
                G = self.gt()
                G["last"] = {"rung": run["rung"], "won": False, "name": "GAVE UP", "score": None}
                G["run"] = None
                self.gt_quit_armed = False
                self.write_save()
                self.toast("RUN ABANDONED", WHITE, 2.0)
            else:
                self.gt_quit_armed = True
            return
        self.gt_quit_armed = False
        for card, r in zip(self.gt_squad_cards(), L["cards"]):
            if r.collidepoint(p):
                self.card_click(card, lambda: None)
                return

    def gt_squad_cards(self):
        run = self.gt_run()
        ids = run["squad"] if run else [k for k in self.save.get("squad", ()) if k in self.cards]
        return [self.cards[k] for k in ids if k in self.cards]

    # ---- drawing -------------------------------------------------------------------------
    GT_RED = (255, 90, 80)
    GT_HOT = (255, 206, 90)

    def gt_brain_name(self, k):
        return GT_BRAIN.get(GT_RUNGS[k][2], "HARD")

    def draw_gauntlet(self, w):
        if getattr(self, "gt_reveal", None) is not None:
            self.draw_gt_reveal(w)
            return
        L = self.gt_layout()
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        run = self.gt_run()
        G = self.gt()
        w.blit(tinted(self.home_bg(), (60, 0, 10, 60), "gauntlet"), (0, 0))   # was a new full-screen surface every frame
        self.draw_glass(w, pygame.Rect(24, 20, WIDTH - 48, 92), radius=24, alpha=120)
        self.draw_glass_back(w, mouse)
        title = self.home_gold("THE GAUNTLET", 52)
        w.blit(title, title.get_rect(midleft=(272, 66)))
        sub = ("RUNG %d OF %d" % (run["rung"] + 1, GT_LEN)) if run else "TEN IN A ROW. ONE LOSS AND IT'S OVER."
        self.home_text(w, sub, (title.get_width() + 300, 68), 28, (255, 190, 180) if run else self.HOME_MUTED,
                       shadow=False, max_w=760)
        self.draw_status(w, mouse)
        # ---- the stairs
        st = L["stairs"]
        self.draw_glass(w, st, radius=30, alpha=130, edge=(255, 110, 100))
        hover = None
        for k, r in enumerate(L["steps"]):
            if r.collidepoint(mouse) or pygame.Rect(r.x, r.y - 110, r.w, 110).collidepoint(mouse):
                hover = k
        cur = run["rung"] if run else -1
        for k, r in enumerate(L["steps"]):
            machine = k == GT_LEN - 1
            done = run is not None and k < cur
            now = k == cur
            # the step itself: a block that gets darker and redder as it climbs
            lift = k / float(GT_LEN - 1)
            top_col = (int(70 + 120 * lift), int(80 - 60 * lift), int(150 - 120 * lift)) if not machine else (150, 20, 30)
            body = (int(top_col[0] * 0.45), int(top_col[1] * 0.45), int(top_col[2] * 0.45))
            if now:
                g = self.home_glow((r.w + 160, r.h + 260), (255, 120, 80) if machine else (255, 200, 80),
                                   int(90 + 60 * (0.5 + 0.5 * math.sin(t * 3))))
                w.blit(g, g.get_rect(center=(r.centerx, r.y + 10)))
            pygame.draw.rect(w, body, r, border_top_left_radius=12, border_top_right_radius=12)
            pygame.draw.rect(w, top_col, (r.x, r.y, r.w, 16), border_top_left_radius=12, border_top_right_radius=12)
            edge = self.GT_HOT if now else ((90, 220, 130) if done else (hover == k and WHITE or _shade(top_col, 1.3)))
            pygame.draw.rect(w, edge, r, 4 if (now or hover == k) else 3, border_top_left_radius=12,
                             border_top_right_radius=12)
            # what sits on top: their badge (or a ? before a run)
            cx, by = r.centerx, r.y - 56
            if run is not None:
                badge = self.gt_team_badge(k)
                if badge is not None:
                    bi = fit_flag(badge, 84 if machine else 70, 84 if machine else 78)
                    w.blit(bi, bi.get_rect(center=(cx, by - (6 if machine else 0))))
                if done:                                     # the score, in a green chip by the badge
                    a, b = run["results"][k][:2]
                    chip = pygame.Rect(0, 0, 62, 34)
                    chip.center = (r.right - 26, r.y - 96)
                    pygame.draw.rect(w, (30, 140, 76), chip, border_radius=17)
                    pygame.draw.rect(w, (170, 255, 190), chip, 3, border_radius=17)
                    self.home_text(w, "%d-%d" % (a, b), chip.center, 22, WHITE, anchor="center", shadow=False)
            else:
                if machine:
                    bi = self.gt_machine_badge(84)
                    w.blit(bi, bi.get_rect(center=(cx, by - 6)))
                else:
                    pygame.draw.circle(w, (20, 18, 40), (cx, by), 32)
                    pygame.draw.circle(w, (110, 100, 150), (cx, by), 32, 3)
                    self.home_text(w, "?", (cx, by), 34, (170, 160, 200), anchor="center", shadow=False)
            # inside the step: its number, then the twist / the 1-0 / the score
            label = "10" if machine else str(k + 1)
            self.home_text(w, label, (cx, r.y + 44), 40 if not machine else 44, WHITE if (now or done) else (220, 214, 236),
                           anchor="center", shadow=True)
            y = r.y + 92
            tw = self.gt_twist(k) if run else ("?" if GT_RUNGS[k][3] else "normal")
            if r.bottom - y > 40 and tw not in ("normal", "?"):
                self.draw_twist_icon(w, tw, (cx, y + 8), 20)
                y += 52
            elif r.bottom - y > 40 and tw == "?":
                self.home_text(w, "TWIST", (cx, y + 2), 20, (200, 190, 230), anchor="center", shadow=False)
                y += 40
            if GT_RUNGS[k][5] and r.bottom - y > 34:
                self.home_text(w, "0-1", (cx, y + 4), 24, (255, 130, 120), anchor="center", shadow=False)
                y += 38
            if GT_RUNGS[k][4] and r.bottom - y > 34:
                self.home_text(w, "+%d" % GT_RUNGS[k][4][0], (cx, y + 4), 24, (255, 206, 120), anchor="center",
                               shadow=False)
                y += 38
            if machine and r.bottom - y > 60:
                self.home_text(w, "THE", (cx, r.bottom - 74), 24, (255, 170, 160), anchor="center", shadow=False)
                self.home_text(w, "MACHINE", (cx, r.bottom - 44), 26, (255, 120, 110), anchor="center", shadow=False,
                               max_w=r.w - 16)
        self.gt_hover = hover
        # ---- the scouting report: the hovered rung, or the next one
        self.draw_gt_scout(w, L, mouse, t, run, hover)
        # ---- your five
        self.draw_gt_squad(w, L, mouse, run, G)
        if getattr(self, "gt_modal", None) is not None:
            self.draw_gt_modal(w, t)

    def draw_gt_scout(self, w, L, mouse, t, run, hover):
        sc = L["scout"]
        self.draw_glass(w, sc, radius=30, alpha=160, hot=True)
        play = L["play"]
        if run is None:
            G = self.gt()
            self.home_text(w, "HOW IT WORKS", (sc.x + 34, sc.y + 40), 24, self.HOME_MUTED, shadow=False)
            lines = ("10 OPPONENTS IN A ROW. LOSE ONCE AND THE RUN IS OVER.",
                     "EACH OF YOUR 5 HAS 4 HALVES FOR THE WHOLE RUN - THE ORDER IS THE GAME.",
                     "IT GETS HARDER: BETTER TEAMS, A HARDER CPU, TWISTS, BOOSTS, 1-0 DOWN.",
                     "NUMBER 10 IS THE MACHINE: THE BEST TEAM THE NUMBERS CAN FIND.")
            for i, line in enumerate(lines):
                self.home_text(w, line, (sc.x + 34, sc.y + 92 + i * 46), 25, WHITE, shadow=False, max_w=sc.w - 68)
            last = G.get("last")
            if last:
                txt = ("LAST RUN: BEAT THE MACHINE" if last.get("won") else
                       "LAST RUN: OUT AT RUNG %d" % (int(last.get("rung", 0)) + 1))
                self.home_text(w, txt, (sc.x + 34, sc.bottom - 82), 24, (255, 190, 180), shadow=False, max_w=480)
            self.home_text(w, "PAYS UP TO %s COINS + A POOL A CARD" % self.fmt(sum(r[6] for r in GT_RUNGS) + GT_WIN_COINS),
                           (sc.x + 34, sc.bottom - 44), 22, (255, 226, 150), shadow=False, max_w=520)
            can = len([k for k in self.save.get("squad", ()) if k in self.cards]) >= SQUAD_SIZE
            self.draw_gt_button(w, play, "START RUN" if can else "NEED 5 IN TEAM", mouse, can)
            return
        k = hover if hover is not None else run["rung"]
        machine = k == GT_LEN - 1
        row = GT_RUNGS[k]
        tag = "NEXT" if k == run["rung"] else ("CLEARED" if k < run["rung"] else "LATER")
        tag_col = self.GT_HOT if tag == "NEXT" else ((120, 240, 160) if tag == "CLEARED" else self.HOME_MUTED)
        self.home_text(w, "RUNG %d  -  %s" % (k + 1, tag), (sc.x + 34, sc.y + 40), 24, tag_col, shadow=False)
        badge = self.gt_team_badge(k)
        if badge is not None:
            bi = fit_flag(badge, 92, 100)
            w.blit(bi, bi.get_rect(center=(sc.x + 84, sc.y + 120)))
        self.home_text(w, self.gt_team_name(k), (sc.x + 146, sc.y + 104), 40,
                       (255, 120, 110) if machine else WHITE, max_w=430)
        self.home_text(w, "STRENGTH %d   -   CPU %s" % (self.gt_strength(k), self.gt_brain_name(k)),
                       (sc.x + 146, sc.y + 146), 22, self.HOME_MUTED, shadow=False, max_w=430)
        # the conditions, one per line
        y = sc.y + 200
        tw = self.gt_twist(k)
        self.draw_twist_icon(w, tw, (sc.x + 60, y), 18)
        nr = self.home_text(w, TWIST_NAME.get(tw, "NORMAL MATCH"), (sc.x + 100, y - 2), 26, TWIST_COL.get(tw, WHITE),
                            shadow=False, max_w=220)
        self.home_text(w, TWIST_LINE.get(tw, ""), (nr.right + 18, y), 22, self.HOME_MUTED, shadow=False,
                       max_w=sc.x + 590 - nr.right)
        y += 46
        if row[4]:
            self.home_text(w, "BOOSTED:  +%d OVR,  +%d SHOOTING / STRENGTH" % row[4], (sc.x + 34, y), 22,
                           (255, 206, 120), shadow=False, max_w=560)
            y += 36
        if row[5]:
            self.home_text(w, "YOU START 1-0 DOWN", (sc.x + 34, y), 22, (255, 130, 120), shadow=False)
            y += 36
        if machine:
            self.home_text(w, "THE 3 CARDS WHOSE STATS DO MOST IN %s" % TWIST_NAME.get(tw, "A NORMAL MATCH"),
                           (sc.x + 34, y), 22, (255, 170, 160), shadow=False, max_w=play.x - sc.x - 50)
            y += 36
        self.home_text(w, "WIN:  +%d COINS" % (row[6] + (GT_WIN_COINS if machine else 0)), (sc.x + 34, sc.bottom - 44),
                       24, (255, 226, 150), shadow=False)
        # their cards, on the right
        cards = self.gt_team_cards(k)[:3]
        for i, c in enumerate(cards):
            r = pygame.Rect(sc.right - 30 - (3 - i) * 128, sc.y + 26, 118, 160)
            boosted = dict(c, rating=c["rating"] + row[4][0]) if row[4] else c
            self.blit_card(w, boosted, r)
            if machine:
                ms = self.gt_machine_stat(tw, c["id"])
                if ms is not None:
                    self.home_text(w, "#%d  %+.2f" % (i + 1, ms[0]), (r.centerx, r.bottom + 20), 22, (255, 150, 140),
                                   anchor="center", shadow=False)
        if k == run["rung"]:
            self.draw_gt_button(w, play, "FACE IT" if machine else "PLAY RUNG %d" % (k + 1), mouse, True,
                                red=machine)
        else:
            self.home_text(w, "SCOUTING RUNG %d" % (k + 1), (play.centerx, play.centery - 14), 26, self.HOME_MUTED,
                           anchor="center", shadow=False)
            self.home_text(w, "MOVE OFF THE STAIRS TO PLAY RUNG %d" % (run["rung"] + 1), (play.centerx, play.centery + 22),
                           20, self.HOME_MUTED, anchor="center", shadow=False)

    def draw_gt_button(self, w, r, text, mouse, can, red=False):
        hov = can and r.collidepoint(mouse)
        if can:
            btn = (self.home_button(r.size, hov, top=(240, 80, 70), bottom=(160, 20, 30), lip=(70, 6, 12)) if red
                   else self.home_button(r.size, hov))
            w.blit(btn, (r.x, r.y - (3 if hov else 0)))
        else:
            pygame.draw.rect(w, (50, 54, 70), r, border_radius=22)
            pygame.draw.rect(w, (110, 116, 140), r, 3, border_radius=22)
        self.home_text(w, text, (r.centerx, r.centery - (3 if hov else 0)), 44, WHITE if can else (170, 176, 196),
                       anchor="center", max_w=r.w - 50)

    def draw_gt_squad(self, w, L, mouse, run, G):
        sq = L["squad"]
        self.draw_glass(w, sq, radius=30, alpha=150)
        self.home_text(w, "YOUR FIVE" if run else "YOUR FIVE  (FROM TEAM)", (sq.x + 30, sq.y + 42), 24,
                       self.HOME_MUTED, shadow=False)
        cards = self.gt_squad_cards()
        stam = self.gt_stam()
        for card, r in zip(cards, L["cards"]):
            full = self.gt_halves_left(card["id"], 100)
            left = self.gt_halves_left(card["id"]) if run else full
            self.blit_card(w, card, r, dim=run is not None and left <= 0, glow=r.collidepoint(mouse))
            step = min(31, (r.w - 16) // max(1, full - 1))
            rad = min(11, step // 2 - 1)
            for h in range(full):                             # one pip per half he has left
                c = (r.centerx - step * (full - 1) // 2 + h * step, r.bottom + 26)
                on = h < left
                pygame.draw.circle(w, (255, 206, 90) if on else (40, 46, 74), c, rad)
                pygame.draw.circle(w, (120, 80, 14) if on else (80, 90, 130), c, rad, 3)
        if run is not None:
            left = sum(self.gt_halves_left(c["id"]) for c in cards)
            need = (GT_LEN - run["rung"]) * 2
            col = (150, 255, 180) if left >= need else (255, 130, 120)
            self.home_text(w, "HALVES LEFT %d  -  NEEDED %d" % (left, need), (sq.x + 30, sq.bottom - 52), 26, col,
                           shadow=False)
            q = L["quit"]
            armed = getattr(self, "gt_quit_armed", False)
            hov = q.collidepoint(mouse)
            self.draw_glass(w, q, radius=22, alpha=170, edge=(255, 120, 110) if (hov or armed) else (130, 140, 190))
            self.home_text(w, "SURE? CLICK AGAIN" if armed else "ABANDON RUN", q.center, 22,
                           (255, 150, 140) if (hov or armed) else (200, 206, 236), anchor="center", shadow=False,
                           max_w=q.w - 20)
        else:
            best = int(G.get("best", 0))
            self.home_text(w, "BEST:  %s     RUNS:  %d     MACHINE BEATEN:  %d" % (
                "%d / 10" % best if best < GT_LEN else "ALL 10", int(G.get("runs", 0)), int(G.get("wins", 0))),
                (sq.x + 30, sq.bottom - 52), 24, (255, 226, 150), shadow=False, max_w=sq.w - 60)

    def draw_gt_modal(self, w, t):
        m = self.gt_modal
        wash(w, (6, 4, 10, 170))
        box = pygame.Rect(WIDTH // 2 - 440, 210, 880, 600)
        won = m["kind"] == "won"
        lost = m["kind"] == "lost"
        edge = (255, 206, 90) if won else ((255, 110, 100) if lost else (120, 240, 160))
        g = self.home_glow((1100, 760), edge, 70)
        w.blit(g, g.get_rect(center=box.center))
        self.draw_glass(w, box, radius=34, alpha=200, edge=edge, hot=True)
        cx = box.centerx
        a, b = m["score"]
        if won:
            art = self.trophy_art("gauntlet")
            art = pygame.transform.scale(art, (int(art.get_width() * 1.3), int(art.get_height() * 1.3)))
            g2 = self.home_glow((420, 360), (255, 80, 60), int(90 + 50 * math.sin(t * 2.5)))
            w.blit(g2, g2.get_rect(center=(cx, box.y + 160)))
            w.blit(art, art.get_rect(midbottom=(cx, box.y + 270)))
            title = self.home_gold("YOU BEAT THE MACHINE", 60)
            w.blit(title, title.get_rect(center=(cx, box.y + 322)))
            self.home_text(w, "%d - %d" % (a, b), (cx, box.y + 392), 44, WHITE, anchor="center")
            self.home_text(w, "+%d COINS AND A POOL A CARD - IN YOUR MAIL" % GT_WIN_COINS, (cx, box.y + 454), 26,
                           (255, 226, 150), anchor="center", shadow=False, max_w=box.w - 80)
            self.home_text(w, "THE GAUNTLET TROPHY IS IN YOUR CABINET", (cx, box.y + 498), 22, self.HOME_MUTED,
                           anchor="center", shadow=False)
        elif lost:
            self.home_text(w, "RUN OVER", (cx, box.y + 100), 76, (255, 110, 100), anchor="center")
            self.home_text(w, "OUT AT RUNG %d:  %d - %d  V  %s" % (m["rung"] + 1, a, b, m["name"]), (cx, box.y + 200),
                           30, WHITE, anchor="center", shadow=False, max_w=box.w - 80)
            for i in range(GT_LEN):                           # how far up you got
                x = cx - 9 * 36 + i * 72
                col = (60, 200, 110) if i < m["rung"] else ((230, 70, 70) if i == m["rung"] else (50, 56, 86))
                pygame.draw.circle(w, col, (x, box.y + 290), 22)
                self.home_text(w, str(i + 1), (x, box.y + 290), 22, WHITE, anchor="center", shadow=False)
            self.home_text(w, "BEST EVER: %d / 10" % max(m["best"], m["rung"]) if m["best"] < GT_LEN else
                           "BEST EVER: BEAT THE MACHINE", (cx, box.y + 370), 26, (255, 226, 150), anchor="center",
                           shadow=False)
        else:
            k = m["rung"]
            self.home_text(w, "RUNG %d CLEARED" % (k + 1), (cx, box.y + 100), 64, (120, 240, 160), anchor="center")
            self.home_text(w, "%d - %d  V  %s" % (a, b, m["name"]), (cx, box.y + 190), 34, WHITE, anchor="center",
                           shadow=False, max_w=box.w - 80)
            if m.get("coins"):
                self.home_text(w, "+%d COINS" % m["coins"], (cx, box.y + 250), 30, (255, 226, 150), anchor="center",
                               shadow=False)
            nk = k + 1
            if nk < GT_LEN:
                nxt = "NEXT:  THE MACHINE" if nk == GT_LEN - 1 else "NEXT:  %s" % self.gt_team_name(nk)
                self.home_text(w, nxt, (cx, box.y + 330), 30, (255, 120, 110) if nk == GT_LEN - 1 else WHITE,
                               anchor="center", shadow=False, max_w=box.w - 80)
                tw = self.gt_twist(nk)
                if tw != "normal":
                    self.home_text(w, TWIST_NAME[tw], (cx, box.y + 374), 24, TWIST_COL.get(tw, WHITE), anchor="center",
                                   shadow=False)
        self.home_text(w, "CLICK TO CONTINUE", (cx, box.bottom - 40), 22, self.HOME_MUTED, anchor="center", shadow=False)

    def draw_gt_reveal(self, w):
        """THE MACHINE's entrance: black and red, its three cards slam in one by one, with the
        number that put each one there."""
        t = pygame.time.get_ticks() * 0.001 - self.gt_reveal
        k = GT_LEN - 1
        tw = self.gt_twist(k)
        w.fill((8, 2, 4))
        for y in range(0, HEIGHT, 6):                          # scanlines
            pygame.draw.line(w, (22, 4, 8), (0, y), (WIDTH, y), 3)
        pulse = 0.5 + 0.5 * math.sin(t * 4)
        g = self.home_glow((1500, 900), (200, 20, 30), int(60 + 50 * pulse))
        w.blit(g, g.get_rect(center=(WIDTH // 2, HEIGHT // 2)))
        if t > 0.2:
            bi = self.gt_machine_badge(150)
            w.blit(bi, bi.get_rect(center=(WIDTH // 2, 150)))
        if t > 0.5:
            self.home_text(w, "THE MACHINE", (WIDTH // 2, 290), 96, (255, 70, 60), anchor="center")
        if t > 0.9:
            self.home_text(w, "THE THREE CARDS WHOSE STATS DO THE MOST IN %s" % TWIST_NAME.get(tw, "A NORMAL MATCH"),
                           (WIDTH // 2, 370), 30, (255, 190, 180), anchor="center", shadow=False)
        cards = self.gt_team_cards(k)
        boost = GT_RUNGS[k][4]
        for i, c in enumerate(cards[:3]):
            at = 1.3 + i * 0.5
            if t < at:
                continue
            s = min(1.0, (t - at) / 0.18)
            scale = 1.0 + (1.0 - s) * 0.6
            cw, ch = int(240 * scale), int(326 * scale)
            r = pygame.Rect(0, 0, cw, ch)
            r.center = (WIDTH // 2 + (i - 1) * 330, 596)
            self.blit_card(w, dict(c, rating=c["rating"] + boost[0]) if boost else c, r)
            ms = self.gt_machine_stat(tw, c["id"])
            if s >= 1.0:
                if ms is not None:
                    self.home_text(w, "SHOT %s   REACH %s" % (self.fmt(ms[1]), self.fmt(ms[2])), (r.centerx, r.bottom + 50),
                                   22, (255, 150, 140), anchor="center", shadow=False)
                    self.home_text(w, "%.1f THROWS A SECOND" % ms[3], (r.centerx, r.bottom + 80), 22, (255, 150, 140),
                                   anchor="center", shadow=False)
                else:
                    self.home_text(w, "TOP RATED", (r.centerx, r.bottom + 50), 24, (255, 150, 140), anchor="center",
                                   shadow=False)
        if t > 3.0:
            self.home_text(w, "STATISTICALLY UNBEATABLE", (WIDTH // 2, 918), 52, WHITE, anchor="center")
            extra = "CPU: IMPOSSIBLE   -   +%d OVR" % boost[0] if boost else "CPU: IMPOSSIBLE"
            if GT_RUNGS[k][5]:
                extra += "   -   YOU START 1-0 DOWN"
            self.home_text(w, extra, (WIDTH // 2, 974), 26, (255, 170, 160), anchor="center", shadow=False)
        if t > 3.4:
            self.home_text(w, "CLICK TO FACE IT", (WIDTH // 2, 1030), 24, (200, 190, 200), anchor="center",
                           shadow=False)

    def draw_gt_play_art(self, w, box, t):
        """The PLAY tab's picture: ten steps climbing to THE MACHINE."""
        base = box.bottom - 60
        for k in range(GT_LEN):
            h = 40 + k * 34 if k < GT_LEN - 1 else 380
            r = pygame.Rect(box.x + 40 + k * 64, base - h, 56, h)
            lift = k / float(GT_LEN - 1)
            col = (int(70 + 120 * lift), int(80 - 60 * lift), int(150 - 120 * lift)) if k < GT_LEN - 1 else (150, 20, 30)
            pygame.draw.rect(w, _shade(col, 0.5), r, border_top_left_radius=8, border_top_right_radius=8)
            pygame.draw.rect(w, col, (r.x, r.y, r.w, 10), border_top_left_radius=8, border_top_right_radius=8)
            self.centre_text_at(w, str(k + 1), r.centerx, r.bottom - 26, WHITE)
        bi = self.gt_machine_badge(110)
        bob = int(math.sin(t * 2.0) * 6)
        w.blit(bi, bi.get_rect(center=(box.x + 40 + 9 * 64 + 28, base - 380 - 70 + bob)))
        G = self.gt()
        run = self.gt_run()
        if run is not None:
            self.centre_text_at(w, "RUN LIVE:  RUNG %d" % (run["rung"] + 1), box.x + 200, box.y + 60, YELLOW)
        else:
            self.centre_text_at(w, "BEST:  %d / 10" % int(G.get("best", 0)) if int(G.get("best", 0)) < GT_LEN
                                else "MACHINE BEATEN", box.x + 200, box.y + 60, (255, 190, 180))

    # ==================================================================================
    # PROFILE (29 Oct). Hubi: "maybe add trophies to a player profile tab". Who you are (your
    # club, level, best card, collection), a TROPHY CABINET - every trophy the game can give, lit
    # and counted when you've won it, a dark silhouette with how to get it when you haven't - and
    # your numbers. Trophies are counted in save["trophies"] from 29 Oct on; league titles and cups
    # won before that are read back out of the ladder's history.
    # ==================================================================================
    TROPHIES = (  # key, name, how to win it, metal, accent
        ("wc", "WORLD CUP", "WIN A WORLD CUP", "gold", (40, 150, 90)),
        ("wc_impossible", "IMPOSSIBLE CUP", "WIN THE IMPOSSIBLE WORLD CUP", "gold", (200, 40, 50)),
        ("cup", "CHAMPIONS CUP", "WIN THE CHAMPIONS CUP", "silver", (60, 90, 200)),
        ("league_0", "PREMIER LEAGUE", "WIN THE PREMIER LEAGUE", "gold", DIV_COLOURS[0]),
        ("league_1", "CHAMPIONSHIP", "WIN THE CHAMPIONSHIP", "silver", DIV_COLOURS[1]),
        ("league_2", "LEAGUE ONE", "WIN LEAGUE ONE", "bronze", DIV_COLOURS[2]),
        ("promotions", "PROMOTIONS", "GO UP A DIVISION", "gold", (60, 200, 110)),
        ("perfect", "PERFECT SEASON", "WIN EVERY LEAGUE MATCH IN A SEASON", "gold", (255, 206, 90)),
        ("gauntlet", "THE GAUNTLET", "BEAT THE MACHINE", "gold", (220, 40, 50)),
    )
    METALS = {"gold": ((120, 76, 20), (196, 140, 40), (240, 196, 80), (255, 236, 160)),
              "silver": ((84, 92, 112), (150, 160, 182), (206, 214, 230), (250, 252, 255)),
              "bronze": ((90, 46, 20), (156, 90, 44), (208, 136, 78), (240, 190, 140))}

    def trophies(self):
        T = self.save.get("trophies")
        if not isinstance(T, dict):
            T = {}
            L = self.save.get("ladder") or {}
            for h in L.get("history", []) or []:              # what the ladder already knows
                if h.get("pos") == 1:
                    k = "league_%d" % int(h.get("div", 2))
                    T[k] = T.get(k, 0) + 1
                if h.get("result") in ("promoted", "champions") and int(h.get("div", 0)) > 0:
                    T["promotions"] = T.get("promotions", 0) + 1
            if L.get("cups"):
                T["cup"] = int(L["cups"])
            self.save["trophies"] = T
        return T

    def add_trophy(self, key, n=1):
        T = self.trophies()
        T[key] = int(T.get(key, 0)) + n
        self.quest_event("trophy", n)                     # the weekly "win a trophy" (1 Nov)

    def trophy_count(self, key):
        T = self.trophies()
        if key == "wc":
            return sum(int(T.get(k, 0)) for k in ("wc_easy", "wc_medium", "wc_hard"))
        return int(T.get(key, 0))

    def count_match(self, result, gf, ga):
        """Every match that counts: played / won / drawn / lost / goals, overall and per mode."""
        S = self.save.setdefault("stats", {})
        for scope in ("all", self.mode):
            s = S.setdefault(scope, {"p": 0, "w": 0, "d": 0, "l": 0, "gf": 0, "ga": 0})
            s["p"] += 1
            s[{"win": "w", "draw": "d", "loss": "l"}[result]] += 1
            s["gf"] += gf
            s["ga"] += ga
        if result == "win" and gf - ga > S.get("best_win", [0, 0])[0] - S.get("best_win", [0, 0])[1]:
            S["best_win"] = [gf, ga]

    TROPHY_MAX = (220, 176)       # the art fits in this on its shelf (five to a shelf since the Gauntlet)

    def trophy_art(self, key, locked=False):
        """The trophy: trophy_<key>.png (make_trophies.py, from the Canva art) if it's there, cut
        out and fitted to the shelf - a dark silhouette while it's still to win. Without the
        sprite it falls back to the little drawn one below. Cached."""
        cache = self.__dict__.setdefault("_trophy_art", {})
        ck = (key, locked)
        if ck in cache:
            return cache[ck]
        path = find_sprite("trophy_%s" % key)
        if path:
            try:
                img = pygame.image.load(path).convert_alpha()
                box = img.get_bounding_rect()
                img = img.subsurface(box).copy()
                k = min(self.TROPHY_MAX[0] / float(img.get_width()), self.TROPHY_MAX[1] / float(img.get_height()))
                img = pygame.transform.smoothscale(img, (max(1, int(img.get_width() * k)),
                                                         max(1, int(img.get_height() * k))))
                if locked:
                    img.fill((0, 0, 0, 255), special_flags=pygame.BLEND_RGBA_MULT)
                    img.fill((24, 30, 56, 0), special_flags=pygame.BLEND_RGBA_ADD)
                cache[ck] = img
                return img
            except Exception:
                pass
        spec = {t[0]: t for t in self.TROPHIES}[key]
        dark, mid, light, hi = self.METALS[spec[3]]
        accent = spec[4]
        if locked:
            dark, mid, light, hi = (14, 18, 34), (26, 32, 56), (34, 42, 70), (44, 54, 86)
            accent = (30, 38, 64)
        s = pygame.Surface((56, 72), pygame.SRCALPHA)
        d = pygame.draw
        # plinth
        d.rect(s, (40, 30, 24) if not locked else (18, 22, 40), (12, 62, 32, 8))
        d.rect(s, accent, (14, 63, 28, 3))
        d.rect(s, dark, (18, 56, 20, 6))
        d.rect(s, mid, (19, 56, 18, 2))
        if key in ("wc", "wc_impossible"):
            d.polygon(s, mid, [(22, 56), (34, 56), (31, 36), (36, 26), (20, 26), (25, 36)])
            d.polygon(s, light, [(24, 54), (27, 54), (26, 36), (22, 27), (21, 27)])
            d.circle(s, mid, (28, 18), 11)
            d.circle(s, light, (25, 15), 6)
            d.circle(s, hi, (23, 13), 2)
            d.arc(s, accent if key == "wc_impossible" else dark, (17, 7, 22, 22), 0.4, 2.8, 2)
            if key == "wc_impossible":
                d.rect(s, accent, (21, 44, 14, 4))
        elif key == "cup":
            d.rect(s, mid, (25, 40, 6, 16))
            d.polygon(s, mid, [(14, 12), (42, 12), (38, 34), (18, 34)])
            d.polygon(s, light, [(17, 13), (24, 13), (22, 33), (19, 33)])
            d.ellipse(s, hi, (14, 9, 28, 6))
            for side in (-1, 1):                               # the big ears
                cx = 28 + side * 20
                d.ellipse(s, mid, (cx - 8, 10, 16, 26), 3)
            d.ellipse(s, dark, (20, 34, 16, 8))
        elif key.startswith("league_"):
            d.rect(s, mid, (25, 42, 6, 14))
            d.polygon(s, mid, [(16, 16), (40, 16), (36, 38), (20, 38)])
            d.polygon(s, light, [(18, 17), (25, 17), (23, 37), (21, 37)])
            d.rect(s, accent, (16, 24, 24, 4))                 # the ribbon in the division's colour
            d.polygon(s, mid, [(20, 16), (36, 16), (32, 8), (24, 8)])   # the lid
            d.circle(s, hi, (28, 6), 3)
            for side in (-1, 1):
                d.arc(s, mid, (28 + side * 13 - 6, 18, 12, 14), -1.6 if side > 0 else 1.6, 1.6 if side > 0 else 4.7, 2)
        elif key == "promotions":
            d.polygon(s, accent, [(18, 14), (26, 14), (30, 30), (24, 30)])
            d.polygon(s, (40, 120, 70) if not locked else accent, [(30, 14), (38, 14), (32, 30), (26, 30)])
            d.circle(s, mid, (28, 40), 12)
            d.circle(s, light, (28, 40), 9)
            d.polygon(s, hi if not locked else mid, [(28, 33), (33, 41), (30, 41), (30, 47), (26, 47), (26, 41), (23, 41)])
        elif key == "perfect":
            d.rect(s, mid, (25, 40, 6, 16))
            pts = [(28 + math.cos(-math.pi / 2 + k * math.pi / 5) * (16 if k % 2 == 0 else 7),
                    22 + math.sin(-math.pi / 2 + k * math.pi / 5) * (16 if k % 2 == 0 else 7)) for k in range(10)]
            d.polygon(s, mid, pts)
            d.polygon(s, light, [pts[0], pts[1], (28, 22), pts[9]])
            d.circle(s, hi, (28, 22), 3)
        s = s.subsurface(s.get_bounding_rect()).copy()        # no empty sky above it
        out = pygame.transform.scale(s, (s.get_width() * 3, s.get_height() * 3))
        cache[ck] = out
        return out

    def open_profile(self):
        self.state = PROFILE
        self.dragging = False

    def profile_click(self, pos):
        pass                                             # BACK is handled for every screen

    def draw_profile(self, w):
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        w.blit(self.home_bg(), (0, 0))
        self.draw_glass(w, pygame.Rect(24, 20, WIDTH - 48, 92), radius=24, alpha=120)
        self.draw_glass_back(w, mouse)
        title = self.home_gold("PROFILE", 52)
        w.blit(title, title.get_rect(midleft=(272, 66)))
        self.draw_status(w, mouse)
        # ---- who you are
        me = pygame.Rect(40, 140, 540, 900)
        self.draw_glass(w, me, radius=30, alpha=150, hot=True)
        club = self.clubs[self.user_idx]
        if club["badge"] is not None:
            g = self.home_glow((300, 300), (90, 140, 255), 80)
            w.blit(g, g.get_rect(center=(me.x + 120, me.y + 130)))
            bi = fit_flag(club["badge"], 140, 162)
            w.blit(bi, bi.get_rect(center=(me.x + 120, me.y + 130)))
        self.home_text(w, club["name"].upper(), (me.x + 222, me.y + 96), 42, WHITE, max_w=me.w - 250)
        level, into, need = level_from_xp(self.save.get("xp", 0))
        self.home_text(w, "LEVEL %d" % level, (me.x + 222, me.y + 150), 30, (255, 226, 150), shadow=False)
        bar = pygame.Rect(me.x + 222, me.y + 178, me.w - 262, 18)
        pygame.draw.rect(w, (6, 10, 28), bar, border_radius=9)
        pygame.draw.rect(w, (90, 220, 255), (bar.x, bar.y, max(18, int(bar.w * into / float(max(1, need)))), bar.h),
                         border_radius=9)
        self.home_text(w, "%s / %s XP" % (self.fmt(into), self.fmt(need)), (bar.right, bar.bottom + 22), 20,
                       self.HOME_MUTED, anchor="midright", shadow=False)
        hero = self.home_hero_card()
        self.home_text(w, "BEST CARD", (me.x + 30, me.y + 262), 22, self.HOME_MUTED, shadow=False)
        if hero is not None:
            cr = pygame.Rect(me.x + 30, me.y + 290, 220, 328)
            g = self.home_glow((360, 420), (255, 200, 90), 60)
            w.blit(g, g.get_rect(center=cr.center))
            self.blit_card(w, hero, cr)
            self.home_text(w, hero["name"].upper(), (cr.right + 24, cr.y + 30), 30, WHITE, shadow=False,
                           max_w=me.right - cr.right - 50)
            self.home_text(w, "%d  %s  -  POOL %s" % (hero["rating"], hero["pos"], self.card_pool(hero)),
                           (cr.right + 24, cr.y + 70), 24, self.HOME_MUTED, shadow=False,
                           max_w=me.right - cr.right - 50)
        owned = sum(1 for v in self.save["owned"].values() if v > 0)
        total = len(self.collection_ids())
        y = me.y + 660
        self.home_text(w, "COLLECTION", (me.x + 30, y), 22, self.HOME_MUTED, shadow=False)
        self.home_text(w, "%d / %d" % (owned, total), (me.right - 30, y), 26, WHITE, anchor="midright", shadow=False)
        bar = pygame.Rect(me.x + 30, y + 26, me.w - 60, 18)
        pygame.draw.rect(w, (6, 10, 28), bar, border_radius=9)
        pygame.draw.rect(w, (255, 206, 90), (bar.x, bar.y, max(18, int(bar.w * owned / float(max(1, total)))), bar.h),
                         border_radius=9)
        L = self.ladder()
        y += 90
        self.home_text(w, "CLUB LEAGUE", (me.x + 30, y), 22, self.HOME_MUTED, shadow=False)
        now = DIVISIONS[self.lg["div"]] if self.lg_ready() and self.lg_phase() != "over" else DIVISIONS[L["mine"]]
        self.home_text(w, now, (me.x + 30, y + 40), 30, WHITE, shadow=False)
        nseas = len(L.get("history", []))
        self.home_text(w, "BEST: %s   -   %d SEASON%s" % (DIVISIONS[L.get("best", 2)], nseas, "" if nseas == 1 else "S"),
                       (me.x + 30, y + 80), 22, self.HOME_MUTED, shadow=False, max_w=me.w - 60)
        G = self.gt()
        self.home_text(w, "THE GAUNTLET", (me.x + 30, y + 124), 22, self.HOME_MUTED, shadow=False)
        gb = int(G.get("best", 0))
        self.home_text(w, ("BEST %d / %d" % (gb, GT_LEN)) if gb < GT_LEN else "MACHINE BEATEN x%d" % int(G.get("wins", 0)),
                       (me.right - 30, y + 124), 24, (255, 150, 140), anchor="midright", shadow=False)
        # ---- the trophy cabinet
        cab = pygame.Rect(600, 140, 1280, 600)
        self.draw_glass(w, cab, radius=30, alpha=150, edge=(255, 206, 90))
        won_total = sum(self.trophy_count(k[0]) for k in self.TROPHIES)
        self.home_text(w, "TROPHY CABINET", (cab.x + 30, cab.y + 38), 28, (255, 226, 150), shadow=False)
        self.home_text(w, "%d WON" % won_total, (cab.right - 30, cab.y + 38), 26, WHITE, anchor="midright", shadow=False)
        per = 4 if len(self.TROPHIES) <= 8 else 5          # 9 or 10 trophies: five to a shelf
        sw = (cab.w - 60 - (per - 1) * 10) // per
        for k, (key, name, how, metal, accent) in enumerate(self.TROPHIES):
            col, row = k % per, k // per
            slot = pygame.Rect(cab.x + 30 + col * (sw + 10), cab.y + 70 + row * 262, sw, 252)
            n = self.trophy_count(key)
            got = n > 0
            if got:
                g = self.home_glow((300, 260), self.METALS[metal][2], int(70 + 30 * math.sin(t * 1.6 + k)))
                w.blit(g, g.get_rect(center=(slot.centerx, slot.y + 100)))
            shelf = pygame.Rect(slot.x + 14, slot.y + 196, slot.w - 28, 10)
            pygame.draw.rect(w, (70, 52, 36) if got else (30, 36, 60), shelf, border_radius=4)
            pygame.draw.rect(w, (120, 92, 60) if got else (44, 52, 84), (shelf.x, shelf.y, shelf.w, 3), border_radius=2)
            art = self.trophy_art(key, locked=not got)
            bob = int(round(math.sin(t * 1.4 + k) * 1.5)) * PIXEL if got else 0
            w.blit(art, art.get_rect(midbottom=(slot.centerx, shelf.y + 4 + bob)))
            if got and n > 1:
                c = (slot.right - 46, slot.y + 34)
                pygame.draw.circle(w, (255, 206, 90), c, 24)
                pygame.draw.circle(w, (120, 80, 14), c, 24, 3)
                self.home_text(w, "x%d" % n, c, 24, (60, 36, 6), anchor="center", shadow=False)
            self.home_text(w, name, (slot.centerx, slot.y + 220), 24, WHITE if got else (150, 162, 200), anchor="center",
                           shadow=False, max_w=slot.w - 10)
            self.home_text(w, ("WON %d" % n) if got else how, (slot.centerx, slot.y + 246), 20,
                           (255, 226, 150) if got else (110, 122, 160), anchor="center", shadow=False, max_w=slot.w - 10)
        # ---- the numbers
        st = pygame.Rect(600, 760, 1280, 280)
        self.draw_glass(w, st, radius=30, alpha=150)
        S = self.save.get("stats", {})
        a = S.get("all", {"p": 0, "w": 0, "d": 0, "l": 0, "gf": 0, "ga": 0})
        pct = int(round(100.0 * a["w"] / a["p"])) if a["p"] else 0
        bw = S.get("best_win")
        tiles = (("MATCHES", str(a["p"])), ("WON", str(a["w"])), ("DRAWN", str(a["d"])), ("LOST", str(a["l"])),
                 ("WIN RATE", "%d%%" % pct), ("GOALS", str(a["gf"])), ("CONCEDED", str(a["ga"])),
                 ("BIGGEST WIN", ("%d-%d" % tuple(bw)) if bw else "-"))
        self.home_text(w, "YOUR NUMBERS", (st.x + 30, st.y + 36), 24, self.HOME_MUTED, shadow=False)
        for k, (lab, val) in enumerate(tiles):
            col, row = k % 4, k // 4
            r = pygame.Rect(st.x + 30 + col * 307, st.y + 64 + row * 104, 296, 94)
            self.draw_glass(w, r, radius=20, alpha=180)
            self.home_text(w, val, (r.x + 24, r.y + 40), 40, WHITE, shadow=False, max_w=r.w - 40)
            self.home_text(w, lab, (r.x + 24, r.y + 76), 20, self.HOME_MUTED, shadow=False)

    # ---- drawing: club select --------------------------------
    def draw_club(self, w):
        if LADDER:
            return self.draw_lg_hub(w)
        w.blit(self.select_bg, (0, 0))
        badges, arrow, diff, table_btn, boxes = self.club_layout()
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        rl = self.club_roulette

        if self.club_over == "champions":
            title, col = "CHAMPIONS!", YELLOW
        elif self.club_over == "relegated":
            title, col = "GAME OVER - RELEGATED", (255, 110, 110)
        elif self.club_over == "finished":
            pos = self.standings().index(self.club) + 1
            title, col = "SEASON OVER - FINISHED %s" % ordinal(pos), WHITE
        elif rl is not None and rl["landed"]:
            title, col = "ROUND %d:  %s  VS  %s" % (self.club_round + 1, self.clubs[self.club]["code"],
                                                  self.clubs[rl["cur"]]["code"]), WHITE
        elif rl is not None:
            title, col = "ROUND %d  -  DRAWING OPPONENT" % (self.club_round + 1), WHITE
        elif self.club is not None and self.club_round > 0:
            title, col = "NEXT: ROUND %d" % (self.club_round + 1), WHITE
        else:
            title, col = "%s  -  NEW SEASON" % self.clubs[self.user_idx]["name"], WHITE
        self.centre_text(w, title, self.font_l, col, 22)
        if len(self.save["squad"]) < SQUAD_SIZE:
            self.centre_text(w, "PICK 5 PLAYERS IN MY CLUB FIRST", self.font_m, (255, 130, 130), 562)
        me = self.clubs[self.user_idx]
        if me["badge"] is not None:
            b = fit_flag(me["badge"], 70, 82)
            w.blit(b, b.get_rect(center=(arrow.centerx, 64)))

        # go button
        ready = self.club_can_draw() or (rl is not None and rl["landed"])
        pygame.draw.rect(w, SELECT_GREEN if ready else (40, 88, 44), arrow)
        pygame.draw.rect(w, WHITE if ready else (120, 140, 120), arrow, 8)
        cx, cy = arrow.centerx, arrow.centery
        nudge = int(math.sin(t * 6.0) * 6) if ready else 0
        acol = (236, 236, 236) if ready else (120, 140, 120)
        pygame.draw.rect(w, acol, (cx - 62 + nudge, cy - 16, 70, 32))
        pygame.draw.polygon(w, acol, [(cx + 8 + nudge, cy - 44), (cx + 62 + nudge, cy), (cx + 8 + nudge, cy + 44)])

        # difficulty: shows your club's player for each level
        locked = self.season_running() or rl is not None
        for i, rect in enumerate(diff):
            chosen = i == self.difficulty
            pygame.draw.rect(w, SELECT_GREEN if (chosen or not locked) else (40, 88, 44), rect)
            pygame.draw.rect(w, YELLOW if chosen else (WHITE if not locked else (120, 140, 120)), rect,
                             6 if chosen else 3)
            txt = self.font_s.render(DIFFICULTY[i][0], True, YELLOW if chosen else WHITE)
            head = None
            if head is not None:
                icon = pygame.transform.scale(head, (int(head.get_width() * 42 / head.get_height()), 42))
                w.blit(icon, icon.get_rect(midleft=(rect.x + 14, rect.centery)))
                w.blit(txt, txt.get_rect(midleft=(rect.x + 78, rect.centery)))
            else:
                w.blit(txt, txt.get_rect(center=rect.center))

        # table button
        hover = table_btn.collidepoint(mouse)
        pygame.draw.rect(w, SELECT_GREEN, table_btn)
        pygame.draw.rect(w, YELLOW if hover else WHITE, table_btn, 3)
        txt = self.font_s.render("TABLE", True, YELLOW if hover else WHITE)
        w.blit(txt, txt.get_rect(center=table_btn.center))

        # club badges
        faced_recent = set(self.club_opps[-(CLUB_NO_REPEAT - 1):]) if self.season_running() else set()
        for i, rect in enumerate(badges):
            club = self.clubs[i]
            img = club["badge"]
            out = self.table[i]["out"]
            pos = rect.copy()
            if i == self.club:
                pos.y -= 8
                pygame.draw.rect(w, YELLOW, pos.inflate(20, 20), 6)
            elif rl is not None and i == rl["cur"]:
                flash = rl["landed"] and rl["hold"] < ROULETTE_BLINK and int(rl["hold"] * 8) % 2 == 1
                if not flash:
                    pygame.draw.rect(w, WHITE, pos.inflate(24, 24), 7)
            elif (not self.season_running() and rl is None
                  and pos.inflate(30, 50).move(0, 20).collidepoint(mouse)):
                pygame.draw.rect(w, WHITE, pos.inflate(14, 14), 3)
            if img is not None:
                im = fit_flag(img, rect.w, rect.h)
                if out or i in faced_recent:
                    im = im.copy()
                    im.fill((90, 90, 90) if out else (150, 150, 150), special_flags=pygame.BLEND_RGB_MULT)
                w.blit(im, im.get_rect(center=pos.center))
            if out:
                pygame.draw.line(w, (230, 60, 60), pos.topleft, pos.bottomright, 8)
                pygame.draw.line(w, (230, 60, 60), pos.topright, pos.bottomleft, 8)
            name = self.label(club["code"], rect.w + 50, YELLOW if i == self.club else WHITE)
            w.blit(name, name.get_rect(midtop=(rect.centerx, rect.bottom + 8)))

        if rl is not None and rl["landed"] and int(t * 2.5) % 2 == 0:
            self.centre_text(w, "CLICK TO START", self.font_m, YELLOW, 562)

        # the 12-round bracket, 6 above and 6 below
        for i, box in enumerate(boxes):
            lab = self.label("ROUND %d" % (i + 1), box.w)
            w.blit(lab, lab.get_rect(midbottom=(box.centerx, box.top - 6)))
            pygame.draw.rect(w, SELECT_GREEN, box)
            current = self.club is not None and i == self.club_round and self.club_over is None
            border = YELLOW if (current and int(t * 3) % 2 == 0) else WHITE
            if i < len(self.club_results):
                mg, tg = self.club_results[i]
                border = (120, 230, 120) if mg > tg else (240, 90, 90)
            pygame.draw.rect(w, border, box, 7)
            if i < len(self.club_opps):
                opp = self.clubs[self.club_opps[i]]
            elif i == len(self.club_opps) and rl is not None:
                opp = self.clubs[rl["cur"]]
            else:
                continue
            if opp["badge"] is not None:
                im = fit_flag(opp["badge"], box.w - 120, box.h - 60)
                if i < len(self.club_results):
                    im = im.copy()
                    im.fill((120, 120, 120), special_flags=pygame.BLEND_RGB_MULT)
                w.blit(im, im.get_rect(center=(box.centerx, box.centery - 12)))
            code = self.font_s.render(opp["code"], True, WHITE)
            w.blit(code, code.get_rect(midbottom=(box.centerx, box.bottom - 8)))
            if i < len(self.club_results):
                mg, tg = self.club_results[i]
                sc = "%d-%d" % (mg, tg)
                w.blit(self.font_l.render(sc, True, INK),
                       self.font_l.render(sc, True, INK).get_rect(center=(box.centerx + 4, box.centery - 7)))
                img = self.font_l.render(sc, True, WHITE)
                w.blit(img, img.get_rect(center=(box.centerx, box.centery - 12)))

        if MISSING_SPRITES:
            note = self.font_s.render("MISSING FROM THE SPRITES FOLDER: " + ", ".join(MISSING_SPRITES[:6]),
                                      True, (255, 110, 110))
            if note.get_width() > WIDTH - 40:
                k = (WIDTH - 40) / note.get_width()
                note = pygame.transform.smoothscale(note, (int(note.get_width() * k), int(note.get_height() * k)))
            w.blit(note, note.get_rect(midbottom=(WIDTH // 2, HEIGHT - 4)))
        self.draw_back_button(w)

    # ---- drawing: league table -------------------------------

    def draw_table(self, w):
        if LADDER and self.lg_ready():
            return self.draw_lg_result(w)
        w.blit(self.select_bg, (0, 0))
        head = "LEAGUE TABLE" + ("  -  AFTER ROUND %d" % self.club_round if self.club_round else "")
        self.centre_text(w, head, self.font_m, WHITE, 14)
        if self.table_msg:
            self.centre_text(w, self.table_msg, self.font_s, YELLOW, 74)

        order = self.standings()
        top, row_h = 124, 42
        cols = {"POS": 70, "CLUB": 200, "P": 900, "W": 990, "D": 1080, "L": 1170, "GD": 1270, "PTS": 1390,
                "ZONE": 1520}
        for name, x in cols.items():
            img = self.font_s.render(name, True, (190, 220, 190))
            w.blit(img, (x, top - 10))
        active = [i for i in order if not self.table[i]["out"]]
        zone = set(active[-RELEGATION_ZONE:]) if len(active) > RELEGATION_ZONE else set()
        for r, i in enumerate(order):
            y = top + 30 + r * row_h
            rec = self.table[i]
            club = self.clubs[i]
            band = pygame.Rect(50, y - 4, WIDTH - 100, row_h - 4)
            if rec["out"]:
                pygame.draw.rect(w, (46, 46, 50), band)
            elif i in zone:
                pygame.draw.rect(w, (110, 34, 38), band)
            elif r % 2:
                pygame.draw.rect(w, (38, 72, 40), band)
            if i == self.club:
                pygame.draw.rect(w, YELLOW, band, 3)
            ink = (140, 140, 140) if rec["out"] else (YELLOW if i == self.club else WHITE)
            pos_txt = "OUT" if rec["out"] else str(r + 1)
            w.blit(self.font_s.render(pos_txt, True, ink), (cols["POS"], y))
            if club["badge"] is not None:
                im = fit_flag(club["badge"], 30, 34)
                w.blit(im, (cols["CLUB"] - 44, y - 2))
            w.blit(self.font_s.render("%s  %s" % (club["code"], club["name"].upper()), True, ink),
                   (cols["CLUB"], y))
            gd = rec["gf"] - rec["ga"]
            for key, val in (("P", rec["p"]), ("W", rec["w"]), ("D", rec.get("d", 0)), ("L", rec["l"]),
                             ("GD", ("+%d" % gd) if gd > 0 else str(gd)), ("PTS", rec["pts"])):
                w.blit(self.font_s.render(str(val), True, ink), (cols[key], y))
            if not rec["out"]:
                for k in range(RELEGATION_STRIKES):
                    c = (240, 70, 70) if k < rec["strikes"] else (70, 90, 70)
                    pygame.draw.circle(w, c, (cols["ZONE"] + 18 + k * 30, y + 14), 10)
            else:
                w.blit(self.font_s.render("ROUND %d" % rec["out_round"], True, ink), (cols["ZONE"], y))

        foot = "BOTTOM 3 FOR 2 ROUNDS IN A ROW = OUT OF THE LEAGUE      CLICK TO CONTINUE"
        img = self.font_s.render(foot, True, (200, 210, 200))
        if img.get_width() > WIDTH - 40:
            k = (WIDTH - 40) / img.get_width()
            img = pygame.transform.smoothscale(img, (int(img.get_width() * k), int(img.get_height() * k)))
        w.blit(img, img.get_rect(midbottom=(WIDTH // 2, HEIGHT - 6)))
        self.draw_back_button(w)

    # ================================================================ META GAME
    # ---- save file -------------------------------------------

    def default_save(self):
        return {"coins": 0, "owned": {}, "squad": [], "stamina": {},
                "team": {"name": "MY TEAM", "c1": 6, "c2": 10, "pattern": "PLAIN"},
                "difficulty": 1, "season": None, "starter_opened": False, "xp": 0,
                "training_coins": 0, "puzzle_points": 0, "star_points": 0, "tutorial_done": False,
                "ren_unlocked": False, "essence": 0, "prog": {}}

    def load_save(self):
        data = self.default_save()
        try:
            loaded = json.loads(read_save_text() or "")
            if isinstance(loaded, dict):
                data.update(loaded)
                if "tutorial_done" not in loaded:
                    data["tutorial_done"] = True           # saves from before the tutorial skip it
        except Exception:
            pass
        self.save = data
        self.migrate_cards()
        # drop anything that no longer exists in the card list
        self.save["owned"] = {k: v for k, v in self.save["owned"].items() if k in self.cards}
        self.save["squad"] = [k for k in self.save["squad"] if k in self.save["owned"]][:SQUAD_SIZE]
        prog = self.save.get("prog") if isinstance(self.save.get("prog"), dict) else {}
        clean = {}
        for cid, p in prog.items():                       # only cards you still own, only sane numbers
            if cid not in self.save["owned"] or not isinstance(p, dict):
                continue
            try:
                skill = {k: max(0, min(SKILL_MAX, int(v))) for k, v in (p.get("skill") or {}).items()
                         if k in STAT_KEYS}
                clean[cid] = {"xp": max(0, min(sum(LEVEL_XP), int(p.get("xp", 0)))),
                              "rank": max(0, min(len(RANK_COST), int(p.get("rank", 0)))), "skill": skill}
            except (TypeError, ValueError):
                continue
        self.save["prog"] = clean
        if not self.save["starter_opened"]:
            self.open_starter_pack()
        try:
            self.save["essence"] = max(0, int(self.save.get("essence") or 0))
        except (TypeError, ValueError):
            self.save["essence"] = 0
        try:
            saved = int(self.save.get("difficulty", 1)) % len(DIFFICULTY)
        except (TypeError, ValueError):
            saved = 1
        if saved == IMPOSSIBLE:
            saved = 2              # a save from when Impossible was a difficulty button: HARD is the nearest
        self.normal_difficulty = saved
        if not self.save.get("ren_unlocked"):
            self.lock_ren()                                       # earn him, don't get given him
        if not (self.difficulty == IMPOSSIBLE and self.wc_slot == "impossible"):
            self.difficulty = saved                               # (a save landing mid-Impossible leaves it be)
        self.brain.skill = DIFFICULTY[self.difficulty][1]
        self.brain.impossible = self.difficulty == IMPOSSIBLE

    # players who changed club keep their card: the old id is swapped for the new one
    CARD_MOVED = {"BRI_joaopedro": "CHE_joaopedro"}

    def migrate_cards(self):
        """A transfer shouldn't cost anyone a card they already pulled."""
        owned = self.save.get("owned") or {}
        for old, new in self.CARD_MOVED.items():
            if old in owned:
                owned[new] = owned.get(new, 0) + owned.pop(old)
        self.save["squad"] = [self.CARD_MOVED.get(k, k) for k in (self.save.get("squad") or [])]

    def write_save(self):
        self.save["difficulty"] = self.normal_difficulty if self.difficulty == IMPOSSIBLE else self.difficulty
        self.save["season"] = self.season_to_dict()
        try:
            write_save_text(json.dumps(self.save, indent=1))
        except Exception as exc:
            print("[ragdoll_football] could not save:", exc)

    def season_to_dict(self):
        if LADDER:
            return self.lg_to_dict()
        if self.mode != "club" and not getattr(self, "club_round", 0):
            return self.save.get("season")
        return {"round": self.club_round, "opps": self.club_opps, "results": self.club_results,
                "over": self.club_over, "table": {str(k): v for k, v in self.table.items()},
                "started": self.club is not None}

    def restore_season(self):
        if LADDER:
            return self.lg_restore()
        s = self.save.get("season")
        self.new_season(None)
        if not s or not s.get("started"):
            return
        try:
            self.club = self.user_idx
            self.club_round = int(s["round"])
            self.club_opps = [int(x) for x in s["opps"]]
            self.club_results = [tuple(r) for r in s["results"]]
            self.club_over = s["over"]
            for k, v in s["table"].items():
                if int(k) in self.table:
                    self.table[int(k)].update(v)
        except Exception:
            self.new_season(None)

    # ---- cards -----------------------------------------------
    def card_head(self, card):
        if card["kind"] in ("sig", "star", "rookie", "no10", "wg", "lb"):
            return self.sig_looks.get(card["id"], {}).get("head")
        looks = self.looks if card["kind"] == "wc" else self.club_looks
        pieces = looks.get(card["team"] if card["kind"] == "club" else card["team"], {})
        heads = pieces.get("head") or []
        return heads[card["slot"]] if card["slot"] < len(heads) else None

    def card_badge(self, card):
        if card["kind"] in ("no10", "wg", "lb"):           # nation cards: the flag is the badge
            return self.nation_flag(card["nation"])
        if card["kind"] in ("star", "rookie"):
            return self.star_badges.get(card["team"])
        if card["kind"] == "club":
            for c in self.clubs:
                if c["code"] == card["team"]:
                    return c["badge"]
            return None
        for t in self.teams:
            if t["name"] == card["team"]:
                return t["flag"]
        return None

    def card_original_look(self, card):
        if card["kind"] in ("sig", "star", "rookie", "no10", "wg", "lb"):
            return dict(self.sig_looks.get(card["id"], {})) or None
        looks = self.looks if card["kind"] == "wc" else self.club_looks
        pieces = looks.get(card["team"])
        if not pieces:
            return None
        return {piece: imgs[card["slot"]] for piece, imgs in pieces.items()}

    def team_colours(self):
        t = self.save["team"]
        return (TEAM_PALETTE[t["c1"] % len(TEAM_PALETTE)], TEAM_PALETTE[t["c2"] % len(TEAM_PALETTE)],
                t.get("pattern", "PLAIN"))

    def team_look(self, card):
        """A card's own head + skin in the custom team kit (with its number)."""
        c1, c2, pattern = self.team_colours()
        key = (card["id"], c1, c2, pattern)
        if key in self.kit_cache:
            return self.kit_cache[key]
        orig = self.card_original_look(card) or {}
        skin, boots = (206, 160, 122), (30, 30, 36)
        try:
            arm, leg = orig.get("arm"), orig.get("leg")
            if arm is not None:
                c = arm.get_at((arm.get_width() // 2, int(arm.get_height() * 0.72)))
                skin = (c[0], c[1], c[2])
            if leg is not None:
                c = leg.get_at((leg.get_width() // 2, leg.get_height() - int(leg.get_height() / 12) - 1))
                boots = (c[0], c[1], c[2])
        except Exception:
            pass
        look = {"head": orig.get("head"),
                "torso": paint_torso(c1, c2, pattern, card["number"], (TORSO_W, TORSO_H)),
                "arm": paint_arm(c1, c2, pattern, skin, (ARM_W, ARM_L)),
                "leg": paint_leg(c1, c2, skin, boots, (LEG_W, LEG_L))}
        self.kit_cache[key] = look
        return look

    def refresh_team(self):
        """Rebuild the custom team's badge and league entry after an edit."""
        c1, c2, _ = self.team_colours()
        name = self.save["team"]["name"].strip() or "MY TEAM"
        badge = paint_badge(name, c1, c2, (96, 112))
        code = "".join(ch for ch in name.upper() if ch in FONT3)[:3] or "YOU"
        entry = {"code": code, "name": name, "strength": 75, "badge": badge, "user": True}
        if len(self.clubs) > len(CLUBS):
            self.clubs[self.user_idx] = entry
        else:
            self.clubs.append(entry)
        self.kit_cache = {}

    def card_frame(self, card):
        """(outer, inner, ink, strip) colours for a card's design."""
        if card["design"] == "icon":
            return (226, 186, 72), (250, 246, 234), (60, 44, 10), (190, 150, 50)
        if card["design"] == "wc":
            return (222, 182, 70), (20, 30, 66), WHITE, (12, 18, 44)
        r = card["rating"]
        if r >= 90:
            return (168, 118, 26), (248, 212, 90), INK, (168, 118, 26)
        if r >= 72:
            return (120, 128, 146), (214, 220, 230), INK, (120, 128, 146)
        return (120, 70, 36), (214, 142, 84), INK, (120, 70, 36)

    def nation_colours(self, code):
        if code in self.flag_colour_cache:
            return self.flag_colour_cache[code]
        cols = [(200, 200, 200)] * 3
        for t in self.teams:
            if t["name"] == code and t["flag"] is not None:
                f = t["flag"]
                fw, fh = f.get_size()
                try:
                    cols = [tuple(f.get_at((int(fw * 0.8), int(fh * y)))[:3]) for y in (0.15, 0.5, 0.85)]
                except Exception:
                    pass
        self.flag_colour_cache[code] = cols
        return cols

    # ---- pool A / B cards: pre-drawn backgrounds + portrait + text ------------------
    TPL_SIZE = (400, 500)
    TPL_BODY = (66, 34, 334, 458)                 # where the card itself sits in a template

    def star_key(self, card):
        """A Star Signing's card (STAR_LOOK): stargold / flag_<nation> / champ_<club>, or the old
        purple "star" when his figure or the card's art is missing."""
        ok = self.__dict__.setdefault("_star_ok", {})
        cid = card["id"]
        if cid not in ok:
            look, k = STAR_LOOK.get(cid), "star"
            if cid in getattr(self, "card_figs", ()):
                if look == "gold":
                    if find_sprite("tpl_stargold_card") and find_sprite("tpl_stargoldframe_card"):
                        k = "stargold"
                elif look == "wc":
                    if find_sprite("tpl_fgold_card") and self.nation_flag(card["nation"]) is not None:
                        k = "flag_" + card["nation"]
                elif look == "club":
                    if find_sprite("tpl_champ_%s_card" % card["team"]):
                        k = "champ_" + card["team"]
            ok[cid] = k
        return ok[cid]

    def card_template_key(self, card):
        pool = self.card_pool(card)
        # 31 Oct: Club Packs 2 + 3, pools A and B, wear the moving Champions card too
        if card["design"] == "champions" or (card.get("id") in CLUB_NATION and pool in ("A", "B")):
                                                           # gold Champions card in his club's colours
            ok = self.__dict__.setdefault("_champ_ok", {})
            if card["team"] not in ok:
                ok[card["team"]] = find_sprite("tpl_champ_%s_card" % card["team"]) is not None
            if ok[card["team"]]:
                return "champ_" + card["team"]
            return ("club_" + card["team"]) if pool == "A" else "b"
        if card.get("id") in WC_SPECIAL and pool in ("A", "B"):
            return WC_SPECIAL[card["id"]]
        # icons keep their crystal card everywhere EXCEPT the World Cup pack, where the
        # whole of pool A and B wears the holo card - otherwise most of pool A isn't in it
        if card["design"] == "icon" and not (card["kind"] == "wc" and pool in ("A", "B")):
            return "icon"
        if card["design"] == "signature":
            # 28 Oct: the Signature card wears the World Cup card's shape and his nation's flag
            # (make_sig_card.py) - the old arch card if those sprites are missing
            ok = self.__dict__.setdefault("_fsig_ok", {})
            if card["team"] not in ok:
                ok[card["team"]] = find_sprite("tpl_fsig_card") is not None and \
                    self.nation_flag(card["team"]) is not None
            if card.get("id") in HOLO_SIG and ok[card["team"]]:       # 1 Nov: the chrome one (Kempes)
                hk = self.__dict__.setdefault("_fholo_ok", None)
                if hk is None:
                    hk = self._fholo_ok = all(find_sprite("tpl_%s_card" % n) for n in ("fholo", "fholoframe",
                                                                                      "fholochrome"))
                if hk:
                    return "flagholo_" + card["team"]
            return "flagsig_" + card["team"] if ok[card["team"]] else "sig"
        if card["design"] == "prodigy":
            return "prodigy"
        if card["design"] == "samba":
            return "samba"
        if card["design"] == "starsign":
            return self.star_key(card)
        if card["design"] == "worldsgame":
            # 1 Nov: the evolving card - the flag card's shape, re-coloured per stage (make_wg_evo.py)
            st = int(card.get("wg_stage", 0))
            ok = self.__dict__.setdefault("_wgevo_ok", {})
            if st not in ok:
                ok[st] = (find_sprite("tpl_wgevo%d_card" % st) is not None
                          and find_sprite("tpl_wgevo%dframe_card" % st) is not None)
            if ok[st] and card.get("nation") and self.nation_flag(card["nation"]) is not None:
                return "flagwg%d_%s" % (st, card["nation"])
            return "wg"
        if card["design"] == "limitbreakers":              # pool C: the same card without the crystal
            return "lbc" if pool == "C" else "lb"
        if card["design"] == "beginner":
            return "rookie"
        if card["design"] == "no10":                       # only the No. 10 pack uses the three pool looks
            return {"A": "eclipse", "B": "neon", "C": "street"}[pool]
        # World Cup cards, pool A and B: the flag flying behind a shimmering frame
        if card["kind"] == "wc" and pool in ("A", "B"):
            return ("flag_" if pool == "A" else "flagb_") + card["team"]
        if pool == "A":
            return ("club_" if card["kind"] == "club" else "nat_") + card["team"]
        return "b"

    def flag_card(self, key, w, h, f=0):
        """The World Cup flag card at frame f: the flag waved behind the card, waved again inside it
        (cut to the card's shape), then the frame layers on top. Same (img, ox, oy, bright) as
        card_template. Built at the template's own 400 x 500, then scaled.
        Memory: frame 0 is kept at 400 x 500 (the grids want it at every size); a moving frame is
        only ever shown on the one big card, so only its card-size copy is kept."""
        tier = ("W" + key[6] if key.startswith("flagwg") else "B" if key.startswith("flagb_")
                else "S" if key.startswith("flagsig_") else "H" if key.startswith("flagholo_") else "A")
        code = key.split("_", 1)[1]
        ck = (key, w, h, f)
        cache = self.__dict__.setdefault("_flag_cache", {})
        if ck in cache:
            return cache[ck]
        raw = self.__dict__.setdefault("_flag_raw", {})
        canvas = raw.get((code, tier)) if f == 0 else None
        if canvas is None:
            tick = pygame.time.get_ticks()
            if f and getattr(self, "_flag_built_at", None) == tick:
                # one new frame per game frame at most (the browser must never stall on the flag):
                # until this one is built, show the last one that is
                for back_f in range(f - 1, 0, -1):
                    if (key, w, h, back_f) in cache:
                        return cache[(key, w, h, back_f)]
                return self.flag_card(key, w, h, 0)
            self._flag_built_at = tick
            canvas = self.flag_canvas(code, tier, f)
            if f == 0:
                if len(raw) > 24:
                    raw.clear()
                raw[(code, tier)] = canvas
        if len(cache) > FLAG_FRAMES + 30:
            for k in [k for k in cache if k[3]]:       # drop moving frames first, keep the stills
                del cache[k]
            if len(cache) > 30:
                cache.clear()
        bx0, by0, bx1, by1 = self.TPL_BODY
        kx, ky = w / float(bx1 - bx0), h / float(by1 - by0)
        img = pygame.transform.smoothscale(canvas, (max(1, int(self.TPL_SIZE[0] * kx)),
                                                    max(1, int(self.TPL_SIZE[1] * ky))))
        cache[ck] = (img, int(bx0 * kx), int(by0 * ky), 90)
        return cache[ck]

    def flag_canvas(self, code, tier, f):
        """One frame of the flag card at the template's 400 x 500."""
        parts = self.__dict__.setdefault("_flag_parts", {})
        for name in ("fgold", "fsilver", "fsig", "fholo", "fmask", "wgevo0", "wgevo1", "wgevo2", "wgevo3"):
            if name not in parts:
                parts[name] = load_pixel("tpl_%s_card" % name, self.TPL_SIZE, quiet=True)
        bx0, by0, bx1, by1 = self.TPL_BODY
        canvas = pygame.Surface(self.TPL_SIZE, pygame.SRCALPHA)
        flag = self.evo_flag(code, int(tier[1])) if tier.startswith("W") else self.nation_flag(code)
        if flag is not None:
            # the flag behind the card is dimmed and half hidden: built at a quarter size
            bw, bh = (self.TPL_SIZE[0] + 170) // 4, int((by1 - by0) * 1.04) // 4
            hol = tier == "H"
            back, pad = cloth_surface(flag, bw, bh, f, 0.075, 0.55 if hol else 0.80, 0.0, dim=0.92 if hol else 0.66,
                                      cell=(1, 3))
            back = pygame.transform.smoothscale(back, (bw * 4, back.get_height() * 4))
            canvas.blit(back, (-85, by0 - 8 - pad * 4))
            # the one inside at half size (the card is pixelated coarser than that anyway)
            iw, ih = ((bx1 - bx0) + 30) // 2, ((by1 - by0) + 10) // 2
            inner, pad = cloth_surface(flag, iw, ih, f, 0.050, 0.40 if tier == "H" else 0.68, 1.4, margin=True)
            inner = pygame.transform.smoothscale(inner, (iw * 2, inner.get_height() * 2))
            lay = pygame.Surface(self.TPL_SIZE, pygame.SRCALPHA)
            lay.blit(inner, (bx0 - 15, by0 - 5 - pad * 2))
            if parts.get("fmask") is not None:
                lay.blit(parts["fmask"], (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
            canvas.blit(lay, (0, 0))
        top = parts.get({"A": "fgold", "B": "fsilver", "S": "fsig", "H": "fholo"}.get(tier) or "wgevo" + tier[1:])
        if top is not None:
            canvas.blit(top, (0, 0))
        return canvas

    def card_template(self, key, w, h):
        """Template scaled so its card body is exactly w x h (cached)."""
        ck = (key, w, h)
        cache = self.__dict__.setdefault("_tpl_cache", {})
        if ck in cache:
            return cache[ck]
        raw = self.__dict__.setdefault("_tpl_raw", {})
        if key not in raw:
            raw[key] = load_pixel("tpl_%s_card" % key, self.TPL_SIZE, quiet=True)
        src = raw[key]
        if src is None:
            cache[ck] = None
            return None
        bx0, by0, bx1, by1 = self.TPL_BODY
        kx, ky = w / (bx1 - bx0), h / (by1 - by0)
        img = pygame.transform.smoothscale(src, (max(1, int(self.TPL_SIZE[0] * kx)),
                                                 max(1, int(self.TPL_SIZE[1] * ky))))
        try:                                              # how bright is the top of the card?
            px = [src.get_at((bx0 + 40 + i * 30, by0 + 60 + i * 20))[:3] for i in range(5)]
            bright = sum(0.299 * p[0] + 0.587 * p[1] + 0.114 * p[2] for p in px) / len(px)
        except Exception:
            bright = 100
        cache[ck] = (img, int(bx0 * kx), int(by0 * ky), bright)
        if len(cache) > 400:                     # full: start again, but keep the one just made
            keep = cache[ck]
            cache.clear()
            cache[ck] = keep
        return cache[ck]

    # 28 Oct: Hubi - "make him have an actually good looking signature". The old one was a sine
    # wave in a gold line (and only on a card design nobody saw any more). Now it is drawn as
    # handwriting in make_signature.py: hand-placed pen paths, a slanted broad nib, tapered
    # strokes. Second go the same night ("the signature looks buns"): a thin silver marker line,
    # a big N, the J's tail running back under the name, a one-pixel shadow. Across his chest,
    # climbing a little, the way a shirt gets signed. At normal sizes it is drawn as pixel art
    # (whole pixels, outlined): the game's 3 px grid broke the smooth hairlines into dashes.
    AUTOGRAPHS = {"SIG_BRA_neymar": "sig_neymar", "SIG_ARG_kempes": "sig_kempes"}
    AUTOGRAPH_AT = (0.50, 0.60, 0.82)           # centre x, y (share of the card), width
    HOLO_AUTOGRAPH_AT = (0.52, 0.47, 1.00)      # the holo card: big, climbing up his chest from the left (2 Nov)
    # the pixel versions (make_signature.py's px_sheet): row i is AUTO_PX_MIN + i * AUTO_PX_STEP
    # art pixels wide, in AUTO_PX_SLOT-tall rows. Wider than AUTO_PX_MAX: the smooth one.
    AUTO_PX_MIN, AUTO_PX_MAX, AUTO_PX_STEP, AUTO_PX_SLOT = 36, 160, 2, 80
    # 2 Nov: Kempes's is drawn smooth at every size - a fat glossy marker like the holo card's chrome; on the
    # 3 px grid its strokes went one pixel thin and the letters broke up
    SMOOTH_AUTOGRAPHS = ("sig_kempes",)

    def autograph_img(self, name, width):
        cache = self.__dict__.setdefault("_autographs", {})
        art = int(round(width / float(PIXEL)))
        px = art <= self.AUTO_PX_MAX and name not in self.SMOOTH_AUTOGRAPHS
        key = (name, max(art, self.AUTO_PX_MIN) // self.AUTO_PX_STEP if px else width, px)
        if key in cache:
            return cache[key]
        img = None
        src_name = name + ("_px" if px else "")
        if src_name not in cache:
            path = find_sprite(src_name)
            cache[src_name] = pygame.image.load(path).convert_alpha() if path else None
        src = cache[src_name]
        if src is not None and px:
            i = (max(self.AUTO_PX_MIN, min(self.AUTO_PX_MAX, art)) - self.AUTO_PX_MIN) // self.AUTO_PX_STEP
            rows = (self.AUTO_PX_MAX - self.AUTO_PX_MIN) // self.AUTO_PX_STEP + 1
            slot = max(self.AUTO_PX_SLOT, src.get_height() // rows)      # Kempes's climbs: taller rows
            if (i + 1) * slot <= src.get_height():
                row = src.subsurface(pygame.Rect(0, i * slot, src.get_width(), slot))
                box = row.get_bounding_rect()
                if box.w and box.h:
                    row = row.subsurface(box)
                    img = pygame.transform.scale(row, (row.get_width() * PIXEL, row.get_height() * PIXEL))
        elif src is not None:
            h = max(4, int(src.get_height() * width / float(src.get_width())))
            img = pygame.transform.smoothscale(src, (max(8, int(width)), h))
        if len(cache) > 60:
            cache.clear()
        cache[key] = img
        return img

    def draw_autograph(self, surf, card, rect):
        name = self.AUTOGRAPHS.get(card["id"])
        if name is None:
            return
        fx, fy, fw = self.HOLO_AUTOGRAPH_AT if card["id"] in HOLO_SIG else self.AUTOGRAPH_AT
        img = self.autograph_img(name, rect.w * fw)
        if img is not None:
            surf.blit(img, img.get_rect(center=(rect.x + int(rect.w * fx), rect.y + int(rect.h * fy))))

    def fit_text(self, text, font, colour, max_w, max_h, outline=None):
        key = ("fit", text, id(font), tuple(colour)[:4], int(max_w), int(max_h),
               tuple(outline)[:4] if outline else None)
        hit = self.text_cache.get(key)
        if hit is not None:
            return hit
        img = self.outlined(text, font, colour, 1.0, outline, 3) if outline else font.render(text, True, colour)
        k = min(max_w / max(1, img.get_width()), max_h / max(1, img.get_height()))
        out = pygame.transform.smoothscale(img, (max(1, int(img.get_width() * k)), max(1, int(img.get_height() * k))))
        self.cache_text(key, out)
        return out

    def cache_text(self, key, surf):
        if len(self.text_cache) >= 1500:
            self.text_cache.clear()
        self.text_cache[key] = surf

    # pool A = ECLIPSE (black/purple), pool B = NEON PLAYMAKER (navy/cyan), pool C = STREET (concrete)
    POOL_DESIGNS = {"eclipse": {"accent": (214, 170, 255), "num": (150, 70, 240), "edge": (236, 214, 255),
                                "size": 0.66, "alpha": 170, "at": (0.5, 0.42)},
                    "neon": {"accent": (120, 235, 255), "num": (40, 200, 255), "edge": (200, 250, 255),
                             "size": 0.5, "alpha": 110, "at": (0.5, 0.40)},
                    "street": {"accent": (196, 204, 186), "num": (150, 160, 142), "edge": (60, 70, 60),
                               "size": 0.14, "alpha": 190, "at": (0.84, 0.13)}}

    # 26 Oct: the PlayStyles sit on the card again - Hubi: "top left outside the border but close
    # to it". Their own badges (silver = level 1, gold = level 2), one under the other, mostly
    # outside the frame so they never cover the rating. (Before that: two small diamonds in the
    # top right, which he had taken off.) SHOW_PS_PIPS = False hides them.
    SHOW_PS_PIPS = True
    PS_PIP_SIZE = 0.225          # badge size as a share of the card's width (26 Oct: 50% bigger)

    def draw_ability_pips(self, surf, card, rect):
        """The card's PlayStyle badges down its top-left corner, just outside the border."""
        styles = card.get("ps", ())
        if not self.SHOW_PS_PIPS or not styles or rect.w < 110:
            return
        size = int(clamp(rect.w * self.PS_PIP_SIZE, 30, 87))
        # a baked card face only has so much room round it (the ten-pack grid has 20 px)
        room = getattr(self, "_face_pad", None) if getattr(self, "_baking_face", False) else None
        out = int(size * 0.96)                     # just touching the frame from outside
        if room is not None:
            out = min(out, max(0, room - 2))
        x = rect.x - out
        y = rect.y + int(rect.h * 0.035)
        for ps, level in styles:
            ic = self.ps_icon(ps["key"], size, level)
            if ic is not None:
                surf.blit(ic, (x, y))
            y += size + max(2, size // 8)

    def draw_big_number(self, surf, card, rect, key):
        """The giant shirt number behind the player (small and flat on Street cards)."""
        d = self.POOL_DESIGNS[key]
        h = max(6, int(rect.h * d["size"]))
        img = self.font_xl.render(str(card["number"]), True, d["num"])
        k = h / max(1, img.get_height())
        img = pygame.transform.smoothscale(img, (max(1, int(img.get_width() * k)), h))
        edge = self.font_xl.render(str(card["number"]), True, d["edge"])
        edge = pygame.transform.smoothscale(edge, img.get_size())
        big = pygame.Surface((img.get_width() + 8, img.get_height() + 8), pygame.SRCALPHA)
        for dx, dy in ((0, 4), (4, 0), (8, 4), (4, 8)):
            big.blit(edge, (dx, dy))
        big.blit(img, (4, 4))
        big.set_alpha(d["alpha"])
        surf.blit(big, big.get_rect(center=(rect.x + int(rect.w * d["at"][0]), rect.y + int(rect.h * d["at"][1]))))

    # A card this wide is the one on screen on its own - the reveal, the popup, the player
    # screen. Only that one animates; a grid of twenty stays still, which is what keeps the
    # browser smooth.
    BIG_CARD_W = 280
    SHEEN_EVERY = 3.4                       # seconds between sweeps
    SHEEN_LEN = 1.0                         # how long one sweep takes

    def draw_card_sheen(self, surf, rect, tier="A", dot=True):
        """Light travelling across the card, and a glint running round the arch."""
        if getattr(self, "_baking_face", False):
            return                      # never bake a moving light into a cached card face
        t = pygame.time.get_ticks() * 0.001
        k = (t % self.SHEEN_EVERY) / self.SHEEN_LEN
        if k <= 1.0:
            band = shine_sweep((max(1, rect.w // 2), rect.h))
            x = int(rect.x - rect.w * 0.6 + (rect.w * 1.7) * k)
            prev = surf.get_clip()
            surf.set_clip(rect)
            surf.blit(band, (x, rect.y))
            surf.set_clip(prev)
        if not dot:
            return
        # the glint: a bright dot sliding down the big curve on the right
        a = (t % 2.8) / 2.8
        gy = rect.y + int(rect.h * (0.10 + 0.80 * a))
        bulge = math.sin(math.pi * (gy - rect.y) / max(1, rect.h))
        gx = rect.x + int(rect.w * (0.52 + 0.45 * bulge))
        col = (255, 246, 206) if tier == "A" else (240, 248, 255)
        r = max(2, rect.w // 90)
        pygame.draw.circle(surf, col, (gx, gy), r + 1)
        pygame.draw.circle(surf, (255, 255, 255), (gx, gy), max(1, r - 1))

    # The extra downsample is OFF. It was right when the card showed a photo-like bust; now
    # the card shows our own pixel art, and quantising already-quantised art on a grid that
    # does not line up with it is what turned every face into mush - the two eyes landing in
    # different blocks is exactly why they came out lopsided. Set it back to 32-56 to bring
    # it back.
    PIXEL_BLOCKS = 0

    # The player on a draft card is drawn on the card's own pixel grid. The card's window is
    # FIG_PX art pixels wide and starts FIG_WIN into the sprite; the rest of the sprite is
    # bleed, for arms that run off the card. On the full-size cards (300 to 340 wide) one art
    # pixel is drawn as exactly PIXEL screen pixels - one pixel of the finished frame - so
    # nothing in his face is doubled or dropped. Smaller cards shrink him smoothly instead.
    FIG_SIZE = (160, 170)    # the sprite, in art pixels
    FIG_WIN = (26, 10)       # where the card's window starts inside it
    FIG_PX = 107.0           # how many art pixels span the card's window
    FIG_SNAP = (2.6, 3.3)    # screen pixels per art pixel that count as "full size"

    def fig_scrim(self, w, h, colour=(6, 10, 26)):
        """The dark wash the player's legs fade into, so the name still reads over him.

        The template paints this band, but a figure this big covers it, so it goes back on
        over the top. Cached per size and colour - it is the same for every card of a kind."""
        cache = self.__dict__.setdefault("_scrims", {})
        key = (w, h, tuple(colour))
        if key in cache:
            return cache[key]
        s = pygame.Surface((w, h), pygame.SRCALPHA)
        y0, y1 = int(h * 0.60), int(h * 0.76)
        for y in range(y0, h):
            a = int(242 * min(1.0, (y - y0) / float(max(1, y1 - y0))) ** 1.5)
            pygame.draw.line(s, tuple(colour) + (a,), (0, y), (w, y))
        cache[key] = s
        return s

    def chunky_face(self, card):
        """The portrait, destructively downsampled. Pose and kit colours survive, the face
        does not - and it is done once per card, not per frame."""
        cache = self.__dict__.setdefault("_chunky", {})
        cid = card["id"]
        if cid in cache:
            return cache[cid]
        face = self.card_faces.get(cid)
        if face is None or not self.PIXEL_BLOCKS:
            cache[cid] = face                              # 0 blocks: leave the art alone
            return face
        w, h = face.get_size()
        k = self.PIXEL_BLOCKS / float(max(1, max(w, h)))
        small = pygame.transform.scale(face, (max(1, int(w * k)), max(1, int(h * k))))
        cache[cid] = small
        return small

    def draw_pool_card(self, surf, card, rect, count=0, stamina=None, dim=False, glow=False):
        key = self.card_template_key(card)
        flagcard = key.startswith(("flag_", "flagb_", "flagsig_", "flagwg", "flagholo_"))
        holo = key.startswith("flagholo_")
        sigcard = key == "sig" or key.startswith(("flagsig_", "flagholo_"))
        baking = getattr(self, "_baking_face", False)
        live_over = False
        t = pygame.time.get_ticks() * 0.001
        if glow:                                           # first: the moving half goes over it
            pulse = int(10 + 6 * (0.5 + 0.5 * math.sin(t * 3)))
            pygame.draw.rect(surf, YELLOW, rect.inflate(pulse, pulse), border_radius=16)
        top = self.live_top_key(key)
        if top and getattr(self, "_split_face", False):
            # a face baked for blit_card with its moving part left out: blit_card draws the
            # waving flag / the lightning under it every frame
            tpl = self.card_template(top, rect.w, rect.h)
        elif top and not baking and not (flagcard and rect.w >= self.BIG_CARD_W and not dim) \
                and self.live_under(surf, key, rect, card):
            tpl = self.card_template(top, rect.w, rect.h)
            live_over = True
        elif flagcard:                                     # the big card: the full-size flag
            live = rect.w >= self.BIG_CARD_W and not dim and not baking
            f = int(pygame.time.get_ticks() * 0.001 * FLAG_FPS) % FLAG_FRAMES if live and not FLAG_STILL else 0
            tpl = self.flag_card(key, rect.w, rect.h, f)
        else:
            tpl = self.card_template(key, rect.w, rect.h)
        wg = key == "wg"                                   # purple flag, rainbow-silver border, stars
        lb = key in ("lb", "lbc")                          # Limit Breakers: red storm, silver frame
        if tpl is None:                                    # art missing: a plain card in its colours
            pygame.draw.rect(surf, (96, 40, 190) if wg else (226, 186, 72), rect, border_radius=14)
            if wg:
                pygame.draw.rect(surf, WG_SILVER, rect, max(2, rect.w // 40), border_radius=14)
        else:
            img, ox, oy, _b = tpl
            surf.blit(img, (rect.x - ox, rect.y - oy))
        W, H = rect.w, rect.h
        pool_key = key in self.POOL_DESIGNS
        light = not pool_key and (key == "b" or (tpl is not None and tpl[3] > 165
                                                and not key.startswith(("sig", "prodigy", "holo", "flag", "champ_", "stargold"))
                                                and key not in WC_SPECIAL_KEYS))
        ink = (20, 28, 76) if light else WHITE
        gold = (150, 104, 14) if light else (246, 206, 100)
        if wg:
            gold = WG_SILVER
        if lb:
            gold = LB_PINK
        if pool_key:
            gold = self.POOL_DESIGNS[key]["accent"]
            self.draw_big_number(surf, card, rect, key)    # the giant shirt number behind the player
        # faded crest / flag behind the player on club + nation cards
        badge = self.card_badge(card)
        if key.startswith(("club_", "nat_")) and badge is not None:
            ghost = fit_flag(badge, int(W * 0.62), int(H * 0.36)).copy()
            ghost.set_alpha(70)
            surf.blit(ghost, ghost.get_rect(center=(rect.x + int(W * 0.62), rect.y + int(H * 0.25))))
        # portrait
        face = self.chunky_face(card) if key.startswith("holo") else self.card_faces.get(card["id"])
        if face is not None:
            # a whole posed player needs more room above him than a bust does, and sits
            # nearer the middle of the card instead of tucked to the right of the rating
            whole = card["id"] in getattr(self, "card_figs", ())
            if whole:
                # He is a waist shot clipped to the card, so his arms crop at the frame the
                # way they do on a real card. All the figures share one lens and one sprite
                # frame, so they all land at the same size.
                keep = surf.get_clip()
                inset = rect.inflate(-int(W * 0.055), -int(H * 0.045))
                s = inset.w / self.FIG_PX                  # screen pixels per art pixel
                if self.FIG_SNAP[0] <= s <= self.FIG_SNAP[1]:
                    s = float(PIXEL)                       # full size: keep every art pixel whole
                size = (max(1, int(round(face.get_width() * s))),
                        max(1, int(round(face.get_height() * s))))
                img = scaled(face, size) if s >= PIXEL else smooth_scaled(face, size)
                if keep is not None:
                    x0, y0 = max(inset.x, keep.x), max(inset.y, keep.y)
                    x1, y1 = min(inset.right, keep.right), min(inset.bottom, keep.bottom)
                    surf.set_clip(pygame.Rect(x0, y0, max(0, x1 - x0), max(0, y1 - y0)))
                else:
                    surf.set_clip(inset)
                surf.blit(img, (inset.centerx - int(round((self.FIG_WIN[0] + self.FIG_PX / 2.0) * s)),
                                inset.y - int(round(self.FIG_WIN[1] * s))))
                surf.blit(self.fig_scrim(inset.w, inset.h, WG_PLATE if wg else (18, 0, 6) if lb else
                                         (6, 12, 40) if key == "gcr" else (8, 14, 12) if key == "dpor"
                                         else (16, 9, 2) if key == "stargold"
                                         else (6, 10, 26)),
                          inset.topleft)
                surf.set_clip(keep)
                # the border (and on a Limit Breaker the crystal, the laurels and a snapped chain)
                # goes back on in front of him; the gem at the foot stays behind him
                over_key = {"wg": "wgframe", "lb": "lbframe", "lbc": "lbcframe",
                            "gcr": "gcrframe", "dpor": "dporframe", "stargold": "stargoldframe"}.get(key)
                if key.startswith("champ_"):
                    over_key = "champframe"
                if flagcard:
                    over_key = ("fsilverframe" if key.startswith("flagb_") else
                                "fsigframe" if key.startswith("flagsig_") else
                                "fholoframe" if holo else
                                "wgevo%sframe" % key[6] if key.startswith("flagwg") else "fgoldframe")
                over = self.card_template(over_key, rect.w, rect.h) if over_key else None
                if over is not None:                       # the border goes back on in front of him
                    surf.blit(over[0], (rect.x - over[1], rect.y - over[2]))
            else:
                fw = int(W * 0.86)
                img = scaled(face, (fw, fw))
                surf.blit(img, img.get_rect(midbottom=(rect.x + W // 2 + int(W * 0.09),
                                                       rect.y + int(H * 0.715))))
        else:
            head = self.card_head(card)
            if head is not None:
                hh = fit_flag(head, int(W * 0.5), int(W * 0.5))
                surf.blit(hh, hh.get_rect(center=(rect.centerx, rect.y + int(H * 0.42))))
        # his autograph across the shirt - on the holo card it's drawn live (it pulses), unless this face is
        # one that will never move (dimmed, or baked whole)
        live_sig = holo and ((baking and getattr(self, "_split_face", False)) or (not baking and not dim))
        if sigcard and not live_sig:
            self.draw_autograph(surf, card, rect)
        # rating + position (+ the nation flag beside the rating on the pool designs)
        num = self.fit_text(str(card["rating"]), self.font_xl, ink, W * 0.38, H * 0.11,
                            (250, 250, 252) if light else (10, 14, 30))
        pos = self.fit_text(card["pos"], self.font_m, gold, W * 0.3, H * 0.065)
        nx, ny = rect.x + int(W * 0.06), rect.y + int(H * 0.03)
        px_, py = rect.x + int(W * 0.075), rect.y + int(H * 0.035) + num.get_height()
        if wg or lb or key in WC_SPECIAL_KEYS or key.startswith(("holo", "sig", "flag", "champ_", "stargold")):
            # Poland, England and the white half of France are pale exactly where the rating
            # goes. A soft dark lozenge under it keeps white text readable on every flag.
            pw = max(num.get_width(), pos.get_width()) + int(W * 0.10)
            ph = num.get_height() + pos.get_height() + int(H * 0.028)
            sh = pygame.Surface((pw, ph), pygame.SRCALPHA)
            for i, a in enumerate((32, 40, 50)):
                pygame.draw.rect(sh, ((16, 6, 36, a) if wg else (20, 0, 6, a) if lb else (3, 7, 20, a)),
                                 sh.get_rect().inflate(-i * 8, -i * 8),
                                 border_radius=max(4, int(ph * 0.3)))
            surf.blit(sh, (nx - int(W * 0.035), ny - int(H * 0.016)))
        surf.blit(num, (nx, ny))
        surf.blit(pos, (px_, py))
        if pool_key:
            flag = self.card_flag(card)
            if flag is not None:
                fl = fit_flag(flag, int(W * 0.17), int(H * 0.07))
                surf.blit(fl, fl.get_rect(midleft=(rect.x + int(W * 0.06) + num.get_width() + int(W * 0.03),
                                                   rect.y + int(H * 0.03) + num.get_height() // 2)))
        if key == "prodigy":                               # PRODIGY ribbon
            rib = pygame.Rect(0, 0, int(W * 0.46), int(H * 0.055))
            rib.midtop = (rect.centerx, rect.y + int(H * 0.005))
            pygame.draw.rect(surf, CYAN, rib, border_radius=6)
            lab = self.fit_text("PRODIGY", self.font_s, (8, 20, 30), rib.w * 0.8, rib.h * 0.8)
            surf.blit(lab, lab.get_rect(center=rib.center))
        if sigcard and not holo:                           # SIGNATURE banner, pinned to the top edge
            rib = pygame.Rect(0, 0, int(W * 0.52), int(H * 0.058))
            rib.midtop = (rect.centerx, rect.y - int(H * 0.032))
            pygame.draw.rect(surf, (28, 20, 6), rib.inflate(int(W * 0.02), int(H * 0.012)),
                             border_radius=int(H * 0.03))
            pygame.draw.rect(surf, (236, 196, 90), rib, border_radius=int(H * 0.028))
            pygame.draw.rect(surf, (255, 240, 182), rib.inflate(-int(W * 0.012), -int(H * 0.012)),
                             width=max(1, int(W / 140)), border_radius=int(H * 0.024))
            lab = self.fit_text("SIGNATURE", self.font_s, (56, 36, 6), rib.w * 0.8, rib.h * 0.78)
            surf.blit(lab, lab.get_rect(center=rib.center))
            for side in (-1, 1):                           # a gold rule under the name, either side
                ex = rect.centerx + side * int(W * 0.40)
                pygame.draw.line(surf, (236, 200, 108), (rect.centerx + side * int(W * 0.14),
                                 rect.y + int(H * 0.825)), (ex, rect.y + int(H * 0.825)),
                                 max(PIXEL, int(W / 150)))      # under 3 px the pixel grid drops it
        # name in the band
        name = card["name"].upper()
        if len(name) > 13 and " " in name:
            name = name.split()[-1]
        name_col = (70, 44, 8) if key == "icon" and card["id"] not in getattr(self, "card_figs", ()) else WHITE
        nm = self.fit_text(name, self.font_m, name_col, W * 0.86, H * 0.075)
        surf.blit(nm, nm.get_rect(center=(rect.centerx, rect.y + int(H * 0.775))))
        # flag / crest row
        row_y = rect.y + int(H * 0.87)
        flag = self.card_flag(card)
        items = [] if pool_key else ([flag] if flag is not None else [])
        if card["kind"] in ("club", "star") and badge is not None:     # (a Star Signing: country | club)
            items.append(badge)
        n = len(items)
        for i, im in enumerate(items):
            b = fit_flag(im, int(W * 0.17), int(H * 0.07))
            cx = rect.centerx + int((i - (n - 1) / 2) * W * 0.24)
            surf.blit(b, b.get_rect(center=(cx, row_y)))
        if n == 2:
            pygame.draw.line(surf, gold, (rect.centerx, row_y - int(H * 0.03)), (rect.centerx, row_y + int(H * 0.03)),
                             max(PIXEL, int(W / 140)))
        # shirt number on the gold plate (club / nation designs)
        if key.startswith(("club_", "nat_", "sig", "flagsig_")):
            nb = self.fit_text(str(card["number"]), self.font_m, (90, 60, 10), W * 0.14, H * 0.05)
            surf.blit(nb, nb.get_rect(center=(rect.centerx, rect.y + int(H * 1.014))))
        if (wg or key in WC_SPECIAL_KEYS or key.startswith(("holo", "sig", "flag", "champ_", "stargold"))) \
                and W >= self.BIG_CARD_W and not dim:
            # no sliding glint on the flag card: it ran down the old card's arch, and on this shape it
            # floated over the flag like a stray speck
            self.draw_card_sheen(surf, rect, "B" if key.startswith(("holob_", "flagb_")) else "A",
                                 dot=not wg and not key.startswith(("flag", "champ_", "stargold")))
        if wg:                                             # stars last: they sit on the border
            self.draw_wg_stars(surf, rect, moving=not getattr(self, "_baking_face", False))
        self.card_overlays(surf, rect, count, stamina, dim, card)
        if live_over or (holo and not baking and not dim):     # (the big holo card moves too)
            self.live_over(surf, key, rect, card)

    # ---- the stars round a World's Game card ------------------------------------------
    # (x, y as a fraction of the card, radius as a fraction of its width, phase)
    WG_STARS = ((-0.072, 0.640, 0.082, 0.0), (0.040, 0.945, 0.118, 1.7), (1.045, 0.300, 0.104, 3.1),
                (1.078, 0.590, 0.066, 4.4), (0.330, -0.012, 0.056, 5.6))

    def wg_star_at(self, rect, i, t, moving):
        """(centre x, centre y, radius, rotation) of star i at time t."""
        fx, fy, fs, ph = self.WG_STARS[i]
        r = rect.w * fs
        rot = -math.pi / 2 + ph * 0.21
        cx, cy = rect.x + rect.w * fx, rect.y + rect.h * fy
        if moving:                                         # rock, breathe and bob - each on its own beat
            r *= 1.0 + 0.11 * math.sin(t * 2.3 + ph)
            rot += 0.30 * math.sin(t * 1.4 + ph * 1.7)
            cy += math.sin(t * 1.1 + ph) * rect.h * 0.007
        return cx, cy, r, rot

    @staticmethod
    def star_outline(cx, cy, r_out, r_in, rot):
        pts = []
        for k in range(10):
            a = rot + k * math.pi / 5
            r = r_out if k % 2 == 0 else r_in
            pts.append((cx + math.cos(a) * r, cy + math.sin(a) * r))
        return pts

    def draw_silver_star(self, surf, cx, cy, r, rot):
        """A five-point star cut like a gem: every arm has a bright side and a dull side."""
        pygame.draw.polygon(surf, (44, 28, 80), self.star_outline(cx, cy, r * 1.16, r * 0.54, rot))
        pts = self.star_outline(cx, cy, r, r * 0.44, rot)
        for k in range(5):
            tip, a, b = pts[2 * k], pts[(2 * k - 1) % 10], pts[(2 * k + 1) % 10]
            pygame.draw.polygon(surf, (240, 244, 252), [(cx, cy), a, tip])
            pygame.draw.polygon(surf, (142, 148, 180), [(cx, cy), tip, b])

    @staticmethod
    def draw_glint(surf, x, y, s):
        """A four-point flash of light."""
        if s < 2:
            return
        w = s * 0.24
        pygame.draw.polygon(surf, (255, 255, 255), [(x, y - s), (x + w, y - w), (x + s, y), (x + w, y + w),
                                                    (x, y + s), (x - w, y + w), (x - s, y), (x - w, y - w)])

    def draw_wg_glints(self, surf, rect, t=None):
        """The moving part on its own: a flash crossing each star in turn, sparks round the border.
        Cheap enough to draw over a cached card every frame."""
        t = pygame.time.get_ticks() * 0.001 if t is None else t
        n = len(self.WG_STARS)
        for i in range(n):
            g = (t * 0.5 + i / float(n)) % 1.0
            if g < 0.18:
                cx, cy, r, _rot = self.wg_star_at(rect, i, t, False)
                self.draw_glint(surf, cx - r * 0.20, cy - r * 0.26, r * (0.22 + 0.58 * math.sin(math.pi * g / 0.18)))
        for k in range(6):                                 # sparks: fixed spots, each winking on its own beat
            a = (t * (0.31 + 0.05 * k) + k * 0.37) % 1.0
            if a < 0.3:
                fx = (0.02, 0.98, 0.50, 0.04, 0.96, 0.72)[k]
                fy = (0.18, 0.80, -0.01, 0.42, 0.06, 1.0)[k]
                self.draw_glint(surf, rect.x + rect.w * fx, rect.y + rect.h * fy,
                                rect.w * 0.035 * math.sin(math.pi * a / 0.3))

    def draw_wg_stars(self, surf, rect, moving=True):
        """Live, the stars rock and breathe and catch the light; baked into a cached card
        face they hold still (blit_card then adds the flashes on top)."""
        t = pygame.time.get_ticks() * 0.001 if moving else 0.0
        for i in range(len(self.WG_STARS)):
            cx, cy, r, rot = self.wg_star_at(rect, i, t, moving)
            if r >= 3:
                self.draw_silver_star(surf, cx, cy, r, rot)
        if moving:
            self.draw_wg_glints(surf, rect, t)

    def draw_icon_card(self, surf, card, rect, count=0, stamina=None, dim=False, glow=False):
        """Big detailed icon card: gold shard frame, portrait, rating, name bar."""
        k = rect.w / 300.0
        t = pygame.time.get_ticks() * 0.001
        sig = card["design"] == "signature"
        gold, deep, navy = (236, 198, 96), (150, 112, 30), ((0, 110, 52) if sig else (18, 26, 62))
        pulse = int(10 + 8 * (0.5 + 0.5 * math.sin(t * 3)))
        aura = glow_blob((rect.w + 120, rect.h + 120), (255, 226, 140), 55 if not glow else 95)
        surf.blit(aura, aura.get_rect(center=rect.center))
        if glow:
            pygame.draw.rect(surf, YELLOW, rect.inflate(pulse, pulse), border_radius=int(18 * k))
        # frame
        pygame.draw.rect(surf, deep, rect, border_radius=int(14 * k))
        pygame.draw.rect(surf, gold, rect.inflate(int(-6 * k), int(-6 * k)), border_radius=int(12 * k))
        inner = rect.inflate(int(-24 * k), int(-24 * k))
        pygame.draw.rect(surf, navy, inner, border_radius=int(8 * k))
        # shattered-glass backdrop inside the card
        rng = random.Random(hash(card["id"]) & 0xffff)
        clip = surf.get_clip()
        surf.set_clip(inner)
        if sig:                                              # Brazil flag behind the player
            cx, cy = inner.centerx, inner.y + int(inner.h * 0.42)
            dw, dh = int(inner.w * 0.62), int(inner.h * 0.36)
            pygame.draw.polygon(surf, (236, 200, 30), [(cx - dw, cy), (cx, cy - dh), (cx + dw, cy), (cx, cy + dh)])
            pygame.draw.circle(surf, (24, 46, 130), (cx, cy), int(dh * 0.62))
            pygame.draw.arc(surf, WHITE, pygame.Rect(cx - dh, cy - int(dh * 0.35), dh * 2, dh * 2), 1.05, 2.1,
                            max(2, int(4 * k)))
        for _ in range(0 if sig else 16):
            x = inner.x + rng.random() * inner.w
            y = inner.y + rng.random() * inner.h * 0.8
            s = (18 + rng.random() * 60) * k
            a = rng.uniform(0, math.tau)
            pts = [(x + math.cos(a + j * 2.1) * s * (0.5 + 0.5 * rng.random()),
                    y + math.sin(a + j * 2.1) * s * (0.5 + 0.5 * rng.random())) for j in range(4)]
            shade = rng.random()
            col = _shade((34, 48, 110), 0.7 + shade * 0.9) if shade < 0.75 else _shade(gold, 0.55)
            pygame.draw.polygon(surf, col, pts)
        for j in range(0 if sig else 4):                     # gold rays behind the player
            x0 = inner.x + int(inner.w * (0.12 + j * 0.26))
            pygame.draw.polygon(surf, _shade(gold, 0.45),
                                [(x0, inner.bottom), (x0 + int(40 * k), inner.y),
                                 (x0 + int(64 * k), inner.y), (x0 + int(28 * k), inner.bottom)])
        surf.set_clip(clip)
        # portrait
        face = self.icon_faces.get(card["id"])
        if face is not None:
            fh = int(inner.h * 0.58)
            fw = int(fh * face.get_width() / face.get_height())
            img = pygame.transform.scale(face, (max(1, fw), max(1, fh)))
            surf.blit(img, img.get_rect(midbottom=(inner.centerx + int(14 * k), inner.bottom - int(98 * k))))
        else:
            head = self.card_head(card)
            if head is not None:
                hh = fit_flag(head, int(150 * k), int(150 * k))
                surf.blit(hh, hh.get_rect(center=(inner.centerx, inner.y + int(150 * k))))
        # rating + position, top left, FC Mobile style
        rt = self.font_xl if k > 0.75 else self.font_l
        num = rt.render(str(card["rating"]), True, WHITE)
        sc = (56 * k) / num.get_height()
        num = pygame.transform.smoothscale(num, (max(1, int(num.get_width() * sc)), max(1, int(56 * k))))
        shadow = num.copy()
        shadow.fill((0, 0, 0), special_flags=getattr(pygame, "BLEND_RGB_MULT", 0))
        surf.blit(shadow, (inner.x + int(16 * k) + 3, inner.y + int(18 * k) + 3))
        surf.blit(num, (inner.x + int(16 * k), inner.y + int(18 * k)))
        pos = self.font_m.render(card["pos"], True, gold)
        sc = (30 * k) / pos.get_height()
        pos = pygame.transform.smoothscale(pos, (max(1, int(pos.get_width() * sc)), max(1, int(30 * k))))
        surf.blit(pos, (inner.x + int(18 * k), inner.y + int(80 * k)))
        pygame.draw.line(surf, gold, (inner.x + int(16 * k), inner.y + int(116 * k)),
                         (inner.x + int(16 * k) + pos.get_width(), inner.y + int(116 * k)), max(2, int(3 * k)))
        # ICON banner top right
        rib = pygame.Rect(0, 0, int((130 if sig else 80) * k), int(28 * k))
        rib.topright = (inner.right - int(14 * k), inner.y + int(16 * k))
        if sig:                                              # ribbon on the top edge of the frame
            rib.midtop = (rect.centerx, rect.y + int(2 * k))
        pygame.draw.polygon(surf, gold, [(rib.x, rib.y), (rib.right, rib.y),
                                         (rib.right, rib.bottom), (rib.x + int(14 * k), rib.bottom)])
        lab = self.font_s.render("SIGNATURE" if sig else "ICON", True, (40, 30, 8))
        sc = (rib.h * 0.66) / lab.get_height()
        lab = pygame.transform.smoothscale(lab, (max(1, int(lab.get_width() * sc)), max(1, int(rib.h * 0.66))))
        surf.blit(lab, lab.get_rect(center=(rib.centerx + int(4 * k), rib.centery)))
        if sig:                                              # gold autograph across the shirt
            pts = []
            x0, y0 = inner.x + int(inner.w * 0.2), inner.bottom - int(104 * k)
            for i in range(40):
                tt = i / 39.0
                pts.append((x0 + tt * inner.w * 0.6, y0 + math.sin(tt * 13.0) * 8 * k * (1 - tt * 0.5) - tt * 14 * k))
            pygame.draw.lines(surf, (255, 230, 130), False, pts, max(2, int(3 * k)))
        # name bar
        bar = pygame.Rect(inner.x, inner.bottom - int(92 * k), inner.w, int(40 * k))
        surf.blit(tint((bar.w, bar.h), (8, 12, 30, 210)), bar.topleft)
        pygame.draw.line(surf, gold, bar.topleft, bar.topright, max(2, int(2 * k)))
        pygame.draw.line(surf, gold, bar.bottomleft, bar.bottomright, max(2, int(2 * k)))
        nm = self.label(card["name"].upper(), bar.w - int(16 * k), gold)
        if nm.get_height() > bar.h * 0.8:
            s2 = bar.h * 0.8 / nm.get_height()
            nm = pygame.transform.smoothscale(nm, (max(1, int(nm.get_width() * s2)), max(1, int(bar.h * 0.8))))
        surf.blit(nm, nm.get_rect(center=bar.center))
        # crest + team row
        badge = self.card_badge(card)
        row_y = bar.bottom + int(24 * k)
        name_txt = self.team_name(card)
        nat = self.font_s.render(name_txt[:14], True, gold)
        sc2 = (20 * k) / nat.get_height()
        nat = pygame.transform.smoothscale(nat, (max(1, int(nat.get_width() * sc2)), max(1, int(20 * k))))
        crest_w = int(54 * k) if badge is not None else 0
        total = crest_w + int(10 * k) + nat.get_width()
        x = inner.centerx - total // 2
        if badge is not None:
            bimg = fit_flag(badge, crest_w, int(38 * k))
            surf.blit(bimg, bimg.get_rect(center=(x + crest_w // 2, row_y)))
            x += crest_w + int(10 * k)
            pygame.draw.line(surf, gold, (x - int(5 * k), row_y - int(14 * k)),
                             (x - int(5 * k), row_y + int(14 * k)), max(1, int(2 * k)))
        surf.blit(nat, nat.get_rect(midleft=(x, row_y)))
        # gem at the bottom
        gx, gy, gs = inner.centerx, inner.bottom - int(14 * k), int(13 * k)
        pygame.draw.polygon(surf, (150, 230, 255),
                            [(gx, gy - gs), (gx + gs, gy), (gx, gy + gs), (gx - gs, gy)])
        pygame.draw.polygon(surf, WHITE, [(gx, gy - gs), (gx + gs, gy), (gx, gy + gs), (gx - gs, gy)],
                            max(1, int(2 * k)))
        # shine sweep
        surf.blit(shine_sweep((inner.w, inner.h)), inner.topleft)
        if count > 1:
            c = self.font_s.render("x%d" % count, True, WHITE)
            pygame.draw.circle(surf, (200, 40, 40), (rect.right - 8, rect.bottom - 8), 24)
            surf.blit(c, c.get_rect(center=(rect.right - 8, rect.bottom - 8)))
        if stamina is not None:
            b2 = pygame.Rect(rect.x, rect.bottom + 8, rect.w, 16)
            pygame.draw.rect(surf, (30, 30, 30), b2)
            col = (90, 220, 90) if stamina > 50 else ((240, 200, 60) if stamina > 0 else (220, 60, 60))
            pygame.draw.rect(surf, col, (b2.x, b2.y, int(b2.w * stamina / 100), b2.h))
            pygame.draw.rect(surf, WHITE, b2, 2)
        if dim:
            surf.blit(tint((rect.w, rect.h), (0, 0, 0, 150)), rect.topleft)

    CARD_PAD = 64            # room for what hangs outside a card: the icon aura, ribbons, stamina bar

    def card_face(self, card, size, count=0, stamina=None, dim=False, pad=None, split=False):
        """A card drawn once into its own surface and kept.

        Drawing a card means dozens of rectangles, lines and bits of text. A screen full of
        them - the ten-pack reveal, my club, the exchange - was doing all of that for every
        card on every frame. Now it happens once per card and size, and the frame is a blit."""
        cache = getattr(self, "_faces", None)
        if cache is None:
            cache = self._faces = _Cache()
        w, h = max(1, int(size[0])), max(1, int(size[1]))
        pad = self.CARD_PAD if pad is None else int(pad)
        key = (card["id"], w, h, count, stamina, bool(dim), pad, self.prog_sig(card), bool(split))
        surf = cache.get(key)
        if surf is None:
            _budget(cache, (w + pad * 2, h + pad * 2), 8)
            surf = pygame.Surface((w + pad * 2, h + pad * 2), pygame.SRCALPHA)
            self._baking_face, self._face_pad, self._split_face = True, pad, bool(split)
            try:
                self.draw_card(surf, card, pygame.Rect(pad, pad, w, h), count, stamina, dim)
            finally:
                self._baking_face = self._split_face = False
            cache[key] = surf
        return surf

    def card_back_face(self, size, pad=None):
        """The back of a card, padded like a face so a flip lines up."""
        cache = getattr(self, "_backs", None)
        if cache is None:
            cache = self._backs = _Cache()
        w, h = max(1, int(size[0])), max(1, int(size[1]))
        pad = self.CARD_PAD if pad is None else int(pad)
        surf = cache.get((w, h, pad))
        if surf is None:
            _budget(cache, (w + pad * 2, h + pad * 2), 3)
            surf = pygame.Surface((w + pad * 2, h + pad * 2), pygame.SRCALPHA)
            inner = pygame.Rect(pad, pad, w, h)
            if self.card_back is not None:
                surf.blit(scaled(self.card_back, inner.size), inner)
            else:
                pygame.draw.rect(surf, (16, 20, 40), inner, border_radius=14)
            cache[(w, h, pad)] = surf
        return surf

    def blit_card(self, target, card, rect, count=0, stamina=None, dim=False, glow=False):
        """draw_card, but from the cache. The glow ring is drawn live so it still pulses."""
        if glow:
            t = pygame.time.get_ticks() * 0.001
            pulse = int(10 + 6 * (0.5 + 0.5 * math.sin(t * 3)))
            pygame.draw.rect(target, YELLOW, rect.inflate(pulse, pulse), border_radius=16)
        split = self.blit_live_under(target, card, rect, dim, self.CARD_PAD)
        face = self.card_face(card, rect.size, count, stamina, dim, split=split)
        target.blit(face, (rect.x - self.CARD_PAD, rect.y - self.CARD_PAD))
        if split:
            self.live_over(target, self.card_template_key(self.upgraded(card)), rect, card)
        if card["design"] == "worldsgame" and not dim and self.card_template_key(self.upgraded(card)) == "wg":
            self.draw_wg_glints(target, rect)          # its stars are in the cache; the light on them is not

    # ---- cards that move everywhere, not just on the big card ---------------------------
    # 27 Oct: Hubi - "why are the flags not animated in the world cup pack and same with the
    # limit breakers". The flag only waved on the one big card (a grid of baked faces was the
    # price of a smooth browser) and the Limit Breakers storm was one still picture.
    # Now both cards come in two halves: the part that moves (the flag cloth; the lightning
    # over the storm) is drawn first, every frame, and the rest of the card - the frame, the
    # player, the text - is still baked once and laid over it. Same picture as before, because
    # the card was always drawn bottom to top in exactly that order.
    LIVE_MIN_W = 90              # smaller than this nobody can see it move
    LIVE_MAX = 24                # moving cards per frame at most (a full club grid stays smooth)
    CLOTH_LO = 4                 # small cards: the flag is built at a quarter of the template
    CLOTH_BUDGET_MS = 4.0        # flag frames built per game frame, at most this long

    def live_top_key(self, key):
        """The template for the still half of a moving card, or None."""
        if key.startswith("flag_"):
            top = "fgold"
        elif key.startswith("flagwg"):
            top = "wgevo" + key[6]
        elif key.startswith("flagb_"):
            top = "fsilver"
        elif key.startswith("flagsig_"):
            top = "fsig"
        elif key.startswith("flagholo_"):
            top = "fholo"
        elif key in ("lb", "lbc"):
            top = key + "top"
        elif key == "stargold":                            # 1 Nov: nothing waves - it glows and shines
            return "stargold"
        elif key.startswith("champ_"):
            top = "champtop_" + key[6:]
            ok = self.__dict__.setdefault("_live_ok", {})
            if top not in ok:                              # old sprites folder: stay still
                ok[top] = (find_sprite("tpl_%s_card" % top) is not None
                           and find_sprite("champpen_" + key[6:]) is not None)
            return top if ok[top] else None
        else:
            return None
        ok = self.__dict__.setdefault("_live_ok", {})
        if top not in ok:                                  # old sprites folder: stay still
            back = None if top.startswith(("f", "wgevo")) else key + "back"
            ok[top] = find_sprite("tpl_%s_card" % top) is not None and \
                (back is None or find_sprite("tpl_%s_card" % back) is not None)
        return top if ok[top] else None

    def live_slot(self):
        """One more moving card this frame? (LIVE_MAX of them; the rest hold still)"""
        tick = pygame.time.get_ticks()
        if getattr(self, "_live_tick", None) != tick:
            self._live_tick, self._live_n = tick, 0
        self._live_n += 1
        return self._live_n <= self.LIVE_MAX

    def blit_live_under(self, target, card, rect, dim, pad, draw=True):
        """For blit_card and the ten-pack grid: draw the moving half of a card under where its
        baked face goes. True if the face should then be baked without it."""
        if rect.w < self.LIVE_MIN_W:                       # (a card you don't own moves too, darkened)
            return False
        card = self.upgraded(card)
        if card["design"] == "beginner" or (card["design"] == "starsign" and self.star_key(card) == "star"):
            return False
        key = self.card_template_key(card)
        if not self.live_top_key(key):
            return False
        if not draw:
            return True
        keep = target.get_clip()
        area = rect.inflate(pad * 2, pad * 2)
        target.set_clip(area.clip(keep) if keep is not None else area)
        try:
            return self.live_under(target, key, rect, card)
        finally:
            target.set_clip(keep)

    def live_under(self, surf, key, rect, card):
        """The moving half of a flag or Limit Breakers card, at rect. False if there is no room
        for another moving card this frame (then the card is drawn still, all in one)."""
        if not self.live_slot():
            return False
        bx0, by0, bx1, by1 = self.TPL_BODY
        if key.startswith(("flag_", "flagb_", "flagsig_", "flagwg", "flagholo_")):
            code = key.split("_", 1)[1]
            beat = int(pygame.time.get_ticks() * 0.001 * FLAG_FPS)
            f = 0 if FLAG_STILL else (beat + sum(map(ord, code)) * 7) % FLAG_FRAMES   # every nation on its own beat
            stage = int(key[6]) if key.startswith("flagwg") else "H" if key.startswith("flagholo_") else None
            if stage == 3:                                   # LIMITLESS: an aura behind the card
                self.draw_aura_glow(surf, rect, card["id"], WG_EVO_AURA)
            lo = self.flag_cloth(code, f, stage)
            if lo is None:
                return False
            kx, ky = rect.w / float(bx1 - bx0), rect.h / float(by1 - by0)
            img = pygame.transform.scale(lo, (max(1, int(self.TPL_SIZE[0] * kx)),
                                              max(1, int(self.TPL_SIZE[1] * ky))))
            surf.blit(img, (rect.x - int(bx0 * kx), rect.y - int(by0 * ky)))
            return True
        if key == "stargold":                              # a warm gold glow behind the big card
            if rect.w >= self.BIG_CARD_W:
                self.draw_aura_glow(surf, rect, card["id"], STAR_GOLD_AURA)
            return True
        if key.startswith("champ_"):                       # the pennants, waving behind the card
            if card.get("id") in CARD_AURA:
                self.draw_aura_glow(surf, rect, card["id"])
            return self.draw_champ_pennants(surf, key[6:], rect)
        back = self.card_template(key + "back", rect.w, rect.h)
        if back is None:
            return False
        surf.blit(back[0], (rect.x - back[1], rect.y - back[2]))
        self.draw_lb_storm(surf, rect, card["id"])
        return True

    def evo_flag(self, code, stage):
        """A nation's flag with only some of its colour: grey at stage 0, full at the last.
        Built once per nation and stage (pygame's grayscale where it has one, else by hand)."""
        if stage is None:
            return self.nation_flag(code)
        cache = self.__dict__.setdefault("_evo_flags", {})
        ck = (code, stage)
        if ck in cache:
            return cache[ck]
        src = self.nation_flag(code)
        if src is None:
            return None
        sat = WG_EVO_SAT[max(0, min(len(WG_EVO_SAT) - 1, int(stage)))]
        if sat >= 0.999:
            out = src
        else:
            try:
                grey = pygame.transform.grayscale(src)
            except Exception:
                grey = src.copy()
                w_, h_ = grey.get_size()
                for y in range(h_):
                    for x in range(w_):
                        r, g, b, a = grey.get_at((x, y))
                        v = int(0.299 * r + 0.587 * g + 0.114 * b)
                        grey.set_at((x, y), (v, v, v, a))
            out = grey.copy()
            if sat > 0.0:
                col = src.copy()
                col.set_alpha(int(255 * sat))
                out.blit(col, (0, 0))
        cache[ck] = out
        return out

    def flag_cloth(self, code, f, stage=None):
        """The waving flags of a World Cup card (the one behind it and the one inside it, cut to
        its shape) at frame f, without the frame: a small 100 x 125 picture of the whole
        template, kept per nation and frame (20 frames x 12 nations is about 12 MB).
        The same cloth as the big card - it shares its folds and light - just built smaller."""
        cache = self.__dict__.setdefault("_cloth_lo", {})
        hit = cache.get((code, f, stage))
        if hit is not None:
            return hit
        tick = pygame.time.get_ticks()
        if getattr(self, "_cloth_tick", None) != tick:
            self._cloth_tick, self._cloth_ms = tick, 0.0
        if self._cloth_ms >= self.CLOTH_BUDGET_MS:
            # this frame's building time is spent: show the last frame already made
            for back_f in range(1, FLAG_FRAMES):
                old = cache.get((code, (f - back_f) % FLAG_FRAMES, stage))
                if old is not None:
                    return old
        t0 = time.perf_counter()
        holo = stage == "H"                                # the holo Signature card: a brighter flag (1 Nov)
        flag = self.evo_flag(code, stage) if stage not in (None, "H") else self.nation_flag(code)
        if flag is None:
            return None
        q = self.CLOTH_LO
        bx0, by0, bx1, by1 = self.TPL_BODY
        tw, th = self.TPL_SIZE[0] // q, self.TPL_SIZE[1] // q
        canvas = pygame.Surface((tw, th), pygame.SRCALPHA)
        # behind the card: exactly the big card's quarter-size cloth, just not blown back up
        bw, bh = (self.TPL_SIZE[0] + 170) // 4, int((by1 - by0) * 1.04) // 4
        back, pad = cloth_surface(flag, bw, bh, f, 0.075, 0.55 if holo else 0.80, 0.0, dim=0.92 if holo else 0.66,
                                  cell=(1, 3))
        k = 4.0 / q
        if k != 1.0:
            back = pygame.transform.smoothscale(back, (int(bw * k), int(back.get_height() * k)))
        canvas.blit(back, (int(round(-85 / float(q))), int(round((by0 - 8) / float(q) - pad * k))))
        # inside it: the big card's half-size cloth, brought down
        iw, ih = ((bx1 - bx0) + 30) // 2, ((by1 - by0) + 10) // 2
        inner, pad = cloth_surface(flag, iw, ih, f, 0.050, 0.40 if holo else 0.68, 1.4, margin=True)
        k = 2.0 / q
        inner = pygame.transform.smoothscale(inner, (max(1, int(iw * k)), max(1, int(inner.get_height() * k))))
        lay = pygame.Surface((tw, th), pygame.SRCALPHA)
        lay.blit(inner, (int(round((bx0 - 15) / float(q))), int(round((by0 - 5) / float(q) - pad * k))))
        mask = self.__dict__.get("_cloth_mask")
        if mask is None:
            full = load_pixel("tpl_fmask_card", self.TPL_SIZE, quiet=True)
            mask = self._cloth_mask = pygame.transform.smoothscale(full, (tw, th)) if full is not None else False
        if mask:
            lay.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        canvas.blit(lay, (0, 0))
        if len(cache) >= 12 * FLAG_FRAMES:
            cache.clear()
        cache[(code, f, stage)] = canvas
        self._cloth_ms += (time.perf_counter() - t0) * 1000.0
        return canvas

    # ---- Limit Breakers lightning ----------------------------------------------------------
    # Where the template's five bolts were (fractions of the card body: start, end, how far a
    # bolt may wander). They strike in turn, each on its own clock, and every strike is a new
    # bolt: flash, gone, flash again, then it fades - the way lightning actually looks.
    LB_BOLTS = (((0.149, -0.024), (0.052, 0.708), 0.172), ((0.948, 0.259), (0.873, 0.778), 0.149),
                ((0.560, -0.014), (0.358, 0.259), 0.097), ((0.784, -0.014), (0.933, 0.283), 0.090),
                ((0.022, 0.542), (0.224, 0.755), 0.090))
    LB_STRIKE = 0.55             # seconds a strike lasts, flicker and fade
    LB_HOT, LB_CORE = (255, 64, 78), (255, 168, 178)

    @staticmethod
    def lb_strike_light(tau):
        """How bright a bolt is tau seconds after it strikes."""
        if tau < 0.05:
            return 1.0
        if tau < 0.10:
            return 0.15
        if tau < 0.15:
            return 1.0
        return max(0.0, 1.0 - (tau - 0.15) / (0.55 - 0.15)) ** 1.7

    def lb_strikes(self, cid):
        """The bolts striking on this card right now: [(slot, strike number, brightness)]."""
        t = pygame.time.get_ticks() * 0.001
        h = sum(ord(ch) * (i + 1) for i, ch in enumerate(cid))
        out = []
        for k in range(len(self.LB_BOLTS)):
            period = 1.9 + 0.47 * k + (h % 7) * 0.08
            x = t / period + ((h * 0.618 + k * 0.37) % 1.0)
            n = int(x)
            tau = (x - n) * period
            if tau < self.LB_STRIKE:
                light = self.lb_strike_light(tau)
                if light > 0.02:
                    out.append((k, n, light))
        return h, out

    def draw_lb_storm(self, surf, rect, cid):
        h, strikes = self.lb_strikes(cid)
        keep = surf.get_clip()
        surf.set_clip(rect.clip(keep) if keep is not None else rect)
        try:
            for k, n, light in strikes:
                img, ox, oy, mid = self.lb_bolt(rect.size, self.LB_BOLTS[k], (h * 31 + k * 977 + n * 131) & 0xFFFFF)
                fl = self.lb_flash(rect.w)                 # the storm lights up round it
                fl.set_alpha(int(120 * light))
                surf.blit(fl, fl.get_rect(center=(rect.x + mid[0], rect.y + mid[1])))
                img.set_alpha(int(255 * light))
                surf.blit(img, (rect.x + ox, rect.y + oy))
        finally:
            surf.set_clip(keep)

    # In front of the player: the player covers most of the storm, so a strike also lights the
    # whole card up for a moment (lightning lights up everything, him too), and on pool A / B
    # sparks jump off the crystal over the frame.
    LB_ARCS = (((0.80, 0.08), (0.52, -0.06), 0.06), ((0.95, 0.20), (1.10, 0.36), 0.06),
               ((0.84, 0.21), (0.70, 0.36), 0.05), ((0.93, 0.04), (1.04, -0.08), 0.05))
    LB_FLASH = (56, 12, 20)      # what a full strike adds to the card's colour

    def live_over(self, surf, key, rect, card):
        """The part of a moving card that goes on top of its face (Limit Breakers; the shine on a
        Champions card's gold; an evolved World's Game card's shine)."""
        if key.startswith("flagholo_"):                    # the holo Signature card: never still
            self.draw_holo_sheen(surf, rect, card["id"])
            self.draw_gold_shine(surf, rect, "fholoframe", card["id"], every=2.6)
            self.draw_sig_pulse(surf, card, rect)
            if rect.w >= 120:
                self.draw_petals(surf, rect, card["id"], PETALS if rect.w >= self.BIG_CARD_W else PETALS // 2)
            return
        if key.startswith("flagwg"):
            stage = int(key[6])
            if stage == 3:                                   # LIMITLESS: the crazy shine
                self.draw_aura_rim(surf, rect, card["id"], WG_EVO_AURA, "wgevo3frame")
                self.draw_gold_shine(surf, rect, "wgevo3frame", card["id"], every=WG_EVO_SHINE[3])
                self.draw_gold_shine(surf, rect, "wgevo3frame", card["id"] + "+", every=WG_EVO_SHINE[3] * 1.7)
                self.draw_aura_sparks(surf, rect, card["id"], WG_EVO_AURA)
            elif WG_EVO_SHINE[stage]:
                self.draw_gold_shine(surf, rect, "wgevo%dframe" % stage, card["id"], every=WG_EVO_SHINE[stage])
            return
        if key == "stargold":                              # light running round the gold, sparks off it
            self.draw_gold_shine(surf, rect, "stargoldframe", card["id"], every=2.2)
            if rect.w >= self.BIG_CARD_W:
                self.draw_aura_sparks(surf, rect, card["id"], STAR_GOLD_AURA)
            return
        if key.startswith("champ_"):
            aura = card.get("id") in CARD_AURA
            if aura:
                self.draw_aura_rim(surf, rect, card["id"])
            self.draw_gold_shine(surf, rect, "champframe", card["id"], every=1.6 if aura else None)
            if aura:
                self.draw_aura_sparks(surf, rect, card["id"])
            return
        if key not in ("lb", "lbc"):
            return
        h, strikes = self.lb_strikes(card["id"])
        if not strikes:
            return
        light = max(l for _k, _n, l in strikes)
        lvl = int(light * 6 + 0.5)
        if lvl > 0:
            surf.blit(self.lb_flash_card(rect.size, lvl), rect.topleft, special_flags=pygame.BLEND_RGB_ADD)
        if key == "lb" and rect.w >= 120:
            for k, n, l in strikes:
                if k % 2:                                  # half the strikes jump off the crystal too
                    continue
                arc = self.LB_ARCS[(n + k) % len(self.LB_ARCS)]
                img, ox, oy, _mid = self.lb_bolt(rect.size, arc, (h * 17 + k * 389 + n * 71) & 0xFFFFF)
                img.set_alpha(int(255 * l))
                surf.blit(img, (rect.x + ox, rect.y + oy))

    # ---- Champion Draft A, moving (31 Oct). Hubi: "make the ribbons animated and make a shine
    # effect on the cards gold borders". The pennants are one flat strip per club
    # (make_champ_cards.py: champpen_<CLUB>.png); each frame of the wave shifts its rows sideways
    # - nothing at the rod, most at the swallow-tail - and shades the folds as they travel down.
    # The shine is a warm band of light that runs across the gold frame now and then, only where
    # there is gold (the frame template's own shape), added on top of the card.
    PEN_FRAMES = 16
    PEN_FPS = 9.0
    PEN_AT = {-1: (18, 42), 1: (330, 42)}          # each strip's top-left on the template canvas
    SHINE_FRAMES = 18
    SHINE_EVERY = 3.4                              # seconds between sweeps
    SHINE_TAKES = 0.85                             # how long one sweep takes

    def champ_pen_frame(self, club, w, h, side, f):
        cache = self.__dict__.setdefault("_pen_frames", {})
        ck = (club, w, h, side, f)
        hit = cache.get(ck)
        if hit is not None:
            return hit
        raw = self.__dict__.setdefault("_pen_raw", {})
        if club not in raw:
            path = find_sprite("champpen_" + club)
            raw[club] = pygame.image.load(path).convert_alpha() if path else None
        src = raw[club]
        if src is None:
            return None
        bx0, by0, bx1, by1 = self.TPL_BODY
        kx, ky = w / float(bx1 - bx0), h / float(by1 - by0)
        sw, sh = max(1, int(src.get_width() * kx)), max(1, int(src.get_height() * ky))
        base = pygame.transform.smoothscale(src, (sw, sh))
        amp = max(2, int(7 * kx))
        out = pygame.Surface((sw + amp * 2, sh), pygame.SRCALPHA)
        step = max(1, int(round(2 * ky)))
        ph = math.tau * f / float(self.PEN_FRAMES) + (0.0 if side < 0 else 1.9)
        rod = int(10 * ky)
        for y in range(0, sh, step):
            t = clamp((y - rod) / float(max(1, sh - rod)), 0.0, 1.0)
            wave = math.sin(ph - t * math.tau * 1.25)
            dx = amp * (t ** 1.1) * wave * side * -1
            v = int(255 * (0.80 + 0.20 * math.sin(ph - t * math.tau * 1.25 + 1.3))) if t > 0 else 255
            band = base.subsurface((0, y, sw, min(step, sh - y))).copy()
            if v < 255:
                band.fill((v, v, v, 255), special_flags=pygame.BLEND_RGBA_MULT)
            out.blit(band, (amp + int(round(dx)), y))
        if len(cache) > 400:
            cache.clear()
        cache[ck] = (out, amp)
        return cache[ck]

    def draw_champ_pennants(self, surf, club, rect):
        bx0, by0, bx1, by1 = self.TPL_BODY
        kx, ky = rect.w / float(bx1 - bx0), rect.h / float(by1 - by0)
        f = int(pygame.time.get_ticks() * 0.001 * self.PEN_FPS) % self.PEN_FRAMES
        drew = False
        for side in (-1, 1):
            hit = self.champ_pen_frame(club, rect.w, rect.h, side, f)
            if hit is None:
                continue
            img, amp = hit
            tx, ty = self.PEN_AT[side]
            surf.blit(img, (rect.x + int((tx - bx0) * kx) - amp, rect.y + int((ty - by0) * ky)))
            drew = True
        return drew

    def gold_mask(self, frame_key, w, h):
        """The frame template's gold as a grey mask (RGB = how much gold), for a multiply."""
        cache = self.__dict__.setdefault("_gold_mask", {})
        ck = (frame_key, w, h)
        if ck not in cache:
            tpl = self.card_template(frame_key, w, h)
            if tpl is None:
                cache[ck] = None
            else:
                img = tpl[0]
                m = pygame.Surface(img.get_size())
                m.fill((0, 0, 0))
                white = img.copy()
                white.fill((0, 0, 0, 255), special_flags=pygame.BLEND_RGBA_MULT)      # black, same alpha...
                white.fill((255, 255, 255, 0), special_flags=pygame.BLEND_RGBA_ADD)   # ...then white
                m.blit(white, (0, 0))                     # onto black: grey = how much gold
                cache[ck] = (m, tpl[1], tpl[2])
            if len(cache) > 60:                     # full: start again, but keep the one just made
                keep = cache[ck]
                cache.clear()
                cache[ck] = keep
        return cache[ck]

    def shine_frame(self, frame_key, w, h, f):
        cache = self.__dict__.setdefault("_shine", {})
        ck = (frame_key, w, h, f)
        hit = cache.get(ck)
        if hit is not None:
            return hit
        gm = self.gold_mask(frame_key, w, h)
        if gm is None:
            return None
        mask, ox, oy = gm
        W, H = mask.get_size()
        band = pygame.Surface((W, H))
        band.fill((0, 0, 0))
        p = -0.35 + 1.7 * f / float(self.SHINE_FRAMES - 1)        # where the band is, across the card
        cx = p * (W + H)
        width = (W + H) * 0.15
        for off, wide, peak in ((0.0, 1.0, 1.0), (-0.22, 0.30, 0.75)):   # the band, and a thin streak behind it
            for i in range(-6, 7):                                # soft-edged, warm white
                k = math.exp(-(i / 3.0) ** 2) * peak
                col = (int(255 * k), int(240 * k), int(185 * k))
                x = cx + off * (W + H) * 0.5 + i * width * wide / 12.0
                pygame.draw.line(band, col, (int(x - H), H), (int(x), 0), max(2, int(width * wide / 12.0) + 2))
        band.blit(mask, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        if len(cache) > 240:
            cache.clear()
        cache[ck] = (band, ox, oy)
        return cache[ck]

    # ---- the holo card's autograph and petals (1 Nov) ----------------------------------------
    def sig_parts(self, name, width):
        """(the autograph, a dimmed copy, its shape as a white-on-black mask) at this width - cached."""
        cache = self.__dict__.setdefault("_sig_parts", {})
        ck = (name, int(width))
        if ck not in cache:
            img = self.autograph_img(name, width)
            if img is None:
                cache[ck] = None
            else:
                dimmed = img.copy()
                g = int(255 * SIG_DIM_TO)
                dimmed.fill((g, g, int(g * 0.92)), special_flags=pygame.BLEND_RGB_MULT)
                m = pygame.Surface(img.get_size())
                m.fill((0, 0, 0))
                white = img.copy()
                white.fill((0, 0, 0, 255), special_flags=pygame.BLEND_RGBA_MULT)
                white.fill((255, 255, 255, 0), special_flags=pygame.BLEND_RGBA_ADD)
                m.blit(white, (0, 0))
                cache[ck] = (img, dimmed, m)
            if len(cache) > 30:                     # full: start again, but keep the one just made
                keep = cache[ck]
                cache.clear()
                cache[ck] = keep
        return cache[ck]

    def sig_shine_img(self, name, width, f, frames=16):
        """The light running along the autograph at step f: a bright band, only on the pen line."""
        cache = self.__dict__.setdefault("_sig_shine", {})
        ck = (name, int(width), f)
        if ck not in cache:
            parts = self.sig_parts(name, width)
            if parts is None:
                return None
            mask = parts[2]
            W, H = mask.get_size()
            band = pygame.Surface((W, H))
            band.fill((0, 0, 0))
            cx = (-0.25 + 1.5 * f / float(frames - 1)) * W
            wide = max(6.0, W * 0.16)
            for i in range(-6, 7):
                k = math.exp(-(i / 3.0) ** 2)
                col = (int(255 * k), int(246 * k), int(200 * k))
                x = cx + i * wide / 12.0
                pygame.draw.line(band, col, (int(x - H * 0.35), H), (int(x + H * 0.35), 0), max(2, int(wide / 12.0) + 2))
            band.blit(mask, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
            if len(cache) > 120:
                cache.clear()
            cache[ck] = band
        return cache[ck]

    def draw_sig_pulse(self, surf, card, rect):
        """The live autograph: normal -> a little dark -> a light runs along it -> back."""
        name = self.AUTOGRAPHS.get(card["id"])
        if name is None:
            return
        fx, fy, fw = self.HOLO_AUTOGRAPH_AT if card["id"] in HOLO_SIG else self.AUTOGRAPH_AT
        parts = self.sig_parts(name, rect.w * fw)
        if parts is None:
            return
        img, dimmed, _m = parts
        t = pygame.time.get_ticks() * 0.001 + (sum(map(ord, card["id"])) % 13) * 0.21
        u = (t % SIG_PULSE) / SIG_PULSE
        pos = img.get_rect(center=(rect.x + int(rect.w * fx), rect.y + int(rect.h * fy)))
        if u < SIG_DIM[1]:                                 # easing into the dark
            k = min(1.0, u / (SIG_DIM[1] * 0.5))
            surf.blit(img, pos)
            if k > 0.05:
                dimmed.set_alpha(int(255 * k))
                surf.blit(dimmed, pos)
                dimmed.set_alpha(None)
        elif u < SIG_SHINE[1]:                             # the light runs along it, out of the dark
            k = (u - SIG_SHINE[0]) / float(SIG_SHINE[1] - SIG_SHINE[0])
            surf.blit(img, pos)
            dimmed.set_alpha(int(255 * max(0.0, 1.0 - k * 1.6)))
            surf.blit(dimmed, pos)
            dimmed.set_alpha(None)
            band = self.sig_shine_img(name, rect.w * fw, min(15, int(k * 16)))
            if band is not None:
                surf.blit(band, pos, special_flags=pygame.BLEND_RGB_ADD)
                if k > 0.5:                                # and it glows for a moment as it finishes
                    surf.blit(band, pos.move(0, -1), special_flags=pygame.BLEND_RGB_ADD)
        else:
            surf.blit(img, pos)

    def petal_img(self, col, size, ang):
        """One petal: a pointed oval, lit down its middle, at a rotation (cached in 15-degree steps)."""
        cache = self.__dict__.setdefault("_petals", {})
        a = int(ang // 15) * 15 % 360
        ck = (col, size, a)
        if ck not in cache:
            w, h = max(4, int(size * 1.9)), max(3, int(size))
            s = pygame.Surface((w, h), pygame.SRCALPHA)
            pts = [(0, h / 2.0), (w * 0.3, 0), (w * 0.7, 0), (w - 1, h / 2.0), (w * 0.7, h - 1), (w * 0.3, h - 1)]
            dark = tuple(int(c * 0.72) for c in col)
            pygame.draw.polygon(s, dark + (230,), pts)
            pygame.draw.polygon(s, col + (240,), [(w * 0.1, h / 2.0), (w * 0.32, h * 0.18), (w * 0.7, h * 0.18),
                                                  (w * 0.92, h / 2.0)])
            pygame.draw.line(s, (255, 255, 255, 220), (int(w * 0.18), int(h / 2.0)), (int(w * 0.84), int(h / 2.0)), 1)
            out = pygame.transform.rotate(s, a)
            if len(cache) > 600:
                cache.clear()
            cache[ck] = out
        return cache[ck]

    def draw_petals(self, surf, rect, seed, n):
        """Blue, white and yellow petals blown across the card from the top left to the bottom right (2 Nov,
        Hubi: they come in from the top left) - each on its own line: carried along by the wind, a flutter
        side to side, turning as it goes but pointing roughly the way it travels, fading in and out."""
        t = pygame.time.get_ticks() * 0.001
        rnd = random.Random(str(seed) + "petals")
        size0 = max(4, int(rect.w * 0.042))
        dx, dy = PETAL_WIND
        L = math.hypot(dx * rect.w, dy * rect.h)
        ux, uy = dx * rect.w / L, dy * rect.h / L          # along the wind, in pixels
        px, py = -uy, ux                                   # across it
        span = L * 1.25
        travel = -math.degrees(math.atan2(uy, ux))         # pygame turns anticlockwise
        cx, cy = rect.centerx, rect.centery
        for i in range(n):
            off = rnd.uniform(-0.62, 0.62) * rect.w * 1.25
            speed = rnd.uniform(0.09, 0.15)                # a whole pass in about 7-11 seconds
            ph = rnd.uniform(0.0, 1.0)
            flut = rnd.uniform(0.02, 0.05) * rect.w
            wob = rnd.uniform(25, 55)
            col = PETAL_COLS[i % len(PETAL_COLS)]
            sz = int(size0 * rnd.uniform(0.7, 1.25))
            u = (ph + t * speed) % 1.0
            f = flut * math.sin(t * 2.1 + ph * 9.0)
            x = cx + px * (off + f) + ux * (u - 0.5) * span
            y = cy + py * (off + f) + uy * (u - 0.5) * span
            if not (rect.x - rect.w * 0.2 < x < rect.right + rect.w * 0.2 and
                    rect.y - rect.h * 0.12 < y < rect.bottom + rect.h * 0.12):
                continue
            fade = min(1.0, u / 0.12, (1.0 - u) / 0.15)
            if fade <= 0.05:
                continue
            ang = travel + wob * math.sin(t * 1.7 + ph * 7.0) + (ph * 360 if i % 4 == 0 else 0) + (t * 90 if i % 4 == 0 else 0)
            img = self.petal_img(col, sz, ang % 360)
            if fade < 0.99:
                img = img.copy()
                img.set_alpha(int(255 * fade))
            surf.blit(img, img.get_rect(center=(int(x), int(y))))

    def holo_frame(self, w, h, f):
        """One frame of the holo card's rainbow: diagonal bands of every colour, drifting, only where
        the chrome and the crystal are (tpl_fholochrome_card.png). Built a third size, scaled: soft."""
        cache = self.__dict__.setdefault("_holo", {})
        ck = (w, h, f)
        hit = cache.get(ck)
        if hit is not None:
            return hit
        gm = self.gold_mask("fholochrome", w, h)
        if gm is None:
            return None
        mask, ox, oy = gm
        W, H = mask.get_size()
        q = 3
        lo = pygame.Surface((max(2, W // q), max(2, H // q)))
        lw, lh = lo.get_size()
        n = 9
        span = (lw + lh) / float(n) * 1.6
        shift = f / float(HOLO_FRAMES) * span * n / 1.6
        for i in range(-2, n * 2):
            hue = ((i / float(n)) % 1.0)
            r_, g_, b_ = colorsys.hsv_to_rgb(hue, 0.75, HOLO_GLOW)
            x0 = i * span / 2.0 - lh + shift % (span * n / 2.0) - span * n / 4.0
            pygame.draw.polygon(lo, (int(r_ * 255), int(g_ * 255), int(b_ * 255)),
                                [(x0, lh), (x0 + span / 2.0 + 1, lh), (x0 + span / 2.0 + lh + 1, 0), (x0 + lh, 0)])
        band = pygame.transform.smoothscale(lo, (W, H))
        band.blit(mask, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        if len(cache) > HOLO_FRAMES * 4:
            cache.clear()
        cache[ck] = (band, ox, oy)
        return cache[ck]

    def draw_holo_sheen(self, surf, rect, seed=""):
        t = pygame.time.get_ticks() * 0.001 + (sum(map(ord, str(seed))) % 31) * 0.1
        f = int(t / HOLO_PERIOD * HOLO_FRAMES) % HOLO_FRAMES
        hit = self.holo_frame(rect.w, rect.h, f)
        if hit is not None:
            img, ox, oy = hit
            surf.blit(img, (rect.x - ox, rect.y - oy), special_flags=pygame.BLEND_RGB_ADD)

    def draw_gold_shine(self, surf, rect, frame_key, seed="", every=None):
        t = pygame.time.get_ticks() * 0.001 + (sum(map(ord, str(seed))) % 97) * 0.13   # cards don't all flash at once
        k = (t % (every or self.SHINE_EVERY)) / self.SHINE_TAKES
        if k >= 1.0:
            return
        f = min(self.SHINE_FRAMES - 1, int(k * self.SHINE_FRAMES))
        hit = self.shine_frame(frame_key, rect.w, rect.h, f)
        if hit is None:
            return
        img, ox, oy = hit
        surf.blit(img, (rect.x - ox, rect.y - oy), special_flags=pygame.BLEND_RGB_ADD)

    # ---- aura (31 Oct): Messi, Salah, Ronaldo, Yamal --------------------------------------
    AURA_LEVELS = 8

    def aura_glow_img(self, w, h, col):
        """A soft glow the card's shape, bigger than it - built small and scaled up so it's soft."""
        cache = self.__dict__.setdefault("_aura_glow", {})
        ck = (w, h, col)
        if ck not in cache:
            m = max(12, min(56, int(w * 0.16)))      # inside CARD_PAD
            W, H = w + m * 2, h + m * 2
            q = 6                                          # built at 1/6 size, scaled up: soft
            lo = pygame.Surface((max(4, W // q), max(4, H // q)), pygame.SRCALPHA)
            r = pygame.Rect(0, 0, int(w / float(q)), int(h / float(q)))
            r.center = lo.get_rect().center
            ml = max(2, m // q - 1)                        # rings stop short of the edge, so no box
            for j in range(ml, -1, -1):                    # outer ring first, each one brighter
                a = int(245 * (1.0 - j / float(ml + 1)) ** 1.4)
                pygame.draw.rect(lo, col + (a,), r.inflate(j * 2, j * 2),
                                 border_radius=max(1, int(r.w * 0.10) + j))
            img = pygame.transform.smoothscale(lo, (W, H))
            cache[ck] = (img, m)
            if len(cache) > 40:                     # full: start again, but keep the one just made
                keep = cache[ck]
                cache.clear()
                cache[ck] = keep
        return cache[ck]

    def draw_aura_glow(self, surf, rect, cid, cols=None):
        a, b = cols or CARD_AURA[cid]
        t = pygame.time.get_ticks() * 0.001
        breathe = 0.55 + 0.45 * math.sin(t * 2.2)
        for col, k, phase in ((a, 1.0, 0.0), (b, 0.7, 1.7)):
            img, m = self.aura_glow_img(rect.w, rect.h, col)
            img.set_alpha(int(255 * clamp(k * (0.55 + 0.45 * math.sin(t * 2.2 + phase)) * breathe + 0.15, 0, 1)))
            surf.blit(img, (rect.x - m, rect.y - m))

    def draw_aura_rim(self, surf, rect, cid, cols=None, frame_key="champframe"):
        """The gold rim lit in his colour, pulsing (an additive blit of the gold, tinted)."""
        a, _b = cols or CARD_AURA[cid]
        t = pygame.time.get_ticks() * 0.001
        lvl = int(round((0.5 + 0.5 * math.sin(t * 3.1)) * (self.AURA_LEVELS - 1)))
        cache = self.__dict__.setdefault("_aura_rim", {})
        ck = (rect.w, rect.h, a, lvl, frame_key)
        hit = cache.get(ck)
        if hit is None:
            gm = self.gold_mask(frame_key, rect.w, rect.h)
            if gm is None:
                return
            mask, ox, oy = gm
            img = mask.copy()
            k = 0.10 + 0.45 * lvl / float(self.AURA_LEVELS - 1)
            img.fill((int(a[0] * k), int(a[1] * k), int(a[2] * k)), special_flags=pygame.BLEND_RGB_MULT)
            hit = cache[ck] = (img, ox, oy)
            if len(cache) > 200:
                cache.clear()
        img, ox, oy = hit
        surf.blit(img, (rect.x - ox, rect.y - oy), special_flags=pygame.BLEND_RGB_ADD)

    def draw_aura_sparks(self, surf, rect, cid, cols=None):
        """Sparks rising up the card, twinkling - in his colour and gold."""
        a, b = cols or CARD_AURA[cid]
        t = pygame.time.get_ticks() * 0.001
        rnd = random.Random(cid)
        keep = surf.get_clip()
        inner = rect.inflate(-int(rect.w * 0.06), -int(rect.h * 0.05))
        surf.set_clip(inner.clip(keep) if keep is not None else inner)
        s = max(2, int(rect.w / 70))
        for i in range(18):
            fx, sp, ph, sz = rnd.random(), 0.10 + 0.12 * rnd.random(), rnd.random(), rnd.random()
            k = (t * sp + ph) % 1.0                        # 0 at the bottom, 1 at the top
            x = inner.x + inner.w * (0.06 + 0.88 * fx) + math.sin(t * 1.7 + i) * s * 2
            y = inner.bottom - k * inner.h * 1.05
            tw = 0.5 + 0.5 * math.sin(t * 7.0 + i * 1.9)
            fade = min(1.0, k * 4.0, (1.0 - k) * 3.0)
            if fade <= 0.05:
                continue
            col = a if i % 2 else b
            c = tuple(int(255 - (255 - v) * 0.5 * (1.0 - tw)) for v in col)  # brighter at the twinkle's peak
            r = max(1, int(s * (0.6 + 0.9 * sz) * fade))
            pygame.draw.polygon(surf, c, [(x, y - r * 2), (x + r, y), (x, y + r * 2), (x - r, y)])
            if tw > 0.8 and r >= 2:                        # a cross of light at the peak
                pygame.draw.line(surf, (255, 255, 240), (x - r * 3, y), (x + r * 3, y), 1)
                pygame.draw.line(surf, (255, 255, 240), (x, y - r * 3), (x, y + r * 3), 1)
        surf.set_clip(keep)

    def lb_flash_card(self, size, lvl):
        """The card's shape filled with a share (lvl / 6) of LB_FLASH, black round it, for an
        additive blit: the colours lift, nothing outside the card does."""
        cache = self.__dict__.setdefault("_lb_flash_card", {})
        key = (size, lvl)
        img = cache.get(key)
        if img is None:
            w, h = size
            k = w / 268.0
            ct, cb = 20 * k, 34 * k
            pts = [(ct, 0), (w - ct, 0), (w, ct)]
            for i in range(9):
                a = i / 8.0 * math.pi / 2
                pts.append((w - cb + cb * math.cos(a), h - cb + cb * math.sin(a)))
            for i in range(9):
                a = math.pi / 2 + i / 8.0 * math.pi / 2
                pts.append((cb + cb * math.cos(a), h - cb + cb * math.sin(a)))
            pts.append((0, ct))
            img = pygame.Surface((w, h))
            img.fill((0, 0, 0))
            pygame.draw.polygon(img, tuple(int(c * lvl / 6.0) for c in self.LB_FLASH), pts)
            if len(cache) > 60:
                cache.clear()
            cache[key] = img
        return img

    def lb_flash(self, w):
        """A soft round red glow, for the storm lighting up round a bolt."""
        cache = self.__dict__.setdefault("_lb_flash", {})
        d = max(8, int(w * 0.9)) // 8 * 8
        img = cache.get(d)
        if img is None:
            small = pygame.Surface((32, 32), pygame.SRCALPHA)
            for r in range(16, 0, -1):
                a = int(150 * (1.0 - r / 16.0) ** 1.5)
                pygame.draw.circle(small, (255, 70, 90, a), (16, 16), r)
            img = cache[d] = pygame.transform.smoothscale(small, (d, d))
            if len(cache) > 12:
                cache.clear()
                cache[d] = img
        return img

    def lb_bolt(self, size, seg, seed):
        """One bolt (with its branches and its glow) for a card of this size:
        (surface, x, y on the card, middle of the bolt on the card). Kept for the strike."""
        cache = self.__dict__.setdefault("_lb_bolts", {})
        key = (size, seg, seed)
        hit = cache.get(key)
        if hit is not None:
            return hit
        w, h = size
        rnd = random.Random(seed)
        (u0, v0), (u1, v1), wander = seg
        p0, p1 = (u0 * w, v0 * h), (u1 * w, v1 * h)

        def bolt(a, b, disp, depth):
            if depth == 0:
                return [a, b]
            dx, dy = b[0] - a[0], b[1] - a[1]
            ln = math.hypot(dx, dy) or 1.0
            off = rnd.uniform(-disp, disp)
            m = ((a[0] + b[0]) / 2.0 - dy / ln * off, (a[1] + b[1]) / 2.0 + dx / ln * off)
            return bolt(a, m, disp / 2.0, depth - 1)[:-1] + bolt(m, b, disp / 2.0, depth - 1)

        main = bolt(p0, p1, wander * w, 6)
        branches = []
        ln = math.hypot(p1[0] - p0[0], p1[1] - p0[1])
        ang = math.atan2(p1[1] - p0[1], p1[0] - p0[0])
        for _ in range(rnd.randint(1, 3)):
            i = rnd.randrange(4, len(main) - 4)
            a = ang + rnd.choice((-1, 1)) * rnd.uniform(0.4, 1.0)
            q = (main[i][0] + math.cos(a) * ln * rnd.uniform(0.18, 0.4),
                 main[i][1] + math.sin(a) * ln * rnd.uniform(0.18, 0.4))
            branches.append(bolt(main[i], q, wander * w * 0.4, 4))
        s = w / 268.0                                       # the template's body is 268 wide
        # The screen is shrunk to a 3 px grid without smoothing, so a line under 3 px wide comes
        # and goes between frames (that is why the first bolts barely showed): every line here
        # is at least one game pixel wide.
        m = int(18 * s) + 8
        xs = [p[0] for line in [main] + branches for p in line]
        ys = [p[1] for line in [main] + branches for p in line]
        x0, y0 = int(min(xs)) - m, int(min(ys)) - m
        bw, bh = int(max(xs)) + m - x0, int(max(ys)) + m - y0

        def shift(line, k=1.0):
            return [((p[0] - x0) * k, (p[1] - y0) * k) for p in line]

        # the wide glow: drawn at a quarter size and blown up, which blurs it for free
        g = pygame.Surface((max(2, bw // 4), max(2, bh // 4)), pygame.SRCALPHA)
        pygame.draw.lines(g, self.LB_HOT + (150,), False, shift(main, 0.25), max(2, int(4.5 * s)))
        for br in branches:
            pygame.draw.lines(g, self.LB_HOT + (100,), False, shift(br, 0.25), max(1, int(2.8 * s)))
        img = pygame.transform.smoothscale(g, (bw, bh))
        for br in branches:
            pygame.draw.lines(img, self.LB_HOT + (170,), False, shift(br), max(4, int(4.0 * s)))
            pygame.draw.lines(img, self.LB_CORE + (240,), False, shift(br), max(3, int(2.6 * s)))
        pygame.draw.lines(img, self.LB_HOT + (200,), False, shift(main), max(7, int(7.5 * s)))
        pygame.draw.lines(img, self.LB_CORE + (255,), False, shift(main), max(5, int(4.6 * s)))
        pygame.draw.lines(img, (255, 255, 255, 255), False, shift(main), max(3, int(2.4 * s)))
        mid = main[len(main) // 2]
        if len(cache) > 160:
            cache.clear()
        cache[key] = (img, x0, y0, (int(mid[0]), int(mid[1])))
        return cache[key]

    MULTI_PAD = 20           # the ten-pack grid sits close together: trim the art like it always did

    def draw_card(self, surf, card, rect, count=0, stamina=None, dim=False, glow=False):
        card = self.upgraded(card)                         # your rank and level, if you own him
        if card["design"] == "beginner" or (card["design"] == "starsign" and self.star_key(card) == "star"):
            self.draw_star_card(surf, card, rect, count, stamina, dim, glow)
        elif card["design"] in ("no10", "worldsgame", "limitbreakers") or self.card_pool(card) in ("A", "B"):
            self.draw_pool_card(surf, card, rect, count, stamina, dim, glow)
        else:
            self.draw_plain_card(surf, card, rect, count, stamina, dim, glow)
        self.draw_rank_gem(surf, card, rect)

    def draw_plain_card(self, surf, card, rect, count=0, stamina=None, dim=False, glow=False):
        """Pool C: the simple bronze / silver / gold card."""
        outer, inner_c, ink, strip_c = self.card_frame(card)
        design = card["design"]
        t = pygame.time.get_ticks() * 0.001
        if design == "icon":                                  # pulsing glow
            g = int(8 + 6 * (0.5 + 0.5 * math.sin(t * 3)))
            pygame.draw.rect(surf, (255, 236, 150), rect.inflate(g, g), border_radius=20)
        if glow:
            pygame.draw.rect(surf, YELLOW, rect.inflate(16, 16), border_radius=18)
        pygame.draw.rect(surf, outer, rect, border_radius=14)
        inner = rect.inflate(-10, -10)
        pygame.draw.rect(surf, inner_c, inner, border_radius=10)
        k = rect.w / 180.0
        if design == "icon":                                  # marble streaks + ribbon
            for j in range(5):
                y0 = inner.y + int((0.15 + j * 0.2) * inner.h)
                pygame.draw.line(surf, (226, 222, 210), (inner.x, y0), (inner.right, y0 - int(40 * k)), 3)
            rib = pygame.Rect(0, 0, int(90 * k), int(26 * k))
            rib.midtop = (rect.centerx, rect.y - int(6 * k))
            pygame.draw.rect(surf, (200, 150, 40), rib, border_radius=6)
            txt = self.font_s.render("ICON", True, WHITE)
            txt = pygame.transform.smoothscale(txt, (int(rib.h * txt.get_width() / txt.get_height() * 0.9),
                                                     int(rib.h * 0.9)))
            surf.blit(txt, txt.get_rect(center=rib.center))
        elif design == "wc":                                  # nation band + trophy
            cols = self.nation_colours(card["team"])
            bh = max(3, int(12 * k))
            for j, c in enumerate(cols):
                y0 = inner.y + int(inner.h * 0.58) + j * bh
                pygame.draw.polygon(surf, c, [(inner.x, y0 + int(30 * k)), (inner.right, y0 - int(30 * k)),
                                              (inner.right, y0 - int(30 * k) + bh), (inner.x, y0 + int(30 * k) + bh)])
            tx, ty = inner.x + int(14 * k), inner.bottom - int(78 * k)
            gold = (236, 196, 70)
            pygame.draw.rect(surf, gold, (tx, ty, int(16 * k), int(12 * k)))           # cup
            pygame.draw.rect(surf, gold, (tx + int(6 * k), ty + int(12 * k), int(4 * k), int(6 * k)))
            pygame.draw.rect(surf, gold, (tx + int(2 * k), ty + int(18 * k), int(12 * k), int(4 * k)))
        # diagonal shine
        shine = pygame.Surface((inner.w, inner.h), pygame.SRCALPHA)
        pygame.draw.polygon(shine, (255, 255, 255, 50),
                            [(inner.w * 0.55, 0), (inner.w * 0.8, 0), (inner.w * 0.25, inner.h), (0, inner.h)])
        surf.blit(shine, inner.topleft)
        f_big = self.font_m if k > 0.8 else self.font_s
        rt = f_big.render(str(card["rating"]), True, ink)
        surf.blit(rt, (inner.x + int(10 * k), inner.y + int(8 * k)))
        pos = self.font_s.render(card["pos"], True, ink)
        if k < 0.8:
            pos = pygame.transform.smoothscale(pos, (int(pos.get_width() * 0.75), int(pos.get_height() * 0.75)))
        surf.blit(pos, (inner.x + int(12 * k), inner.y + int(8 * k) + rt.get_height() - 4))
        badge = self.card_badge(card)
        if badge is not None:
            b = fit_flag(badge, int(46 * k), int(40 * k))
            surf.blit(b, b.get_rect(topright=(inner.right - int(8 * k), inner.y + int(12 * k))))
        head = self.card_head(card)
        if head is not None:
            hh = fit_flag(head, int(104 * k), int(104 * k))
            surf.blit(hh, hh.get_rect(center=(rect.centerx, rect.y + int(128 * k))))
        strip = pygame.Rect(inner.x, inner.bottom - int(52 * k), inner.w, int(40 * k))
        pygame.draw.rect(surf, strip_c, strip)
        nm = self.label(card["name"].split()[-1].upper() if len(card["name"]) > 12 else card["name"].upper(),
                        strip.w - 10)
        if nm.get_height() > strip.h:
            sc = strip.h / nm.get_height()
            nm = pygame.transform.smoothscale(nm, (int(nm.get_width() * sc), int(nm.get_height() * sc)))
        surf.blit(nm, nm.get_rect(center=strip.center))
        if count > 1:
            c = self.font_s.render("x%d" % count, True, WHITE)
            pygame.draw.circle(surf, (200, 40, 40), (rect.right - 8, rect.bottom - 8), 24)
            surf.blit(c, c.get_rect(center=(rect.right - 8, rect.bottom - 8)))
        if stamina is not None:
            bar = pygame.Rect(rect.x, rect.bottom + 8, rect.w, 16)
            pygame.draw.rect(surf, (30, 30, 30), bar)
            col = (90, 220, 90) if stamina > 50 else ((240, 200, 60) if stamina > 0 else (220, 60, 60))
            pygame.draw.rect(surf, col, (bar.x, bar.y, int(bar.w * stamina / 100), bar.h))
            pygame.draw.rect(surf, WHITE, bar, 2)
        if dim:
            surf.blit(tint((rect.w, rect.h), (0, 0, 0, 150)), rect.topleft)

    # ---- double-click a card to see its stats ------------------------
    def card_click(self, card, action):
        """Single click runs `action` after a short wait; a second click on the
        same card inside that wait opens the stats view instead."""
        now = pygame.time.get_ticks() / 1000.0
        p = self.pending_click
        if p is not None and p[1] == card["id"] and now - p[0] < DOUBLE_CLICK:
            self.pending_click = None
            self.card_detail = card
            self.card_tab = 0
            return
        if p is not None:
            p[2]()
        self.pending_click = (now, card["id"], action)

    def process_pending(self):
        p = self.pending_click
        if p is not None and pygame.time.get_ticks() / 1000.0 - p[0] >= DOUBLE_CLICK:
            self.pending_click = None
            p[2]()

    def team_name(self, card):
        if card["kind"] in ("no10", "wg", "lb"):
            return NATION_NAMES.get(card["nation"], card["nation"])
        if card["kind"] in ("star", "rookie"):
            return "%s  -  %s" % (NATION_NAMES.get(card["nation"], card["nation"]),
                                  STAR_CLUB_NAMES.get(card["team"], card["team"]).upper())
        if card["kind"] == "club":
            for code, name, _s, _p in CLUBS:
                if code == card["team"]:
                    return name.upper()
            return card["team"]
        return NATION_NAMES.get(card["team"], card["team"])

    # ================================================================ THE PLAYER SCREEN
    # Four tabs over one card: what he is, what the numbers mean, his PlayStyles and
    # his traits. It replaces the old popup everywhere a card can be opened.
    CV_TABS = ("SUMMARY", "ATTRIBUTES", "PLAYSTYLES", "TRAITS", "UPGRADE")
    UPG_TAB = 4
    CV_CARD = pygame.Rect(96, 150, 320, 440)
    CV_PANEL = pygame.Rect(600, 268, 1250, 690)

    def card_view_layout(self):
        """(back button, [tab rects], content panel)."""
        back = pygame.Rect(40, 36, 104, 96)
        tabs, w = [], WIDTH // len(self.CV_TABS)
        for i in range(len(self.CV_TABS)):
            tabs.append(pygame.Rect(i * w, HEIGHT - 96, w, 96))
        return back, tabs, self.CV_PANEL

    def card_view_click(self, pos):
        back, tabs, _ = self.card_view_layout()
        if back.collidepoint(pos.x, pos.y):
            self.card_detail = None
            self.feed_ui = None
            return
        for i, r in enumerate(tabs):
            if r.collidepoint(pos.x, pos.y):
                self.card_tab = i
                self.feed_ui = None
                return
        if getattr(self, "card_tab", 0) == self.UPG_TAB:
            self.upgrade_click(pos)

    def stat_colour(self, value):
        """Green when it's a strength, orange when it isn't."""
        if value >= 125:
            return (90, 232, 128)
        if value >= 100:
            return (150, 226, 120)
        if value >= 80:
            return (240, 198, 74)
        return (236, 134, 70)

    def star_row(self, w, x, y, n, of=5, size=26, col=(246, 200, 70)):
        for i in range(of):
            cx, cy = x + i * (size + 6) + size // 2, y + size // 2
            pts = []
            for k in range(10):
                a = -math.pi / 2 + k * math.pi / 5
                r = size * 0.5 if k % 2 == 0 else size * 0.22
                pts.append((cx + math.cos(a) * r, cy + math.sin(a) * r))
            pygame.draw.polygon(w, col if i < n else (62, 70, 86), pts)

    def cv_medal(self, w, rect, level, group, key=None):
        """The PlayStyle badge - its own icon, with a silver or gold ring for the level."""
        col = PS_LEVEL_COLOUR[max(1, min(PS_MAX_LEVEL, level)) - 1]
        ic = self.ps_icon(key, rect.w, level) if key else None
        if ic is not None:
            w.blit(ic, rect.topleft)
            pygame.draw.rect(w, col, rect.inflate(8, 8), 3, border_radius=10)
            return
        cx, cy = rect.center
        r = rect.w // 2
        pts = [(cx, cy - r), (cx + r, cy - r // 3), (cx + r, cy + r // 3),
               (cx, cy + r), (cx - r, cy + r // 3), (cx - r, cy - r // 3)]
        pygame.draw.polygon(w, col, pts)
        pygame.draw.polygon(w, (28, 32, 44), pts, 3)
        mark = {"gk": (120, 200, 255), "def": (90, 140, 230),
                "mid": (120, 220, 150), "att": (235, 120, 90)}.get(group, WHITE)
        pygame.draw.circle(w, mark, (cx, cy), max(5, r // 3))

    def draw_card_detail(self, w):
        card = self.upgraded(self.card_detail)
        tab = getattr(self, "card_tab", 0)
        outer, inner, _ink, _strip = self.card_frame(card)
        w.fill((10, 13, 22))
        # ---- the header band, tinted with the card's own colours
        head = pygame.Rect(0, 0, WIDTH, 252)
        pygame.draw.rect(w, (18, 22, 36), head)
        pygame.draw.rect(w, inner, (0, 0, WIDTH, 6))
        wash(w, tuple(outer) + (46,), head)
        pygame.draw.line(w, outer, (0, head.bottom), (WIDTH, head.bottom), 4)
        back, tabs, panel = self.card_view_layout()
        pygame.draw.polygon(w, WHITE, [(back.right - 18, back.y + 14), (back.x + 16, back.centery),
                                       (back.right - 18, back.bottom - 14)], 6)
        name = card["name"].upper()
        first, last = (name.rsplit(" ", 1) if " " in name else ("", name))
        x = 600
        if first:
            w.blit(self.font_s.render(first, True, (198, 210, 232)), (x, 56))
        big = self.fit_text(last, self.font_xl, WHITE, 1100, 104)
        w.blit(big, (x, 92))
        bits = [card["pos"], "#%d" % card["number"], self.team_name(card)]
        if card.get("nation") and card["nation"] not in str(bits[-1]).upper():
            bits.append(card["nation"])
        bits.append("POOL %s" % card.get("pool", "C"))
        line = self.fit_text("   |   ".join(str(b) for b in bits), self.font_s, (190, 206, 230),
                             WIDTH - x - 90, 36)
        w.blit(line, (x, 206))
        kind = {"icon": ("ICON", (255, 220, 120)), "signature": ("SIGNATURE", (140, 255, 160)),
                "starsign": ("STAR SIGNING ELITE", STAR_LILAC), "beginner": ("BEGINNER", ROOKIE_MINT),
                "worldsgame": ("THE WORLD'S GAME", WG_LILAC),
                "limitbreakers": ("LIMIT BREAKERS", LB_RED),
                "samba": ("SAMBA CARD", SAMBA_GREEN), "prodigy": ("PRODIGY", (120, 235, 245)),
                "wc": ("WORLD CUP", (255, 220, 120))}.get(card["design"])
        if kind:
            tag = self.font_s.render(kind[0], True, kind[1])
            w.blit(tag, (WIDTH - tag.get_width() - 60, 60))
        # ---- the card itself, hanging off the band
        self.draw_card(w, card, self.CV_CARD)
        self.cv_side(w, card)
        # ---- the panel for whichever tab is open
        pygame.draw.rect(w, (16, 20, 32), panel, border_radius=18)
        pygame.draw.rect(w, (44, 54, 76), panel, 2, border_radius=18)
        (self.cv_summary, self.cv_attributes, self.cv_styles, self.cv_traits, self.cv_upgrade)[tab](w, card, panel)
        # ---- tabs
        pygame.draw.rect(w, (14, 18, 28), (0, HEIGHT - 96, WIDTH, 96))
        for i, (r, nm) in enumerate(zip(tabs, self.CV_TABS)):
            on = i == tab
            if on:
                pygame.draw.rect(w, (24, 32, 50), r)
                pygame.draw.rect(w, (90, 228, 200), (r.x, r.y, r.w, 5))
            lab = self.font_m.render(nm, True, WHITE if on else (150, 164, 188))
            w.blit(lab, lab.get_rect(center=r.center))

    def cv_side(self, w, card):
        """Under the card: position, stamina, skill moves, weak foot."""
        st = card.get("stats") or {}
        stam = self.save.get("stamina", {}).get(card["id"], 100) if card.get("id") else 100
        rows = (("Position", None, card["pos"]),
                ("Stamina", int(round(clamp(stam / 100.0, 0.0, 1.0) * 5)), None),
                ("Skill Moves", 1 + int(round(4 * stat01(st.get("drib", 100)))), None),
                ("Weak Foot", 1 + int(round(4 * stat01(st.get("pass", 100)))), None))
        y = 640
        for title, stars, text in rows:
            lab = self.fit_text(title, self.font_s, (176, 192, 214), 220, 34)
            w.blit(lab, (96, y + 4))
            if stars is None:
                val = self.fit_text(str(text), self.font_m, (120, 236, 180), 160, 46)
                w.blit(val, val.get_rect(topright=(540, y - 2)))
            else:
                self.star_row(w, 352, y + 6, stars, size=30)
            y += 70
            pygame.draw.line(w, (40, 48, 68), (96, y - 14), (540, y - 14), 2)

    # ---- tab 1: summary
    def cv_summary(self, w, card, panel):
        st = card.get("stats") or {}
        box = pygame.Rect(panel.x + 26, panel.y + 24, panel.w - 52, 150)
        pygame.draw.rect(w, (22, 28, 44), box, border_radius=14)
        pygame.draw.rect(w, (70, 212, 190), box, 2, border_radius=14)
        ovr = self.fit_text(str(card["rating"]), self.font_xl, WHITE, 150, 86)
        w.blit(ovr, ovr.get_rect(center=(box.x + 104, box.centery - 4)))
        lab = self.font_s.render("OVR", True, (176, 192, 214))
        w.blit(lab, lab.get_rect(center=(box.x + 104, box.bottom - 30)))
        pygame.draw.line(w, (60, 72, 98), (box.x + 200, box.y + 20), (box.x + 200, box.bottom - 20), 2)
        step = (box.w - 230) // 6
        for i, key in enumerate(STAT_KEYS):
            cx = box.x + 230 + step * i + step // 2
            val = st.get(key, 100)
            num = self.fit_text(str(val), self.font_l, self.stat_colour(val), step - 22, 66)
            w.blit(num, num.get_rect(center=(cx, box.centery - 10)))
            nm = self.fit_text(STAT_NAMES[key], self.font_s, (176, 192, 214), step - 8, 26)
            w.blit(nm, nm.get_rect(center=(cx, box.bottom - 30)))
        # PlayStyles and traits side by side
        half = (panel.w - 78) // 2
        left = pygame.Rect(panel.x + 26, box.bottom + 24, half, panel.bottom - box.bottom - 50)
        right = pygame.Rect(left.right + 26, left.y, half, left.h)
        evo = card.get("design") == "worldsgame"          # World's Game: its evolution instead
        for rect, title in ((left, "PLAYSTYLES"), (right, "EVOLUTION" if evo else "TRAITS")):
            pygame.draw.rect(w, (22, 28, 44), rect, border_radius=14)
            w.blit(self.font_m.render(title, True, WHITE), (rect.x + 24, rect.y + 18))
        styles = card.get("ps", ())
        if not styles:
            y = left.y + 92
            for ln in self.wrap_lines("None - this one trades them for higher stats and an extra trait.",
                                      self.font_s, left.w - 48):
                w.blit(ln, (left.x + 24, y))
                y += 44
        for i, (ps, level) in enumerate(styles):
            y = left.y + 96 + i * 124
            med = pygame.Rect(left.x + 28, y + 6, 72, 72)
            self.cv_medal(w, med, level, ps["group"], ps["key"])
            nm = self.fit_text(ps["name"], self.font_m, WHITE, left.w - 150, 50)
            w.blit(nm, (med.right + 24, y))
            sub = self.fit_text("Lvl %d  -  %s" % (level, PS_GROUP_NAME[ps["group"]]), self.font_s,
                                PS_LEVEL_COLOUR[level - 1], left.w - 150, 32)
            w.blit(sub, (med.right + 24, y + 56))
        if evo:
            self.cv_evolution(w, card, right)
            return
        tx, ty = right.x + 24, right.y + 86
        for t in card.get("traits", ()):
            chip = self.font_s.render(t["name"], True, (224, 234, 250))
            box2 = pygame.Rect(tx, ty, chip.get_width() + 34, 48)
            if box2.right > right.right - 24:
                tx, ty = right.x + 24, ty + 62
                box2 = pygame.Rect(tx, ty, chip.get_width() + 34, 48)
            pygame.draw.rect(w, (34, 44, 66), box2, border_radius=10)
            pygame.draw.rect(w, ABILITY_CATS.get(t["cat"], ("", (120, 190, 255)))[1], box2, 2, border_radius=10)
            w.blit(chip, chip.get_rect(center=box2.center))
            tx = box2.right + 16

    def cv_evolution(self, w, card, box):
        """A World's Game card's evolution: the four stages, the quest he's on, what's next."""
        stage = self.wg_stage(card)
        owned = self.owns(card)
        n = len(WG_EVO_NAMES)
        pip_w = (box.w - 48 - (n - 1) * 14) // n
        y = box.y + 84
        for i, nm in enumerate(WG_EVO_NAMES):               # the stages as a row of pips
            r = pygame.Rect(box.x + 24 + i * (pip_w + 14), y, pip_w, 64)
            done, here = i < stage, i == stage
            fill = (60, 26, 104) if done else (96, 40, 168) if here else (30, 34, 50)
            pygame.draw.rect(w, fill, r, border_radius=10)
            pygame.draw.rect(w, WG_EVO_AURA[0] if (done or here) else (60, 66, 88), r, 3 if here else 2,
                             border_radius=10)
            lab = self.fit_text(nm, self.font_s, WHITE if (done or here) else (120, 130, 150), r.w - 12, 26)
            w.blit(lab, lab.get_rect(center=(r.centerx, r.y + 22)))
            ov = self.fit_text("%d" % self.wg_evo_ovr(card, i), self.font_s,
                               (255, 236, 255) if (done or here) else (110, 120, 140), r.w - 12, 24)
            w.blit(ov, ov.get_rect(center=(r.centerx, r.y + 48)))
        y += 92
        if not owned:
            lines = ["Sign him in the Essence shop to start his evolution:",
                     "%d up to %d OVR, and his PlayStyles up to level 3." % (self.wg_evo_ovr(card, 0), WG_EVO_OVR)]
        elif stage >= len(WG_EVO_QUESTS):
            lines = ["FULLY EVOLVED - %s." % WG_EVO_NAMES[-1],
                     "%d OVR, a level 3 and a level 2 PlayStyle." % self.wg_evo_ovr(card, stage)]
        else:
            what, need, txt = WG_EVO_QUESTS[stage]
            have = int(self.wg_evo(card["id"]).get("n", 0))
            q = self.fit_text(txt, self.font_m, WHITE, box.w - 48, 40)
            w.blit(q, (box.x + 24, y))
            bar = pygame.Rect(box.x + 24, y + 56, box.w - 150, 24)
            pygame.draw.rect(w, (10, 12, 22), bar, border_radius=12)
            fill = int(bar.w * min(1.0, have / float(need)))
            if fill > 0:
                pygame.draw.rect(w, WG_EVO_AURA[0], (bar.x, bar.y, max(24, fill), bar.h), border_radius=12)
            cnt = self.fit_text("%d / %d" % (have, need), self.font_s, WHITE, 110, 30)
            w.blit(cnt, cnt.get_rect(midleft=(bar.right + 14, bar.centery)))
            nxt = stage + 1
            lv = WG_EVO_PS[nxt]
            lines = ["NEXT: %s - %d OVR, PlayStyles level %d and %d." % (WG_EVO_NAMES[nxt], self.wg_evo_ovr(card, nxt),
                                                                       lv[0], lv[1])]
            y += 96
        for ln in lines:
            img = self.fit_text(ln, self.font_s, (200, 190, 230), box.w - 48, 32)
            w.blit(img, (box.x + 24, y))
            y += 44

    # ---- tab 2: attributes
    def cv_attributes(self, w, card, panel):
        st = card.get("stats") or {}
        cw, ch = (panel.w - 78) // 2, (panel.h - 90) // 3
        for i, key in enumerate(STAT_KEYS):
            col, row = divmod(i, 3)
            r = pygame.Rect(panel.x + 26 + col * (cw + 26), panel.y + 24 + row * (ch + 14), cw, ch - 8)
            pygame.draw.rect(w, (22, 28, 44), r, border_radius=14)
            val = st.get(key, 100)
            nm = self.fit_text(STAT_NAMES[key], self.font_m, WHITE, r.w - 230, 48)
            w.blit(nm, (r.x + 26, r.y + 22))
            num = self.fit_text(str(val), self.font_l, self.stat_colour(val), 190, 70)
            w.blit(num, num.get_rect(midright=(r.right - 26, r.y + 48)))
            bar = pygame.Rect(r.x + 26, r.y + 92, r.w - 52, 20)
            pygame.draw.rect(w, (38, 46, 66), bar, border_radius=10)
            frac = stat01(val)
            if frac > 0:
                pygame.draw.rect(w, self.stat_colour(val),
                                 (bar.x, bar.y, max(8, int(bar.w * frac)), bar.h), border_radius=10)
            blurb = self.fit_text(STAT_BLURB[key], self.font_s, (168, 184, 208), r.w - 52, 34)
            w.blit(blurb, (r.x + 26, r.y + 126))

    # ---- tab 3: playstyles
    def cv_styles(self, w, card, panel):
        styles = card.get("ps", ())
        if not styles:
            self.centre_in(w, "NO PLAYSTYLES", pygame.Rect(panel.x, panel.y + 220, panel.w, 60), self.font_l)
            sub = "This one trades them for higher stats and an extra trait."
            self.centre_in(w, sub, pygame.Rect(panel.x, panel.y + 300, panel.w, 44), self.font_s,
                           (168, 184, 208))
            return
        cw = (panel.w - 78) // 2
        for i, (ps, level) in enumerate(styles):
            r = pygame.Rect(panel.x + 26 + i * (cw + 26), panel.y + 30, cw, panel.h - 80)
            pygame.draw.rect(w, (22, 28, 44), r, border_radius=16)
            pygame.draw.rect(w, PS_LEVEL_COLOUR[level - 1], r, 2, border_radius=16)
            self.cv_medal(w, pygame.Rect(r.centerx - 70, r.y + 36, 140, 140), level, ps["group"], ps["key"])
            lv = self.fit_text("Lvl %d" % level, self.font_m, PS_LEVEL_COLOUR[level - 1], 200, 46)
            w.blit(lv, lv.get_rect(midtop=(r.centerx, r.y + 196)))
            nm = self.fit_text(ps["name"], self.font_l, WHITE, r.w - 70, 76)
            w.blit(nm, nm.get_rect(midtop=(r.centerx, r.y + 252)))
            grp = self.fit_text(PS_GROUP_NAME[ps["group"]], self.font_s, (150, 164, 188), r.w - 70, 32)
            w.blit(grp, grp.get_rect(midtop=(r.centerx, r.y + 344)))
            how = "FIRES BY ITSELF  -  %s" % ("PURPLE: 2x" if level >= 3 else "GOLD: 1.5x" if level >= 2 else "SILVER")
            howimg = self.fit_text(how, self.font_s, (150, 164, 188), r.w - 60, 28)
            w.blit(howimg, howimg.get_rect(midtop=(r.centerx, r.y + 384)))
            trig = self.fit_text("HOW:  " + PS_HOW.get(ps["key"], ""), self.font_s, (120, 255, 170), r.w - 50, 34)
            w.blit(trig, trig.get_rect(midtop=(r.centerx, r.y + 420)))
            y = r.y + 470
            for line in self.wrap_lines(ps["text"], self.font_s, r.w - 80):
                w.blit(line, line.get_rect(midtop=(r.centerx, y)))
                y += 40

    # ---- tab 4: traits
    TRAIT_ICON = {"DEFENDING": (150, 196, 255), "DRIBBLING": (150, 240, 170),
                  "ATTACKING": (255, 164, 132), "DETAIL": (246, 214, 140),
                  "SKILL MOVE": (206, 176, 255), "CELEBRATION": (255, 190, 220)}

    def cv_traits(self, w, card, panel):
        items = [(t["name"], ABILITY_CATS.get(t["cat"], ("TRAIT", WHITE))[0], t["text"])
                 for t in card.get("traits", ())]
        items += [(f[1], f[2].upper(), "") for f in card.get("flavour", ())]
        cols, cw, ch = 4, (panel.w - 26 * 5) // 4, 196
        for i, (name, cat, text) in enumerate(items[:8]):
            col, row = i % cols, i // cols
            r = pygame.Rect(panel.x + 26 + col * (cw + 26), panel.y + 36 + row * (ch + 26), cw, ch)
            pygame.draw.rect(w, (22, 28, 44), r, border_radius=14)
            pygame.draw.rect(w, (52, 64, 90), r, 2, border_radius=14)
            cx, cy, rad = r.centerx, r.y + 62, 34
            hexa = [(cx + rad * math.cos(math.pi / 6 + k * math.pi / 3),
                     cy + rad * math.sin(math.pi / 6 + k * math.pi / 3)) for k in range(6)]
            col = self.TRAIT_ICON.get(cat.upper(), (236, 242, 255))
            pygame.draw.polygon(w, col, hexa)
            pygame.draw.polygon(w, (26, 32, 48), hexa, 3)
            pygame.draw.circle(w, (26, 32, 48), (cx, cy), 13)
            nm = self.fit_text(name, self.font_s, WHITE, r.w - 24, 30)
            w.blit(nm, nm.get_rect(center=(cx, r.y + 122)))
            ct = self.fit_text(cat.title(), self.font_s, (150, 164, 188), r.w - 24, 24)
            w.blit(ct, ct.get_rect(center=(cx, r.y + 158)))
        if len(items) < 1:
            self.centre_in(w, "NO TRAITS", pygame.Rect(panel.x, panel.y + 240, panel.w, 60), self.font_l)

    # ---- packs -------------------------------------------------
    # ---- Ren Aoyagi: the one card you have to earn ----------
    def ren_unlocked(self):
        return bool(self.save.get("ren_unlocked"))

    def lock_ren(self):
        """He never sits in a save that hasn't beaten Impossible with Japan."""
        self.save["owned"].pop(REN_CARD, None)
        self.save["stamina"].pop(REN_CARD, None)
        self.save["squad"] = [k for k in self.save["squad"] if k != REN_CARD]

    def ren_unlock_ready(self, result):
        """True the moment the Japan Impossible World Cup is won."""
        return (result == "win" and self.mode == "wc" and self.difficulty == IMPOSSIBLE
                and self.run_impossible                   # no dropping the difficulty mid-run
                and self.team is not None and self.teams
                and self.teams[self.team]["name"] == REN_UNLOCK_TEAM
                and self.round + 1 >= len(ROUNDS) and not self.ren_unlocked())

    def unlock_ren(self):
        if self.ren_unlocked() or REN_CARD not in self.cards:
            return False
        self.save["ren_unlocked"] = True
        self.give_card(self.cards[REN_CARD])
        self.toast("REN AOYAGI (187) UNLOCKED", CYAN)
        if len(self.save["squad"]) < SQUAD_SIZE:
            self.save["squad"].append(REN_CARD)
        self.write_save()
        return True

    def reveal_ren(self):
        """His card walks out over the CHAMPIONS screen."""
        card = self.cards[REN_CARD]
        self.pack_reveal = {"card": card, "t": 0.0, "count": self.save["owned"].get(REN_CARD, 1),
                            "pack": 0, "tier": "A", "opened": True, "back": "ren",
                            "art": self.pack_art[0]}
        self.fx = []
        self.state = PACK_OPEN
        self.sfx.play_track("pack", force=True)

    def give_card(self, card):
        owned = self.save["owned"]
        owned[card["id"]] = owned.get(card["id"], 0) + 1
        self.save["stamina"].setdefault(card["id"], 100)
        return owned[card["id"]]

    def open_starter_pack(self):
        pool = [c for c in self.cards.values() if c["kind"] == "club"]
        picked = []
        for tier in STARTER_TIERS:
            options = [c for c in pool if c["tier"] == tier and c not in picked]
            card = random.choice(options)
            picked.append(card)
            self.give_card(card)
        self.save["squad"] = [c["id"] for c in picked]
        self.save["starter_opened"] = True
        self.starter_cards = picked

    # ---- mail ------------------------------------------------
    # Messages live in the save file, so the website can drop one in (the admin console
    # writes into a player's save, and the site merges the broadcast ones) and the game
    # just reads them. A message can carry coins, star points or players, claimed once.
    MAIL_KEEP = 40

    def mail_list(self):
        box = self.save.setdefault("mail", [])
        if not isinstance(box, list):
            box = self.save["mail"] = []
        box.sort(key=lambda m: str(m.get("at", "")), reverse=True)
        del box[self.MAIL_KEEP:]
        return box

    def unread_mail(self):
        return sum(1 for m in self.mail_list() if not m.get("read"))

    def open_mail(self):
        self.state = MAIL
        self.mail_pick = 0
        self.mail_scroll = 0.0
        box = self.mail_list()
        if box:
            box[0]["read"] = True
            self.write_save()

    def mail_layout(self):
        rows = [pygame.Rect(60, 190 + i * 96, 620, 84) for i in range(7)]
        pane = pygame.Rect(720, 190, WIDTH - 780, 700)
        claim = pygame.Rect(0, 0, 380, 92)
        claim.center = (pane.centerx, pane.bottom - 70)
        return {"rows": rows, "pane": pane, "claim": claim}

    def mail_gift_words(self, gift):
        bits = []
        if gift.get("coins"):
            bits.append("%d COINS" % int(gift["coins"]))
        if gift.get("sp"):
            bits.append("%d STAR POINTS" % int(gift["sp"]))
        for cid in gift.get("cards", []) or []:
            card = self.cards.get(cid)
            if card:
                bits.append("%s (%d)" % (card["name"].upper(), card["rating"]))
        return "  +  ".join(bits)

    def claim_mail(self, msg):
        gift = msg.get("gift") or {}
        if msg.get("claimed") or not gift:
            return False
        coins = int(gift.get("coins") or 0)
        sp = int(gift.get("sp") or 0)
        if coins:
            self.save["coins"] = max(0, int(self.save.get("coins", 0)) + coins)
        if sp:
            self.save["star_points"] = max(0, int(self.save.get("star_points", 0)) + sp)
        given = []
        for cid in gift.get("cards", []) or []:
            card = self.cards.get(cid)
            if card:
                self.give_card(card)
                given.append(card["name"].upper())
        msg["claimed"] = True
        msg["read"] = True
        self.write_save()
        got = self.mail_gift_words(gift) or "NOTHING"
        self.toast("CLAIMED  -  %s" % got, YELLOW, 2.6)
        self.sfx.play("tap", 0.5)
        return True

    def mail_click(self, pos):
        L = self.mail_layout()
        box = self.mail_list()
        start = int(self.mail_scroll)
        for i, r in enumerate(L["rows"]):
            if start + i >= len(box):
                break
            if r.collidepoint(pos.x, pos.y):
                self.mail_pick = start + i
                box[self.mail_pick]["read"] = True
                self.write_save()
                return
        if box and L["claim"].collidepoint(pos.x, pos.y):
            msg = box[min(self.mail_pick, len(box) - 1)]
            self.claim_mail(msg)

    def draw_mail(self, w):
        w.blit(self.select_bg, (0, 0))
        wash(w, (6, 8, 18, 150))
        box = self.mail_list()
        self.centre_text(w, "MAIL", self.font_l, WHITE, 70)
        L = self.mail_layout()
        mouse = pygame.mouse.get_pos()
        if not box:
            self.centre_text(w, "NOTHING HERE YET", self.font_m, (190, 200, 210), 460)
            self.centre_text(w, "MESSAGES AND GIFTS FROM THE GAME SHOW UP HERE",
                             self.font_s, (150, 160, 175), 540)
            self.draw_back_button(w)
            return
        start = int(self.mail_scroll)
        pick = min(self.mail_pick, len(box) - 1)
        for i, r in enumerate(L["rows"]):
            idx = start + i
            if idx >= len(box):
                break
            m = box[idx]
            on = idx == pick
            hot = r.collidepoint(mouse)
            w.blit(tint(r.size, (12, 18, 30, 220) if on else (8, 12, 22, 170)), r.topleft)
            pygame.draw.rect(w, YELLOW if on else (WHITE if hot else (90, 104, 120)), r, 3,
                             border_radius=10)
            sub = self.fit_text(str(m.get("subject", "MESSAGE")).upper(), self.font_s, WHITE, r.w - 150, 30)
            w.blit(sub, (r.x + 18, r.y + 14))
            frm = self.fit_text(str(m.get("from", "THE GAME")).upper(), self.font_s, (160, 172, 190),
                                r.w - 150, 24)
            w.blit(frm, (r.x + 18, r.y + 50))
            if not m.get("read"):
                pygame.draw.circle(w, CYAN, (r.right - 34, r.y + 28), 10)
            if (m.get("gift") or {}) and not m.get("claimed"):
                tag = self.fit_text("GIFT", self.font_s, YELLOW, 90, 24)
                w.blit(tag, tag.get_rect(midright=(r.right - 20, r.bottom - 26)))
        if len(box) > len(L["rows"]):
            self.centre_text_at(w, "%d / %d" % (pick + 1, len(box)), 370, 900, (150, 160, 175))

        pane = L["pane"]
        msg = box[pick]
        w.blit(tint(pane.size, (8, 12, 22, 200)), pane.topleft)
        pygame.draw.rect(w, (120, 136, 156), pane, 3, border_radius=14)
        head = self.fit_text(str(msg.get("subject", "MESSAGE")).upper(), self.font_m, WHITE,
                             pane.w - 60, 54)
        w.blit(head, (pane.x + 30, pane.y + 26))
        meta = "%s   %s" % (str(msg.get("from", "THE GAME")).upper(), str(msg.get("at", ""))[:10])
        w.blit(self.fit_text(meta, self.font_s, (160, 172, 190), pane.w - 60, 26), (pane.x + 30, pane.y + 92))
        y = pane.y + 150
        for line in self.wrap_lines(str(msg.get("body", "")).upper(), self.font_s, pane.w - 60):
            w.blit(line, (pane.x + 30, y))
            y += 40
            if y > pane.bottom - 120:
                break
        gift = msg.get("gift") or {}
        if gift:
            words = self.mail_gift_words(gift)
            att = self.fit_text("ATTACHED:  " + words, self.font_s, YELLOW, pane.w - 60, 30)
            w.blit(att, att.get_rect(midtop=(pane.centerx, pane.bottom - 190)))
            btn = L["claim"]
            done = msg.get("claimed")
            hot = btn.collidepoint(mouse) and not done
            pygame.draw.rect(w, (40, 120, 70) if not done else (48, 54, 64), btn, border_radius=14)
            pygame.draw.rect(w, YELLOW if hot else WHITE, btn, 4, border_radius=14)
            self.centre_in(w, "CLAIMED" if done else "CLAIM", btn)
        self.draw_back_button(w)

    def wrap_lines(self, text, font, width):
        """Render a block of text into lines that fit, keeping the writer's own breaks."""
        out = []
        for para in str(text).split("\n"):
            words = para.split()
            if not words:
                out.append(font.render("", True, WHITE))
                continue
            line = words[0]
            for word in words[1:]:
                trial = line + " " + word
                if font.size(trial)[0] <= width:
                    line = trial
                else:
                    out.append(font.render(line, True, (222, 230, 240)))
                    line = word
            out.append(font.render(line, True, (222, 230, 240)))
        return out

    BACK_RECT = pygame.Rect(40, 30, 200, 70)

    def back_target(self):
        """Where the BACK button on this screen goes, or None if the screen has none."""
        st = self.state
        if st == TITLE:
            return (lambda: setattr(self, "menu_page", "main")) \
                if getattr(self, "menu_page", "main") == "play" else None
        if st in (SELECT, CLUB):
            return lambda: setattr(self, "state", TITLE)
        if st == TABLE:
            return self.table_click
        if st == PACKS:
            return self.open_store
        if st == PACK_VIEW:
            return (lambda: setattr(self, "view_more", False)) if self.view_more \
                else (lambda: setattr(self, "state", PACKS))
        if st == PACK_MULTI:
            return lambda: self.open_packs(self.multi["pack"])
        if st == LINEUP:
            if self.mode == "gauntlet":
                return self.enter_gauntlet if self.lineup_half == 1 else None
            return (self.go_to_club if self.mode == "club" else self.go_to_select) \
                if self.lineup_half == 1 else None
        if st == GAUNTLET:
            return lambda: setattr(self, "state", TITLE)
        if st in (MAIL, PROFILE, QUESTS):
            return lambda: setattr(self, "state", TITLE)
        if st == MYCLUB:
            def leave():
                self.refresh_team()
                self.write_save()
                self.state = TITLE
            return leave
        if st == STORE:
            return lambda: setattr(self, "state", TITLE)
        if st in (STARS, EXCHANGE):
            if st == STARS and self.store_confirm is None and self.ss()["modal"] is not None:
                return None                                 # the search box is over the BACK button
            return (lambda: setattr(self, "store_confirm", None)) if self.store_confirm is not None \
                else self.open_store
        if st == ESSENCE:
            return (lambda: setattr(self, "store_confirm", None)) if self.store_confirm is not None \
                else self.leave_essence
        if st == ARCHIVE:
            return (lambda: setattr(self, "store_confirm", None)) if self.store_confirm is not None \
                else self.open_store
        if st == EVENT:
            return self.open_store if self.event_spin is None else None
        if st == FREE_SELECT:
            def to_menu():
                self.state = TITLE
                self.menu_page = "play"
            return to_menu
        return None

    def back_click(self, pos):
        """True if that click was the BACK button. Every screen that has one answers here."""
        if self.tut is not None:
            return False                       # the tutorial drives you, it has its own buttons
        if not self.BACK_RECT.collidepoint(pos[0], pos[1]):
            return False
        go = self.back_target()
        if go is None:
            return False
        go()
        return True

    def draw_back_button(self, w):
        r = pygame.Rect(40, 30, 200, 70)
        hover = r.collidepoint(pygame.mouse.get_pos())
        pygame.draw.rect(w, SELECT_GREEN, r)
        pygame.draw.rect(w, YELLOW if hover else WHITE, r, 4)
        t = self.font_s.render("< BACK", True, YELLOW if hover else WHITE)
        w.blit(t, t.get_rect(center=r.center))
        return r

    def draw_coins(self, w):
        t = self.font_m.render("%d COINS" % self.save["coins"], True, YELLOW)
        pygame.draw.circle(w, YELLOW, (WIDTH - 60 - t.get_width() - 30, 64), 20)
        pygame.draw.circle(w, (190, 140, 20), (WIDTH - 60 - t.get_width() - 30, 64), 20, 4)
        w.blit(t, (WIDTH - 60 - t.get_width(), 40))

    def draw_essence_icon(self, w, centre, r=20):
        """A drop of something hot: dark rim, red body, a pale core."""
        x, y = int(centre[0]), int(centre[1])
        for k, col in ((1.0, (112, 20, 28)), (0.78, ESSENCE_RED), (0.42, ESSENCE_HOT)):
            rr = max(2, int(r * k))
            cy = y + int(r * 0.26) + int((r - rr) * 0.30)
            pygame.draw.circle(w, col, (x, cy), max(2, int(rr * 0.78)))
            pygame.draw.polygon(w, col, [(x, cy - int(rr * 1.42)), (x + int(rr * 0.72), cy - int(rr * 0.30)),
                                         (x - int(rr * 0.72), cy - int(rr * 0.30))])

    def draw_essence_count(self, w, y=112, right=WIDTH - 60):
        t = self.font_m.render("%s ESSENCE" % self.fmt(self.essence()), True, (255, 168, 140))
        w.blit(t, (right - t.get_width(), y))
        self.draw_essence_icon(w, (right - t.get_width() - 30, y + 22), 20)

    def burst_fireworks(self, x, y, colour, n=40):
        cap, scale = fx_budget()
        for _ in range(max(6, int(n * scale))):
            a = random.uniform(0, math.tau)
            sp = random.uniform(150, 520)
            self.fx.append([x, y, math.cos(a) * sp, math.sin(a) * sp,
                            random.uniform(0.8, 1.5), colour])
        if len(self.fx) > cap:                         # the oldest ones go, nobody notices
            del self.fx[:len(self.fx) - cap]

    def draw_fx(self, w, dt=None):
        """The firework squares. They move with real time, not with the frame, so they keep
        the same speed on the screens the browser only repaints every other frame."""
        now = pygame.time.get_ticks() / 1000.0
        last = getattr(self, "_fx_t", None)
        self._fx_t = now
        dt = min(0.1, max(0.0, now - last)) if last is not None else (dt or 1.0 / FPS)
        alive = []
        for p in self.fx:
            p[0] += p[2] * dt
            p[1] += p[3] * dt
            p[3] += 380 * dt
            p[4] -= dt
            if p[4] > 0:
                alive.append(p)
                pygame.draw.rect(w, p[5], (int(p[0]), int(p[1]), 9, 9))
        self.fx = alive

    # ---- My Club: team editor + squad ---------------------------
    def myclub_layout(self):
        L = {}
        L["name"] = pygame.Rect(60, 170, 680, 80)
        L["c1"] = [pygame.Rect(60 + i * 48, 330, 42, 42) for i in range(len(TEAM_PALETTE))]
        L["c2"] = [pygame.Rect(60 + i * 48, 440, 42, 42) for i in range(len(TEAM_PALETTE))]
        L["pattern"] = [pygame.Rect(60 + i * 172, 550, 160, 56) for i in range(len(PATTERNS))]
        L["squad"] = [pygame.Rect(830 + i * 205, 150, 180, 250) for i in range(SQUAD_SIZE)]
        L["coll"] = [pygame.Rect(830 + (i % 7) * 148, 520 + (i // 7) * 222, 130, 180) for i in range(14)]
        L["prev"] = pygame.Rect(830, 980, 120, 60)
        L["tutorial"] = pygame.Rect(60, 972, 320, 70)
        L["next"] = pygame.Rect(1760, 980, 120, 60)
        return L

    def owned_cards(self):
        cards = [self.cards[k] for k in self.save["owned"]]
        return sorted(cards, key=lambda c: (-c["rating"], c["name"]))

    def myclub_click(self, pos):
        L = self.myclub_layout()
        if pygame.Rect(40, 30, 200, 70).collidepoint(pos.x, pos.y):
            self.editing_name = False
            self.refresh_team()
            self.write_save()
            self.state = TITLE
            return
        if L["tutorial"].collidepoint(pos.x, pos.y):
            self.editing_name = False
            self.refresh_team()
            self.write_save()
            self.start_tutorial(replay=True)
            return
        self.editing_name = L["name"].collidepoint(pos.x, pos.y)
        t = self.save["team"]
        for i, r in enumerate(L["c1"]):
            if r.collidepoint(pos.x, pos.y):
                t["c1"] = i
        for i, r in enumerate(L["c2"]):
            if r.collidepoint(pos.x, pos.y):
                t["c2"] = i
        for i, r in enumerate(L["pattern"]):
            if r.collidepoint(pos.x, pos.y):
                t["pattern"] = PATTERNS[i]
        squad = self.save["squad"]
        # A press on a card only picks it up. What it means is decided when you let go
        # (club_release): moved = a drag, not moved = the click it always was.
        for i, r in enumerate(L["squad"]):
            if r.collidepoint(pos.x, pos.y) and i < len(squad):
                self.club_press(squad[i], "squad", r, pos)
        owned = self.owned_cards()
        page = owned[self.coll_page * 14:(self.coll_page + 1) * 14]
        for i, r in enumerate(L["coll"]):
            if r.collidepoint(pos.x, pos.y) and i < len(page):
                self.club_press(page[i]["id"], "coll", r, pos)
        pages = max(1, math.ceil(len(owned) / 14))
        if L["prev"].collidepoint(pos.x, pos.y):
            self.coll_page = (self.coll_page - 1) % pages
        if L["next"].collidepoint(pos.x, pos.y):
            self.coll_page = (self.coll_page + 1) % pages
        self.refresh_team()
        self.write_save()

    # ---- MY CLUB: drag and drop ------------------------------------------------------
    DRAG_START = 14            # pixels the pointer must travel before a press becomes a drag
    DRAG_CARD = (180, 250)     # the card in your hand is the size of a squad slot

    def club_toggle(self, cid):
        """What a plain click on a card does: into the squad if there is room, out if he is in it."""
        def run():
            squad = self.save["squad"]
            if self.season_running():
                return
            if cid in squad:
                squad.remove(cid)
            elif len(squad) < SQUAD_SIZE:
                squad.append(cid)
            self.refresh_team()
            self.write_save()
        return run

    def club_press(self, cid, src, rect, pos):
        # where on the card you took hold of it, as a fraction - so it doesn't jump under the pointer
        self.club_drag = {"id": cid, "src": src, "press": (pos.x, pos.y), "live": False,
                          "grab": ((pos.x - rect.x) / float(rect.w), (pos.y - rect.y) / float(rect.h)),
                          "locked": self.season_running()}

    def club_slot_at(self, pos):
        """Which squad slot a point is over (the nearest one, anywhere in the squad row), or None."""
        rects = self.myclub_layout()["squad"]
        row = rects[0].union(rects[-1]).inflate(40, 90)
        if not row.collidepoint(pos[0], pos[1]):
            return None
        return min(range(len(rects)), key=lambda i: abs(rects[i].centerx - pos[0]))

    def club_drag_live(self, pos):
        """True once the press has travelled far enough to be a drag. Stays true after that."""
        d = self.club_drag
        if d is None or d["locked"]:
            return False
        if not d["live"] and math.hypot(pos[0] - d["press"][0], pos[1] - d["press"][1]) >= self.DRAG_START:
            d["live"] = True
        return d["live"]

    def club_release(self, pos):
        d = self.club_drag
        live = self.club_drag_live((pos.x, pos.y))
        self.club_drag = None
        card = self.cards.get(d["id"])
        if card is None:
            return
        if not live:                                       # never moved: the click it always was
            self.card_click(card, self.club_toggle(d["id"]))
            return
        squad = self.save["squad"]
        cid = d["id"]
        slot = self.club_slot_at((pos.x, pos.y))
        if slot is None:
            if d["src"] == "squad" and cid in squad:       # carried out of the row: he is dropped
                squad.remove(cid)
        elif cid in squad:                                 # already in the squad: the two change places
            i, j = squad.index(cid), min(slot, len(squad) - 1)
            squad[i], squad[j] = squad[j], squad[i]
        elif slot < len(squad):                            # onto someone: takes his place
            squad[slot] = cid
        elif len(squad) < SQUAD_SIZE:                      # onto an empty slot: joins the end
            squad.append(cid)
        self.refresh_team()
        self.write_save()

    def draw_club_drag(self, w, L, mouse):
        """The card in your hand, and where it would land if you let go now."""
        d = self.club_drag
        card = self.cards.get(d["id"])
        if card is None:
            return
        squad = self.save["squad"]
        slot = self.club_slot_at(mouse)
        if slot is not None:
            j = slot if d["id"] in squad or slot < len(squad) else len(squad)
            j = min(j, len(squad) - 1) if d["id"] in squad else min(j, SQUAD_SIZE - 1)
            r = L["squad"][j]
            pygame.draw.rect(w, YELLOW, r.inflate(16, 16), 6, border_radius=18)
            if d["id"] in squad:
                word = "SWAP" if squad[j] != d["id"] else ""
            else:
                word = "REPLACE" if j < len(squad) else "ADD"
            if word:
                self.drag_tag(w, word, (r.centerx, r.bottom + 50), YELLOW, INK)
        cw, ch = self.DRAG_CARD
        r = pygame.Rect(int(mouse[0] - d["grab"][0] * cw), int(mouse[1] - d["grab"][1] * ch) - 10, cw, ch)
        wash(w, (0, 0, 0, 90), r.move(10, 16).clip(w.get_rect()))             # its shadow on the table
        self.blit_card(w, card, r)
        if slot is None and d["src"] == "squad":
            self.drag_tag(w, "LET GO TO REMOVE", (r.centerx, r.bottom + 30), (150, 30, 36), WHITE)

    def drag_tag(self, w, word, centre, fill, ink):
        """A small plate saying what letting go would do."""
        img = scaled_text(self.label(word, 420, ink, self.font_s), 0.74)
        box = img.get_rect(center=(int(centre[0]), int(centre[1]))).inflate(26, 10)
        pygame.draw.rect(w, fill, box, border_radius=10)
        pygame.draw.rect(w, ink, box, 2, border_radius=10)
        w.blit(img, img.get_rect(center=box.center))

    def myclub_key(self, event):
        t = self.save["team"]
        if event.key in (pygame.K_RETURN, pygame.K_ESCAPE):
            self.editing_name = False
        elif event.key == pygame.K_BACKSPACE:
            t["name"] = t["name"][:-1]
        elif event.unicode and (event.unicode.isalnum() or event.unicode == " ") and len(t["name"]) < 14:
            t["name"] = (t["name"] + event.unicode).upper()
        self.refresh_team()

    def draw_myclub(self, w):
        w.blit(self.select_bg, (0, 0))
        self.draw_back_button(w)
        self.draw_coins(w)
        self.centre_text(w, "MY CLUB", self.font_l, WHITE, 30)
        L = self.myclub_layout()
        t = self.save["team"]
        c1, c2, pattern = self.team_colours()
        mouse = pygame.mouse.get_pos()
        blink = int(pygame.time.get_ticks() / 400) % 2 == 0

        w.blit(self.font_s.render("TEAM NAME (CLICK TO TYPE)", True, (200, 220, 200)), (60, 130))
        pygame.draw.rect(w, (20, 40, 22), L["name"])
        pygame.draw.rect(w, YELLOW if self.editing_name else WHITE, L["name"], 4)
        name = t["name"] + ("_" if self.editing_name and blink else "")
        w.blit(self.font_m.render(name, True, WHITE), (L["name"].x + 16, L["name"].y + 14))
        for label, key, rects, y in (("SHIRT COLOUR", "c1", L["c1"], 290), ("SECOND COLOUR", "c2", L["c2"], 400)):
            w.blit(self.font_s.render(label, True, (200, 220, 200)), (60, y))
            for i, r in enumerate(rects):
                pygame.draw.rect(w, TEAM_PALETTE[i], r)
                pygame.draw.rect(w, YELLOW if t[key] == i else INK, r, 5 if t[key] == i else 2)
        w.blit(self.font_s.render("PATTERN", True, (200, 220, 200)), (60, 512))
        for i, r in enumerate(L["pattern"]):
            on = PATTERNS[i] == pattern
            pygame.draw.rect(w, SELECT_GREEN, r)
            pygame.draw.rect(w, YELLOW if on else WHITE, r, 5 if on else 2)
            tx = self.label(PATTERNS[i], r.w - 10, YELLOW if on else WHITE)
            w.blit(tx, tx.get_rect(center=r.center))
        # preview: badge + a player in the kit
        me = self.clubs[self.user_idx]
        if me["badge"] is not None:
            b = fit_flag(me["badge"], 150, 175)
            w.blit(b, b.get_rect(center=(200, 800)))
        squad = [self.cards[k] for k in self.save["squad"]]
        if squad:
            look = self.team_look(squad[0])
            self.draw_look_preview(w, look, (520, 800))
        # squad
        locked = self.season_running()
        drag = self.club_drag if self.club_drag_live(mouse) else None
        held = drag["id"] if drag else None
        w.blit(self.label("SQUAD (%d/%d)%s" % (len(squad), SQUAD_SIZE,
                          "  -  LOCKED DURING A SEASON" if locked
                          else "  -  DRAG TO SWAP PLACES, DRAG OUT TO REMOVE"), 1040, (200, 220, 200), self.font_s),
               (830, 110))
        for i, r in enumerate(L["squad"]):
            if i < len(squad):
                self.blit_card(w, squad[i], r, stamina=self.save["stamina"].get(squad[i]["id"], 100),
                               dim=squad[i]["id"] == held)
            else:
                pygame.draw.rect(w, (40, 70, 42), r, border_radius=14)
                pygame.draw.rect(w, (120, 150, 120), r, 3, border_radius=14)
                self.centre_in(w, "EMPTY", r)
        owned = self.owned_cards()
        pages = max(1, math.ceil(len(owned) / 14))
        self.coll_page %= pages
        w.blit(self.label("YOUR CARDS (%d)  -  DRAG ONE UP INTO THE SQUAD, DOUBLE-CLICK FOR STATS" % len(owned),
                          1040, (200, 220, 200), self.font_s), (830, 470))
        if REN_IN_GAME and not self.ren_unlocked():
            note = self.label("LOCKED:  REN AOYAGI (187)  -  " + REN_UNLOCK_HOW, 1000,
                              (150, 205, 235), font=self.font_s)
            w.blit(note, (830, 438))
        page = owned[self.coll_page * 14:(self.coll_page + 1) * 14]
        for i, r in enumerate(L["coll"]):
            if i < len(page):
                c = page[i]
                insq = c["id"] in self.save["squad"]
                self.blit_card(w, c, r, count=self.save["owned"][c["id"]], dim=insq or c["id"] == held,
                               glow=r.collidepoint(mouse) and not insq and drag is None)
        for key, txt in (("prev", "<"), ("next", ">")):
            pygame.draw.rect(w, SELECT_GREEN, L[key])
            pygame.draw.rect(w, WHITE, L[key], 3)
            self.centre_in(w, txt, L[key])
        self.centre_text_at(w, "PAGE %d / %d" % (self.coll_page + 1, pages),      # between the two arrows
                            (L["prev"].right + L["next"].x) // 2, L["prev"].centery)
        tb = L["tutorial"]
        pygame.draw.rect(w, (40, 80, 160), tb, border_radius=14)
        pygame.draw.rect(w, YELLOW if tb.collidepoint(mouse) else WHITE, tb, 3, border_radius=14)
        lab = self.label("REPLAY TUTORIAL", tb.w - 30, WHITE)
        w.blit(lab, lab.get_rect(center=tb.center))
        if drag is not None:                               # last, so the card in your hand is on top
            self.draw_club_drag(w, L, mouse)

    def centre_in(self, w, text, rect, font=None, color=WHITE):
        img = (font or self.font_s).render(text, True, color)
        w.blit(img, img.get_rect(center=rect.center))

    def draw_look_preview(self, w, look, centre):
        """Standing preview of a player in a look (not physics, just pieces)."""
        cx, cy = centre
        for piece, off in (("leg", (-12, TORSO_H / 2 + LEG_L / 2 - 4)), ("leg", (12, TORSO_H / 2 + LEG_L / 2 - 4)),
                           ("arm", (-SHOULDER_X, SHOULDER_Y + ARM_L / 2)), ("arm", (SHOULDER_X, SHOULDER_Y + ARM_L / 2)),
                           ("torso", (0, 0)), ("head", (0, -TORSO_H / 2 - HEAD_R - 2))):
            img = look.get(piece)
            if img is None:
                continue
            img = scaled(img, (img.get_width() * 2, img.get_height() * 2))
            w.blit(img, img.get_rect(center=(int(cx + off[0] * 2), int(cy + off[1] * 2))))

    # ---- lineup / half-time sub ------------------------------------
    def lineup_cards(self):
        if self.mode == "gauntlet":
            return self.gt_squad_cards()
        if self.mode == "club":
            return [self.cards[k] for k in self.save["squad"]]
        if self.mode == "pvp":                            # online: your own squad is your bench
            squad = [self.cards[k] for k in self.save.get("squad", ()) if k in self.cards and self.owns(self.cards[k])]
            if self.my_card is not None and all(c["id"] != self.my_card["id"] for c in squad):
                squad.insert(0, self.my_card)
            return squad[:6] or [self.my_card]
        code = self.teams[self.team]["name"]
        return [c for c in self.cards.values() if c["kind"] == "wc" and c["team"] == code]

    def stamina_of(self, card):
        if self.mode == "gauntlet":
            return self.gt_stam().get(card["id"], 0)
        if self.mode == "club":
            return self.save["stamina"].get(card["id"], 100)
        return self.wc_stamina.get(card["id"], 100)

    def set_stamina(self, card, value):
        value = int(clamp(value, 0, 100))
        if self.mode == "gauntlet":
            if self.gt_run() is not None:
                self.gt_stam()[card["id"]] = value
            return
        if self.mode == "club":
            self.save["stamina"][card["id"]] = value
        else:
            self.wc_stamina[card["id"]] = value

    def go_lineup(self, half):
        self.lineup_half = half
        self.state = LINEUP
        self.dragging = False
        self.slowmo = 1.0

    def lineup_layout(self):
        n = len(self.lineup_cards())
        w, h, gap = 260, 360, 50
        x0 = (WIDTH - (n * w + (n - 1) * gap)) // 2
        return [pygame.Rect(x0 + i * (w + gap), 330, w, h) for i in range(n)]

    def available(self, card):
        cards = self.lineup_cards()
        if all(self.stamina_of(c) <= 0 for c in cards):
            return True                                   # everyone's tired: anyone can go
        return self.stamina_of(card) > 0

    def lineup_click(self, pos):
        if getattr(self, "sub", None) is not None:
            self.sub_click(pos)
            return
        cards = self.lineup_cards()
        for card, rect in zip(cards, self.lineup_layout()):
            if rect.collidepoint(pos.x, pos.y):
                ok = self.available(card)
                self.card_click(card, (lambda c=card: self.pick_player(c)) if ok else (lambda: None))
                return

    def half_cost(self, card, base=None):
        """Stamina a half costs this card - RELENTLESS takes a quarter off (a third at gold)."""
        if base is None:
            base = GT_HALF if self.mode == "gauntlet" else STAMINA_PER_HALF
        for ps, level in card.get("ps", ()):
            if ps["key"] == "relentless":
                return int(round(base * (1.0 - (0.40 if level >= 3 else 0.33 if level >= 2 else 0.25))))
        return base

    def pick_player(self, card):
        if getattr(self, "sub", None) is not None:        # half time: pick him and go (SKIP)
            if self.sub["phase"] == "pick":
                self.sub["pick"] = card["id"]
                self.end_sub_pick()
            return
        self.set_stamina(card, self.stamina_of(card) - self.half_cost(card))
        self.played_this_match.add(card["id"])
        self.my_card = card
        self.player.set_stats(self.upgraded(card))
        # CPU sends out a random player each half
        self.pick_cpu()
        if self.lineup_half == 1:
            self.new_match()
            self.start_versus()                            # TEAM1 vs TEAM2 before kick-off
        else:
            self.half = 2                                  # second half kicks off
            if (self.mode == "club" and LADDER) or self.mode == "gauntlet":
                self.apply_twist()                         # the wind turns round
            self.apply_looks()
            self.setup_kickoff(None)
        self.write_save()

    def pick_cpu(self):
        if self.mode == "gauntlet":
            self.cpu_card = self.gt_pick_cpu()
            boost = self.opp_boost()
            if self.cpu_card is not None and boost:
                c = self.cpu_card
                self.cpu_card = dict(c, rating=c["rating"] + boost[0], sho=c["sho"] + boost[1],
                                     str=c["str"] + boost[1], boosted=True)
            self.cpu.set_stats(self.cpu_card)
            return
        if self.mode == "club":
            code = self.clubs[self.club_opps[-1]]["code"]
            pool = [c for c in self.cards.values() if c["kind"] == "club" and c["team"] == code]
        else:
            code = self.teams[self.opponents[-1]]["name"]
            pool = [c for c in self.cards.values() if c["kind"] == "wc" and c["team"] == code]
        self.cpu_card = random.choice(pool) if pool else None
        boost = self.opp_boost()
        if self.cpu_card is not None and boost:
            c = self.cpu_card
            self.cpu_card = dict(c, rating=c["rating"] + boost[0], sho=c["sho"] + boost[1],
                                 str=c["str"] + boost[1], boosted=True)
        self.cpu.set_stats(self.cpu_card)

    def draw_lineup(self, w):
        if getattr(self, "sub", None) is not None:
            self.draw_sub(w)
            return
        w.blit(self.select_bg, (0, 0))
        if self.lineup_half == 1:
            title = "KICK-OFF: WHO STARTS?"
        else:
            title = "HALF TIME  %d - %d  :  WHO PLAYS THE 2ND HALF?" % (self.score_home, self.score_away)
        self.centre_text(w, title, self.font_l if self.lineup_half == 1 else self.font_m, WHITE, 60)
        opp = (self.clubs[self.club_opps[-1]] if self.mode == "club" else None)
        sub = "PLAYING A HALF COSTS %d%% STAMINA  -  0%% = CAN'T PLAY" % (
            GT_HALF if self.mode == "gauntlet" else STAMINA_PER_HALF)
        if self.mode == "gauntlet":
            sub = "THE GAUNTLET, RUNG %d:  A HALF COSTS %d%%  -  4 HALVES EACH FOR THE WHOLE RUN" % (
                self.gt_rung() + 1, GT_HALF)
            b = self.gt_team_badge(self.gt_rung())
            if b is not None:
                b = fit_flag(b, 90, 100)
                w.blit(b, b.get_rect(center=(WIDTH - 120, 110)))
        self.centre_text(w, sub, self.font_s, (200, 220, 200), 190)
        if opp is not None and opp["badge"] is not None:
            b = fit_flag(opp["badge"], 90, 100)
            w.blit(b, b.get_rect(center=(WIDTH - 120, 110)))
        mouse = pygame.mouse.get_pos()
        for card, rect in zip(self.lineup_cards(), self.lineup_layout()):
            ok = self.available(card)
            st = self.stamina_of(card)
            self.blit_card(w, card, rect, stamina=st, dim=not ok, glow=ok and rect.collidepoint(mouse))
            lab = "%d%%" % st if ok else "TIRED"
            self.centre_text_at(w, lab, rect.centerx, rect.bottom + 34, YELLOW if ok else (230, 90, 90))
            if card.get("id") in self.played_this_match:
                self.centre_text_at(w, "PLAYED 1ST HALF", rect.centerx, rect.y - 34, (200, 220, 200))
        self.draw_back_button(w)

    # ---- half time: the timed IN / OUT sub ------------------------------------------
    # pick (20 s vs the CPU, SKIP ends it; 10 s online) -> the CPU (or the rival) picks ->
    # the reveal: both teams, who went OFF and who came ON -> the second half.
    def start_sub(self):
        online = self.mode == "pvp"
        cards = self.lineup_cards()
        cur = self.my_card
        ok = [c for c in cards if self.available(c)]
        keep = cur if cur is not None and any(c["id"] == cur["id"] for c in ok) else None
        pick = keep or (max(ok, key=lambda c: (self.stamina_of(c), c["rating"])) if ok else cur)
        self.sub = {"t": 0.0, "phase": "pick", "online": online,
                    "limit": SUB_ONLINE if online else SUB_OFFLINE,
                    "out": cur["id"] if cur else None, "pick": pick["id"] if pick else None,
                    "opp_out": self.cpu_card["id"] if self.cpu_card else None, "opp_in": None,
                    "why": "", "remote": getattr(self, "remote_sub", None), "sent": False}
        self.remote_sub = None
        self.lineup_half = 2
        self.state = LINEUP
        self.dragging = False
        self.slowmo = 1.0
        self.sfx.play("whistle", 0.3)

    def update_sub(self, dt):
        sub = self.sub
        sub["t"] += dt
        if sub["phase"] == "pick":
            if sub["t"] >= sub["limit"]:
                self.end_sub_pick()
        elif sub["phase"] == "wait":                      # online, host: my clock is up, theirs?
            if sub["remote"] is not None or sub["t"] >= SUB_GRACE:
                self.finish_online_sub()
        elif sub["phase"] == "reveal":
            if sub["t"] >= (SUB_REVEAL_ONLINE if sub["online"] else SUB_REVEAL):
                self.kick_off_second_half()

    def sub_layout(self):
        cards = self.lineup_cards()
        n = max(1, len(cards))
        area = pygame.Rect(470, 300, WIDTH - 470 - 70, 500)
        gap = 78                                          # room for the flag cards' flag and badges
        cw = min(240, (area.w - (n - 1) * gap) // n)
        ch = int(cw * 1.36)
        x0 = area.x + (area.w - (n * cw + (n - 1) * gap)) // 2
        bench = [pygame.Rect(x0 + i * (cw + gap), area.y + 40, cw, ch) for i in range(n)]
        out = pygame.Rect(110, 340, 250, 340)
        skip = pygame.Rect(WIDTH - 360, HEIGHT - 150, 290, 92)
        bar = pygame.Rect(WIDTH // 2 - 520, 186, 1040, 26)
        return {"cards": cards, "bench": bench, "out": out, "skip": skip, "bar": bar}

    def sub_click(self, pos):
        sub = self.sub
        if sub["phase"] == "reveal":
            if not sub["online"]:
                self.kick_off_second_half()               # click: straight to kick-off
            return
        if sub["phase"] != "pick":
            return
        L = self.sub_layout()
        if not sub["online"] and L["skip"].collidepoint(pos[0], pos[1]):
            self.end_sub_pick()                           # SKIP: go with who's picked
            return
        for card, rect in zip(L["cards"], L["bench"]):
            if rect.collidepoint(pos[0], pos[1]):
                if self.available(card):
                    self.card_click(card, lambda c=card: self.sub.__setitem__("pick", c["id"])
                                    if self.sub is not None and self.sub["phase"] == "pick" else None)
                else:
                    self.toast("%s IS TOO TIRED TO PLAY" % card["name"].upper(), (255, 150, 150), 1.6)
                return

    def end_sub_pick(self):
        """The clock ran out (or SKIP): your pick is final."""
        sub = self.sub
        if sub is None or sub["phase"] != "pick":
            return
        if sub["online"]:
            self.net.send({"t": "sub", "card": sub["pick"]})
            sub["sent"] = True
            if self.pvp_host():
                sub["phase"], sub["t"] = "wait", 0.0       # wait (briefly) for the rival's pick
            else:
                sub["phase"], sub["t"] = "guest_wait", 0.0  # the host says when
            return
        card = self.cards[sub["pick"]] if sub["pick"] in self.cards else self.my_card
        if card is not None:                              # what picking a player always did
            self.set_stamina(card, self.stamina_of(card) - self.half_cost(card))
            self.played_this_match.add(card["id"])
            self.my_card = card
            self.player.set_stats(self.upgraded(card))
        self.cpu_sub()                                    # then the CPU answers it
        sub["opp_in"] = self.cpu_card["id"] if self.cpu_card else None
        sub["phase"], sub["t"] = "reveal", 0.0
        self.write_save()

    # ---- online: the host collects both picks and tells the guest -------------------------
    def got_remote_sub(self, msg):
        cid = msg.get("card")
        if cid not in self.cards:
            return
        if getattr(self, "sub", None) is not None:
            self.sub["remote"] = cid
        else:
            self.remote_sub = cid                         # it beat our own half-time whistle

    def finish_online_sub(self):
        """Host: apply both picks, tell the guest, show the reveal."""
        sub = self.sub
        mine = self.cards.get(sub["pick"]) or self.my_card
        theirs = self.cards.get(sub["remote"]) if sub["remote"] else None
        theirs = theirs or self.cpu_card                  # no word from them: they keep their player
        self.net.send({"t": "subgo", "host": mine["id"], "guest": theirs["id"]})
        self.apply_online_sub(mine, theirs)

    def got_subgo(self, msg):
        """Guest: the host's word on both picks (host's 'guest' card is mine)."""
        if getattr(self, "sub", None) is None:
            return
        mine = self.cards.get(msg.get("guest")) or self.my_card
        theirs = self.cards.get(msg.get("host")) or self.cpu_card
        self.apply_online_sub(mine, theirs)

    def apply_online_sub(self, mine, theirs):
        sub = self.sub
        self.my_card, self.cpu_card = mine, theirs
        self.player.set_stats(mine)
        self.cpu.set_stats(theirs)
        sub["opp_in"] = theirs["id"]
        sub["why"] = ""
        sub["phase"], sub["t"] = "reveal", 0.0

    def kick_off_second_half(self):
        self.sub = None
        self.half = 2                                     # second half kicks off
        if (self.mode == "club" and LADDER) or self.mode == "gauntlet":
            self.apply_twist()                            # the wind turns round (it never did, via the sub)
        self.apply_looks()
        self.setup_kickoff(None)

    # ---- the CPU's half-time sub: how good it is decides how clever it is ----------------
    SUB_SMART = {0: "random", 1: "situation", 2: "counter", IMPOSSIBLE: "counter"}

    @staticmethod
    def sub_profile(card):
        st = card.get("stats") or {}
        g = lambda k: float(st.get(k, card.get("rating", 80)))
        return {"att": (g("shot") + g("drib")) / 2.0, "wall": (g("def") + g("phys")) / 2.0,
                "pace": g("speed"), "ovr": float(card.get("rating", 80))}

    def sub_score(self, c, mine, how, behind):
        """How good card c is for the CPU's second half (higher is better)."""
        p = self.sub_profile(c)
        score = p["ovr"]
        # the situation: chasing the game wants goals, protecting a lead wants a wall
        if behind > 0:
            score += 0.30 * min(2, behind) * (p["att"] - p["wall"])
        elif behind < 0:
            score += 0.30 * min(2, -behind) * (p["wall"] - p["att"])
        if how == "counter" and mine is not None:
            y = self.sub_profile(mine)
            stop = p["wall"] - y["att"]                  # can he stop your man?
            beat = p["att"] - y["wall"]                  # can he get past him?
            w = clamp((y["att"] - y["wall"]) / 120.0 + 0.5, 0.2, 0.8)   # how dangerous yours is
            score += 0.55 * (w * stop + (1.0 - w) * beat) + 0.30 * (p["pace"] - y["pace"])
        return score

    def cpu_pool(self):
        if self.mode == "gauntlet":
            return self.gt_team_cards(self.gt_rung())
        if self.mode == "club":
            code = self.clubs[self.club_opps[-1]]["code"]
            return [c for c in self.cards.values() if c["kind"] == "club" and c["team"] == code]
        code = self.teams[self.opponents[-1]]["name"]
        return [c for c in self.cards.values() if c["kind"] == "wc" and c["team"] == code]

    def cpu_sub(self):
        """EASY: anyone (as before). MEDIUM: the best card for the score. HARD and IMPOSSIBLE:
        the best COUNTER to the player you just sent on (and the score)."""
        pool = self.cpu_pool()
        if not pool:
            return
        diff = IMPOSSIBLE if self.impossible_run() else self.difficulty
        if self.mode == "gauntlet":
            diff = self.gt_cpu_level()
        how = self.SUB_SMART.get(diff, "random")
        before = self.cpu_card
        if how == "random":
            pick = random.choice(pool)
            why = ""
        else:
            behind = self.score_home - self.score_away    # goals the CPU is behind
            pick = max(pool, key=lambda c: self.sub_score(c, self.my_card, how, behind))
            if how == "counter":
                why = "COUNTERS YOUR %s" % self.my_card["name"].upper() if self.my_card else ""
            elif behind > 0:
                why = "CHASING THE GAME"
            elif behind < 0:
                why = "PROTECTING THE LEAD"
            else:
                why = "ITS BEST PLAYER"
        boost = self.opp_boost()
        if boost:
            pick = dict(pick, rating=pick["rating"] + boost[0], sho=pick["sho"] + boost[1],
                        str=pick["str"] + boost[1], boosted=True)
        self.cpu_card = pick
        self.cpu.set_stats(pick)
        if self.sub is not None:
            self.sub["why"] = why if (before is None or before["id"] != pick["id"]) else \
                ("KEEPS HIM ON" if not why else why)

    # ---- drawing ----------------------------------------------------------------------
    def draw_sub(self, w):
        w.blit(tinted(self.select_bg, (4, 8, 20, 150), "subs"), (0, 0))
        if self.sub["phase"] == "reveal":
            self.draw_sub_reveal(w)
            return
        sub, L = self.sub, self.sub_layout()
        self.centre_text(w, "HALF TIME  %d - %d" % (self.score_home, self.score_away), self.font_l, WHITE, 62)
        tip = "PICK WHO COMES ON" if sub["phase"] == "pick" else "WAITING FOR YOUR RIVAL..."
        self.centre_text(w, "SUBSTITUTION  -  " + tip, self.font_s, (200, 220, 240), 140)
        # the clock
        left = max(0.0, sub["limit"] - sub["t"]) if sub["phase"] == "pick" else 0.0
        bar = L["bar"]
        pygame.draw.rect(w, (18, 24, 44), bar, border_radius=12)
        k = left / sub["limit"]
        hurry = left <= 5.0 and sub["phase"] == "pick"
        col = (230, 70, 70) if hurry else (90, 210, 120)
        if k > 0:
            pygame.draw.rect(w, col, (bar.x, bar.y, max(12, int(bar.w * k)), bar.h), border_radius=12)
        pygame.draw.rect(w, WHITE, bar, 3, border_radius=12)
        secs = self.outlined("%d" % int(math.ceil(left)), self.font_l, col if hurry else WHITE, 0.9, INK, 5)
        pulse = 1.0 + (0.12 * math.sin(pygame.time.get_ticks() * 0.02) if hurry else 0.0)
        if pulse != 1.0:
            secs = pygame.transform.smoothscale(secs, (int(secs.get_width() * pulse), int(secs.get_height() * pulse)))
        w.blit(secs, secs.get_rect(midleft=(bar.right + 30, bar.centery)))
        # OUT: who played the first half
        out = self.cards.get(sub["out"])
        r = L["out"]
        self.centre_text_at(w, "ON THE PITCH", r.centerx, r.y - 36, (200, 220, 240))
        if out is not None:
            self.blit_card(w, out, r, stamina=self.stamina_of(out) if not sub["online"] else None)
        changing = sub["pick"] != sub["out"]
        self.draw_sub_tag(w, "OUT" if changing else "STAYS", (r.centerx, r.bottom + 60),
                          (230, 70, 70) if changing else (150, 160, 180), down=True if changing else None)
        # the swap arrow
        ax, ay = r.right + 50, r.centery
        pygame.draw.polygon(w, (255, 255, 255), [(ax, ay - 20), (ax + 40, ay - 20), (ax + 40, ay - 40),
                                                 (ax + 72, ay), (ax + 40, ay + 40), (ax + 40, ay + 20), (ax, ay + 20)])
        # the bench: tap who comes ON
        mouse = pygame.mouse.get_pos()
        for card, rect in zip(L["cards"], L["bench"]):
            ok = self.available(card)
            on = card["id"] == sub["pick"]
            st = None if sub["online"] else self.stamina_of(card)
            self.blit_card(w, card, rect, stamina=st, dim=not ok,
                           glow=on or (ok and rect.collidepoint(mouse) and sub["phase"] == "pick"))
            if on:
                self.draw_sub_tag(w, "IN", (rect.centerx, rect.y - 40), (80, 220, 110), down=False)
            elif card["id"] == sub["out"]:
                self.centre_text_at(w, "PLAYED 1ST HALF", rect.centerx, rect.y - 30, (200, 220, 200))
            if not sub["online"]:
                lab = "%d%%" % self.stamina_of(card) if ok else "TIRED"
                self.centre_text_at(w, lab, rect.centerx, rect.bottom + 56, YELLOW if ok else (230, 90, 90))
        # SKIP (offline only)
        if not sub["online"] and sub["phase"] == "pick":
            b = L["skip"]
            hov = b.collidepoint(mouse)
            pygame.draw.rect(w, (40, 170, 70), b, border_radius=16)
            pygame.draw.rect(w, YELLOW if hov else WHITE, b, 5, border_radius=16)
            self.centre_in(w, "SKIP  >>", b, self.font_m)
        note = ("PLAYING A HALF COSTS %d%% STAMINA" % STAMINA_PER_HALF) if not sub["online"] else \
            "ONLINE: %d SECONDS, THEN BOTH SUBS ARE SHOWN" % int(SUB_ONLINE)
        self.centre_text(w, note, self.font_s, (170, 190, 220), HEIGHT - 60)

    def draw_sub_tag(self, w, text, centre, colour, down):
        """A coloured tag with an arrow: green IN (up), red OUT (down)."""
        img = self.font_m.render(text, True, WHITE)
        box = img.get_rect(center=centre).inflate(70, 18)
        pygame.draw.rect(w, colour, box, border_radius=12)
        pygame.draw.rect(w, WHITE, box, 3, border_radius=12)
        w.blit(img, img.get_rect(center=(box.centerx + 14, box.centery)))
        x, y = box.x + 24, box.centery
        if down is None:
            pygame.draw.circle(w, WHITE, (x, y), 7)
        elif down:
            pygame.draw.polygon(w, WHITE, [(x - 11, y - 8), (x + 11, y - 8), (x, y + 10)])
        else:
            pygame.draw.polygon(w, WHITE, [(x - 11, y + 8), (x + 11, y + 8), (x, y - 10)])

    def draw_sub_reveal(self, w):
        """Both teams, side by side: OUT -> IN (or STAYS ON)."""
        sub = self.sub
        self.centre_text(w, "SUBSTITUTIONS", self.font_l, WHITE, 70)
        home, away = self.match_sides() if hasattr(self, "match_sides") else (("YOU", None), ("RIVAL", None))
        names = (home[0] if home else "YOU", away[0] if away else "RIVAL")
        if self.mode == "pvp" and self.pvp:
            names = (self.pvp["name"].upper(), self.pvp["opp"].upper())
        pairs = ((sub["out"], self.my_card["id"] if self.my_card else None),
                 (sub["opp_out"], sub["opp_in"]))
        for side, ((o, i), name) in enumerate(zip(pairs, names)):
            cx = WIDTH // 4 + side * WIDTH // 2
            self.centre_text_at(w, name, cx, 190, YELLOW if side == 0 else (255, 150, 150), self.font_m)
            out, inn = self.cards.get(o), self.cards.get(i)
            if out is not None and inn is not None and out["id"] != inn["id"]:
                ro = pygame.Rect(cx - 330, 330, 220, 300)
                ri = pygame.Rect(cx + 80, 290, 260, 354)
                self.blit_card(w, out, ro, dim=True)
                self.blit_card(w, inn, ri, glow=True)
                self.draw_sub_tag(w, "OUT", (ro.centerx, ro.bottom + 54), (230, 70, 70), down=True)
                self.draw_sub_tag(w, "IN", (ri.centerx, ri.bottom + 54), (80, 220, 110), down=False)
                ax, ay = cx - 70, ro.centery
                pygame.draw.polygon(w, WHITE, [(ax, ay - 16), (ax + 60, ay - 16), (ax + 60, ay - 34),
                                               (ax + 104, ay), (ax + 60, ay + 34), (ax + 60, ay + 16), (ax, ay + 16)])
            else:
                keep = inn or out
                if keep is not None:
                    rk = pygame.Rect(cx - 130, 290, 260, 354)
                    self.blit_card(w, keep, rk)
                    self.draw_sub_tag(w, "STAYS ON", (rk.centerx, rk.bottom + 54), (110, 120, 150), down=None)
            if side == 1 and sub.get("why"):
                diff = "IMPOSSIBLE" if self.impossible_run() else DIFFICULTY[self.difficulty][0]
                self.centre_text_at(w, "CPU (%s): %s" % (diff, sub["why"]), cx, 790, (200, 214, 240))
        pygame.draw.line(w, (90, 110, 160), (WIDTH // 2, 170), (WIDTH // 2, 820), 3)
        hint = "SECOND HALF IN A MOMENT" if sub["online"] else "CLICK TO KICK OFF"
        self.centre_text(w, hint, self.font_s, (170, 190, 220), HEIGHT - 60)

    def centre_text_at(self, w, text, x, y, color=WHITE, font=None):
        img = (font or self.font_s).render(text, True, color)
        w.blit(img, img.get_rect(center=(int(x), int(y))))

    # ---- after the whistle ----------------------------------------
    # ---- levels ----------------------------------------------------
    def level(self):
        return level_from_xp(self.save.get("xp", 0))[0]

    def award_xp(self, amount):
        before = self.level()
        self.save["xp"] = self.save.get("xp", 0) + int(amount)
        self.last_xp = int(amount)
        after = self.level()
        if after > before:
            bonus = sum(LEVEL_UP_COINS * lv for lv in range(before + 1, after + 1))
            self.save["coins"] += bonus
            self.toast("LEVEL UP!  LEVEL %d   +%d COINS" % (after, bonus), YELLOW)
            if before < IMPOSSIBLE_LEVEL <= after:
                self.toast("IMPOSSIBLE MODE UNLOCKED  -  ITS TAB IS OPEN IN PLAY", (255, 110, 110))
        self.write_save()

    def toast(self, text, colour=WHITE, seconds=3.5):
        if not hasattr(self, "toasts"):
            self.toasts = []
        self.toasts.append([text, colour, seconds])

    def draw_toasts(self, w):
        alive = []
        for i, t in enumerate(getattr(self, "toasts", [])[:3]):
            t[2] -= 1.0 / FPS
            if t[2] <= 0:
                continue
            alive.append(t)
            img = self.label(t[0], 1200, t[1], self.font_m)
            box = img.get_rect(center=(WIDTH // 2, 150 + i * 96)).inflate(60, 30)
            veil = pygame.Surface(box.size, pygame.SRCALPHA)
            veil.fill((8, 10, 24, 215))
            w.blit(veil, box.topleft)
            pygame.draw.rect(w, t[1], box, 4, border_radius=10)
            w.blit(img, img.get_rect(center=box.center))
        self.toasts = alive + getattr(self, "toasts", [])[3:]

    def draw_level(self, w, x, y, width=340):
        level, into, need = level_from_xp(self.save.get("xp", 0))
        badge = pygame.Rect(x, y, 110, 56)
        pygame.draw.rect(w, (30, 60, 140), badge, border_radius=12)
        pygame.draw.rect(w, (140, 220, 255), badge, 4, border_radius=12)
        self.centre_in(w, "LV %d" % level, badge)
        bar = pygame.Rect(x + 124, y + 12, width - 124, 32)
        pygame.draw.rect(w, (20, 24, 40), bar, border_radius=8)
        pygame.draw.rect(w, (80, 190, 255), (bar.x, bar.y, int(bar.w * into / max(1, need)), bar.h),
                         border_radius=8)
        pygame.draw.rect(w, WHITE, bar, 3, border_radius=8)
        t = self.font_s.render("%d / %d XP" % (into, need), True, WHITE)
        k = min(1.0, (bar.h - 6) / max(1, t.get_height()), (bar.w - 20) / max(1, t.get_width()))
        t = pygame.transform.smoothscale(t, (max(1, int(t.get_width() * k)), max(1, int(t.get_height() * k))))
        w.blit(t, t.get_rect(center=bar.center))

    def essence(self):
        return int(self.save.get("essence", 0))

    def settle_match(self):
        """Coins + stamina recovery for everyone who sat the match out."""
        self.last_essence = 0
        self.last_puzzle = 0
        if self.mode == "free":                           # freeplay: a random few coins, nothing else
            self.last_earned = random.randint(*FREE_REWARD)
            self.last_xp = 0
            self.save["coins"] += self.last_earned
            self.write_save()
            return
        hs, as_ = self.score_home, self.score_away
        result = "win" if hs > as_ else ("draw" if hs == as_ else "loss")
        earned = REWARD[result] + REWARD_PER_GOAL * hs
        if self.mode == "gauntlet":
            earned = self.gt_pay(result, hs)
        if self.impossible_run():
            earned *= IMPOSSIBLE_COINS
        earned = self.lg_pay(earned)                      # club: the ladder's multiplier + the bonus
        self.save["coins"] += earned
        self.last_earned = earned
        self.last_puzzle = 0 if getattr(self, "forfeited", False) else PUZZLE_REWARD[result]
        self.save["puzzle_points"] = int(self.save.get("puzzle_points", 0)) + self.last_puzzle
        xp = XP_REWARD[result] + XP_PER_GOAL * hs
        if self.mode in ("wc", "club", "pvp", "gauntlet"):
            self.count_match(result, hs, as_)             # the profile's numbers
        self.quest_match(result, hs, as_)                 # daily + weekly quests (1 Nov)
        if self.mode in WG_EVO_MODES and result == "win" and not getattr(self, "forfeited", False):
            for cid in list(self.played_this_match):      # World's Game quests (1 Nov)
                if self.impossible_run():                 # (this first: one match moves one quest)
                    self.wg_evo_event("imp_win", cid)
                self.wg_evo_event("win", cid)
        if self.mode == "wc" and result == "win" and self.round + 1 >= len(ROUNDS):
            xp += XP_TROPHY                               # world champions
            self.add_trophy("wc_impossible" if self.impossible_run() else
                            "wc_" + ("easy", "medium", "hard")[min(2, self.difficulty)])
            opp = self.teams[self.opponents[self.round]]["name"] if self.round < len(self.opponents) else None
            if opp == "NET" and hs >= 3:                  # the Signature Archive's 1978 final (1 Nov)
                self.archive_event("wc_final_net")
        if self.impossible_run() and not getattr(self, "forfeited", False):
            gain = ESSENCE_REWARD[result]                 # a forfeit pays nothing, or quitting would be a farm
            if result == "win" and self.round + 1 >= len(ROUNDS):
                gain += ESSENCE_TROPHY
            self.save["essence"] = self.essence() + gain
            self.last_essence = gain
        if self.ren_unlock_ready(result):                 # Japan + Impossible + the trophy
            self.unlock_ren()
            self.ren_pending = True
        self.award_xp(xp)
        if self.mode == "gauntlet":                       # no rest in a run: 4 halves each, that's it
            self.write_save()
            return
        for card in self.lineup_cards():
            rest = STAMINA_REST if card["id"] not in self.played_this_match else STAMINA_RECOVER
            self.set_stamina(card, self.stamina_of(card) + rest)
        self.write_save()

    # ================================================================ PACKS (v3)
    def card_pool(self, card):
        return pool_of(card)

    def pack_tier(self, card):
        return self.card_pool(card)

    def pack_pool(self, pack, pool=None):
        cards = [c for c in self.cards.values() if c["pack"] == pack]
        if pool is not None:
            cards = [c for c in cards if self.card_pool(c) == pool]
        return sorted(cards, key=lambda c: (-c["rating"], c.get("rank", 999), c["name"]))

    def pity(self, pack):
        p = self.save.setdefault("pity", {}).setdefault(str(pack), {"a": 0, "b": 0})
        return p

    def roll_pack(self, pack):
        """Pool odds with pity: pool B guaranteed every 10 packs, A every 40."""
        p = self.pity(pack)
        if p["a"] + 1 >= PITY_A:
            pool = "A"
        elif p["b"] + 1 >= PITY_B:
            pool = random.choices(["A", "B"], weights=[POOL_ODDS["A"], POOL_ODDS["B"]])[0]
        else:
            pool = random.choices(list(POOL_ODDS), weights=list(POOL_ODDS.values()))[0]
        cards = self.pack_pool(pack, pool) or self.pack_pool(pack)
        card = random.choice(cards)
        pool = self.card_pool(card)
        if pool == "A":
            p["a"], p["b"] = 0, 0
        elif pool == "B":
            p["a"], p["b"] = p["a"] + 1, 0
        else:
            p["a"], p["b"] = p["a"] + 1, p["b"] + 1
        return card

    def buy_pack(self, pack):
        if not self.pack_on_sale(pack):
            self.draft_rotated_out(pack)
            return False
        if self.save["coins"] < PACK_PRICE:
            return False
        if self.tut is not None and self.tut["step"] == "packs":
            self.tutorial_progress()["packs"] += 1
        self.save["coins"] -= PACK_PRICE
        self.quest_event("pack")                          # daily + weekly quests (1 Nov)
        card = self.roll_pack(pack)
        count = self.give_card(card)
        self.pack_reveal = {"card": card, "t": 0.0, "count": count, "pack": pack,
                            "tier": self.card_pool(card), "opened": False}
        self.fx = []
        self.state = PACK_OPEN
        self.write_save()
        return True

    # ---- packs list -------------------------------------------------------
    # ---- the pack store: draft-style list + featured banner ----------------
    PACK_THEME = {0: ((26, 44, 96), (120, 170, 255)), 1: ((80, 18, 34), (255, 130, 140)),
                  2: ((80, 18, 34), (255, 130, 140)), 3: ((80, 18, 34), (255, 130, 140)),   # Drafts B, C
                  4: ((30, 8, 60), (190, 120, 255)), 5: ((60, 6, 16), LB_RED), 6: ((60, 6, 16), LB_RED)}

    # ---- rotating drafts (ROTATIONS, DRAFT_ROTATE): each group shares one store slot
    def draft_clock(self):
        return time.time() + getattr(self, "draft_offset", 0.0)     # (checks move the clock)

    def rotation_of(self, pack):
        for group in ROTATIONS:
            if pack in group:
                return group
        return None

    def active_in(self, group):
        return group[int(self.draft_clock() // DRAFT_ROTATE) % len(group)]

    def next_in(self, group):
        return group[(group.index(self.active_in(group)) + 1) % len(group)]

    def shown_pack(self, pack):
        """The pack itself, or - if it's in a rotation - whichever of its group is in now."""
        group = self.rotation_of(pack)
        return self.active_in(group) if group else pack

    def active_draft(self):
        return self.active_in(DRAFT_PACKS)

    def next_draft(self):
        return self.next_in(DRAFT_PACKS)

    def draft_left(self):
        """Seconds until the store's Champion Draft changes."""
        return DRAFT_ROTATE - (self.draft_clock() % DRAFT_ROTATE)

    def draft_left_text(self):
        left = int(math.ceil(self.draft_left()))
        return "%d:%02d" % (left // 60, left % 60)

    def pack_on_sale(self, pack):
        return pack not in RETIRED_PACKS and self.shown_pack(pack) == pack

    def collection_ids(self):
        """The cards there are to collect: everything still in a pack, plus retired cards you own."""
        owned = self.save.get("owned", {})
        return [cid for cid, c in self.cards.items()
                if c.get("pack") not in RETIRED_PACKS or owned.get(cid, 0) > 0]

    def store_packs(self):
        """The packs in the store list, top to bottom: the drafts share one slot."""
        return [p for p in range(len(PACK_NAMES)) if self.pack_on_sale(p)]

    def draft_rotated_out(self, pack):
        """Buying a draft that has rotated out: say so, and go to the one that's in."""
        if pack in RETIRED_PACKS:
            self.toast("THE %s HAS BEEN RETIRED" % PACK_NAMES[pack], (255, 200, 120))
            self.view_pack = self.store_packs()[0]
            return
        now = self.shown_pack(pack)
        self.toast("%s HAS ROTATED OUT - %s IS IN" % (draft_title(pack), draft_title(now)), (255, 200, 120))
        self.view_pack = now

    def packs_layout(self):
        """The pack list down the left, one row per pack in the store (the Champion Drafts share
        one row). Six rows close up to fit above the Game Box button."""
        n = len(self.store_packs())
        step, h = (152, 140) if n <= 5 else (128, 118)
        return [pygame.Rect(40, 140 + i * step, 292, h) for i in range(n)]

    def packs_ui(self):
        L = {"panel": pygame.Rect(360, 120, 1520, 716), "info": pygame.Rect(0, 0, 54, 54),
             "all": pygame.Rect(388, 892, 300, 116), "one": pygame.Rect(748, 892, 420, 116),
             "ten": pygame.Rect(1204, 892, 500, 116), "box": pygame.Rect(40, 916, 292, 84),
             "pools": []}
        for i, pool in enumerate(("A", "B", "C")):
            L["pools"].append((pool, pygame.Rect(398 + i * 94, 946, 84, 52)))
        return L

    def featured_cards(self, pack):
        """The banner's players: every pool A player (big panels), then pool B's best four (small)."""
        A = self.pack_pool(pack, "A")
        B = sorted(self.pack_pool(pack, "B"), key=lambda c: -c["rating"])[:4]
        return A, B

    # 26 Oct: the banner laid out like FC's draft page (Hubi's picture): three tall panels, each
    # with the player big behind his name and a huge gold OVERALL, his card over the panel's
    # bottom-right corner; a last column with two more cards and MORE; the guarantee box in the
    # bottom right. (Was: four skewed slices with the name running down the side.)
    DRAFT_CREAM = (250, 236, 204)

    DRAFT_PANEL_W, DRAFT_GAP, DRAFT_COL_W = 384, 14, 270

    def draft_strip(self):
        """The window the panels scroll through (inside the banner, under the title)."""
        panel = self.packs_ui()["panel"]
        top, bottom = panel.y + 116, panel.bottom - 12
        return pygame.Rect(panel.x + 10, top, panel.w - 20, bottom - top)

    def draft_content_w(self, pack=None):
        A, B = self.featured_cards(self.view_pack if pack is None else pack)
        cols = (len(B) + 1) // 2
        return (12 + len(A) * (self.DRAFT_PANEL_W + self.DRAFT_GAP)
                + cols * (self.DRAFT_COL_W + self.DRAFT_GAP) + 12)

    def draft_max_scroll(self):
        return max(0, self.draft_content_w() - self.draft_strip().w)

    def draft_layout(self, scroll=None):
        """Pool A: a tall panel each, the card over its bottom-right corner. Then pool B's best
        four, two to a column, MORE on the last. Everything slides left by `scroll`; the
        guarantee box stays put in the bottom right."""
        strip = self.draft_strip()
        if scroll is None:
            scroll = getattr(self, "draft_x", 0.0)
        A, B = self.featured_cards(self.view_pack)
        top = strip.y
        h = strip.h
        D = {"panels": [], "cards": [], "cols": [], "side": [], "strip": strip}
        x = strip.x + 12 - int(scroll)
        for c in A:
            r = pygame.Rect(x, top, self.DRAFT_PANEL_W, h)
            cr = pygame.Rect(0, 0, 184, 256)
            cr.bottomright = (r.right + 22, top + 492)     # under the number, out over the panel's edge
            D["panels"].append((r, c))
            D["cards"].append((cr, c))
            x += self.DRAFT_PANEL_W + self.DRAFT_GAP
        for k in range(0, len(B), 2):
            col = pygame.Rect(x, top, self.DRAFT_COL_W, h)
            D["cols"].append(col)
            for j, c in enumerate(B[k:k + 2]):
                cr = pygame.Rect(0, 0, 160, 222)
                cr.midtop = (col.centerx, top + 6 + j * 232)
                D["side"].append((cr, c))
            x += self.DRAFT_COL_W + self.DRAFT_GAP
        D["more"] = None
        if D["cols"]:
            last = D["cols"][-1]
            D["more"] = pygame.Rect(0, 0, 200, 54)
            D["more"].midbottom = (last.centerx, top + 6 + 232 + 222 + 8)
        D["box"] = pygame.Rect(strip.right - 12 - 700, top + 502, 700, h - 502)
        D["left"] = pygame.Rect(strip.x + 6, top + 180, 58, 58)
        D["right"] = pygame.Rect(strip.right - 64, top + 180, 58, 58)
        return D

    def draft_scroll_by(self, dx):
        self.draft_target = clamp(getattr(self, "draft_target", 0.0) + dx, 0, self.draft_max_scroll())

    def draft_wheel_event(self, event):
        """Mouse wheel slides the draft banner (MOUSEWHEEL; the old button 4/5 "clicks" are eaten)."""
        if self.card_detail is not None:
            return False
        if hasattr(pygame, "MOUSEWHEEL") and event.type == pygame.MOUSEWHEEL:
            step = getattr(event, "y", 0) or -getattr(event, "x", 0)
            self.draft_scroll_by(-step * 300)
            return True
        if event.type == pygame.MOUSEBUTTONDOWN and event.button in (4, 5):
            if not hasattr(pygame, "MOUSEWHEEL"):
                self.draft_scroll_by(-300 if event.button == 4 else 300)
            return True
        return False

    def draw_draft_arrow(self, w, r, left, hover):
        bg = pygame.Surface(r.size, pygame.SRCALPHA)
        pygame.draw.circle(bg, (10, 12, 22, 210), (r.w // 2, r.h // 2), r.w // 2)
        w.blit(bg, r.topleft)
        pygame.draw.circle(w, YELLOW if hover else WHITE, r.center, r.w // 2, 3)
        cx, cy, k = r.centerx + (3 if left else -3), r.centery, 11
        pts = [(cx + k // 2, cy - k), (cx - k // 2, cy), (cx + k // 2, cy + k)] if left else \
              [(cx - k // 2, cy - k), (cx + k // 2, cy), (cx - k // 2, cy + k)]
        pygame.draw.lines(w, WHITE, False, pts, 5)

    def draft_panel_bg(self, size, tint):
        """A panel's dark slate gradient with rounded corners (one per size and pack)."""
        cache = self.__dict__.setdefault("_draft_bg", {})
        key = (int(size[0]), int(size[1]), tuple(tint))
        out = cache.get(key)
        if out is None:
            if len(cache) > 12:
                cache.clear()
            w, h = key[0], key[1]
            out = pygame.Surface((w, h), pygame.SRCALPHA)
            hi = lerp_rgb((70, 78, 98), tint, 0.25)
            lo = (12, 14, 26)
            for y in range(0, h, 4):
                t = min(1.0, y / float(h) * 1.3)
                c = lerp_rgb(hi, lo, t)
                out.fill((c[0], c[1], c[2], 236), (0, y, w, 4))
            mask = pygame.Surface((w, h), pygame.SRCALPHA)
            pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(), border_radius=16)
            out.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
            pygame.draw.rect(out, (120, 128, 150, 120), out.get_rect(), 2, border_radius=16)
            cache[key] = out
        return out

    def draft_panel_shade(self, size):
        """Over the portrait: fades the bottom into the banner and darkens behind the number."""
        cache = self.__dict__.setdefault("_draft_shade", {})
        key = (int(size[0]), int(size[1]))
        out = cache.get(key)
        if out is None:
            if len(cache) > 8:
                cache.clear()
            w, h = key
            out = pygame.Surface((w, h), pygame.SRCALPHA)
            for y in range(0, h, 4):
                a = int(255 * min(1.0, max(0.0, (y - h * 0.48) / (h * 0.40))) ** 1.3)
                out.fill((12, 14, 26, a), (0, y, w, 4))
            wash = pygame.Surface((w, int(h * 0.46)), pygame.SRCALPHA)
            for x in range(0, w, 4):
                a = int(130 * min(1.0, max(0.0, (x - w * 0.40) / (w * 0.50))))
                wash.fill((8, 10, 20, a), (x, 0, 4, wash.get_height()))
            out.blit(wash, (0, 0))
            cache[key] = out
        return out

    def gold_number(self, text, max_w, max_h):
        """The huge OVERALL: cream at the top running into old gold, with a drop shadow."""
        key = ("goldnum", text, int(max_w), int(max_h))
        hit = self.text_cache.get(key)
        if hit is not None:
            return hit
        base = self.fit_text(text, self.font_xl, WHITE, max_w, max_h)
        w, h = base.get_size()
        grad = pygame.Surface((w, h), pygame.SRCALPHA)
        stops = ((0.0, (255, 248, 226)), (0.42, (242, 210, 146)), (0.62, (192, 142, 66)),
                 (1.0, (236, 196, 124)))
        for y in range(h):
            t = y / float(max(1, h - 1))
            for (t0, c0), (t1, c1) in zip(stops, stops[1:]):
                if t <= t1:
                    c = lerp_rgb(c0, c1, (t - t0) / max(1e-6, t1 - t0))
                    break
            grad.fill((c[0], c[1], c[2], 255), (0, y, w, 1))
        img = base.copy()
        img.blit(grad, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        shadow = self.fit_text(text, self.font_xl, (6, 4, 2), max_w, max_h).copy()
        shadow.set_alpha(170)
        out = pygame.Surface((w + 6, h + 6), pygame.SRCALPHA)
        out.blit(shadow, (6, 6))
        out.blit(img, (0, 0))
        self.cache_text(key, out)
        return out

    def draft_name(self, card):
        name = card["name"].upper()
        if len(name) > 13 and " " in name:                 # same rule as the card
            name = name.split()[-1]
        return name

    def draw_draft_panel(self, w, r, card, tint):
        """One tall panel: the player big behind, his name, OVERALL and the gold number."""
        w.blit(self.draft_panel_bg(r.size, tint), r.topleft)
        clip = w.get_clip()
        inner = r.inflate(-4, -4)
        w.set_clip(inner.clip(clip) if clip is not None else inner)
        face = self.card_faces.get(card["id"])
        if face is not None:
            # three screen pixels per art pixel, like the cards; head a little left of the middle
            img = scaled(face, (face.get_width() * 3, face.get_height() * 3))
            w.blit(img, (r.x + int(r.w * 0.38) - int(img.get_width() * 0.48), r.y - 24))
        w.blit(self.draft_panel_shade(r.size), r.topleft)
        w.set_clip(clip)
        cream = self.DRAFT_CREAM
        nm = self.fit_text(self.draft_name(card), self.font_m, cream, r.w * 0.66, 46, outline=(20, 14, 6))
        w.blit(nm, nm.get_rect(topright=(r.right - 16, r.y + 12)))
        cx, ty = r.right - 66, r.y + 68
        pygame.draw.polygon(w, cream, [(cx - 7, ty - 4), (cx + 7, ty - 4), (cx, ty + 4)])
        ov = self.fit_text("OVERALL", self.font_s, (226, 216, 196), 140, 26)
        w.blit(ov, ov.get_rect(topright=(r.right - 18, r.y + 78)))
        num = self.gold_number(str(card["rating"]), r.w * 0.56, 114)
        w.blit(num, num.get_rect(topright=(r.right - 10, r.y + 106)))

    def draw_more_button(self, w, r, hover):
        pill = pygame.Surface(r.size, pygame.SRCALPHA)
        pygame.draw.rect(pill, (12, 14, 24, 236), pill.get_rect(), border_radius=r.h // 2)
        w.blit(pill, r.topleft)
        pygame.draw.rect(w, YELLOW if hover else (214, 216, 226), r, 3, border_radius=r.h // 2)
        c = (r.x + 32, r.centery - 3)                      # a magnifying glass
        pygame.draw.circle(w, WHITE, c, 13, 4)
        pygame.draw.line(w, WHITE, (c[0] + 9, c[1] + 9), (c[0] + 18, c[1] + 18), 6)
        lab = self.fit_text("MORE", self.font_s, WHITE, r.w - 90, 32)
        w.blit(lab, lab.get_rect(center=(r.x + 60 + (r.w - 60) // 2, r.centery)))

    def draw_draft_box(self, w, box, pack):
        """The guarantee box: POOL B or Higher Guaranteed in: N Drafts / POOL A Guaranteed in: N Drafts."""
        bg = pygame.Surface(box.size, pygame.SRCALPHA)
        pygame.draw.rect(bg, (22, 26, 42, 232), bg.get_rect(), border_radius=22)
        w.blit(bg, box.topleft)
        p = self.pity(pack)
        rows = (("POOL B", (140, 50, 236), (214, 96, 255), WHITE, "or Higher Guaranteed in:", PITY_B - p["b"]),
                ("POOL A", (238, 112, 24), (255, 178, 70), WHITE, "Guaranteed in:", PITY_A - p["a"]))
        for i, (chip_t, c0, c1, ink, rest, n) in enumerate(rows):
            y = box.y + 6 + i * 40
            pill = pygame.Rect(box.right - 14 - 200, y, 200, 36)
            pygame.draw.rect(w, (6, 6, 12), pill, border_radius=18)
            pygame.draw.rect(w, (58, 60, 78), pill, 2, border_radius=18)
            cnt = self.fit_text("%d Draft%s" % (n, "" if n == 1 else "s"), self.font_s, (255, 226, 56),
                                pill.w - 30, 28)
            w.blit(cnt, cnt.get_rect(center=pill.center))
            lab = self.fit_text(rest, self.font_s, (232, 234, 242), 300, 27)
            lr = lab.get_rect(midright=(pill.x - 14, pill.centery))
            w.blit(lab, lr)
            chip = pygame.Rect(0, 0, 190, 32)
            chip.midright = (lr.x - 12, pill.centery)
            for k in range(0, chip.w, 6):                   # left to right, darker into lighter
                col = lerp_rgb(c0, c1, k / float(chip.w))
                pygame.draw.rect(w, col, (chip.x + k, chip.y, min(6, chip.w - k), chip.h))
            pygame.draw.rect(w, (22, 26, 42), chip, 3, border_radius=10)   # rounds the corners off
            ct = self.fit_text(chip_t, self.font_s, ink, chip.w - 30, 25)
            w.blit(ct, ct.get_rect(center=chip.center))
            pygame.draw.line(w, (70, 76, 100), (chip.x, pill.bottom + 2), (pill.x - 10, pill.bottom + 2), 2)

    def draw_draft_arcs(self, w, panel):
        """Two faint gold arcs sweeping across the banner, behind the panels."""
        cache = self.__dict__.setdefault("_draft_arcs", {})
        key = panel.size
        if key not in cache:
            s = pygame.Surface(panel.size, pygame.SRCALPHA)
            for (cx, cy, rad) in ((0.16, 1.55, 1.25), (1.02, -0.62, 0.95)):
                pygame.draw.circle(s, (214, 170, 90, 46), (int(panel.w * cx), int(panel.h * cy)),
                                   int(panel.w * rad), 3)
            cache[key] = s
        w.blit(cache[key], panel.topleft)

    def draft_info_rect(self, head=None):
        """The i after the title (it moves with the title's width)."""
        panel = self.packs_ui()["panel"]
        if head is None:
            head = self.fit_text(draft_title(self.view_pack), self.font_l, WHITE, 860, 66)
        r = pygame.Rect(0, 0, 54, 54)
        r.midleft = (panel.x + 30 + head.get_width() + 20, panel.y + 16 + head.get_height() // 2)
        return r

    def draw_packs(self, w):
        w.blit(self.shop_bg or self.select_bg, (0, 0))
        self.draw_back_button(w)
        self.draw_coins(w)
        mouse = pygame.mouse.get_pos()
        if self.view_pack in RETIRED_PACKS:                  # (old save / old link: pack 4 is gone)
            self.view_pack = self.store_packs()[0]
        if self.shown_pack(self.view_pack) != self.view_pack:
            self.view_pack = self.shown_pack(self.view_pack)  # it rotated while you were looking
            self.toast("%s IS IN!" % draft_title(self.view_pack), (255, 214, 110))
        pack = self.view_pack
        L = self.packs_ui()
        base, accent = self.PACK_THEME.get(pack, ((30, 30, 60), WHITE))
        # ---- the pack list
        for i, r in zip(self.store_packs(), self.packs_layout()):
            on = i == pack
            tb, ta = self.PACK_THEME.get(i, ((30, 30, 60), WHITE))
            pygame.draw.rect(w, _shade(tb, 1.25 if on else 0.75), r, border_radius=14)
            pygame.draw.rect(w, YELLOW if on or r.collidepoint(mouse) else _shade(ta, 0.7), r,
                             5 if on else 3, border_radius=14)
            art = self.pack_art[i] if i < len(self.pack_art) else None
            if art is not None:
                im = scaled(art, (78, 110))
                w.blit(im, im.get_rect(midleft=(r.x + 14, r.centery)))
            nm = self.fit_text(PACK_NAMES[i], self.font_m, WHITE, r.w - 120, 40)
            w.blit(nm, nm.get_rect(midleft=(r.x + 104, r.centery - 18)))
            chip = pygame.Rect(r.x + 104, r.centery + 12, min(170, r.w - 116), 34)
            pygame.draw.rect(w, ta, chip, border_radius=8)
            label = "ENDS " + self.draft_left_text() if self.rotation_of(i) else PACK_TAGS[i]
            tag = self.fit_text(label, self.font_s, (10, 10, 20), chip.w - 12, 24)
            w.blit(tag, tag.get_rect(center=chip.center))
        box = L["box"]
        pygame.draw.rect(w, (0, 130, 60), box, border_radius=14)
        pygame.draw.rect(w, YELLOW if box.collidepoint(mouse) else (254, 214, 0), box, 4, border_radius=14)
        lab = self.fit_text(GAME_BOXES[0][3] + "  >", self.font_m, WHITE, box.w - 24, 38)
        w.blit(lab, lab.get_rect(center=box.center))
        # ---- the banner (the FC draft page)
        panel = L["panel"]
        pygame.draw.rect(w, (10, 12, 26), panel, border_radius=18)
        self.draw_draft_arcs(w, panel)
        pygame.draw.rect(w, accent, panel, 4, border_radius=18)
        head = self.fit_text(draft_title(pack), self.font_l, WHITE, 860, 66)
        w.blit(head, (panel.x + 30, panel.y + 16))
        info = self.draft_info_rect(head)
        pygame.draw.circle(w, WHITE, info.center, 24, 4)
        self.centre_in(w, "i", info, self.font_m, WHITE)
        ic = (panel.x + 50, panel.y + 100)                   # odds, where FC puts "Ends in"
        pygame.draw.circle(w, WHITE, ic, 18)
        pc = self.fit_text("%", self.font_s, (10, 12, 26), 26, 26)
        w.blit(pc, pc.get_rect(center=ic))
        od = self.fit_text("Odds:", self.font_s, WHITE, 120, 34)
        w.blit(od, od.get_rect(midleft=(ic[0] + 30, ic[1])))
        ov = self.fit_text("A %d%%   B %d%%   C %d%%" % (POOL_ODDS["A"] * 100, POOL_ODDS["B"] * 100,
                                                      POOL_ODDS["C"] * 100), self.font_s, (88, 150, 255), 420, 34)
        w.blit(ov, ov.get_rect(midleft=(ic[0] + 40 + od.get_width(), ic[1])))
        if self.rotation_of(pack):                           # FC's "Ends in": the rotation
            nxt = "ENDS IN %s   -   NEXT: %s" % (self.draft_left_text(),
                                                 draft_title(self.next_in(self.rotation_of(pack))))
            nt = self.fit_text(nxt, self.font_s, (255, 214, 110), 640, 34)
            w.blit(nt, nt.get_rect(midright=(panel.right - 30, ic[1])))
        # slide toward where the wheel / arrows asked (eased, so it glides)
        if getattr(self, "draft_pack", None) != pack:
            self.draft_pack, self.draft_x, self.draft_target = pack, 0.0, 0.0
        tgt = clamp(getattr(self, "draft_target", 0.0), 0, self.draft_max_scroll())
        self.draft_target = tgt
        self.draft_x = tgt if abs(tgt - self.draft_x) < 1.0 else self.draft_x + (tgt - self.draft_x) * 0.22
        D = self.draft_layout()
        strip = D["strip"]
        clip = w.get_clip()
        w.set_clip(strip)
        for r, c in D["panels"]:
            if r.right > strip.x and r.x < strip.right:
                self.draw_draft_panel(w, r, c, accent)
        for col in D["cols"]:
            if col.right > strip.x and col.x < strip.right:
                w.blit(self.draft_panel_bg(col.size, accent), col.topleft)
        for cr, c in D["cards"] + D["side"]:                # cards last: they overlap the next panel
            if cr.right > strip.x and cr.x < strip.right:
                self.draw_card(w, c, cr)
        if D["more"] is not None:
            self.draw_more_button(w, D["more"], D["more"].collidepoint(mouse))
        self.draw_draft_box(w, D["box"], pack)
        if self.draft_target > 0:
            self.draw_draft_arrow(w, D["left"], True, D["left"].collidepoint(mouse))
        if self.draft_target < self.draft_max_scroll():
            self.draw_draft_arrow(w, D["right"], False, D["right"].collidepoint(mouse))
        w.set_clip(clip)
        # ---- buy row
        coins = self.save["coins"]
        for key, txt, cost in (("one", "1 DRAW", PACK_PRICE), ("ten", "10 DRAWS", PACK_PRICE * MULTI_PACKS)):
            r = L[key]
            can = coins >= cost
            pygame.draw.rect(w, (40, 170, 70) if can else (58, 70, 60), r, border_radius=58)
            pygame.draw.rect(w, YELLOW if can and r.collidepoint(mouse) else WHITE, r, 5, border_radius=58)
            lab = self.fit_text(txt, self.font_m, WHITE if can else (190, 190, 190), r.w * 0.5, 46)
            w.blit(lab, lab.get_rect(midleft=(r.x + 30, r.centery)))
            pygame.draw.circle(w, YELLOW, (r.right - 130, r.centery), 20)
            pygame.draw.circle(w, (190, 140, 20), (r.right - 130, r.centery), 20, 4)
            price = self.fit_text(self.fmt(cost), self.font_m, YELLOW if can else (190, 160, 120), 170, 42)
            w.blit(price, price.get_rect(midleft=(r.right - 100, r.centery)))
        r = L["all"]
        pygame.draw.rect(w, (36, 54, 110), r, border_radius=20)
        pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else WHITE, r, 4, border_radius=20)
        lab = self.fit_text("WHO'S INSIDE", self.font_s, WHITE, r.w - 30, 30)
        w.blit(lab, lab.get_rect(midtop=(r.centerx, r.y + 10)))
        for pool, pr in L["pools"]:                          # jump straight to a pool's players
            col = {"A": (120, 46, 170), "B": (150, 116, 20), "C": (46, 60, 84)}[pool]
            pygame.draw.rect(w, col, pr, border_radius=12)
            pygame.draw.rect(w, YELLOW if pr.collidepoint(mouse) else WHITE, pr, 3, border_radius=12)
            pl = self.fit_text(pool, self.font_m, WHITE, pr.w - 10, 34)
            w.blit(pl, pl.get_rect(center=pr.center))
        n_owned = len(self.save["owned"])
        coll = self.fit_text("COLLECTION  %d / %d" % (n_owned, len(self.collection_ids())), self.font_s,
                             (200, 214, 240), 460, 32)
        w.blit(coll, coll.get_rect(midright=(panel.right - 28, 1044)))

    def box_button(self):
        return self.packs_ui()["box"]

    def packs_click(self, pos):
        L = self.packs_ui()
        if pygame.Rect(40, 30, 200, 70).collidepoint(pos.x, pos.y):
            self.open_store()
            return
        if L["box"].collidepoint(pos.x, pos.y):
            self.open_event()
            return
        for i, rect in zip(self.store_packs(), self.packs_layout()):
            if rect.collidepoint(pos.x, pos.y):
                self.view_pack = i                          # pick a pack from the list
                return
        for pool, pr in L["pools"]:
            if pr.collidepoint(pos.x, pos.y):
                self.open_pack_view(self.view_pack, pool)    # straight to pool A / B / C
                return
        D = self.draft_layout()
        strip = D["strip"]
        if strip.collidepoint(pos.x, pos.y):
            if self.draft_target > 0 and D["left"].collidepoint(pos.x, pos.y):
                self.draft_scroll_by(-(self.DRAFT_PANEL_W + self.DRAFT_GAP) * 2)
                return
            if self.draft_target < self.draft_max_scroll() and D["right"].collidepoint(pos.x, pos.y):
                self.draft_scroll_by((self.DRAFT_PANEL_W + self.DRAFT_GAP) * 2)
                return
            if D["more"] is not None and D["more"].collidepoint(pos.x, pos.y):
                self.open_pack_view(self.view_pack)         # MORE: everyone in the pack
                return
            if not D["box"].collidepoint(pos.x, pos.y):
                for cr, c in D["cards"] + D["side"]:
                    if cr.collidepoint(pos.x, pos.y):
                        self.card_click(c, lambda: None)     # double-click = stats
                        return
        if self.draft_info_rect().collidepoint(pos.x, pos.y) or L["all"].collidepoint(pos.x, pos.y):
            self.open_pack_view(self.view_pack)
            return
        if L["one"].collidepoint(pos.x, pos.y):
            self.buy_pack(self.view_pack)
            return
        if L["ten"].collidepoint(pos.x, pos.y):
            self.buy_pack10(self.view_pack)
            return

    # ---- pack view: buy on the left, the players on the right --------------
    def open_packs(self, pack=None):
        """The pack store itself (the draft-style screen)."""
        if pack is not None:
            self.view_pack = pack
        self.state = PACKS

    def open_pack_view(self, pack, pool="A"):
        self.view_pack = pack
        self.view_scroll = 0.0
        self.view_more = False
        self.view_more_scroll = 0.0
        self.state = PACK_VIEW
        self.show_pool(pool)

    def pool_offset(self, pool):
        """Where pool B starts along the strip."""
        items, _total = self.view_strip()
        for it in items:
            if it[0] == "header" and it[1] == pool:
                return max(0.0, it[2] - 20.0)
        return 0.0

    def show_pool(self, pool):
        """Jump the pack view to pool A, B or C."""
        self.view_more = pool == "C"
        if pool == "C":
            self.view_more_scroll = 0.0
        else:
            self.view_scroll = 0.0
            if pool == "B":
                self.scroll_view(self.pool_offset("B"))

    def shown_pool(self):
        if self.view_more:
            return "C"
        return "B" if self.view_scroll >= max(60.0, self.pool_offset("B") - 160.0) else "A"

    def view_layout(self):
        L = {"art": pygame.Rect(90, 150, 330, 462), "buy": pygame.Rect(90, 636, 330, 92),
             "buy10": pygame.Rect(90, 740, 330, 92),
             "panel": pygame.Rect(560, 130, WIDTH - 600, 900),
             "left": pygame.Rect(600, 880, 90, 70), "right": pygame.Rect(WIDTH - 150, 880, 90, 70),
             "tabs": [(pool, pygame.Rect(600 + i * 176, 52, 166, 62))
                      for i, pool in enumerate(("A", "B", "C"))]}
        L["more"] = L["tabs"][2][1]                         # the old MORE button is now the POOL C tab
        return L

    def view_strip(self):
        """Cards along the scrolling strip: pool A big, then pool B."""
        items, x = [], 0
        for pool, size in (("A", (270, 375)), ("B", (200, 278))):
            cards = self.pack_pool(self.view_pack, pool)
            if not cards:
                continue
            items.append(("header", pool, x))
            x += 20
            for c in cards:
                items.append(("card", c, x, size))
                x += size[0] + 26
            x += 60
        return items, x

    def view_more_layout(self):
        cards = self.pack_pool(self.view_pack, "C")
        cols = 8
        rects = []
        for i, c in enumerate(cards):
            r, k = divmod(i, cols)
            rects.append((c, pygame.Rect(600 + k * 158, 260 + r * 214 - int(self.view_more_scroll), 136, 190)))
        return rects

    def pack_view_click(self, pos):
        L = self.view_layout()
        if pygame.Rect(40, 30, 200, 70).collidepoint(pos.x, pos.y):
            if self.view_more:
                self.view_more = False
            else:
                self.state = PACKS
            return
        if L["buy"].collidepoint(pos.x, pos.y) or L["art"].collidepoint(pos.x, pos.y):
            self.buy_pack(self.view_pack)
            return
        if L["buy10"].collidepoint(pos.x, pos.y):
            self.buy_pack10(self.view_pack)
            return
        for pool, r in L["tabs"]:
            if r.collidepoint(pos.x, pos.y):
                self.show_pool(pool)                        # POOL A / POOL B / POOL C
                return
        if not self.view_more:
            if L["left"].collidepoint(pos.x, pos.y):
                self.scroll_view(-600)
                return
            if L["right"].collidepoint(pos.x, pos.y):
                self.scroll_view(600)
                return
        for card, rect in self.visible_view_cards():
            if rect.collidepoint(pos.x, pos.y):
                self.card_click(card, lambda: None)          # double-click = stats
                return

    def scroll_view(self, dx):
        if self.view_more:
            rows = math.ceil(len(self.pack_pool(self.view_pack, "C")) / 8)
            panel = self.view_layout()["panel"]
            self.view_more_scroll = clamp(self.view_more_scroll + dx, 0,
                                          max(0, rows * 214 - (panel.bottom - 300)))
            return
        _items, total = self.view_strip()
        width = self.view_layout()["panel"].w - 40
        self.view_scroll = clamp(self.view_scroll + dx, 0, max(0, total - width))

    def visible_view_cards(self):
        if self.view_more:
            return [(c, r) for c, r in self.view_more_layout() if 230 < r.y < 1000]
        L = self.view_layout()
        items, _ = self.view_strip()
        out = []
        for it in items:
            if it[0] != "card":
                continue
            _k, c, x, size = it
            r = pygame.Rect(L["panel"].x + 20 + x - int(self.view_scroll), 0, *size)
            r.bottom = 820
            if r.right > L["panel"].x and r.x < L["panel"].right:
                out.append((c, r))
        return out

    def draw_pack_view(self, w):
        w.blit(self.shop_bg or self.select_bg, (0, 0))
        self.draw_back_button(w)
        self.draw_coins(w)
        L = self.view_layout()
        pack = self.view_pack
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        head = self.label(PACK_NAMES[pack], 400, WHITE, self.font_m)
        w.blit(head, head.get_rect(center=(L["art"].centerx, 124)))
        art = self.pack_art[pack]
        bob = int(math.sin(t * 2.2) * 8)
        if art is not None:
            w.blit(scaled(art, L["art"].size), L["art"].move(0, bob))
        afford = self.save["coins"] >= PACK_PRICE
        b = L["buy"]
        hover = b.collidepoint(mouse) and afford
        pygame.draw.rect(w, (40, 170, 70) if afford else (70, 90, 72), b, border_radius=16)
        pygame.draw.rect(w, YELLOW if hover else WHITE, b, 5, border_radius=16)
        self.centre_in(w, "BUY  %d" % PACK_PRICE if afford else "NEED %d" % PACK_PRICE, b, self.font_m,
                       WHITE if afford else (200, 150, 150))
        cost10 = PACK_PRICE * MULTI_PACKS
        afford10 = self.save["coins"] >= cost10
        b10 = L["buy10"]
        pygame.draw.rect(w, (30, 120, 170) if afford10 else (60, 76, 90), b10, border_radius=16)
        pygame.draw.rect(w, YELLOW if b10.collidepoint(mouse) and afford10 else WHITE, b10, 5, border_radius=16)
        lab10 = self.label("OPEN 10x  %s" % self.fmt(cost10) if afford10 else "10x NEEDS %s" % self.fmt(cost10),
                           b10.w - 30, WHITE if afford10 else (200, 150, 150), self.font_m)
        w.blit(lab10, lab10.get_rect(center=b10.center))
        p = self.pity(pack)
        lines = [("PITY", WHITE),
                 ("POOL A IN %d" % (PITY_A - p["a"]), (220, 150, 255)),
                 ("POOL B IN %d" % (PITY_B - p["b"]), (255, 214, 90)),
                 ("ODDS  A %d%%  B %d%%" % (POOL_ODDS["A"] * 100, POOL_ODDS["B"] * 100), (200, 220, 200)),
                 ("POOL C %d%%" % (POOL_ODDS["C"] * 100), (200, 220, 200))]
        for k, (txt, col) in enumerate(lines):
            img = self.label(txt, 380, col)
            w.blit(img, img.get_rect(center=(b.centerx, 868 + k * 42)))

        panel = L["panel"]
        pygame.draw.rect(w, (12, 20, 52), panel, border_radius=18)
        pygame.draw.rect(w, (92, 128, 220), panel, 3, border_radius=18)
        shown = self.shown_pool()
        for pool, r in L["tabs"]:
            on = pool == shown
            col = {"A": (120, 46, 170), "B": (150, 116, 20), "C": (46, 60, 84)}[pool]
            pygame.draw.rect(w, _shade(col, 1.35 if on else 0.75), r, border_radius=12)
            pygame.draw.rect(w, YELLOW if on or r.collidepoint(mouse) else WHITE, r, 5 if on else 3,
                             border_radius=12)
            lab = self.fit_text("POOL %s" % pool, self.font_m, WHITE, r.w - 20, 38)
            w.blit(lab, lab.get_rect(center=r.center))

        clip = w.get_clip()
        w.set_clip(panel.inflate(-8, -8))
        if self.view_more:
            w.blit(self.font_m.render("POOL C", True, (200, 200, 210)), (panel.x + 40, panel.y + 24))
            for c, r in self.view_more_layout():
                if r.bottom > panel.y + 110 and r.y < panel.bottom:
                    self.blit_card(w, c, r, count=self.save["owned"].get(c["id"], 0),
                                   dim=c["id"] not in self.save["owned"])
        else:
            items, total = self.view_strip()
            for it in items:
                if it[0] == "header":
                    x = panel.x + 20 + it[2] - int(self.view_scroll)
                    col = (220, 150, 255) if it[1] == "A" else (255, 214, 90)
                    w.blit(self.font_m.render("POOL %s" % it[1], True, col), (x, panel.y + 24))
            for c, r in self.visible_view_cards():
                self.blit_card(w, c, r, count=self.save["owned"].get(c["id"], 0),
                               dim=c["id"] not in self.save["owned"], glow=r.collidepoint(mouse))
            hint = self.label("POOL A / B / C UP TOP, OR SCROLL   -   DOUBLE-CLICK A CARD FOR STATS",
                              panel.w - 80, (168, 190, 240))
            w.blit(hint, hint.get_rect(center=(panel.centerx, panel.bottom - 50)))
        w.set_clip(clip)
        if not self.view_more:
            for key, txt in (("left", "<"), ("right", ">")):
                pygame.draw.rect(w, SELECT_GREEN, L[key], border_radius=10)
                pygame.draw.rect(w, WHITE, L[key], 3, border_radius=10)
                self.centre_in(w, txt, L[key], self.font_m)

    # ---- FC Mobile-style opening ---------------------------------------------
    POOL_GLOW = {"A": (190, 90, 255), "B": (255, 205, 70), "C": (225, 225, 235)}
    POOL_SHARD = {"A": ((26, 40, 110), (58, 86, 190), (236, 200, 96)),
                  "B": ((44, 36, 16), (120, 92, 30), (250, 214, 110)),
                  "C": ((26, 30, 38), (66, 74, 90), (190, 200, 215)),
                  "S": ((40, 10, 82), (122, 52, 214), (232, 212, 255)),
                  "W": ((34, 14, 82), (126, 76, 224), (236, 240, 252)),
                  "L": ((48, 4, 12), (196, 20, 40), (255, 190, 196))}

    def shard_colours(self, card, pool):
        """Star Signings shatter purple, World's Game players violet and silver, Limit Breakers
        (pool A and B) crimson, the rest by pool."""
        if card["design"] == "limitbreakers" and pool in ("A", "B"):
            return self.POOL_SHARD["L"]
        return self.POOL_SHARD[{"starsign": "S", "worldsgame": "W"}.get(card["design"], pool)]

    def opening_marks(self, pool):
        """(pack shatters, reveals end, beams end, card lands, -, beats).
        Pools A and B follow openingpack.mp3: flag 0:02, position 0:03.5,
        club 0:05, player 0:07. Pool C has no cutscene."""
        if pool == "C":
            return 0.0, 0.0, 0.0, 1.15, 0.0, 0                # (31 Oct: it rips too, then the stadium)
        return 1.3, 6.2, 6.75, PACK_CARD_AT, 1.5, len(PACK_BEATS)

    def opening_done_at(self, pool):
        return self.opening_marks(pool)[3]

    def nation_flag(self, code):
        for t in self.teams:
            if t["name"] == code:
                return t["flag"]
        return self.extra_flags.get(code)

    def card_flag(self, card):
        """Nation flag - or, for a club card, the flag of the club's country."""
        if card["kind"] in ("wc", "sig", "no10", "wg", "lb"):
            return self.card_badge(card)
        code = card["nation"] if card["kind"] in ("star", "rookie") else CLUB_COUNTRY.get(card["team"], "ENG")
        nat = card.get("nation") if card.get("design") == "champions" else CLUB_NATION.get(card["id"])
        if nat:
            flag = self.nation_flag(nat)
            if flag is not None:
                return flag
        return self.nation_flag(code)

    def card_club(self, card):
        """Club crest - or, for a World Cup card, the World Cup badge."""
        if card["kind"] == "no10":
            return self.no10_badge or self.wc_badge
        if card["kind"] == "lb":
            return self.lb_badge or self.wc_badge
        if card["kind"] in ("club", "star", "rookie"):
            return self.card_badge(card)
        return self.wc_badge

    def reveal_beats(self, card, n):
        """flag -> position -> club, then the player lands."""
        beats = [("image", self.card_flag(card)), ("text", card["pos"]), ("image", self.card_club(card))]
        return beats[:n]

    def pack_shards(self, pr):
        if "shards" not in pr:
            rng = random.Random(hash(pr["card"]["id"]) & 0xffff)
            pr["shards"] = [(rng.uniform(0, math.tau), rng.uniform(0.05, 1.0), rng.uniform(26, 150),
                             rng.uniform(-3, 3), rng.uniform(0.3, 1.0), rng.random())
                            for _ in range(46)]
        return pr["shards"]

    def pack_backdrop(self, cx, cy):
        """The dark starburst behind a sealed pack - built once, then blitted."""
        if getattr(self, "_pack_bg", None) is None:
            bg = pygame.Surface((WIDTH, HEIGHT)).convert()
            bg.fill((6, 8, 16))
            for k in range(20):
                a = k * math.tau / 20
                pygame.draw.polygon(bg, (14, 18, 34) if k % 2 else (9, 11, 22),
                                    [(cx, cy), (cx + math.cos(a) * 1400, cy + math.sin(a) * 1400),
                                     (cx + math.cos(a + 0.13) * 1400, cy + math.sin(a + 0.13) * 1400)])
            self._pack_bg = bg
        return self._pack_bg

    def pack_stage(self, gold):
        """The chevron stage the card lands on - one surface per pool colour."""
        cache = getattr(self, "_pack_stage", None)
        if cache is None:
            cache = self._pack_stage = {}
        key = tuple(gold)[:3]
        stage = cache.get(key)
        if stage is None:
            if len(cache) > 6:
                cache.clear()
            stage = pygame.Surface((WIDTH, HEIGHT)).convert()
            stage.fill((6, 8, 16))
            for j in range(11):
                x = int(WIDTH * (j + 0.5) / 11)
                lean = 150 if j % 2 else -150
                col = _shade(gold, 0.26 + 0.09 * (j % 3))
                pygame.draw.polygon(stage, col, [(x - 60, HEIGHT), (x + 60, HEIGHT),
                                                 (x + 20 + lean, 60), (x - 30 + lean, 60)])
            deep = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)   # once, not every frame
            deep.fill((6, 10, 24, 120))
            stage.blit(deep, (0, 0))
            cache[key] = stage
        return stage

    def pack_flare(self, glow):
        """The radial bloom under the wall of light - same picture every frame."""
        cache = getattr(self, "_pack_flare", None)
        if cache is None:
            cache = self._pack_flare = {}
        key = tuple(glow)[:3]
        flare = cache.get(key)
        if flare is None:
            if len(cache) > 6:
                cache.clear()
            flare = pygame.Surface((900, 900), pygame.SRCALPHA)
            for j in range(7):
                r = 900 - j * 120
                pygame.draw.ellipse(flare, tuple(glow)[:3] + (16 + j * 6,),
                                    pygame.Rect((900 - r) // 2, (900 - r) // 2, r, r))
            cache[key] = flare
        return flare

    def rating_shield(self, value, gold, dark):
        """The shield with the rating in it, one surface per number."""
        cache = getattr(self, "_shields", None)
        if cache is None:
            cache = self._shields = {}
        key = (int(value), tuple(gold)[:3], tuple(dark)[:3])
        shield = cache.get(key)
        if shield is None:
            if len(cache) > 120:
                cache.clear()
            shield = pygame.Surface((320, 360), pygame.SRCALPHA)
            pts = [(160, 0), (320, 60), (300, 250), (160, 360), (20, 250), (0, 60)]
            pygame.draw.polygon(shield, gold, pts)
            pygame.draw.polygon(shield, _shade(dark, 1.1), [(x * 0.86 + 22, y * 0.86 + 25) for x, y in pts])
            num = self.font_xl.render(str(int(value)), True, WHITE)
            nk = min(1.0, 190.0 / max(1, num.get_width()), 150.0 / max(1, num.get_height()))
            num = pygame.transform.smoothscale(num, (max(1, int(num.get_width() * nk)),
                                                     max(1, int(num.get_height() * nk))))
            shield.blit(num, num.get_rect(center=(160, 175)))
            cache[key] = shield
        return shield

    def draw_shard_field(self, w, pr, local, pool, cx, cy):
        """Crystal debris flying past the camera."""
        dark, mid, gold = self.shard_colours(pr["card"], pool)
        for a, phase, size, spin, depth, kind in self.pack_shards(pr):
            k = (local * 0.55 + phase) % 1.0
            dist = 60 + k * 1500 * depth
            sc = size * (0.35 + k * 1.8) * depth
            x, y = cx + math.cos(a) * dist, cy + math.sin(a) * dist * 0.72
            if x < -300 or x > WIDTH + 300 or y < -300 or y > HEIGHT + 300:
                continue
            ang = a + spin * local
            pts = []
            for j, rad in enumerate((1.0, 0.55, 0.85, 0.45)):
                th = ang + j * math.tau / 4
                pts.append((x + math.cos(th) * sc * rad, y + math.sin(th) * sc * rad * 0.85))
            body = gold if kind > 0.72 else (mid if kind > 0.35 else dark)
            fade = max(0.0, 1.0 - k * 1.1)
            col = _shade(body, 0.35 + 0.75 * fade)
            pygame.draw.polygon(w, col, pts)
            pygame.draw.line(w, _shade(col, 1.6), pts[0], pts[2], max(1, int(sc * 0.08)))

    def pack_open_click(self):
        pr = self.pack_reveal
        if not pr:
            return
        if not pr["opened"]:
            pr["opened"] = True                           # tap the pack to open it
            pr["t"] = 0.0
            pr.pop("start", None)
            if pr["tier"] in ("A", "B"):
                self.sfx.play_track("pack", force=True)
            return
        end = self.opening_done_at(pr["tier"])
        if pr["t"] < end:
            pr["t"] = end                                 # skip straight to the card
            pr.pop("start", None)
            if pr["tier"] in ("A", "B"):
                self.sfx.play_track("pack", start=end, force=True)
            return
        if pr["t"] >= end + 0.4:
            if pr.get("multi"):                          # 10x: the best card walked out, now all 10
                self.card_click(pr["card"], lambda m=pr["multi"]: self.open_multi(m))
                return
            back = (lambda: self.open_event()) if pr.get("back") == "event" \
                else (lambda: self.tutorial_next() if self.tut else self.finish_tutorial()) \
                if pr.get("back") == "tutorial" \
                else (lambda: self.go_to_select()) if pr.get("back") == "ren" \
                else (lambda: self.open_stars()) if pr.get("back") == "stars" \
                else (lambda: self.open_essence()) if pr.get("back") == "essence" \
                else (lambda: self.open_quests()) if pr.get("back") == "quests" \
                else (lambda: self.open_archive()) if pr.get("back") == "archive" \
                else (lambda: self.open_packs(pr["pack"]))
            self.card_click(pr["card"], back)

    def draw_pack_open_classic(self, w):
        """The opening before 31 Oct (kept for an old sprites folder without the walkout's pictures)."""
        pr = self.pack_reveal
        dt = 1.0 / FPS
        card, pool = pr["card"], pr["tier"]
        glow = (255, 226, 130) if card["design"] in ("icon", "signature") else (
            (206, 178, 255) if card["design"] == "worldsgame" else
            LB_RED if card["design"] == "limitbreakers" and pool in ("A", "B") else self.POOL_GLOW[pool])
        dark, mid, gold = self.shard_colours(card, pool)
        cx, cy = WIDTH // 2, HEIGHT // 2 - 40
        tt = pygame.time.get_ticks() * 0.001
        art = pr.get("art") or self.pack_art[pr["pack"]]

        # ---- idle: the pack waiting for a tap
        if not pr["opened"]:
            w.blit(self.pack_backdrop(cx, cy), (0, 0))      # opaque: no need to clear first
            rect = pygame.Rect(0, 0, 330, 462)
            rect.center = (cx, cy + int(math.sin(tt * 2.4) * 10))
            aura = glow_blob((rect.w + 160, rect.h + 160), glow, 45 + 30 * math.sin(tt * 3))
            w.blit(aura, aura.get_rect(center=rect.center))
            if art is not None:
                w.blit(scaled(art, rect.size), rect)
            else:
                pygame.draw.rect(w, SELECT_GREEN, rect, border_radius=16)
                self.centre_in(w, PACK_NAMES[pr["pack"]], rect, self.font_m)
            btn = pygame.Rect(0, 0, 420, 92)
            btn.center = (cx, rect.bottom + 110)
            pygame.draw.rect(w, (40, 190, 90), btn, border_radius=46)
            pygame.draw.rect(w, WHITE, btn, 5, border_radius=46)
            lab = self.fit_text("TAP TO OPEN", self.font_m, WHITE, btn.w - 56, 58)
            w.blit(lab, lab.get_rect(center=btn.center))
            return

        # clocked in real time so the reveals stay locked to the song
        now = pygame.time.get_ticks() / 1000.0
        if "start" not in pr:
            pr["start"] = now - pr["t"]
        prev = pr["t"]
        pr["t"] = max(prev, now - pr["start"])
        t = pr["t"]
        t1, t2, t3, t4, beat_len, n_beats = self.opening_marks(pool)
        beats = self.reveal_beats(card, n_beats)
        plain = n_beats == 0                       # pool C: straight to the card

        def crossed(m):
            return prev < m <= t

        if t < t1:
            # ---- 1) the pack rushes at the camera and shatters
            w.fill((6, 8, 16))
            k = t / t1
            sc = 1.0 + k * k * 2.6
            shake = 6 + 26 * k
            rect = pygame.Rect(0, 0, int(330 * sc), int(462 * sc))
            rect.center = (cx + int(random.uniform(-shake, shake)), cy + int(random.uniform(-shake, shake)))
            aura = glow_blob((rect.w + 200, rect.h + 200), glow, 60 + 140 * k)
            w.blit(aura, aura.get_rect(center=rect.center))
            if art is not None:
                w.blit(scaled(art, (rect.w // 24 * 24, rect.h // 24 * 24)), rect)
            else:
                pygame.draw.rect(w, mid, rect, border_radius=16)
        elif t < t2:
            # ---- 2) flying through the crystal debris, one reveal per beat
            w.fill((6, 8, 16))
            local = t - t1
            self.draw_shard_field(w, pr, local, pool, cx, cy)
            starts = [b for b in PACK_BEATS[:len(beats)] if b <= t]
            if not starts:                                 # shards only until the first beat
                self.draw_fx(w, dt)
                self.centre_text(w, "CLICK TO SKIP", self.font_s, (150, 150, 160), 1010)
                return
            i = len(starts) - 1
            end = PACK_BEATS[i + 1] if i + 1 < len(beats) else t2
            f = (t - PACK_BEATS[i]) / max(0.01, end - PACK_BEATS[i])
            zoom = 0.45 + 0.55 * min(1.0, f * 4.5)
            fade = 1.0 if f < 0.72 else max(0.0, 1.0 - (f - 0.72) / 0.28)
            kind, val = beats[i]
            img = None
            if kind == "text":
                img = self.font_xl.render(str(val), True, WHITE)          # cached by CachedFont
                img = scaled(img, (max(1, int(img.get_width() * zoom * 1.4)) // 6 * 6,
                                   max(1, int(img.get_height() * zoom * 1.4)) // 6 * 6))
            elif kind == "rating":
                shown = int(min(1.0, f / 0.55) * val)
                slam = 1.0 + max(0.0, 1.0 - max(0.0, f - 0.55) * 7) * 0.35 if f >= 0.55 else 1.0
                shield = self.rating_shield(shown, gold, dark)
                img = scaled(shield, (max(1, int(320 * zoom * slam)) // 6 * 6,
                                      max(1, int(360 * zoom * slam)) // 6 * 6))
                if crossed(t1 + i * beat_len + beat_len * 0.55):
                    pass                                          # (no ball-kick sound in packs)
            elif val is not None:
                img = fit_flag(val, max(1, int(430 * zoom)), max(1, int(330 * zoom)))
            if img is not None:
                if fade < 1.0:
                    img = img.copy()
                    img.set_alpha(int(255 * fade))
                w.blit(img, img.get_rect(center=(cx, cy)))
        elif t < t3:
            # ---- 3) white flash, then a wall of light beams
            w.fill((6, 8, 16))
            k = (t - t2) / max(0.01, t3 - t2)
            self.draw_shard_field(w, pr, t2 - t1 + (t - t2), pool, cx, cy)
            nb = {"A": 13, "B": 8, "C": 4}[pool]
            h = HEIGHT * min(1.0, k * 2.2)
            band = min(HEIGHT, (int(h) + 121) // 120 * 120)   # the strip the beams live in,
            band = max(120, band)                      # rounded so the same surface is reused
            top = HEIGHT - band
            veil = scratch((WIDTH, band))
            for j in range(nb):
                off = (j - (nb - 1) / 2) * (WIDTH / (nb + 1))
                width = 22 + 14 * math.sin(tt * 7 + j * 1.6)
                col = glow if (pool != "A" or j % 3) else (255, 235, 150)
                x = cx + off
                bright = tuple(min(255, int(c * 0.45 + 255 * 0.55)) for c in col)
                base, tip = band, band - h
                pygame.draw.polygon(veil, col + (95,),
                                    [(x - width * 1.9, base), (x + width * 1.9, base),
                                     (x + width * 0.3, tip), (x - width * 0.3, tip)])
                pygame.draw.polygon(veil, bright + (150,),
                                    [(x - width * 0.9, base), (x + width * 0.9, base),
                                     (x + width * 0.14, tip), (x - width * 0.14, tip)])
                pygame.draw.polygon(veil, (255, 255, 255, 120),
                                    [(x - width * 0.34, base), (x + width * 0.34, base),
                                     (x + width * 0.07, band - h * 0.85), (x - width * 0.07, band - h * 0.85)])
            flare = self.pack_flare(glow)
            veil.blit(flare, flare.get_rect(center=(cx, band - int(h * 0.55))))
            veil.blit(tint((WIDTH, 208), glow + (12,)), (0, band - 220))
            w.blit(veil, (0, top))
            if crossed(t2 + 0.001):
                pass                                          # (no ball-kick sound in packs)
            wash(w, (255, 255, 255, int(235 * max(0.0, 1 - k * 2.4))), slot=1)
        else:
            # ---- 4) the stage: chevrons, the card slams in, confetti
            if plain:
                if self.shop_bg is not None:
                    w.blit(self.shop_bg, (0, 0))
                else:
                    w.fill((6, 8, 16))
            else:
                w.blit(self.pack_stage(gold), (0, 0))       # opaque, so nothing to clear
            w.blit(tint((WIDTH, 260), glow + (40,)), (0, HEIGHT - 260))
            local = t - t3
            slam_len = max(0.01, t4 - t3)
            k = min(1.0, local / slam_len)
            ease = 1 - (1 - k) ** 3
            sc = (1.5 - 0.5 * ease) if plain else (2.6 - 1.6 * ease)
            rect = pygame.Rect(0, 0, int(300 * sc), int(416 * sc))
            rect.center = (cx, cy - 20)
            if not plain:
                a = int(70 + 50 * math.sin(tt * 4)) if pool == "A" else 55
                halo = glow_blob((rect.w + 200, rect.h + 200), glow, a)
                w.blit(halo, halo.get_rect(center=rect.center))
            if crossed(t4):                                # impact
                self.burst_fireworks(cx, cy - 20, glow, 90 if pool == "A" else (45 if not plain else 16))
                if pool == "A":
                    for _ in range(5):
                        self.burst_fireworks(random.uniform(250, WIDTH - 250), random.uniform(120, 480),
                                             random.choice([glow, WHITE, YELLOW, (120, 220, 255)]))
            self.draw_card(w, card, rect, glow=k >= 1.0)
            if k >= 1.0:
                if pool == "A" and int(local * 1.5) != int((local - dt) * 1.5) and local < 5:
                    self.burst_fireworks(random.uniform(250, WIDTH - 250), random.uniform(120, 450),
                                         random.choice([glow, WHITE, YELLOW]))
                dup = pr["count"] > 1
                msg = "DUPLICATE  x%d" % pr["count"] if dup else "NEW PLAYER!"
                if card["design"] == "icon" and not dup:
                    msg = "ICON UNLOCKED!"
                elif card["design"] == "signature" and not dup:
                    msg = "SIGNATURE UNLOCKED!"
                elif card["design"] == "starsign":
                    msg = "STAR SIGNING COMPLETE!"
                elif card["design"] == "worldsgame":
                    msg = "SIGNED FROM THE WORLD'S GAME!"
                elif card["design"] == "samba" and not dup:
                    msg = "SAMBA CARD UNLOCKED!"
                elif card["design"] == "limitbreakers" and pool in ("A", "B") and not dup:
                    msg = "LIMIT BREAKER UNLOCKED!"
                self.centre_text(w, msg, self.font_l, (200, 200, 220) if dup else glow, 760)
                self.centre_text(w, "%s  -  %s" % (card["name"].upper(),
                                                   "STAR SIGNING ELITE" if card["design"] == "starsign"
                                                   else "THE WORLD'S GAME" if card["design"] == "worldsgame"
                                                   else "BEGINNER CARD" if card["design"] == "beginner"
                                                   else "LIMIT BREAKERS - POOL %s" % pool
                                                   if card["design"] == "limitbreakers"
                                                   else "POOL %s" % pool), self.font_m, WHITE, 862)
                self.centre_text(w, "CLICK TO CONTINUE  -  DOUBLE-CLICK FOR STATS", self.font_s,
                                 (200, 220, 200), 950)
        self.draw_fx(w, dt)
        if t < t4:
            self.centre_text(w, "CLICK TO SKIP", self.font_s, (150, 150, 160), 1010)

    # ================================================================ THE WALKOUT (31 Oct)
    # Hubi: "can we make a new pack opening animation? its pretty outdated" - and sent FC Mobile's
    # World's Game walkout. Its story, told again in this game's own pictures (make_pack_scene.py)
    # and on the beats of Hubi's pack song (PACK_BEATS / PACK_CARD_AT):
    #   0.00  the pack's flap folds back, light pours out of it, everything goes white
    #   1.00  a gold globe comes out of the light, on a burst in the card's colours
    #   2.00  FLAG on the globe, gold ribbons orbiting it
    #   3.20  the camera dives at the globe...
    #   3.50  ...POSITION, skimming low over its gold, chevron ribbons whipping past
    #   5.00  CREST on the globe: confetti bursts, streamers unfurl out from behind it
    #   6.00  it all goes dark - the stadium: lasers, an empty stage, a pillar of light rising
    #   7.00  the pillar becomes the card, his flag unfurls behind him, pyro both sides
    # Pool C has no cutscene: straight into the stadium, a short pillar, the card.
    WK_OPEN_END = 0.85
    WK_WHITE_END = 1.0
    WK_SWOOP = 3.2
    WK_POS_OUT = 4.85
    WK_CLUB_OUT = 6.0
    WK_DARK = 6.25
    WK_PILLAR = 6.45
    WK_STAGE_Y = 792             # where the card stands: the top of the stage
    WK_GLOBE_PX = 152
    WK_CLOSE = (480, 270, 24)
    WK_FLAG_FRAMES = 12
    # (centre of the burst, its middle, its edge, accent) - make_pack_scene.py's THEMES
    WK_THEME = {"A": ((255, 196, 255), (150, 62, 255), (84, 18, 226), (60, 255, 150)),
                "B": ((206, 232, 255), (60, 120, 255), (18, 40, 176), (255, 214, 90)),
                "L": ((255, 206, 196), (222, 40, 64), (108, 6, 26), (255, 164, 44)),
                "C": ((214, 222, 240), (92, 106, 140), (34, 40, 60), (190, 204, 230))}
    WK_STREAMERS = (((255, 150, 30), 196), ((232, 40, 52), 232), ((70, 120, 255), 300),
                    ((60, 200, 80), 344), ((170, 60, 255), 24), ((30, 24, 44), 150))
    WK_CONFETTI = ((240, 196, 90), (255, 226, 140), (222, 226, 238), (255, 255, 255))

    def wk_soft(self, size, col, alpha):
        """A soft round glow that fades to nothing at its edge (glow_blob is a flat oval).
        Built at 32 px and smoothed up; kept per size and colour, faded with set_alpha."""
        cache = self.__dict__.setdefault("_wk_soft", {})
        key = (max(16, int(size[0]) // 16 * 16), max(16, int(size[1]) // 16 * 16), tuple(col)[:3])
        img = cache.get(key)
        if img is None:
            lo = pygame.Surface((34, 34), pygame.SRCALPHA)
            for i in range(16, 0, -1):
                pygame.draw.ellipse(lo, tuple(col)[:3] + (int(255 * (1 - i / 16.0) ** 1.6),),
                                    (17 - i, 17 - i, 2 * i, 2 * i))
            img = pygame.transform.smoothscale(lo, key[:2])
            if len(cache) > 60:
                cache.clear()
            cache[key] = img
        img.set_alpha(max(0, min(255, int(alpha))))
        return img

    def wk_theme(self, card, pool):
        if pool == "C":
            return "C"
        if card["design"] == "limitbreakers":
            return "L"
        return "B" if pool == "B" else "A"

    def wk_ok(self):
        ok = self.__dict__.get("_wk_ok")
        if ok is None:
            names = ["pk_globe", "pk_close"] + ["pk_%s_%s" % (k, t) for k in ("burst", "stadium") for t in "ABLC"]
            ok = self._wk_ok = all(find_sprite(n) is not None for n in names)   # old sprites: old opening
        return ok

    def wk_img(self, name):
        cache = self.__dict__.setdefault("_wk_img", {})
        if name not in cache:
            path = find_sprite(name)
            img = pygame.image.load(path) if path else None
            if img is not None:
                img = img.convert_alpha() if name in ("pk_globe", "pk_close") else img.convert()
            cache[name] = img
        return cache[name]

    def wk_full(self, name):
        """A 640 x 360 picture blown up x3 to fill the screen - one kept per kind."""
        cache = self.__dict__.setdefault("_wk_full", {})
        kind = name.split("_")[1]
        hit = cache.get(kind)
        if hit is None or hit[0] != name:
            src = self.wk_img(name)
            hit = cache[kind] = (name, pygame.transform.scale(src, (WIDTH, HEIGHT)) if src else None)
        return hit[1]

    def wk_blit_globe(self, w, i, cx, cy, d):
        """Globe turn i, d px across, centred on (cx, cy). Up to 720 px it's scaled and kept;
        bigger (the dive) only the part that's on screen gets scaled."""
        fr = self.__dict__.get("_wk_globe")
        if fr is None:
            sheet, P = self.wk_img("pk_globe"), self.WK_GLOBE_PX
            fr = self._wk_globe = [sheet.subsurface((k * P, 0, P, P)) for k in range(sheet.get_width() // P)]
        src, P = fr[int(i) % len(fr)], self.WK_GLOBE_PX
        d = max(8, int(d))
        if d <= 720:
            d = d // 8 * 8
            w.blit(scaled(src, (d, d)), (int(cx - d / 2), int(cy - d / 2)))
            return
        k = d / float(P)
        x0, y0 = cx - d / 2.0, cy - d / 2.0
        vis = pygame.Rect(int(x0), int(y0), d, d).clip(w.get_rect())
        if vis.w <= 0 or vis.h <= 0:
            return
        sx0, sy0 = max(0, int((vis.x - x0) / k)), max(0, int((vis.y - y0) / k))
        sx1 = min(P, int(math.ceil((vis.right - x0) / k)))
        sy1 = min(P, int(math.ceil((vis.bottom - y0) / k)))
        if sx1 <= sx0 or sy1 <= sy0:
            return
        part = src.subsurface((sx0, sy0, sx1 - sx0, sy1 - sy0))
        img = pygame.transform.scale(part, (int(round((sx1 - sx0) * k)), int(round((sy1 - sy0) * k))))
        w.blit(img, (int(x0 + sx0 * k), int(y0 + sy0 * k)))

    def wk_close_frames(self, theme):
        """The close-up over the globe, put on a sky in the theme's colours (once per theme)."""
        hit = self.__dict__.get("_wk_close")
        if hit is None or hit[0] != theme:
            sheet = self.wk_img("pk_close")
            W, H, N = self.WK_CLOSE
            c, m, e, acc = self.WK_THEME[theme]
            sky = pygame.Surface((W, H)).convert()
            for y in range(H):
                sky.fill(lerp_rgb(e, m, min(1.0, y / (H * 0.45))), (0, y, W, 1))
            frames = []
            for i in range(N):
                f = sky.copy()
                f.blit(sheet.subsurface((0, i * H, W, H)), (0, 0))
                frames.append(f)
            hit = self._wk_close = (theme, frames)
        return hit[1]

    def wk_rings(self, w, cx, cy, R, t, front):
        """Gold ribbons orbiting the globe. The half behind it is drawn before it, the half in
        front after, so they go round it rather than over it."""
        for j, (tilt, spd, span, rx) in enumerate(((-0.35, 1.5, 2.6, 1.20), (0.55, -1.1, 2.0, 1.32))):
            ca, sa = math.cos(tilt), math.sin(tilt)
            a0 = t * spd + j * 2.0
            n = 24
            pts = []
            for s in range(n + 1):
                th = a0 + span * s / n
                x, y = math.cos(th) * R * rx, math.sin(th) * R * 0.30
                pts.append((cx + x * ca - y * sa, cy + x * sa + y * ca, math.sin(th), s / float(n)))
            for s in range(n):
                p, q = pts[s], pts[s + 1]
                if (p[2] + q[2] > 0) != front:
                    continue
                taper = min(1.0, p[3] * 5, (1 - p[3]) * 5)
                wd = max(2, int(R * 0.075 * taper))
                lit = 0.55 + 0.45 * (0.5 + 0.5 * p[2])
                col = (int(238 * lit), int(186 * lit), int(80 * lit))
                pygame.draw.line(w, _shade(col, 0.4), (p[0], p[1] + wd * 0.5), (q[0], q[1] + wd * 0.5), wd + 3)
                pygame.draw.line(w, col, p[:2], q[:2], wd)
                pygame.draw.line(w, (255, 242, 190), (p[0], p[1] - wd * 0.3), (q[0], q[1] - wd * 0.3),
                                 max(1, wd // 4))

    def wk_speed_lines(self, w, t, col, cx, cy):
        for j in range(20):
            a = j * math.tau / 20 + 0.17 * (j % 3)
            r = (t * 0.9 + j * 0.37) % 1.0
            r0 = 170 + r * 1150
            r1 = r0 + 80 + 180 * r
            ca, sa = math.cos(a), math.sin(a) * 0.8
            pygame.draw.line(w, col, (cx + ca * r0, cy + sa * r0), (cx + ca * r1, cy + sa * r1), max(1, int(1 + 5 * r)))

    def wk_whoosh(self, w, k, col, cx, cy):
        """Bright streaks rushing in from the edges - the beat before something arrives."""
        if not 0.0 < k < 1.0:
            return
        for j, a in enumerate((-0.55, 0.30, 2.55, 3.55, 1.45, -1.9, 0.95, 4.3)):
            sp = 0.012 + 0.012 * (j % 3)
            r0 = 1500 - k * (1100 + 120 * (j % 3))
            r1 = r0 + 900
            pygame.draw.polygon(w, col, [(cx + math.cos(a - sp) * r0, cy + math.sin(a - sp) * r0),
                                         (cx + math.cos(a + sp) * r0, cy + math.sin(a + sp) * r0),
                                         (cx + math.cos(a + sp * 2.2) * r1, cy + math.sin(a + sp * 2.2) * r1),
                                         (cx + math.cos(a - sp * 2.2) * r1, cy + math.sin(a - sp * 2.2) * r1)])

    def wk_chevrons(self, w, t):
        """Gold zig-zag ribbons whipping past the close-up."""
        for y, sc, spd, ph in ((720, 1.0, 1000, 0), (930, 1.6, 1500, 1500), (470, 0.65, 700, 600)):
            x0 = -1500 + ((t * spd + ph) % 3600)
            wd = int(24 * sc)
            pts = [(x0 + i * 120 * sc, y + (70 if i % 2 else -70) * sc + i * 9 * sc) for i in range(13)]
            pygame.draw.lines(w, (110, 70, 20), False, [(x + 5, yy + 8) for x, yy in pts], wd + 6)
            pygame.draw.lines(w, (226, 172, 70), False, pts, wd)
            pygame.draw.lines(w, (255, 236, 170), False, [(x, yy - wd * 0.3) for x, yy in pts], max(2, wd // 4))

    def wk_streamers(self, w, cx, cy, R, t, grow):
        """Fabric streamers unfurling out from behind the globe, waving, twisting as they go."""
        for k, (col, deg) in enumerate(self.WK_STREAMERS):
            a = math.radians(deg)
            dx, dy = math.cos(a), math.sin(a)
            px, py = -dy, dx
            L = 1500 * grow
            prev = None
            for s in range(19):
                u = s / 18.0
                d = R * 0.4 + L * u
                ph = u * 5.0 - t * 6.5 + k * 1.3
                off = math.sin(ph) * (16 + 130 * u)
                half = (22 + 105 * u) * (0.35 + 0.65 * abs(math.cos(ph * 0.6)))
                mx, my = cx + dx * d + px * off, cy + dy * d + py * off
                a1, a2 = (mx + px * half, my + py * half), (mx - px * half, my - py * half)
                if prev is not None:
                    pygame.draw.polygon(w, _shade(col, 0.62 + 0.5 * math.cos(ph)), [prev[0], prev[1], a2, a1])
                prev = (a1, a2)

    def wk_pillar(self, w, cx, base, h, k, col):
        """The pillar of light on the stage that the card comes out of."""
        if h <= 2 or k <= 0.02:
            return
        halo = self.wk_soft((520, int(h) + 420), col, int(255 * k))
        w.blit(halo, halo.get_rect(midbottom=(cx, base + 90)))
        r = pygame.Rect(0, 0, 300, int(h))
        r.midbottom = (cx, base)
        wash(w, (255, 255, 255, int(200 * k)), r.clip(w.get_rect()))
        wash(w, (255, 255, 255, int(255 * k)), r.inflate(-130, 0).clip(w.get_rect()))

    def wk_lasers(self, w, t, theme):
        c, m, e, acc = self.WK_THEME[theme]
        cols = ((255, 255, 255), c, acc, (120, 230, 255), (255, 140, 220))
        for k in range({"C": 4, "B": 8}.get(theme, 12)):     # pool C gets a quieter show
            side = -1 if k % 2 else 1
            ox = WIDTH / 2 + side * (230 + (k // 2) * 140)
            oy = 690 - (k // 2) * 18
            sweep = -0.35 + 1.2 * (0.5 + 0.5 * math.sin(t * (0.6 + 0.11 * k) + k * 1.7))
            ang = -math.pi / 2 + side * sweep
            ex, ey = ox + math.cos(ang) * 1600, oy + math.sin(ang) * 1600
            col = cols[k % len(cols)]
            pygame.draw.line(w, _shade(col, 0.42), (ox, oy), (ex, ey), 8)
            pygame.draw.line(w, col, (ox, oy), (ex, ey), 3)

    def wk_flag(self, card, f, size):
        """His flag as cloth, waving - built small, shaded fold by fold, kept for this card."""
        cache = self.__dict__.setdefault("_wk_flag", {})
        if cache.get("id") != (card["id"], size):
            cache.clear()
            cache["id"] = (card["id"], size)
        hit = cache.get(f)
        if hit is None:
            src = self.card_flag(card)
            if src is None:
                return None
            lw, lh, amp = 132, 84, 10
            try:
                lo = pygame.transform.smoothscale(src.convert_alpha(), (lw, lh))
            except Exception:
                lo = pygame.transform.scale(src, (lw, lh))
            out = pygame.Surface((lw, lh + amp * 2), pygame.SRCALPHA)
            for x in range(lw):
                ph = x / float(lw) * math.tau * 1.15 - f * math.tau / self.WK_FLAG_FRAMES
                col = lo.subsurface((x, 0, 1, lh)).copy()
                sh = 0.80 + 0.34 * math.cos(ph)
                if sh < 1:
                    v = int(255 * sh)
                    col.fill((v, v, v), special_flags=pygame.BLEND_RGB_MULT)
                else:
                    v = int(255 * (sh - 1))
                    col.fill((v, v, v), special_flags=pygame.BLEND_RGB_ADD)
                out.blit(col, (x, amp + int(round(math.sin(ph) * amp))))
            hit = cache[f] = pygame.transform.scale(out, size)
        return hit

    # ---- particles: confetti that flutters, pyro sparks
    def wk_confetti(self, pr, x, y, n, speed, cols):
        parts = pr.setdefault("wk_parts", [])
        for _ in range(n):
            a = random.uniform(0, math.tau)
            sp = random.uniform(0.25, 1.0) * speed
            parts.append([x, y, math.cos(a) * sp, math.sin(a) * sp - speed * 0.25, random.uniform(0, 6.3),
                          random.uniform(5, 13), random.uniform(7, 15), random.choice(cols),
                          random.uniform(3.0, 6.0), 0])
        if len(parts) > 700:
            del parts[:len(parts) - 700]

    def wk_pyro(self, pr, x, y, col):
        parts = pr.setdefault("wk_parts", [])
        for _ in range(70):
            parts.append([x + random.uniform(-24, 24), y, random.uniform(-190, 190), random.uniform(-1700, -900),
                          0.0, 0.0, random.uniform(5, 10),
                          random.choice(((255, 255, 255), (255, 236, 170), (255, 200, 90), col)),
                          random.uniform(0.7, 1.3), 1])
        pr.setdefault("wk_flash", []).append([x, y - 120, 0.45])

    def wk_particles(self, w, pr, dt):
        for fl in pr.get("wk_flash", []):
            fl[2] -= dt
            if fl[2] > 0:
                k = fl[2] / 0.45
                g = self.wk_soft((int(520 * (1.3 - k * 0.3)), int(620 * (1.3 - k * 0.3))), (255, 236, 200), int(230 * k))
                w.blit(g, g.get_rect(center=(int(fl[0]), int(fl[1]))))
        pr["wk_flash"] = [fl for fl in pr.get("wk_flash", []) if fl[2] > 0]
        alive = []
        for p in pr.get("wk_parts", []):
            p[8] -= dt
            if p[8] <= 0:
                continue
            if p[9] == 1:                                  # spark: thrown up, falls back
                p[3] += 1800 * dt
                p[0] += p[2] * dt
                p[1] += p[3] * dt
                col = p[7] if p[8] > 0.35 else _shade(p[7], p[8] / 0.35)
                s = int(p[6])
                pygame.draw.rect(w, col, (int(p[0]), int(p[1]), s, s))
            else:                                          # confetti: drag, a slow fall, a flutter
                drag = max(0.0, 1.0 - 2.4 * dt)
                p[2] *= drag
                p[3] = min(230.0, p[3] * drag + 520 * dt)
                p[4] += p[5] * dt
                p[0] += (p[2] + math.sin(p[4] * 0.7) * 45) * dt
                p[1] += p[3] * dt
                if p[1] > HEIGHT + 30:
                    continue
                c, s = math.cos(p[4]), math.sin(p[4] * 0.45)
                hw, hh = p[6] * max(0.12, abs(c)), p[6] * 0.42
                ca, sa = math.cos(p[4] * 0.45), s
                pts = [(p[0] + ca * dx - sa * dy, p[1] + sa * dx + ca * dy)
                       for dx, dy in ((-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh))]
                pygame.draw.polygon(w, p[7] if c > 0 else _shade(p[7], 0.6), pts)
            alive.append(p)
        pr["wk_parts"] = alive

    # ---- the scenes
    # 31 Oct, Hubi: "make like actually opening the pack better". The flap squashing flat read as a
    # picture shrinking. Now it RIPS: shaking harder and harder while a line of light zips across
    # its seam (0 - 0.3 s), then it tears along that jagged edge - the top flies off spinning, the
    # bottom drops away, light and sparks burst out with a shockwave, and it whites out (0.85 s).
    WK_PACK = (380, 532)          # the pack, waiting and opening (its art, scaled up a little)
    WK_TEAR_AT = 0.30             # seconds after the tap that it rips

    # ---- 31 Oct, "make it 100x better - it should be like a viral game": SWIPE TO TEAR and the
    # RARITY TELL. A walkout you watch is a cutscene; one you do is yours.
    #  * Swipe: drag across the pack's seam and it rips where your finger goes - a light follows
    #    you. Cover most of its width and it tears (straight to the rip, in time with the song).
    #    A tap still opens it the old way.
    #  * Tell: before the rip every pack looks the same. The light that pours out of the rip says
    #    how good: white (pool C), blue (B), gold (A) - always the truth. (Fake-outs that cracked
    #    and shouted UPGRADE! were tried the same night; Hubi: "looks ass" - gone.)
    WK_TELL = {"C": (250, 250, 255), "B": (110, 180, 255), "A": (255, 205, 70)}
    WK_C_OPEN = 0.75             # pool C: the rip, then the stadium
    WK_SWIPE_NEED = 0.72         # how much of the seam you have to swipe

    def wk_tell(self, card, shown):
        if card["design"] == "limitbreakers":
            return LB_RED
        return self.WK_TELL[shown]

    def wk_rip_now(self, pr):
        """The swipe got there: open it at the moment of the rip, the song from the same moment."""
        pr["opened"] = True
        pr["t"] = self.WK_TEAR_AT
        pr["wk_swiped"] = True
        pr.pop("start", None)
        pr.pop("swipe", None)
        if pr["tier"] in ("A", "B"):
            self.sfx.play_track("pack", start=self.WK_TEAR_AT, force=True)

    def pack_swipe_event(self, event):
        """Swipe to tear, on the sealed pack. True when the event was the swipe's."""
        pr = self.pack_reveal
        if not pr or pr.get("opened") or not self.wk_ok():
            return False
        rect = pr.get("wk_rect")
        if rect is None:
            return False
        sw = pr.get("swipe")
        if event.type == pygame.MOUSEBUTTONDOWN and getattr(event, "button", 1) == 1:
            x, y = event.pos
            if not rect.inflate(160, 160).collidepoint(x, y):
                return False                                 # elsewhere: a plain tap opens it
            x = clamp(x, rect.left, rect.right)
            done = sw or {"lo": x, "hi": x, "moved": 0.0}
            done.update({"held": True, "x": x, "y": y})
            pr["swipe"] = done
            return True
        if event.type == pygame.MOUSEMOTION and sw and sw.get("held"):
            x = clamp(event.pos[0], rect.left, rect.right)
            sw["moved"] += abs(x - sw["x"])
            sw["x"], sw["y"] = x, event.pos[1]
            sw["lo"], sw["hi"] = min(sw["lo"], x), max(sw["hi"], x)
            if (sw["hi"] - sw["lo"]) >= self.WK_SWIPE_NEED * rect.w:
                self.wk_rip_now(pr)
            return True
        if event.type == pygame.MOUSEBUTTONUP and getattr(event, "button", 1) == 1 and sw and sw.get("held"):
            sw["held"] = False
            if sw["moved"] < 30 and sw["hi"] - sw["lo"] < 30:
                pr.pop("swipe", None)
                self.pack_open_click()                       # it was a tap
            return True
        return False

    def wk_pack_pieces(self, pr, art, theme):
        """The pack cut along a jagged seam into its top strip and its body (once per opening)."""
        hit = pr.get("wk_pieces")
        if hit is not None:
            return hit
        W, H = self.WK_PACK
        base = pygame.Surface((W, H), pygame.SRCALPHA)
        if art is not None:
            base.blit(pygame.transform.scale(art, (W, H)), (0, 0))
        else:
            pygame.draw.rect(base, self.WK_THEME[theme][1], base.get_rect(), border_radius=18)
        seam = int(H * 0.088)                              # under the crimped top strip, above the crown
        rnd = random.Random(11)
        pts = [(0, seam)]
        for x in range(20, W, 20):                         # a torn zig-zag, never quite even
            pts.append((x, seam + (7 if (x // 20) % 2 else -7) + rnd.randint(-3, 3)))
        pts.append((W, seam))
        top, body = base.copy(), base.copy()
        pygame.draw.polygon(top, (0, 0, 0, 0), pts + [(W, H), (0, H)])
        pygame.draw.polygon(body, (0, 0, 0, 0), pts + [(W, 0), (0, 0)])
        top = top.subsurface((0, 0, W, seam + 16)).copy()
        hit = pr["wk_pieces"] = (top, body, pts, seam)
        return hit

    def wk_idle(self, w, pr, art, theme, tt, cx, cy):
        """The pack waiting for a tap: in the dark, in a spotlight, light leaking from its seam."""
        c, m, e, acc = self.WK_THEME[theme]
        stage = self.__dict__.setdefault("_wk_stage", {})
        sk = (theme, int(cx), int(cy))
        if sk not in stage:
            st = pygame.Surface((WIDTH, HEIGHT)).convert()
            st.fill(_shade(e, 0.16))
            cone = self.wk_soft((1200, 1800), m, 130)
            st.blit(cone, cone.get_rect(midtop=(cx, -520)))
            floor = self.wk_soft((780, 170), c, 130)
            st.blit(floor, floor.get_rect(center=(cx, cy + 330)))
            if len(stage) > 6:
                stage.clear()
            stage[sk] = st
        w.blit(stage[sk], (0, 0))
        top, body, pts, seam = self.wk_pack_pieces(pr, art, theme)
        rect = pygame.Rect((0, 0), self.WK_PACK)
        rect.center = (cx, cy)
        pr["wk_rect"] = rect.copy()                          # what a swipe is measured against
        sw = pr.get("swipe")
        prog = (sw["hi"] - sw["lo"]) / (self.WK_SWIPE_NEED * rect.w) if sw else 0.0
        bob = int(math.sin(tt * 2.4) * 10) if not sw else 0
        shake = 2 + 12 * prog * prog if sw else 0
        rect.move_ip(int(random.uniform(-shake, shake)), bob + int(random.uniform(-shake, shake)))
        aura = self.wk_soft((rect.w + 280, rect.h + 280), c, 150 + 60 * math.sin(tt * 3) + 60 * prog)
        w.blit(aura, aura.get_rect(center=rect.center))
        w.blit(body, rect)
        w.blit(top, rect)
        leak = 0.5 + 0.5 * math.sin(tt * 5.0)                # light leaking through the seam
        g = self.wk_soft((rect.w + 140, 120), (255, 250, 236), int(120 + 110 * leak))
        w.blit(g, g.get_rect(center=(rect.centerx, rect.y + seam)))
        line = [(rect.x + x, rect.y + y) for x, y in pts]
        pygame.draw.lines(w, (255, 252, 240), False, line, 2 + int(2 * leak))
        if sw:                                               # the rip so far, under your finger
            lo, hi = sw["lo"] - pr["wk_rect"].x, sw["hi"] - pr["wk_rect"].x
            seg = [(rect.x + x, rect.y + y) for x, y in pts if lo - 20 <= x <= hi + 20]
            if len(seg) >= 2:
                pygame.draw.lines(w, (255, 236, 170), False, seg, 12)
                pygame.draw.lines(w, (255, 255, 255), False, seg, 5)
            fx = rect.x + (sw["x"] - pr["wk_rect"].x)
            g = self.wk_soft((260, 260), (255, 250, 236), 255)
            w.blit(g, g.get_rect(center=(int(fx), rect.y + seam)))
            if sw.get("held"):
                parts = pr.setdefault("wk_parts", [])
                for _ in range(3):
                    parts.append([fx, rect.y + seam, random.uniform(-300, 300), random.uniform(-650, -150), 0.0, 0.0,
                                  random.uniform(4, 7), random.choice(((255, 255, 255), (255, 236, 170))),
                                  random.uniform(0.3, 0.6), 1])
            last = pr.get("wk_idle_t")
            pr["wk_idle_t"] = tt
            self.wk_particles(w, pr, min(0.1, max(0.0, tt - last)) if last else 1.0 / FPS)
        else:                                                # the hint: a finger sliding along the seam
            u = (tt % 1.6) / 1.2
            if u <= 1.0:
                hx = rect.x + 30 + (rect.w - 60) * (1 - (1 - u) ** 2)
                hy = rect.y + seam
                trail = [(rect.x + x, rect.y + y) for x, y in pts if rect.x + x <= hx and rect.x + x >= hx - 160]
                if len(trail) >= 2:
                    pygame.draw.lines(w, (255, 244, 200), False, trail, 6)
                pygame.draw.circle(w, (255, 255, 255), (int(hx), int(hy)), 26, 5)
                pygame.draw.circle(w, (255, 255, 255), (int(hx), int(hy)), 12)
        pill = pygame.Rect(0, 0, 520, 96)
        pill.center = (cx, rect.bottom + 90)
        btn = self.home_button(pill.size, False, top=_shade(m, 1.25), bottom=m, lip=_shade(e, 0.5))
        w.blit(btn, pill)
        self.home_text(w, "SWIPE TO TEAR", (pill.centerx, pill.y + 48), 56, WHITE, anchor="center")
        self.home_text(w, "or tap", (pill.centerx, pill.bottom + 40), 30, (200, 196, 230), anchor="center")

    def wk_pack_opens(self, w, pr, t, art, cx, cy, theme, tell, end):
        """It shakes, light zips along the seam, it rips, the top flies off, light pours out -
        in the tell's colour (the pack before the rip gives nothing away)."""
        c, m, e, acc = self.WK_THEME[theme]
        w.fill(_shade(e, 0.16))
        top, body, pts, seam = self.wk_pack_pieces(pr, art, theme)
        T = self.WK_TEAR_AT
        a = max(0.0, t - T)                                  # time since it ripped
        push = 1.0 + 0.08 * min(1.0, t / T) + 0.5 * a
        W, H = int(self.WK_PACK[0] * push) // 4 * 4, int(self.WK_PACK[1] * push) // 4 * 4
        k = W / float(self.WK_PACK[0])
        shake = (4 + 16 * (t / T) ** 2) if t < T else 26 * math.exp(-a * 9)
        x0 = cx - W / 2.0 + random.uniform(-shake, shake)
        y0 = cy - H / 2.0 + random.uniform(-shake, shake)
        line = [(x0 + x * k, y0 + y * k) for x, y in pts]
        tear_y = y0 + seam * k
        back = self.wk_soft((int(W * 2.4), int(H * 1.8)), c if t < T else tell, int(90 + 140 * min(1.0, t / T)))
        w.blit(back, back.get_rect(center=(cx, tear_y)))
        if t < T:
            u = t / T                                         # the light zipping across the seam
            w.blit(scaled(body, (W, H)), (int(x0), int(y0)))
            w.blit(scaled(top, (W, int(top.get_height() * k))), (int(x0), int(y0)))
            n = max(2, int(len(line) * u) + 1)
            seg = line[:n]
            pygame.draw.lines(w, (255, 236, 170), False, seg, 9)
            pygame.draw.lines(w, (255, 255, 250), False, seg, 4)
            tip = seg[-1]
            g = self.wk_soft((220, 220), (255, 250, 236), 255)
            w.blit(g, g.get_rect(center=(int(tip[0]), int(tip[1]))))
            parts = pr.setdefault("wk_parts", [])
            for _ in range(3):                                # sparks off the zip
                parts.append([tip[0], tip[1], random.uniform(-320, 320), random.uniform(-700, -150), 0.0, 0.0,
                              random.uniform(4, 7), random.choice(((255, 255, 255), (255, 236, 170), c)),
                              random.uniform(0.3, 0.6), 1])
            return
        if not pr.get("wk_ripped"):                          # RIP: a burst of sparks
            pr["wk_ripped"] = True
            parts = pr.setdefault("wk_parts", [])
            for _ in range(90):
                ang = random.uniform(-math.pi * 0.95, -math.pi * 0.05)
                sp = random.uniform(500, 1900)
                parts.append([cx + random.uniform(-W * 0.4, W * 0.4), tear_y, math.cos(ang) * sp,
                              math.sin(ang) * sp, 0.0, 0.0, random.uniform(5, 10),
                              random.choice(((255, 255, 255), tell, tell, _shade(tell, 1.3))),
                              random.uniform(0.5, 1.0), 1])
        o = min(1.0, a / 0.22)
        veil = scratch((WIDTH, HEIGHT), slot=3)              # god rays out of the tear
        for j in range(13):
            ang = -math.pi / 2 + (j - 6) * 0.16 + 0.05 * math.sin(j * 7.3)
            wd = 0.03 + 0.018 * (j % 3)
            L = 1700 * o
            base_x = cx + (j - 6) * W * 0.06
            pygame.draw.polygon(veil, lerp_rgb((255, 252, 240), tell, 0.45) + (int(60 + 80 * o),),
                                [(base_x, tear_y), (cx + math.cos(ang - wd) * L, tear_y + math.sin(ang - wd) * L),
                                 (cx + math.cos(ang + wd) * L, tear_y + math.sin(ang + wd) * L)])
        w.blit(veil, (0, 0))
        # the body drops away a little; its torn edge glows
        by = y0 + 700 * a * a
        w.blit(scaled(body, (W, H)), (int(x0), int(by)))
        g = self.wk_soft((int(W * 1.8), int(260 * k)), lerp_rgb((255, 250, 236), tell, 0.5), 255)
        w.blit(g, g.get_rect(center=(cx, int(tear_y + (by - y0)))))
        pygame.draw.lines(w, (255, 255, 250), False, [(x, y + (by - y0)) for x, y in line], 6)
        # the top strip flies off, spinning
        th = int(top.get_height() * k)
        strip = scaled(top, (W, th))
        spin = pygame.transform.rotate(strip, a * 620)
        px = cx + 520 * a
        py = y0 + th / 2.0 - 2300 * a + 4200 * a * a
        w.blit(spin, spin.get_rect(center=(int(px), int(py))))
        if a < 0.45:                                         # the shockwave ring
            rr = int(80 + 2600 * a)
            ring_w = max(2, int(22 * (1 - a / 0.45)))
            pygame.draw.circle(w, tell, (cx, int(tear_y)), rr + ring_w, ring_w + 6)
            pygame.draw.circle(w, (255, 250, 236), (cx, int(tear_y)), rr, ring_w)
        if a < 0.12:
            wash(w, (255, 255, 255, int(210 * (1 - a / 0.12))))
        if t > 0.58:
            wash(w, (255, 255, 255, int(255 * min(1.0, (t - 0.58) / (end - 0.58)) ** 1.3)))

    def wk_big_text(self, w, text, x, y, k_in, k_out):
        """POSITION: big white letters that slam in, then smear away."""
        img = self.font_xl.render(str(text), True, WHITE)
        shadow = self.font_xl.render(str(text), True, (40, 20, 70))
        pop = 1.0 + 0.5 * (1.0 - k_in) ** 3
        sw, sh = int(img.get_width() * 2.1 * pop) // 8 * 8, int(img.get_height() * 2.1 * pop) // 8 * 8
        im, sd = scaled(img, (sw, sh)), scaled(shadow, (sw, sh))
        a = int(255 * min(1.0, k_in * 3) * (1.0 - k_out))
        if a <= 4:
            return
        r = im.get_rect(center=(int(x), int(y)))
        if k_out > 0:                                        # the smear as it goes
            for j in (3, 2, 1):
                ghost = im.copy()
                ghost.set_alpha(int(a * 0.25))
                w.blit(ghost, r.move(int(j * 60 * k_out), 0))
        sd = sd.copy()
        sd.set_alpha(int(a * 0.75))
        w.blit(sd, r.move(14, 16))
        im = im.copy()
        im.set_alpha(a)
        w.blit(im, r)

    def wk_cutscene(self, w, pr, t, card, theme, art, cx, cy, tt, real_theme):
        c, m, e, acc = self.WK_THEME[theme]
        F, P, C = PACK_BEATS[0], PACK_BEATS[1], PACK_BEATS[2]
        spin = tt * 3.0
        if P <= t < C:                                       # POSITION, low over the globe
            frames = self.wk_close_frames(theme)
            k = (t - P) / (self.WK_POS_OUT - P)
            w.blit(scale_into(frames[min(len(frames) - 1, int(k * len(frames)))], (WIDTH, HEIGHT), "wkclose"), (0, 0))
            self.wk_chevrons(w, t - P)
            self.wk_big_text(w, card["pos"], cx, HEIGHT // 2, min(1.0, (t - P) / 0.18),
                             clamp((t - (self.WK_POS_OUT - 0.3)) / 0.3, 0.0, 1.0))
            if t < P + 0.15:
                wash(w, (255, 255, 255, int(255 * (1 - (t - P) / 0.15))))
            if t > self.WK_POS_OUT:
                wash(w, (255, 255, 255, int(255 * clamp((t - self.WK_POS_OUT) / (C - self.WK_POS_OUT), 0, 1))))
            return
        w.blit(self.wk_full("pk_burst_" + theme), (0, 0))
        if t < self.WK_WHITE_END + 0.1:                      # build the close-up while the screen is white
            self.wk_close_frames(real_theme)
            self.wk_full("pk_stadium_" + real_theme)
        if t < F:                                            # the globe out of the light
            self.wk_speed_lines(w, t, c, cx, cy)
            d = 440 + 70 * (t - self.WK_OPEN_END) / (F - self.WK_OPEN_END)   # (31 Oct: all bigger)
            if t > F - 0.22:
                d += 130 * ((t - (F - 0.22)) / 0.22) ** 2
            self.wk_blit_globe(w, spin, cx, cy, d)
            self.wk_whoosh(w, (t - (F - 0.22)) / 0.22, acc, cx, cy)
            if t < self.WK_WHITE_END + 0.6:
                wash(w, (255, 255, 255, int(255 * clamp(1 - (t - self.WK_WHITE_END) / 0.6, 0, 1))))
            return
        if t < self.WK_SWOOP:                                # FLAG on the globe
            k = t - F
            d = 640
            self.wk_speed_lines(w, t, c, cx, cy)
            self.wk_rings(w, cx, cy, d / 2, t, False)
            self.wk_blit_globe(w, spin, cx, cy, d)
            flag = self.card_flag(card)
            if flag is not None:
                x = min(1.0, k / 0.28)
                pop = 1 + 2.7 * (x - 1) ** 3 + 1.7 * (x - 1) ** 2  # overshoots, settles
                fw, fh = max(16, int(d * 0.64 * pop) // 16 * 16), max(16, int(d * 0.46 * pop) // 16 * 16)
                img = fit_flag(flag, fw, fh)
                fade = 1.0 - clamp((t - (self.WK_SWOOP - 0.28)) / 0.22, 0.0, 1.0)
                if fade < 1.0:
                    img = img.copy()
                    img.set_alpha(int(255 * fade))
                r = img.get_rect(center=(cx, cy))
                if fade >= 1.0:
                    pygame.draw.rect(w, (40, 24, 6), r.inflate(12, 12))
                w.blit(img, r)
            self.wk_rings(w, cx, cy, d / 2, t, True)
            if k < 0.14:
                wash(w, (255, 255, 255, int(220 * (1 - k / 0.14))))
            return
        if t < P:                                            # the dive at the globe
            k = (t - self.WK_SWOOP) / (P - self.WK_SWOOP)
            d = 640 + 3000 * k * k
            self.wk_blit_globe(w, spin * 1.6, cx, cy + 950 * k * k, d)
            self.wk_whoosh(w, k, acc, cx, cy)
            if k > 0.75:
                wash(w, (255, 255, 255, int(255 * (k - 0.75) / 0.25)))
            return
        # CREST, confetti, streamers
        k = t - C
        grow = 1.0 - (1.0 - min(1.0, k / 0.5)) ** 3
        d = 660
        self.wk_streamers(w, cx, cy, d / 2, t, grow)
        self.wk_blit_globe(w, spin, cx, cy, d)
        badge = self.card_club(card)
        if badge is not None:
            x = min(1.0, k / 0.28)
            pop = 1 + 2.7 * (x - 1) ** 3 + 1.7 * (x - 1) ** 2
            bs = max(16, int(d * 0.66 * pop) // 16 * 16)
            kb = bs / float(max(badge.get_width(), badge.get_height()))
            img = scaled(badge, (max(1, int(badge.get_width() * kb)), max(1, int(badge.get_height() * kb))))
            fade = 1.0 - clamp((t - (self.WK_CLUB_OUT - 0.3)) / 0.25, 0.0, 1.0)
            if fade < 1.0:
                img = img.copy()
                img.set_alpha(int(255 * fade))
            w.blit(img, img.get_rect(center=(cx, cy)))
        if not pr.get("wk_crest"):
            pr["wk_crest"] = True
            self.wk_confetti(pr, cx, cy, 190, 1500, self.WK_CONFETTI + (c, acc))
        if k < 0.14:
            wash(w, (255, 255, 255, int(220 * (1 - k / 0.14))))
        if t > self.WK_CLUB_OUT:
            wash(w, (0, 0, 0, int(255 * clamp((t - self.WK_CLUB_OUT) / (self.WK_DARK - self.WK_CLUB_OUT), 0, 1))))

    def wk_landing_text(self, w, card, pool, count, glow, cx):
        dup = count > 1
        msg = "DUPLICATE  x%d" % count if dup else "NEW PLAYER!"
        if card["design"] == "icon" and not dup:
            msg = "ICON UNLOCKED!"
        elif card["design"] == "signature" and not dup:
            msg = "SIGNATURE UNLOCKED!"
        elif card["design"] == "starsign":
            msg = "STAR SIGNING COMPLETE!"
        elif card["design"] == "worldsgame":
            msg = "SIGNED FROM THE WORLD'S GAME!"
        elif card["design"] == "samba" and not dup:
            msg = "SAMBA CARD UNLOCKED!"
        elif card["design"] == "limitbreakers" and pool in ("A", "B") and not dup:
            msg = "LIMIT BREAKER UNLOCKED!"
        sub = "%s  -  %s" % (card["name"].upper(),
                             "STAR SIGNING ELITE" if card["design"] == "starsign"
                             else "THE WORLD'S GAME" if card["design"] == "worldsgame"
                             else "BEGINNER CARD" if card["design"] == "beginner"
                             else "LIMIT BREAKERS - POOL %s" % pool if card["design"] == "limitbreakers"
                             else "POOL %s" % pool)
        pad = tint((WIDTH, 230), (6, 4, 16, 150))
        w.blit(pad, (0, HEIGHT - 230))
        self.home_text(w, msg, (cx, 892), 70, (210, 210, 228) if dup else glow, anchor="center")
        self.home_text(w, sub, (cx, 962), 44, WHITE, anchor="center")
        self.home_text(w, "CLICK TO CONTINUE  -  DOUBLE-CLICK FOR STATS", (cx, 1030), 30, (200, 220, 200),
                       anchor="center")

    def wk_stadium(self, w, pr, t, land, plain, card, pool, theme, glow, cx, now, rdt):
        c, m, e, acc = self.WK_THEME[theme]
        if not pr.get("wk_stadium"):
            pr["wk_stadium"] = True
            pr["wk_parts"], pr["wk_flash"] = [], []
        w.blit(self.wk_full("pk_stadium_" + theme), (0, 0))
        self.wk_lasers(w, now, theme)
        base = self.WK_STAGE_Y
        start = self.WK_C_OPEN if plain else self.WK_DARK
        if t < land:                                         # the pillar rising
            p0 = self.WK_C_OPEN if plain else self.WK_PILLAR
            k = clamp((t - p0) / max(0.05, land - p0), 0.0, 1.0)
            self.wk_pillar(w, cx, base, 640 * (1 - (1 - k) ** 3), min(1.0, k * 3), c)
            self.wk_particles(w, pr, rdt)
            if t < start + 0.2:                              # out of the dark (C: out of the white)
                wash(w, ((255, 255, 255) if plain else (0, 0, 0)) + (int(255 * clamp(1 - (t - start) / 0.2, 0, 1)),))
            self.centre_text(w, "CLICK TO SKIP", self.font_s, (220, 220, 240), 1010)
            return
        if not pr.get("wk_landed"):                          # he's here
            pr["wk_landed"] = True
            pr["wk_pyro_n"] = 0
            if not plain:
                for x in (470, WIDTH - 470):
                    self.wk_pyro(pr, x, 800, c)
                self.wk_confetti(pr, cx, 420, 120 if pool == "A" else 60, 1300, self.WK_CONFETTI + (c, acc))
        local = t - land
        if pool == "A" and int(local / 3.0) > pr.get("wk_pyro_n", 0):   # pyro again every 3 s
            pr["wk_pyro_n"] = int(local / 3.0)
            for x in (470, WIDTH - 470):
                self.wk_pyro(pr, x, 800, c)
        rate = {"A": 55, "B": 26}.get(pool, 0 if plain else 12)        # confetti raining down
        if rate:
            pr["wk_rain"] = pr.get("wk_rain", 0.0) + rate * rdt
            while pr["wk_rain"] >= 1.0:
                pr["wk_rain"] -= 1.0
                pr.setdefault("wk_parts", []).append(
                    [random.uniform(0, WIDTH), -20, 0.0, random.uniform(60, 160), random.uniform(0, 6.3),
                     random.uniform(4, 10), random.uniform(7, 14), random.choice(self.WK_CONFETTI + (c, acc)),
                     9.0, 0])
        unfurl = 1.0 - (1.0 - min(1.0, local / 0.4)) ** 3
        flag = self.wk_flag(card, int(now * 11) % self.WK_FLAG_FRAMES, (780, 520))
        if flag is not None:
            fw = max(8, int(flag.get_width() * unfurl))
            img = flag if fw == flag.get_width() else pygame.transform.scale(flag, (fw, flag.get_height()))
            w.blit(img, img.get_rect(center=(cx, base - 330)))
        rect = pygame.Rect(0, 0, 390, 536)
        sc = 1.0 + 0.10 * (1.0 - min(1.0, local / 0.25)) ** 2
        rect.size = (int(390 * sc), int(536 * sc))
        rect.midbottom = (cx, base)
        halo = self.wk_soft((rect.w + 360, rect.h + 360), glow, 190 + 50 * math.sin(now * 4) if pool == "A" else 150)
        w.blit(halo, halo.get_rect(center=rect.center))
        self.blit_card(w, card, rect, glow=True)
        if local < 0.35:                                     # the light he came out of
            self.wk_pillar(w, cx, base, 640, 1.0 - local / 0.35, c)
            wash(w, (255, 255, 255, int(230 * (1.0 - local / 0.35))), rect.clip(w.get_rect()))
        self.wk_particles(w, pr, rdt)
        if local < 0.12 and not plain:
            wash(w, (255, 255, 255, int(200 * (1 - local / 0.12))))
        if local >= 0.4:
            self.wk_landing_text(w, card, pool, pr["count"], glow, cx)

    def draw_pack_open(self, w):
        pr = self.pack_reveal
        if not self.wk_ok():
            return self.draw_pack_open_classic(w)
        card, pool = pr["card"], pr["tier"]
        glow = (255, 226, 130) if card["design"] in ("icon", "signature") else (
            (206, 178, 255) if card["design"] == "worldsgame" else
            LB_RED if card["design"] == "limitbreakers" and pool in ("A", "B") else self.POOL_GLOW[pool])
        theme = self.wk_theme(card, pool)
        cx, cy = WIDTH // 2, HEIGHT // 2 - 40
        tt = pygame.time.get_ticks() * 0.001
        art = pr.get("art") or self.pack_art[pr["pack"]]
        if not pr["opened"]:
            self.wk_idle(w, pr, art, "A", tt, cx, cy)        # every pack looks the same until it rips
            return
        # clocked in real time so the beats stay locked to the song
        now = pygame.time.get_ticks() / 1000.0
        if "start" not in pr:
            pr["start"] = now - pr["t"]
        pr["t"] = max(pr["t"], now - pr["start"])
        t = pr["t"]
        last = pr.get("wk_now")
        pr["wk_now"] = now
        rdt = min(0.1, max(0.0, now - last)) if last is not None else 1.0 / FPS
        land = self.opening_done_at(pool)
        plain = pool == "C"
        ts = t
        seen = theme
        tell = self.wk_tell(card, pool)
        if plain and t < self.WK_C_OPEN:
            self.wk_pack_opens(w, pr, t, art, cx, cy, "A", tell, self.WK_C_OPEN)
            self.wk_particles(w, pr, rdt)
        elif not plain and t < self.WK_DARK:
            if ts < self.WK_OPEN_END:
                self.wk_pack_opens(w, pr, ts, art, cx, cy, "A", tell, self.WK_OPEN_END)
            else:
                self.wk_cutscene(w, pr, ts, card, seen, art, cx, cy, tt, theme)
            self.wk_particles(w, pr, rdt)
            self.centre_text(w, "CLICK TO SKIP", self.font_s, (235, 225, 255), 1010)
        else:
            self.wk_stadium(w, pr, t, land, plain, card, pool, theme, glow, cx, now, rdt)
        self.draw_fx(w, 1.0 / FPS)

    # ================================================================ TUTORIAL (first launch, replay from TEAM)
    TUT_TEXT = {
        "welcome": ("WELCOME TO A SMALL WORLD CUP!",
                    "This is you - a little ragdoll footballer. You don't walk: you THROW yourself around the pitch."),
        "drag": ("DRAG TO THROW",
                 "Hold the mouse button anywhere, drag, then let go. You fly the way the arrow points - "
                 "the longer the drag, the harder the throw."),
        "air": ("THROW AGAIN - EVEN IN THE AIR",
                "You can throw as often as you like, even mid-air, to change direction. Do 3 more throws."),
        "ball": ("HIT THE BALL",
                 "Fling yourself into the ball. The faster you're moving when you hit it, the further it flies."),
        "goal": ("SCORE!",
                 "Knock the ball into the goal on the RIGHT. The robot in front of it is just a dummy."),
        "match": ("MATCHES",
                  "Two 30-second halves - most goals wins. OVR = how hard you hit, SHO = how steady your aim is, "
                  "STR = how far you can throw. Players get tired, so rotate your squad of 5."),
        "menu": ("THE MENU",
                 "PLAY: World Cup, Club Football, Freeplay and Practice.   STORE: packs, Star Signing and the "
                 "exchange.   TEAM: your squad, kit and badge."),
        "done": ("YOU'RE READY!",
                 "Your new player is in your squad. Check TEAM, then hit PLAY. You can replay this tutorial from TEAM."),
    }
    TUT_ACTION = ("drag", "air", "ball", "goal")               # steps finished by doing something
    TUT_PITCH = ("welcome", "drag", "air", "ball", "goal", "match")

    def tutorial_progress(self):
        return self.save.setdefault("tutorial", {"coins": False, "packs": 0, "picked": None})

    def start_tutorial(self, replay=False):
        prog = self.tutorial_progress()
        self.tut = {"step": "welcome", "throws": 0, "touches": 0, "goals": 0, "replay": replay,
                    "nice": 0.0, "arrow_t": 0.0}
        self.card_detail = None
        if not replay and prog["coins"]:                   # closed the game half way: carry on where we were
            self.tut["step"] = "done" if prog["picked"] else ("pick" if prog["packs"] >= TUTORIAL_PACKS else "packs")
            self.enter_tutorial_step()
            return
        self.start_practice()
        self.clear_robots()
        self.practice_reset_ball()

    def enter_tutorial_step(self):
        t = self.tut
        step = t["step"]
        t["throws"] = t["touches"] = t["goals"] = 0
        t["nice"] = 0.0
        if step in ("ball", "goal"):
            self.practice_reset_ball()
        if step == "goal":
            bot = self.add_robot("DUMMY")
            if bot is not None:
                bot["doll"].reset_to(WIDTH - GOAL_DEPTH - 330)
        if step in ("menu", "packs", "pick", "done") and self.mode == "practice":
            self.end_practice()
            self.menu_page = "main"
        if step == "packs":
            prog = self.tutorial_progress()
            if not prog["coins"]:
                prog["coins"] = True
                self.save["coins"] += TUTORIAL_COINS
                self.toast("+%d COINS - BUY %d PACKS!" % (TUTORIAL_COINS, TUTORIAL_PACKS), YELLOW)
                self.write_save()
            self.state = TITLE
            self.menu_page = "main"
        if step == "pick":
            self.rookie_sel = None
            self.state = ROOKIE_PICK
        if step == "done":
            self.state = TITLE
            self.menu_page = "main"

    def tutorial_next(self):
        t = self.tut
        i = TUTORIAL_STEPS.index(t["step"]) + 1
        nxt = TUTORIAL_STEPS[i] if i < len(TUTORIAL_STEPS) else None
        if t["replay"] and nxt in ("packs", "pick"):
            nxt = "done"                                     # the rewards only come once
        if nxt is None:
            self.finish_tutorial()
            return
        t["step"] = nxt
        self.enter_tutorial_step()

    def skip_tutorial(self):
        """SKIP jumps past the lessons - the 3 packs + beginner pick still happen (first time only)."""
        t = self.tut
        if t["replay"]:
            if self.mode == "practice":
                self.end_practice()
            self.finish_tutorial()
            return
        t["step"] = "packs"
        self.enter_tutorial_step()

    def finish_tutorial(self):
        if self.mode == "practice":
            self.end_practice()
        self.tut = None
        self.save["tutorial_done"] = True
        self.state = TITLE
        self.menu_page = "main"
        self.write_save()

    def update_tutorial(self, dt):
        t = self.tut
        t["arrow_t"] += dt
        step = t["step"]
        if t["nice"] > 0.0:                                  # "NICE!" for a moment, then the next step
            t["nice"] -= dt
            if t["nice"] <= 0.0:
                self.tutorial_next()
            return
        done = {"drag": t["throws"] >= 1, "air": t["throws"] >= 3, "ball": t["touches"] >= 1,
                "goal": t["goals"] >= 1}.get(step, False)
        if done:
            t["nice"] = 1.0
            self.sfx.play("buff", 0.5)
        if step == "packs" and self.tutorial_progress()["packs"] >= TUTORIAL_PACKS and self.state in (PACKS, PACK_VIEW):
            self.tutorial_next()                             # 3 packs opened: pick your beginner
        elif step == "pick" and self.state not in (ROOKIE_PICK, PACK_OPEN):
            self.state = ROOKIE_PICK                         # nothing else to do until he's picked

    TUT_LINE = 38

    def tutorial_texts(self):
        t = self.tut
        step = t["step"]
        if t["nice"] > 0.0:
            return "NICE!", "On to the next one..."
        if step not in self.TUT_TEXT and step != "packs":
            return "", ""                                  # "pick" has its own screen, no text box
        if step == "packs":
            n = self.tutorial_progress()["packs"]
            body = {TITLE: "Here's %d coins! Click STORE." % TUTORIAL_COINS, STORE: "Click PACKS.",
                    PACKS: "Pick a pack on the left, then hit 1 DRAW (300 coins).",
                    PACK_VIEW: "Click BUY to open it (300 coins)."}.get(self.state, "Keep going!")
            return "BUY %d PACKS  (%d / %d)" % (TUTORIAL_PACKS, n, TUTORIAL_PACKS), body
        return self.TUT_TEXT.get(step, ("", ""))

    def wrap_text(self, text, width, height=34):
        """Split text into lines that fit `width` once drawn `height` px tall."""
        k = height / float(max(1, self.font_s.get_height()))
        lines, line = [], ""
        for word in text.split():
            test = (line + " " + word).strip()
            if line and self.font_s.size(test)[0] * k > width:
                lines.append(line)
                line = word
            else:
                line = test
        if line:
            lines.append(line)
        return lines

    def tutorial_layout(self):
        """(text box, NEXT button or None, SKIP button or None) for the current screen."""
        t = self.tut
        step = t["step"]
        if step in self.TUT_PITCH:
            box = pygame.Rect(260, 14, 1400, 0)
        elif self.state == PACK_VIEW:
            box = pygame.Rect(706, 0, 1060, 0)
        else:
            box = pygame.Rect(260, 0, 1400, 0)
        lines = self.wrap_text(self.tutorial_texts()[1], box.w - 60)
        box.h = 70 + len(lines) * self.TUT_LINE + 76
        if step not in self.TUT_PITCH:
            box.bottom = 1030 if self.state == PACK_VIEW else 1064
        nxt = skip = None
        if step in ("welcome", "match", "menu", "done") and t["nice"] <= 0.0:
            nxt = pygame.Rect(box.right - 210, box.bottom - 66, 190, 54)
        if step in self.TUT_PITCH:
            skip = pygame.Rect(box.right - (420 if nxt else 210), box.bottom - 66, 190, 54)
        return box, nxt, skip

    def tutorial_reset_rect(self):
        """RESET BALL in the text box for the ball + goal steps (in case it gets stuck)."""
        if self.tut is None or self.tut["step"] not in ("ball", "goal") or self.tut["nice"] > 0.0:
            return None
        box, nxt, skip = self.tutorial_layout()
        return pygame.Rect(box.right - 460, box.bottom - 66, 230, 54)

    def tutorial_click(self, pos):
        """NEXT / SKIP / DONE. True = the click was the tutorial's."""
        if self.state in (ROOKIE_PICK, PACK_OPEN) or self.tut["step"] == "pick":
            return False
        box, nxt, skip = self.tutorial_layout()
        if nxt is not None and nxt.collidepoint(pos):
            self.tutorial_next()
            return True
        if skip is not None and skip.collidepoint(pos):
            self.skip_tutorial()
            return True
        reset = self.tutorial_reset_rect()
        if reset is not None and reset.collidepoint(pos):
            self.practice_reset_ball()
            return True
        return box.collidepoint(pos) and self.tut["step"] in self.TUT_PITCH

    def tutorial_target(self):
        """The one thing you're allowed to click while buying the tutorial packs."""
        if self.tut is None or self.tut["step"] != "packs":
            return []
        if self.state == TITLE:
            if HOME_V2:
                return [r for tab, r in self.home_layout()["tabs"] if tab == "STORE"]
            return [r for item, r in zip(self.menu_items(), self.menu_layout()) if item == "STORE"]
        if self.state == STORE:
            return [self.store_layout()[0]]
        if self.state == PACKS:
            return self.packs_layout() + [self.packs_ui()["one"]]
        if self.state == PACK_VIEW:
            return [self.view_layout()["buy"]]
        return []

    def tutorial_allows(self, pos):
        step = self.tut["step"]
        if step in ("menu", "done"):
            return False                                     # only NEXT / DONE for now
        if step == "packs":
            if self.state in (PACK_OPEN, ROOKIE_PICK):
                return True
            L = self.view_layout() if self.state == PACK_VIEW else None
            extra = [L["art"], L["left"], L["right"], pygame.Rect(40, 30, 200, 70)] + \
                [r for _p, r in L["tabs"]] if L else []
            if self.state == PACKS:
                ui = self.packs_ui()
                extra = [ui["info"], ui["all"]] + [r for _p, r in ui["pools"]]
            return any(r.collidepoint(pos) for r in self.tutorial_target() + extra)
        return True

    def draw_tutorial(self, w):
        t = self.tut
        step = t["step"]
        if step == "pick" or self.state in (PACK_OPEN, ROOKIE_PICK):
            if step == "packs" and self.state == PACK_OPEN:
                n = self.tutorial_progress()["packs"]
                tag = self.label("TUTORIAL PACK %d / %d" % (n, TUTORIAL_PACKS), 500, YELLOW)
                w.blit(tag, (40, 30))
            return
        mouse = pygame.mouse.get_pos()
        box, nxt, skip = self.tutorial_layout()
        title, body = self.tutorial_texts()
        # highlight + bouncing arrow on what to click
        bob = int(abs(math.sin(t["arrow_t"] * 5)) * 18)
        for r in self.tutorial_target():
            pygame.draw.rect(w, YELLOW, r.inflate(16, 16), 5, border_radius=16)
            tip = (r.centerx, r.y - 18 - bob)
            pygame.draw.polygon(w, YELLOW, [(tip[0] - 26, tip[1] - 40), (tip[0] + 26, tip[1] - 40), tip])
            pygame.draw.polygon(w, INK, [(tip[0] - 26, tip[1] - 40), (tip[0] + 26, tip[1] - 40), tip], 3)
        w.blit(tint(box.size, (8, 12, 26, 228)), box.topleft)
        pygame.draw.rect(w, YELLOW, box, 4, border_radius=18)
        if step in TUTORIAL_STEPS[:7]:
            k = TUTORIAL_STEPS.index(step) + 1
            num = self.label("STEP %d / 7" % k, 220, (170, 180, 206))
            w.blit(num, num.get_rect(topright=(box.right - 24, box.y + 16)))
        head = self.fit_text(title, self.font_m, YELLOW, box.w - 300, 52)
        w.blit(head, (box.x + 30, box.y + 14))
        reset = self.tutorial_reset_rect()
        for i, line in enumerate(self.wrap_text(body, box.w - 60)):
            img = self.fit_text(line, self.font_s, WHITE, box.w - 60, 34)
            w.blit(img, (box.x + 30, box.y + 70 + i * self.TUT_LINE))
        for r, txt, col in ((nxt, "DONE" if step == "done" else "NEXT >", (40, 170, 70)),
                            (skip, "SKIP", (110, 50, 60)), (reset, "RESET BALL", (40, 90, 170))):
            if r is None:
                continue
            pygame.draw.rect(w, col, r, border_radius=14)
            pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else WHITE, r, 3, border_radius=14)
            lab = self.fit_text(txt, self.font_s, WHITE, r.w - 24, 34)
            w.blit(lab, lab.get_rect(center=r.center))

    # ---- pick your beginner --------------------------------------------------
    def rookie_layout(self):
        cards = [pygame.Rect(0, 0, 340, 472) for _ in self.rookie_ids]
        for i, r in enumerate(cards):
            r.midtop = (WIDTH // 2 + (i - 1) * 470, 230)
        return cards, pygame.Rect(WIDTH // 2 - 230, 930, 460, 110)

    def rookie_click(self, pos):
        cards, sign = self.rookie_layout()
        for cid, r in zip(self.rookie_ids, cards):
            if r.collidepoint(pos.x, pos.y):
                if self.rookie_sel == cid:
                    self.card_detail = self.cards[cid]
                    self.card_tab = 0
                self.rookie_sel = cid
                return
        if sign.collidepoint(pos.x, pos.y) and self.rookie_sel:
            self.sign_rookie(self.cards[self.rookie_sel])

    def sign_rookie(self, card):
        prog = self.tutorial_progress()
        if prog["picked"]:
            return False
        prog["picked"] = card["id"]
        count = self.give_card(card)
        squad = self.save["squad"]
        if len(squad) < SQUAD_SIZE:
            squad.append(card["id"])
        elif card["id"] not in squad:                        # he replaces your weakest starter
            weakest = min(squad, key=lambda k: self.cards[k]["rating"] if k in self.cards else 0)
            squad[squad.index(weakest)] = card["id"]
        self.pack_reveal = {"card": card, "t": 0.0, "count": count, "pack": 0, "tier": "B",
                            "opened": True, "back": "tutorial", "art": self.pack_art[0]}
        self.fx = []
        self.state = PACK_OPEN
        self.write_save()
        return True

    def draw_rookie_pick(self, w):
        w.blit(self.shop_bg or self.select_bg, (0, 0))
        head = self.outlined("PICK YOUR FIRST STAR", self.font_l, YELLOW, 0.9, width=5)
        w.blit(head, head.get_rect(center=(WIDTH // 2, 80)))
        sub = self.label("BEGINNER VERSIONS  -  HE JOINS YOUR SQUAD  -  CLICK AGAIN FOR STATS", 1300,
                         (200, 230, 214))
        w.blit(sub, sub.get_rect(center=(WIDTH // 2, 170)))
        cards, sign = self.rookie_layout()
        mouse = pygame.mouse.get_pos()
        for cid, r in zip(self.rookie_ids, cards):
            c = self.cards[cid]
            sel = self.rookie_sel == cid
            rr = r.move(0, -14) if sel else r
            self.blit_card(w, c, rr, glow=sel or r.collidepoint(mouse))
            info = self.label("%s  -  %s" % (c["pos"], STAR_CLUB_NAMES.get(c["team"], c["team"]).upper()), r.w + 40,
                              ROOKIE_MINT if sel else WHITE)
            w.blit(info, info.get_rect(center=(r.centerx, r.bottom + 44)))
        ok = self.rookie_sel is not None
        pygame.draw.rect(w, (40, 170, 90) if ok else (60, 76, 70), sign, border_radius=18)
        pygame.draw.rect(w, YELLOW if ok and sign.collidepoint(mouse) else WHITE, sign, 5, border_radius=18)
        txt = "SIGN %s" % self.cards[self.rookie_sel]["name"].split()[-1].upper() if ok else "PICK ONE"
        lab = self.label(txt, sign.w - 40, WHITE if ok else (170, 190, 180), self.font_m)
        w.blit(lab, lab.get_rect(center=sign.center))

    # ================================================================ PRACTICE: spawn robot CPUs
    def start_practice(self):
        if getattr(self, "_match_cpu", None) is None:
            self._match_cpu = (self.cpu, self.brain)       # the normal CPU, parked while we practise
        self.mode = "practice"
        self.practice = {"goals": {"home": 0, "away": 0}, "reset_t": 0.0, "flash": "home", "next_id": 1}
        self.robots = []
        squad = [self.cards[k] for k in self.save["squad"] if k in self.cards]
        self.my_card = squad[0] if squad else None
        self.player.set_stats(self.upgraded(self.my_card))
        self.sync_robots()
        self.new_match()
        self.add_robot("MEDIUM")
        self.quit_prompt = False
        self.paused = False

    def end_practice(self):
        if getattr(self, "_match_cpu", None) is not None:
            self.cpu, self.brain = self._match_cpu
            self._match_cpu = None
        self.robots = []
        self.cpu.reset_to(WIDTH * 0.5 + 430)
        self.brain.skill = DIFFICULTY[self.difficulty][1]
        self.brain.impossible = self.difficulty == IMPOSSIBLE
        self.mode = "wc"
        self.quit_prompt = False
        self.paused = False
        self.dragging = False
        self.slowmo = 1.0
        self.state = TITLE
        self.menu_page = "play"

    def robot_look(self, mode):
        key = mode.lower()
        cache = self.__dict__.setdefault("_robot_looks", {})
        if key not in cache:
            look = {}
            for piece in ("head", "torso", "arm", "leg"):
                size, fit = PIECE_SIZE[piece]
                look[piece] = load_pixel("ROBOT_%s_%s" % (key, piece), size, fit=fit, quiet=True)
            cache[key] = look
        return cache[key]

    def sync_robots(self):
        """Robot 1 doubles as `self.cpu` (so abilities have a defender to beat).
        With no robots the normal CPU is parked far off the pitch."""
        if self.robots:
            self.cpu, self.brain = self.robots[0]["doll"], self.robots[0]["brain"]
        else:
            self.cpu, self.brain = self._match_cpu
            self.cpu.pos.update(-4000, GROUND_Y - 100)
            self.cpu.vel.update(0, 0)

    def add_robot(self, mode="MEDIUM"):
        if len(self.robots) >= ROBOT_MAX:
            self.toast("MAX %d ROBOTS" % ROBOT_MAX, (255, 150, 150))
            return None
        n = len(self.robots)
        doll = Player(WIDTH * 0.5 + 260 + n * 150, -1, AWAY_KIT)
        doll.pos.y = 260                                   # dropped in from the sky
        brain = Brain(doll, -1, 0.72, opponent=self.player)
        bot = {"doll": doll, "brain": brain, "mode": mode, "id": self.practice["next_id"]}
        self.practice["next_id"] += 1
        self.robots.append(bot)
        self.set_robot_mode(bot, mode)
        self.sync_robots()
        return bot

    def set_robot_mode(self, bot, mode):
        rating, skill = ROBOT_STATS[mode]
        bot["mode"] = mode
        bot["doll"].set_stats({"rating": rating, "sho": rating, "str": rating})
        bot["brain"].skill = skill
        bot["doll"].set_look(self.robot_look(mode))

    def cycle_robot(self, bot):
        self.set_robot_mode(bot, ROBOT_MODES[(ROBOT_MODES.index(bot["mode"]) + 1) % len(ROBOT_MODES)])

    def remove_robot(self, bot):
        if bot in self.robots:
            self.robots.remove(bot)
            self.sync_robots()

    def clear_robots(self):
        self.robots = []
        self.sync_robots()

    def place_robots(self):
        for i, bot in enumerate(self.robots):
            bot["doll"].reset_to(WIDTH * 0.5 + 300 + i * 150)

    def practice_reset_ball(self):
        self.ball.reset(WIDTH * 0.5, 220, frozen=False)
        self.ball.vel.update(random.uniform(-160, 160), 120.0)
        self.ball.home_ghost_t = 0.0
        self.practice["reset_t"] = 0.0
        self.last_touch = None

    def practice_squad(self):
        return [self.cards[k] for k in self.save["squad"] if k in self.cards]

    def practice_next_player(self):
        squad = self.practice_squad()
        if not squad:
            self.toast("PICK YOUR SQUAD IN TEAM FIRST", (255, 150, 150))
            return
        i = squad.index(self.my_card) + 1 if self.my_card in squad else 0
        self.my_card = squad[i % len(squad)]
        self.player.set_stats(self.upgraded(self.my_card))
        self.ren.reset_match()
        self.apply_looks()

    def practice_step(self, h):
        dolls = [b["doll"] for b in self.robots]
        self.player.step(h, self.segments, self.sfx, self.particles)
        for d in dolls:
            d.step(h, self.segments, self.sfx, self.particles)
        self.ball.step(h, self.segments, self.sfx, self.particles)
        prev, v0 = self.last_touch, Vector2(self.ball.vel)
        if self.ball.home_ghost_t <= 0.0 and \
                ball_vs_player(self.ball, self.player, self.sfx, self.particles, self.on_big_hit):
            self.last_touch = "home"
            self.ren.on_touch((self.ball.vel - v0).length(), prev)
            if self.tut is not None:
                self.tut["touches"] += 1
        if self.ball.ghost_t <= 0.0:
            for d in dolls:
                if ball_vs_player(self.ball, d, self.sfx, self.particles, self.on_big_hit):
                    self.last_touch = "away"
        for d in dolls:
            player_vs_player(self.player, d, self.sfx, self.ball)
        for i in range(len(dolls)):
            for j in range(i + 1, len(dolls)):
                player_vs_player(dolls[i], dolls[j], self.sfx, self.ball)
        if self.state == PLAY and self.practice["reset_t"] <= 0.0:
            self.check_goal()

    def practice_layout(self):
        L = {"exit": pygame.Rect(24, 18, 170, 62), "player": pygame.Rect(206, 18, 400, 62),
             "ball": pygame.Rect(618, 18, 230, 62), "clear": pygame.Rect(860, 18, 230, 62),
             "add": pygame.Rect(1102, 18, 290, 62), "bots": []}
        for i, bot in enumerate(self.robots):
            chip = pygame.Rect(24 + i * 390, 92, 310, 56)
            L["bots"].append((bot, chip, pygame.Rect(chip.right + 8, 92, 56, 56)))
        return L

    def practice_click(self, pos):
        """Clicks on the practice panel (they never start a throw)."""
        L = self.practice_layout()
        if L["exit"].collidepoint(pos):
            self.end_practice()
        elif L["player"].collidepoint(pos):
            self.practice_next_player()
        elif L["ball"].collidepoint(pos):
            self.practice_reset_ball()
        elif L["clear"].collidepoint(pos):
            self.clear_robots()
        elif L["add"].collidepoint(pos):
            self.add_robot("MEDIUM")
        else:
            for bot, chip, x in L["bots"]:
                if x.collidepoint(pos):
                    self.remove_robot(bot)
                    return True
                if chip.collidepoint(pos):
                    self.cycle_robot(bot)
                    return True
            return False
        return True

    def draw_practice_ui(self, w):
        L = self.practice_layout()
        mouse = pygame.mouse.get_pos()
        name = self.my_card["name"].upper() if self.my_card else "YOU"
        for key, txt, col in (("exit", "< EXIT", (150, 40, 50)), ("player", "PLAYER: %s  >" % name, (40, 90, 170)),
                              ("ball", "RESET BALL", SELECT_GREEN), ("clear", "CLEAR ROBOTS", (90, 70, 40)),
                              ("add", "+ ADD ROBOT  (%d/%d)" % (len(self.robots), ROBOT_MAX),
                               (60, 60, 76) if len(self.robots) >= ROBOT_MAX else (70, 110, 190))):
            r = L[key]
            pygame.draw.rect(w, col, r, border_radius=14)
            pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else WHITE, r, 3, border_radius=14)
            lab = self.label(txt, r.w - 24, WHITE)
            w.blit(lab, lab.get_rect(center=r.center))
        for i, (bot, chip, x) in enumerate(L["bots"]):
            light = ROBOT_LIGHT[bot["mode"]]
            pygame.draw.rect(w, (26, 30, 40), chip, border_radius=12)
            pygame.draw.rect(w, light, chip, 3, border_radius=12)
            pygame.draw.circle(w, light, (chip.x + 30, chip.centery), 11)
            lab = self.label("ROBOT %d:  %s" % (i + 1, bot["mode"]), chip.w - 70, WHITE)
            w.blit(lab, lab.get_rect(midleft=(chip.x + 52, chip.centery)))
            pygame.draw.rect(w, (150, 40, 50), x, border_radius=12)
            pygame.draw.rect(w, YELLOW if x.collidepoint(mouse) else WHITE, x, 3, border_radius=12)
            self.centre_in(w, "X", x)
        if not self.robots:
            hint = self.label("NO ROBOTS - ADD ONE, OR PRACTISE YOUR SHOTS ON YOUR OWN", 900, (220, 226, 236))
            w.blit(hint, hint.get_rect(midleft=(28, 120)))
        g = self.practice["goals"]
        score = self.label("YOU %d  -  %d ROBOTS" % (g["home"], g["away"]), 400, WHITE, self.font_m)
        pad = pygame.Rect(0, 0, score.get_width() + 36, 70)
        pad.topright = (WIDTH - 20, 14)
        pygame.draw.rect(w, (10, 14, 24), pad, border_radius=14)
        w.blit(score, score.get_rect(center=pad.center))
        tip = self.label("CLICK A ROBOT TO CHANGE ITS LEVEL:  EASY - MEDIUM - HARD - DUMMY", 900, (200, 206, 220))
        if self.robots:
            w.blit(tip, tip.get_rect(midleft=(30, 172)))
        self.draw_practice_flash(w)

    def draw_practice_flash(self, w):
        if self.practice["reset_t"] > 0.0:                    # quick GOAL! flash, then the ball comes back
            k = clamp((PRACTICE_RESET - self.practice["reset_t"]) * 5.0, 0.0, 1.0)
            col = HOME_KIT["shirt"] if self.practice["flash"] == "home" else AWAY_KIT["shirt"]
            txt = self.outlined("GOAL!", self.font_xl, col, 0.6 + 0.4 * k, INK, 6)
            w.blit(txt, txt.get_rect(center=(WIDTH // 2, int(HEIGHT * 0.34))))

    # ================================================================ FREEPLAY: any player you own
    def open_freeplay(self):
        owned = self.owned_cards()
        if not owned:
            self.toast("YOU DON'T OWN ANY PLAYERS YET", (255, 150, 150))
            return
        f = self.__dict__.setdefault("free", {"me": None, "opp": None, "slot": "me", "page": 0, "diff": 1})
        if f["me"] not in self.save["owned"]:
            f["me"] = owned[0]["id"]
        if f["opp"] not in self.save["owned"]:
            f["opp"] = random.choice(owned)["id"]
        f["page"] %= self.free_pages()
        self.state = FREE_SELECT

    def free_pages(self):
        return max(1, math.ceil(len(self.owned_cards()) / FREE_PER_PAGE))

    def free_layout(self):
        f = self.free
        L = {"me": pygame.Rect(84, 236, 206, 286), "opp": pygame.Rect(392, 236, 206, 286),
             "diff": [pygame.Rect(70 + i * 184, 648, 172, 64) for i in range(3)],
             "random": pygame.Rect(70, 736, 540, 70), "play": pygame.Rect(70, 916, 540, 116),
             "prev": pygame.Rect(670, 990, 110, 64), "next": pygame.Rect(1768, 990, 110, 64), "grid": []}
        owned = self.owned_cards()
        page = owned[f["page"] * FREE_PER_PAGE:(f["page"] + 1) * FREE_PER_PAGE]
        for i, c in enumerate(page):
            r, k = divmod(i, 7)
            L["grid"].append((c, pygame.Rect(670 + k * 174, 196 + r * 262, 156, 216)))
        return L

    def free_click(self, pos):
        f = self.free
        L = self.free_layout()
        if pygame.Rect(40, 30, 200, 70).collidepoint(pos.x, pos.y):
            self.state = TITLE
            self.menu_page = "play"
            return
        for key in ("me", "opp"):
            if L[key].collidepoint(pos.x, pos.y):
                if f["slot"] == key:
                    self.card_detail = self.cards[f[key]]
                    self.card_tab = 0
                f["slot"] = key
                return
        for i, r in enumerate(L["diff"]):
            if r.collidepoint(pos.x, pos.y):
                f["diff"] = i
                return
        if L["random"].collidepoint(pos.x, pos.y):
            f["opp"] = random.choice(self.owned_cards())["id"]
            return
        if L["play"].collidepoint(pos.x, pos.y):
            self.start_freeplay()
            return
        if L["prev"].collidepoint(pos.x, pos.y) or L["next"].collidepoint(pos.x, pos.y):
            step = -1 if L["prev"].collidepoint(pos.x, pos.y) else 1
            f["page"] = (f["page"] + step) % self.free_pages()
            return
        now = pygame.time.get_ticks() / 1000.0
        for c, r in L["grid"]:
            if r.collidepoint(pos.x, pos.y):
                last = getattr(self, "free_click_t", (None, -9.0))
                if last[0] == c["id"] and now - last[1] < DOUBLE_CLICK:
                    self.card_detail = c                       # double-click: stats
                    self.card_tab = 0
                    return
                self.free_click_t = (c["id"], now)
                f[f["slot"]] = c["id"]
                if f["slot"] == "me":
                    f["slot"] = "opp"                          # next pick is the opponent
                return

    def start_freeplay(self):
        f = self.free
        me, opp = self.cards.get(f["me"]), self.cards.get(f["opp"])
        if me is None or opp is None:
            return
        self.mode = "free"
        self.my_card, self.cpu_card = me, opp
        self.player.set_stats(self.upgraded(me))
        self.cpu.set_stats(opp)
        self.brain.skill = DIFFICULTY[f["diff"]][1]
        self.brain.impossible = False
        self.played_this_match = set()
        self.last_earned = 0
        self.last_xp = 0
        self.new_match()
        self.start_versus()

    # ---- online player vs player ---------------------------------
    def start_pvp(self, info):
        """The page found an opponent: set the match up and kick off."""
        me = self.cards.get(info.get("card")) or (self.owned_cards() or [None])[0]
        opp = self.cards.get(info.get("oppCard")) or me
        if me is None:
            return
        self.pvp = {"role": info.get("role", "host"), "name": info.get("name", "YOU"),
                    "opp": info.get("oppName", "RIVAL"), "ranked": bool(info.get("ranked", True)),
                    "rank": info.get("rank", ""), "oppRank": info.get("oppRank", ""),
                    "sent": 0, "got": 0, "last": 0.0}
        self.mode = "pvp"
        self.my_card, self.cpu_card = me, opp
        self.player.set_stats(me)
        self.cpu.set_stats(opp)
        self.played_this_match = set()
        self.last_earned = self.last_xp = 0
        self.chat_log = []
        self.net_t = 0.0
        self.opp_squad = getattr(self, "early_squad", None) or [opp["id"]]
        self.early_squad = None
        self.new_match()
        self.net.send({"t": "squad", "ids": [c["id"] for c in self.lineup_cards()]})   # for their team sheet
        self.start_versus()
        self.toast("MATCH FOUND  -  %s" % self.pvp["opp"].upper(), CYAN)

    def find_online(self):
        """Ask the page to look for an opponent. It sends back a start message."""
        if not self.net.on:
            self.toast("ONLINE ONLY WORKS ON THE WEBSITE", (255, 150, 150))
            return
        owned = self.owned_cards()
        if not owned:
            self.toast("YOU DON'T OWN ANY PLAYERS YET", (255, 150, 150))
            return
        squad = [c for c in owned if c["id"] in self.save["squad"]] or owned
        best = max(squad, key=lambda c: c["rating"])
        self.searching = {"t": 0.0, "card": best["id"]}
        self.net.send({"t": "find", "ranked": True, "card": best["id"]})
        self.toast("LOOKING FOR AN OPPONENT...", CYAN)

    def cancel_search(self):
        if getattr(self, "searching", None):
            self.net.send({"t": "cancel"})
            self.searching = None
            self.toast("SEARCH CANCELLED", WHITE)

    def pvp_host(self):
        return self.pvp is not None and self.pvp["role"] == "host"

    def leave_pvp(self, why=None):
        self.pvp = None
        self.sub = None
        self.mode = "free"
        self.quit_prompt = False
        self.paused = False
        self.versus = None
        self.slowmo = 1.0
        self.dragging = False
        self.brain.skill = DIFFICULTY[self.difficulty][1]
        self.state = TITLE
        self.menu_page = "play"
        if why:
            self.toast(why, (255, 150, 150))

    def net_pump(self, dt):
        """Read whatever the page has for us, then (as host) send the world back."""
        for msg in self.net.poll():
            kind = msg.get("t")
            if kind == "start":
                self.searching = None
                self.start_pvp(msg)
            elif kind == "searching":
                self.searching = {"t": 0.0, "card": None}
            elif kind == "nomatch":
                self.searching = None
                self.toast(msg.get("why", "NOBODY AROUND RIGHT NOW"), (255, 150, 150))
            elif kind == "chat":
                self.chat_log.append([msg.get("from", "?"), msg.get("text", ""), 0.0])
                del self.chat_log[:-12]
            elif kind == "left" and self.pvp is not None:
                self.finish_pvp(walkover=True)
            elif kind == "snap" and self.pvp is not None and not self.pvp_host():
                self.apply_snapshot(msg)
            elif kind == "input" and self.pvp is not None and self.pvp_host():
                self.apply_remote_throw(msg)
            elif kind == "squad":                          # the rival's bench, for the team sheet
                ids = [k for k in msg.get("ids", ()) if k in self.cards][:SHEET_SIZE["pvp"]]
                if self.pvp is not None:
                    self.opp_squad = ids or self.opp_squad
                else:
                    self.early_squad = ids                 # it beat our own start message
            elif kind == "half" and self.pvp is not None and not self.pvp_host():
                if getattr(self, "sub", None) is None:
                    self.start_sub()                       # the host blew for half time
            elif kind == "sub" and self.pvp is not None and self.pvp_host():
                self.got_remote_sub(msg)
            elif kind == "subgo" and self.pvp is not None and not self.pvp_host():
                self.got_subgo(msg)
        if self.searching:
            self.searching["t"] += dt
        for line in self.chat_log:
            line[2] += dt
        self.chat_log = [c for c in self.chat_log if c[2] < CHAT_SECONDS]

        if self.pvp is not None and self.pvp_host() and self.state in (KICKOFF, PLAY, GOAL, FULLTIME):
            self.net_t -= dt
            if self.net_t <= 0.0:
                self.net_t = 1.0 / NET_SNAP_HZ
                self.send_snapshot()

    def doll_state(self, d):
        return [round(d.pos.x, 1), round(d.pos.y, 1), round(d.vel.x, 1), round(d.vel.y, 1),
                round(d.angle, 3), round(d.av, 3)]

    def send_snapshot(self):
        b = self.ball
        self.net.send({
            "t": "snap",
            "p": self.doll_state(self.player), "c": self.doll_state(self.cpu),
            "b": [round(b.pos.x, 1), round(b.pos.y, 1), round(b.vel.x, 1), round(b.vel.y, 1),
                  round(b.spin, 1), 1 if b.frozen else 0],
            "s": [self.score_home, self.score_away],
            "k": round(self.match_time, 2), "h": self.half, "st": self.state,
        })

    def apply_doll(self, d, v, pull):
        if not v or len(v) < 6:
            return
        d.pos.x += (v[0] - d.pos.x) * pull
        d.pos.y += (v[1] - d.pos.y) * pull
        d.vel.update(v[2], v[3])
        d.angle += (v[4] - d.angle) * pull
        d.av = v[5]

    @staticmethod
    def flip_doll(v):
        """Host coordinates -> guest coordinates. Both players see themselves on the left."""
        if not v or len(v) < 6:
            return v
        return [WIDTH - v[0], v[1], -v[2], v[3], -v[4], -v[5]]

    def apply_snapshot(self, msg):
        """Guest: the host's world is the real one - slide onto it rather than snapping.
        Everything is mirrored, so the guest's own doll is always the one on the left."""
        pull = NET_LERP
        self.apply_doll(self.player, self.flip_doll(msg.get("c")), pull)   # mine = host's away doll
        self.apply_doll(self.cpu, self.flip_doll(msg.get("p")), pull)
        b = msg.get("b")
        if b and len(b) >= 6:
            self.ball.pos.x += ((WIDTH - b[0]) - self.ball.pos.x) * pull
            self.ball.pos.y += (b[1] - self.ball.pos.y) * pull
            self.ball.vel.update(-b[2], b[3])
            self.ball.spin = -b[4]
            self.ball.frozen = bool(b[5])
        sc = msg.get("s")
        if sc and len(sc) == 2:
            sc = [sc[1], sc[0]]                                            # their goals are my goals conceded
            if sc[0] > self.score_home or sc[1] > self.score_away:
                self.goal_text_pop = 0.0
                self.sfx.play("cheer", 0.6)
            self.score_home, self.score_away = sc[0], sc[1]
        self.match_time = msg.get("k", self.match_time)
        self.half = msg.get("h", self.half)
        st = msg.get("st")
        if st in (KICKOFF, PLAY, GOAL, FULLTIME) and getattr(self, "sub", None) is not None:
            self.sub = None                                 # the host has kicked off the 2nd half
            self.apply_looks()
        if st in (KICKOFF, PLAY, GOAL, FULLTIME) and st != self.state:
            self.state = st
            if st == FULLTIME:
                self.finish_pvp()

    def apply_remote_throw(self, msg):
        """Host: the guest let go somewhere - throw their doll at it."""
        target = Vector2(msg.get("x", 0.0), msg.get("y", 0.0))
        launch = target - self.cpu.pos
        if launch.length() > 1.0:
            self.cpu.throw(launch, self.throw_power_for(self.cpu, launch), self.sfx, self.particles)

    def throw_power_for(self, doll, launch):
        return lerp(THROW_MIN, doll.max_power(), clamp(launch.length() / doll.drag_range(), 0.0, 1.0))

    def send_chat(self, text):
        self.net.chat(text)
        self.chat_log.append([self.pvp["name"] if self.pvp else "YOU", text, 0.0])
        del self.chat_log[:-12]

    def finish_pvp(self, walkover=False):
        """Full time online: the host is the one who reports the score."""
        if self.pvp is None:
            return
        if walkover:
            self.score_home = max(self.score_home, self.score_away + 1)
            self.toast("OPPONENT LEFT  -  YOU WIN", YELLOW)
        self.net.result(self.score_home, self.score_away)   # both sides see themselves as home
        self.state = FULLTIME
        self.pvp["done"] = True

    def leave_freeplay(self):
        self.brain.skill = DIFFICULTY[self.difficulty][1]
        self.brain.impossible = self.difficulty == IMPOSSIBLE
        self.quit_prompt = False
        self.paused = False
        self.versus = None
        self.slowmo = 1.0
        self.dragging = False
        self.open_freeplay()

    def draw_freeplay(self, w):
        w.blit(self.shop_bg or self.select_bg, (0, 0))
        self.draw_back_button(w)
        self.draw_coins(w)
        f = self.free
        L = self.free_layout()
        mouse = pygame.mouse.get_pos()
        head = self.outlined("FREEPLAY", self.font_l, WHITE, 0.85, width=5)
        w.blit(head, head.get_rect(center=(760, 64)))
        sub = self.label("PICK YOUR PLAYER, THEN ANY PLAYER YOU OWN AS THE OPPONENT", 1000, (200, 214, 240))
        w.blit(sub, sub.get_rect(center=(820, 140)))
        for key, title in (("me", "YOU"), ("opp", "OPPONENT")):
            r = L[key]
            on = f["slot"] == key
            lab = self.label(title + ("  (PICKING)" if on else ""), r.w + 60, YELLOW if on else WHITE, self.font_s)
            w.blit(lab, lab.get_rect(center=(r.centerx, r.y - 44)))
            self.blit_card(w, self.cards[f[key]], r, glow=on)
        vs = self.outlined("VS", self.font_m, YELLOW, 1.0, INK, 4)
        w.blit(vs, vs.get_rect(center=(341, L["me"].centery)))
        w.blit(self.label("CPU DIFFICULTY", 540, (200, 214, 240)), (70, 604))
        for i, r in enumerate(L["diff"]):
            on = f["diff"] == i
            pygame.draw.rect(w, (40, 150, 70) if on else (30, 50, 90), r, border_radius=12)
            pygame.draw.rect(w, YELLOW if on or r.collidepoint(mouse) else WHITE, r, 3, border_radius=12)
            lab = self.label(DIFFICULTY[i][0], r.w - 20, WHITE)
            w.blit(lab, lab.get_rect(center=r.center))
        for key, txt, col in (("random", "RANDOM OPPONENT", (60, 70, 130)), ("play", "PLAY", (40, 170, 70))):
            r = L[key]
            pygame.draw.rect(w, col, r, border_radius=16)
            pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else WHITE, r, 5, border_radius=16)
            lab = self.label(txt, r.w - 40, WHITE, self.font_l if key == "play" else self.font_m)
            w.blit(lab, lab.get_rect(center=r.center))
        note = self.label("REWARD: RANDOM %d-%d COINS  -  NO STAMINA USED" % FREE_REWARD, 540, YELLOW)
        w.blit(note, note.get_rect(center=(340, 856)))
        for c, r in L["grid"]:
            picked = c["id"] in (f["me"], f["opp"])
            self.blit_card(w, c, r, count=self.save["owned"].get(c["id"], 0),
                           glow=r.collidepoint(mouse) or picked)
        for key, txt in (("prev", "<"), ("next", ">")):
            pygame.draw.rect(w, (30, 50, 90), L[key], border_radius=12)
            pygame.draw.rect(w, YELLOW if L[key].collidepoint(mouse) else WHITE, L[key], 3, border_radius=12)
            self.centre_in(w, txt, L[key])
        pg = self.label("PAGE %d / %d  -  %d PLAYERS  -  DOUBLE-CLICK FOR STATS"
                        % (f["page"] + 1, self.free_pages(), len(self.owned_cards())), 900, (200, 214, 240))
        w.blit(pg, pg.get_rect(center=(1274, 1022)))

    # ================================================================ OPEN 10 PACKS AT ONCE
    def buy_pack10(self, pack):
        if not self.pack_on_sale(pack):
            self.draft_rotated_out(pack)
            return False
        cost = PACK_PRICE * MULTI_PACKS
        if self.save["coins"] < cost:
            self.toast("OPEN 10x NEEDS %s COINS" % self.fmt(cost), (255, 150, 150))
            return False
        self.save["coins"] -= cost
        self.quest_event("pack", MULTI_PACKS)             # daily + weekly quests (1 Nov)
        before = set(self.save["owned"])
        cards, new, seen = [], [], set()
        for _ in range(MULTI_PACKS):
            c = self.roll_pack(pack)                       # pity counts every single pack
            self.give_card(c)
            cards.append(c)
            new.append(c["id"] not in before and c["id"] not in seen)
            seen.add(c["id"])
        rank = {"A": 2, "B": 1, "C": 0}
        best_i = max(range(len(cards)), key=lambda i: (rank[self.card_pool(cards[i])], cards[i]["rating"]))
        best = cards[best_i]
        self.pack_reveal = {"card": best, "t": 0.0, "count": 1 if new[best_i] else self.save["owned"][best["id"]],
                            "pack": pack, "tier": self.card_pool(best), "opened": False,
                            "multi": {"cards": cards, "new": new, "pack": pack, "best": best_i}}
        self.fx = []
        self.state = PACK_OPEN
        self.write_save()
        return True

    def open_multi(self, m):
        self.multi = dict(m, t=0.0, boom=set())
        self.state = PACK_MULTI

    MULTI_FLIP_AT, MULTI_FLIP_GAP, MULTI_FLIP_LEN = 0.35, 0.2, 0.3

    def multi_done_at(self):
        return self.MULTI_FLIP_AT + (MULTI_PACKS - 1) * self.MULTI_FLIP_GAP + self.MULTI_FLIP_LEN

    def multi_layout(self):
        rects = []
        for i in range(len(self.multi["cards"])):
            r, k = divmod(i, 5)
            rects.append(pygame.Rect(305 + k * 270, 214 + r * 356, 230, 316))
        return rects, pygame.Rect(540, 930, 500, 100), pygame.Rect(1080, 930, 300, 100)

    def multi_click(self, pos):
        m = self.multi
        if m["t"] < self.multi_done_at():
            m["t"] = self.multi_done_at()                    # skip the flips
            return
        rects, again, done = self.multi_layout()
        for c, r in zip(m["cards"], rects):
            if r.collidepoint(pos.x, pos.y):
                self.card_detail = c
                self.card_tab = 0
                return
        if again.collidepoint(pos.x, pos.y):
            self.buy_pack10(m["pack"])
            return
        self.open_packs(m["pack"])

    def draw_multi(self, w):
        m = self.multi
        w.blit(self.shop_bg or self.select_bg, (0, 0))
        self.draw_coins(w)
        n_new = sum(m["new"])
        head = self.outlined("%d PACKS OPENED" % len(m["cards"]), self.font_l, WHITE, 0.8, width=5)
        w.blit(head, head.get_rect(center=(WIDTH // 2, 58)))
        best = m["cards"][m["best"]]
        sub = self.label("%d NEW   -   BEST: %s %d" % (n_new, best["name"].upper(), best["rating"]), 1100,
                         (200, 214, 240))
        w.blit(sub, sub.get_rect(center=(WIDTH // 2, 124)))
        rects, again, done = self.multi_layout()
        mouse = pygame.mouse.get_pos()
        for i, (c, r) in enumerate(zip(m["cards"], rects)):
            p = (m["t"] - self.MULTI_FLIP_AT - i * self.MULTI_FLIP_GAP) / self.MULTI_FLIP_LEN
            front = p >= 0.5
            sx = abs(1.0 - 2.0 * clamp(p, 0.0, 1.0)) if 0.0 < p < 1.0 else 1.0
            if front and i not in m["boom"]:
                m["boom"].add(i)
                pool = self.card_pool(c)
                if pool in ("A", "B"):
                    self.burst_fireworks(r.centerx, r.centery, self.POOL_GLOW[pool], 50 if pool == "A" else 22)
            if front:
                split = sx >= 1.0 and self.blit_live_under(w, c, r, False, self.MULTI_PAD, draw=False)
                tmp = self.card_face(c, r.size, pad=self.MULTI_PAD, split=split)
                lit = self.card_pool(c) == "A" or (p >= 1 and r.collidepoint(mouse))
            else:
                tmp = self.card_back_face(r.size, self.MULTI_PAD)
                lit = False
            if sx < 1.0:                                   # mid-flip: squeeze the kept picture
                width = max(6, int(tmp.get_width() * sx)) // 6 * 6
                tmp = scaled(tmp, (width, tmp.get_height()))
            elif lit:
                t = pygame.time.get_ticks() * 0.001
                pulse = int(10 + 6 * (0.5 + 0.5 * math.sin(t * 3)))
                pygame.draw.rect(w, YELLOW, r.inflate(pulse, pulse), border_radius=16)
            if front and split:                            # the waving flag / the lightning, under the face
                self.blit_live_under(w, c, r, False, self.MULTI_PAD)
            w.blit(tmp, tmp.get_rect(center=r.center))
            if front and split:
                self.live_over(w, self.card_template_key(self.upgraded(c)), r, c)
            if front and p >= 1.0 and m["new"][i]:
                tag = pygame.Rect(0, 0, 110, 40)
                tag.midbottom = (r.centerx, r.y - 4)
                pygame.draw.rect(w, (220, 40, 60), tag, border_radius=10)
                self.centre_in(w, "NEW", tag)
        self.draw_fx(w, 1.0 / FPS)
        if m["t"] >= self.multi_done_at():
            can = self.save["coins"] >= PACK_PRICE * MULTI_PACKS
            for r, txt, col in ((again, "OPEN 10 MORE  %s" % self.fmt(PACK_PRICE * MULTI_PACKS),
                                 (40, 170, 70) if can else (70, 90, 72)), (done, "CONTINUE", (40, 80, 170))):
                pygame.draw.rect(w, col, r, border_radius=16)
                pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else WHITE, r, 5, border_radius=16)
                lab = self.label(txt, r.w - 40, WHITE, self.font_m)
                w.blit(lab, lab.get_rect(center=r.center))
            self.centre_text(w, "CLICK A CARD FOR ITS STATS", self.font_s, (200, 214, 240), 1044)
        else:
            self.centre_text(w, "CLICK TO SKIP", self.font_s, (170, 176, 190), 1000)
        self.draw_back_button(w)

    # ================================================================ STORE: packs, Star Signing, exchange

    def open_store(self):
        self.store_confirm = None
        self.state = STORE

    def star_points(self):
        return int(self.save.get("star_points", 0))

    @staticmethod
    def fmt(n):
        return "{:,}".format(int(n))

    def draw_sp_icon(self, w, centre, r=20):
        cache = self.__dict__.setdefault("_sp_icons", {})
        img = cache.get(r)
        if img is None:
            img = pygame.Surface((2 * r + 2, 2 * r + 2), pygame.SRCALPHA)
            self.draw_sp_icon_raw(img, (r + 1, r + 1), r)
            cache[r] = img
        w.blit(img, (int(centre[0]) - r - 1, int(centre[1]) - r - 1))

    def draw_sp_icon_raw(self, w, centre, r=20):
        x, y = int(centre[0]), int(centre[1])
        pygame.draw.circle(w, (96, 34, 170), (x, y), r)
        pygame.draw.circle(w, STAR_LILAC, (x, y), r, max(2, r // 6))
        pts = []
        for k in range(10):
            a = -math.pi / 2 + k * math.pi / 5
            rad = r * (0.72 if k % 2 == 0 else 0.3)
            pts.append((x + math.cos(a) * rad, y + math.sin(a) * rad))
        pygame.draw.polygon(w, WHITE, pts)

    def draw_star_points(self, w, y=112):
        t = self.font_m.render("%s SP" % self.fmt(self.star_points()), True, STAR_LILAC)
        w.blit(t, (WIDTH - 60 - t.get_width(), y))
        self.draw_sp_icon(w, (WIDTH - 60 - t.get_width() - 30, y + 24), 20)

    def draw_purple_bg(self, w):
        if self.star_bg is not None:
            w.blit(self.star_bg, (0, 0))
        else:
            w.fill((30, 10, 60))

    # ---- store hub ---------------------------------------------------------
    STORE_TILES = (("packs", "PACKS", "300 COINS EACH"), ("stars", "STAR SIGNINGS", "ANY PLAYER FOR STAR POINTS"),
                   ("exchange", "RELEASE PLAYERS", "PLAYERS FOR STAR POINTS"), ("box", "GAME BOXES", "13 DRAWS"))

    def store_layout(self):
        w, h, gap = 400, 560, 40
        x0 = (WIDTH - (4 * w + 3 * gap)) // 2
        return [pygame.Rect(x0 + i * (w + gap), 230, w, h) for i in range(4)]

    def store_essence_rect(self):
        return pygame.Rect(100, 812, (WIDTH - 220) // 2, 112)

    def store_archive_rect(self):
        return pygame.Rect(120 + (WIDTH - 220) // 2, 812, (WIDTH - 220) // 2, 112)

    def store_click(self, pos):
        if pygame.Rect(40, 30, 200, 70).collidepoint(pos.x, pos.y):
            self.state = TITLE
            return
        if self.store_essence_rect().collidepoint(pos.x, pos.y):
            self.open_essence()
            return
        if self.store_archive_rect().collidepoint(pos.x, pos.y):
            self.open_archive()
            return
        for (key, _t, _s), rect in zip(self.STORE_TILES, self.store_layout()):
            if rect.collidepoint(pos.x, pos.y):
                if key == "packs":
                    self.state = PACKS
                elif key == "stars":
                    self.open_stars()
                elif key == "exchange":
                    self.open_stars("mine")                # 1 Nov: MY PLAYERS in Star Signings
                else:
                    self.open_event()
                return

