        self.draw_essence_icon(w, (r.x + 70, r.centery - 2), 34)
        lab = self.label("ESSENCE SHOP", 380, WHITE, self.font_m)
        w.blit(lab, lab.get_rect(midleft=(r.x + 126, r.centery - 18)))
        today = self.wg_today()
        mid = "THE WORLD'S GAME  -  TODAY: %s" % today["name"].upper() if today is not None \
            else "THE WORLD'S GAME  -  COINS  -  STAR POINTS"
        ml = self.label(mid, 500, WG_LILAC, self.font_s)
        ml = scaled_text(ml, 0.8)
        w.blit(ml, ml.get_rect(midleft=(r.x + 128, r.centery + 22)))
        have = self.label("%s ESSENCE" % self.fmt(self.essence()), 240, ESSENCE_HOT, self.font_s)
        w.blit(have, have.get_rect(midright=(r.right - 30, r.centery)))
        # 1 Nov: the Signature Archive, beside it
        ar = self.store_archive_rect()
        hover = ar.collidepoint(mouse)
        r = ar.move(0, -6 if hover else 0)
