        self.draw_sig_token(w, (r.x + 70, r.centery - 2), 34)
        lab = self.label("SIGNATURE ARCHIVE", 420, WHITE, self.font_m)
        w.blit(lab, lab.get_rect(midleft=(r.x + 126, r.centery - 18)))
        q = self.archive_next_quest()
        mid = ("QUEST AT LEVEL %d" % q[1]) if q and not self.archive_quest_open(q) else \
            ("QUEST: %s" % q[2]) if q else "NEW QUEST EVERY %d LEVELS" % ARCHIVE_EVERY
        ml = self.label(mid + "  -  SIGNATURE CARDS", 500, (250, 226, 160), self.font_s)
