    def draw_ss_bar(self, w, bar):
        rows, shown = self.ss_rows()
        S = self.ss()
        pos = S["scroll"] if S["tab"] == "players" else S["mine_scroll"]
        pygame.draw.rect(w, (10, 14, 30), bar, border_radius=7)
        if rows > shown:
            h = max(40, int(bar.h * shown / float(rows)))
            y = bar.y + int((bar.h - h) * pos / float(max(1, rows - shown)))
            pygame.draw.rect(w, self.SS_TEAL, (bar.x, y, bar.w, h), border_radius=7)

