    def owns(self, card):
        return card is not None and self.save["owned"].get(card.get("id"), 0) > 0

    def prog(self, cid, create=False):
        allp = self.save.setdefault("prog", {})
        p = allp.get(cid)
        if p is None and create:
            p = allp[cid] = {"xp": 0, "rank": 0, "skill": {}}
        return p

    def prog_sig(self, card):
        """What a cached card face depends on, progress-wise (None = nothing to show)."""
        if card.get("boosted"):
            return None
        evo = self.wg_stage(card)
        p = self.save.get("prog", {}).get(card.get("id"))
        if not p:
            return ("evo", evo) if evo else None
        return (int(p.get("xp", 0)), int(p.get("rank", 0)), tuple(sorted((p.get("skill") or {}).items())), evo)


    # ---- QUESTS (1 Nov): three dailies, three weeklies, the daily chest ----------------------
    def quest_day(self):
        return today_number() + int(getattr(self, "quest_shift", 0))      # (the checks move the calendar)

    @staticmethod
    def quest_new(key):
        return {"k": key, "n": 0, "done": False, "claimed": False}

    def quests(self):
        """The quest board in your save: new dailies at local midnight, new weeklies on Monday.
        Everyone gets the same quests on the same day (they're seeded by the date)."""
        Q = self.save.get("quests")
        if not isinstance(Q, dict):
            Q = self.save["quests"] = {}
        day = self.quest_day()
        week = (day - 1) // 7                                  # date.toordinal(): day 1 was a Monday
        if Q.get("day") != day or not isinstance(Q.get("daily"), list):
            keys = random.Random(day * 7919).sample([q[0] for q in QUEST_DAILY], QUEST_DAILY_N)
            Q.update(day=day, daily=[self.quest_new(k) for k in keys], rerolled=False, chest=False)
        if Q.get("week") != week or not isinstance(Q.get("weekly"), list):
            rest = random.Random(week * 104729).sample([q[0] for q in QUEST_WEEKLY[1:]], QUEST_WEEKLY_N - 1)
            Q.update(week=week, weekly=[self.quest_new(k) for k in [QUEST_WEEKLY[0][0]] + rest])
        for k in ("daily", "weekly"):                          # (a quest that no longer exists is dropped)
            Q[k] = [q for q in Q[k] if isinstance(q, dict) and q.get("k") in QUEST_DEF]
        return Q

    def quest_event(self, ev, n=1):
        """Something that counts just happened: every open quest that counts it moves on."""
        if getattr(self, "tut", None) is not None or n <= 0:
            return
        Q = self.quests()
        for q in Q["daily"] + Q["weekly"]:
            _key, what, need, text, _rew = QUEST_DEF[q["k"]]
            if what != ev or q["done"]:
                continue
            q["n"] = min(need, int(q["n"]) + n)
            if q["n"] >= need:
                q["done"] = True
                self.toast("QUEST COMPLETE  -  %s" % text, (150, 255, 170), 3.5)
                self.sfx.play("tap", 0.6)

    def quest_match(self, result, gf, ga):
        """A match that counts has finished (settle_match): the match quests move."""
        if self.mode not in WG_EVO_MODES or getattr(self, "forfeited", False):
            return
        self.quest_event("play")
        if ga == 0:
            self.quest_event("clean")
        if result != "win":
            return
        self.quest_event("win")
        if gf - ga >= 3:
            self.quest_event("big")
        if self.mode == "club":
            self.quest_event("club_win")
        elif self.mode == "wc":
            self.quest_event("wc_win")
            if self.impossible_run():
                self.quest_event("imp_win")
        elif self.mode == "gauntlet":
            self.quest_event("gt_win")

    def quest_chest_ready(self):
        Q = self.quests()
        return (not Q.get("chest") and len(Q["daily"]) == QUEST_DAILY_N
                and all(q["claimed"] for q in Q["daily"]))

    def quest_claimable(self):
        """How many things are waiting to be claimed (the red dot on the tab)."""
        Q = self.quests()
        n = sum(1 for q in Q["daily"] + Q["weekly"] if q["done"] and not q["claimed"])
        return n + (1 if self.quest_chest_ready() else 0) + int(self.save.get("free_packs", 0) or 0)

    def give_reward(self, rew):
        S = self.save
        for key, save_key in (("coins", "coins"), ("tp", "training_coins"), ("pz", "puzzle_points"),
                              ("ess", "essence"), ("pack", "free_packs")):
            if rew.get(key):
                S[save_key] = int(S.get(save_key, 0) or 0) + int(rew[key])

    @staticmethod
    def reward_words(rew):
        bits = []
        for key, name, _col in QUEST_REWARD_LOOK:
            v = int(rew.get(key, 0) or 0)
            if v:
                bits.append(name if key == "pack" and v == 1 else "%d %s" % (v, name))
        return "  +  ".join(bits)

    def quest_claim(self, which, i=None):
        """CLAIM: a daily or a weekly (which, i), or the daily chest (which="chest").
        A FREE PACK in the reward opens straight away, into the walkout."""
        Q = self.quests()
        if which == "chest":
            if not self.quest_chest_ready():
                return False
            Q["chest"] = True
            rew, label = QUEST_CHEST, "DAILY CHEST"
        else:
            lst = Q.get(which) or []
            if i is None or not 0 <= i < len(lst) or not lst[i]["done"] or lst[i]["claimed"]:
                return False
            lst[i]["claimed"] = True
            rew, label = QUEST_DEF[lst[i]["k"]][4], QUEST_DEF[lst[i]["k"]][3]
            if which == "daily":
                self.quest_event("daily")                      # the weekly "complete 10 daily quests"
        self.give_reward(rew)
        self.toast("%s  -  %s" % (label, self.reward_words(rew)), YELLOW, 3.0)
        self.sfx.play("cheer", 0.5)
        self.write_save()
        if rew.get("pack"):
            self.quest_open_pack()
        return True

    def quest_open_pack(self):
        """Open one of your free packs: the store's current Champion Draft, full walkout."""
        n = int(self.save.get("free_packs", 0) or 0)
        if n <= 0:
            return False
        pack = self.active_draft()
        if not self.pack_on_sale(pack):
            pack = 0
        self.save["free_packs"] = n - 1
        card = self.roll_pack(pack)
        count = self.give_card(card)
        self.pack_reveal = {"card": card, "t": 0.0, "count": count, "pack": pack,
                            "tier": self.card_pool(card), "opened": False, "back": "quests"}
        self.fx = []
        self.state = PACK_OPEN
        self.write_save()
        return True

    def quest_reroll(self, i):
        """One free reroll a day: swap a daily you haven't finished for another one."""
        Q = self.quests()
        if Q.get("rerolled") or not 0 <= i < len(Q["daily"]) or Q["daily"][i]["done"]:
            return False
        have = {q["k"] for q in Q["daily"]}
        pool = [q[0] for q in QUEST_DAILY if q[0] not in have]
        if not pool:
            return False
        Q["daily"][i] = self.quest_new(random.choice(pool))
        Q["rerolled"] = True
        self.sfx.play("tap", 0.5)
        self.write_save()
        return True

    @staticmethod
    def quest_left(weekly=False):
        """Time until the dailies (or the weeklies) are replaced."""
        import datetime
        now = datetime.datetime.now()
        nxt = datetime.datetime.combine(now.date() + datetime.timedelta(days=1), datetime.time())
        secs = (nxt - now).total_seconds() + (86400 * (6 - now.weekday()) if weekly else 0)
        h, m = int(secs // 3600), int(secs % 3600 // 60)
        return ("%dD %dH" % (h // 24, h % 24)) if h >= 24 else ("%dH %02dM" % (h, m))

    def open_quests(self):
        self.quests()
        self.state = QUESTS
        self.dragging = False

    def quests_layout(self):
        L = {"daily": pygame.Rect(40, 136, 900, 916), "weekly": pygame.Rect(980, 136, 900, 916)}
        L["rows"], L["btn"] = {}, {}
        for k in ("daily", "weekly"):
            p = L[k]
            L["rows"][k] = [pygame.Rect(p.x + 24, p.y + 104 + i * 206, p.w - 48, 190) for i in range(3)]
            L["btn"][k] = [pygame.Rect(r.right - 226, r.centery - 34, 200, 68) for r in L["rows"][k]]
        L["chest"] = pygame.Rect(L["daily"].x + 24, L["daily"].y + 104 + 3 * 206, L["daily"].w - 48, 170)
        L["chest_btn"] = pygame.Rect(L["chest"].right - 226, L["chest"].centery - 34, 200, 68)
        L["packs"] = pygame.Rect(L["weekly"].x + 24, L["chest"].y, L["weekly"].w - 48, 170)
        L["pack_btn"] = pygame.Rect(L["packs"].right - 226, L["packs"].centery - 34, 200, 68)
        return L

    def quests_click(self, pos):
        L, Q = self.quests_layout(), self.quests()
        for which in ("daily", "weekly"):
            for i, b in enumerate(L["btn"][which]):
                if i < len(Q[which]) and b.collidepoint(pos.x, pos.y):
                    q = Q[which][i]
                    if q["done"] and not q["claimed"]:
                        self.quest_claim(which, i)
                    elif which == "daily" and not q["done"] and not Q.get("rerolled"):
                        self.quest_reroll(i)
                    return
        if L["chest_btn"].collidepoint(pos.x, pos.y):
            self.quest_claim("chest")
        elif L["pack_btn"].collidepoint(pos.x, pos.y):
            self.quest_open_pack()

    def draw_reward_chips(self, w, rew, x, y, dim=False):
        for key, name, col in QUEST_REWARD_LOOK:
            v = int(rew.get(key, 0) or 0)
            if not v:
                continue
            col = tuple(int(c * 0.55) for c in col) if dim else col
            txt = name if key == "pack" and v == 1 else "+%d %s" % (v, name)
            r = self.home_text(w, txt, (x + 16, y), 22, col, shadow=False)
            pygame.draw.rect(w, col, r.inflate(30, 14).move(-1, 0), 2, border_radius=14)
            x = r.right + 34

    def draw_quest_button(self, w, b, label, mouse, kind="claim"):
        hov = b.collidepoint(mouse)
        if kind == "claim":
            btn = self.home_button(b.size, hov)
            w.blit(btn, (b.x, b.y - (3 if hov else 0)))
            self.home_text(w, label, (b.centerx, b.centery - (3 if hov else 0)), 30, WHITE, anchor="center")
        else:
            self.draw_glass(w, b, radius=22, alpha=170 if hov else 120,
                            edge=self.HOME_GOLD_EDGE if hov else (130, 160, 240))
            self.home_text(w, label, b.center, 24, (255, 226, 150) if hov else (215, 226, 255),
                           anchor="center", shadow=False)

    def draw_quests(self, w):
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        w.blit(self.home_bg(), (0, 0))
        self.draw_glass(w, pygame.Rect(24, 20, WIDTH - 48, 92), radius=24, alpha=120)
        self.draw_glass_back(w, mouse)
        title = self.home_gold("QUESTS", 52)
        w.blit(title, title.get_rect(midleft=(272, 66)))
        self.draw_status(w, mouse)
        L, Q = self.quests_layout(), self.quests()
        for which, name, left, edge in (("daily", "DAILY", self.quest_left(), (120, 200, 255)),
                                        ("weekly", "WEEKLY", self.quest_left(True), (200, 140, 255))):
            p = L[which]
            self.draw_glass(w, p, radius=30, alpha=150, edge=edge)
            self.home_text(w, name, (p.x + 34, p.y + 52), 40, WHITE)
            note = "NEW IN " + left
            if which == "daily":
                note = ("1 FREE REROLL  -  " if not Q.get("rerolled") else "") + note
            self.home_text(w, note, (p.right - 34, p.y + 52), 24, self.HOME_MUTED, anchor="midright",
                           shadow=False)
            for i, r in enumerate(L["rows"][which]):
                if i >= len(Q[which]):
                    break
                q = Q[which][i]
                _k, _ev, need, text, rew = QUEST_DEF[q["k"]]
                ready = q["done"] and not q["claimed"]
                glow = 0.5 + 0.5 * math.sin(t * 4.0) if ready else 0.0
                self.draw_glass(w, r, radius=22, alpha=170 if not q["claimed"] else 90,
                                edge=(110 + int(80 * glow), 230, 140) if ready else
                                ((90, 110, 150) if q["claimed"] else (110, 130, 190)))
                tcol = (150, 160, 185) if q["claimed"] else WHITE
                self.home_text(w, text, (r.x + 28, r.y + 40), 32, tcol, shadow=False, max_w=r.w - 290)
                bar = pygame.Rect(r.x + 28, r.y + 78, r.w - 400, 22)
                pygame.draw.rect(w, (6, 10, 28), bar, border_radius=11)
                k = min(1.0, int(q["n"]) / float(need))
                if k > 0:
                    pygame.draw.rect(w, (90, 220, 130) if q["done"] else edge,
                                     (bar.x, bar.y, max(22, int(bar.w * k)), bar.h), border_radius=11)
                self.home_text(w, "%d / %d" % (int(q["n"]), need), (bar.right + 18, bar.centery), 24,
                               self.HOME_MUTED, shadow=False)
                self.draw_reward_chips(w, rew, r.x + 28, r.y + 148, dim=q["claimed"])
                b = L["btn"][which][i]
                if ready:
                    self.draw_quest_button(w, b, "CLAIM", mouse)
                elif q["claimed"]:
                    self.home_text(w, "CLAIMED", b.center, 28, (120, 220, 150), anchor="center", shadow=False)
                elif which == "daily" and not Q.get("rerolled"):
                    self.draw_quest_button(w, b, "REROLL", mouse, kind="glass")
        # the daily chest: all three dailies claimed
        c = L["chest"]
        ready = self.quest_chest_ready()
        glow = 0.5 + 0.5 * math.sin(t * 4.0) if ready else 0.0
        self.draw_glass(w, c, radius=22, alpha=170, edge=(255, 200 + int(40 * glow), 90) if ready else (110, 130, 190))
        done = sum(1 for q in Q["daily"] if q["claimed"])
        self.home_text(w, "DAILY CHEST", (c.x + 28, c.y + 42), 32, (255, 226, 150) if not Q.get("chest") else (150, 160, 185))
        self.home_text(w, "CLAIM ALL THREE DAILIES  -  %d / %d" % (done, QUEST_DAILY_N), (c.x + 28, c.y + 88), 22,
                       self.HOME_MUTED, shadow=False, max_w=c.w - 290)
        self.draw_reward_chips(w, QUEST_CHEST, c.x + 28, c.y + 132, dim=bool(Q.get("chest")))
        if ready:
            self.draw_quest_button(w, L["chest_btn"], "OPEN", mouse)
        elif Q.get("chest"):
            self.home_text(w, "OPENED", L["chest_btn"].center, 28, (120, 220, 150), anchor="center", shadow=False)
        # free packs waiting (a weekly's reward you didn't open yet)
        pk = L["packs"]
        n = int(self.save.get("free_packs", 0) or 0)
        self.draw_glass(w, pk, radius=22, alpha=170 if n else 100, edge=(255, 130, 140) if n else (110, 130, 190))
        self.home_text(w, "FREE PACKS", (pk.x + 28, pk.y + 42), 32, WHITE if n else (150, 160, 185))
        self.home_text(w, ("%d WAITING  -  THE STORE'S CHAMPION DRAFT" % n) if n else
                       "WEEKLY QUESTS GIVE THEM  -  THEY OPEN HERE", (pk.x + 28, pk.y + 88), 22,
                       self.HOME_MUTED, shadow=False, max_w=pk.w - 290)
        if n:
            self.draw_quest_button(w, L["pack_btn"], "OPEN", mouse)

    # ---- THE WORLD'S GAME evolutions (1 Nov) -------------------------------------------------
    def wg_evo(self, cid):
        """His evolution in your save: {"stage": 0-3, "n": progress on the current quest}."""
        e = self.save.setdefault("wg_evo", {}).setdefault(cid, {"stage": 0, "n": 0})
        e["stage"] = int(clamp(int(e.get("stage", 0)), 0, len(WG_EVO_NAMES) - 1))
        return e

    def wg_stage(self, card):
        """0-3 for a World's Game card you own (a CPU's copy is always the grey one)."""
        if card is None or card.get("design") != "worldsgame" or card.get("boosted"):
            return 0
        if "wg_stage" in card:
            return int(card["wg_stage"])
        if not self.owns(card):
            return 0
        return self.wg_evo(card["id"])["stage"]

    def wg_evo_ovr(self, card, stage):
        """His OVR at a stage: the base, then even steps up to WG_EVO_OVR at the last one."""
        base = self.cards[card["id"]]["rating"] if card.get("id") in self.cards else card["rating"]
        top = len(WG_EVO_NAMES) - 1
        return int(round(base + (max(base, WG_EVO_OVR) - base) * stage / float(top)))

    def wg_evo_event(self, kind, cid):
        """Something he did for you - "goal", "win", "imp_win". Moves his quest on; finishing it
        moves him to the next stage straight away."""
        card = self.cards.get(cid)
        if card is None or card.get("design") != "worldsgame" or not self.owns(card):
            return False
        e = self.wg_evo(cid)
        if e["stage"] >= len(WG_EVO_QUESTS):
            return False
        what, need, _txt = WG_EVO_QUESTS[e["stage"]]
        if kind != what:
            return False
        e["n"] = int(e.get("n", 0)) + 1
        if e["n"] >= need:
            e["stage"] += 1
            e["n"] = 0
            new = self.upgraded(card)
            self.toast("%s EVOLVED!  %s  -  %d OVR" % (card["name"].upper(), WG_EVO_NAMES[e["stage"]], new["rating"]),
                       WG_EVO_AURA[0], 5.0)
            self.sfx.play("cheer", 0.7)
            self.evolved = (cid, e["stage"])               # (for whatever wants to celebrate it)
        return True

    def upgraded(self, card):
        """The card as YOU have it: his gem's overall, his level's and skill points' stats.
        The table's card is never changed, so a CPU sending out the same player plays him
        as he comes out of the pack."""
        if card is None or card.get("boosted") or card.get("prog_view"):
            return card
        evo = self.wg_stage(card)                          # a World's Game card's evolution (1 Nov)
        p = self.save.get("prog", {}).get(card["id"])
        if (not p or not self.owns(card)) and not evo:
            return card
        p = p if (p and self.owns(card)) else {}
        lvl = card_level(p.get("xp", 0))[0]
        rank = int(p.get("rank", 0))
        skill = p.get("skill") or {}
        if lvl <= 1 and rank <= 0 and not any(skill.values()) and not evo:
            return card
        dr = self.wg_evo_ovr(card, evo) - card["rating"] if evo else 0
        add = level_stat_bonus(lvl) + rank + dr
        st = {k: int(clamp(v + add + SKILL_STEP * int(skill.get(k, 0)), STAT_FLOOR, STAT_CEIL))
              for k, v in (card.get("stats") or {}).items()}
        view = dict(card, rating=card["rating"] + rank + dr, stats=st, prog_view=True,
                    fixed_pool=pool_of(card), card_lvl=lvl, gem_rank=rank)
        if evo:                                            # his PlayStyles grow with him
            view["wg_stage"] = evo
            view["ps"] = tuple((ps, WG_EVO_PS[evo][j] if j < 2 else lv) for j, (ps, lv) in enumerate(card["ps"]))
        if "shot" in st and "phys" in st:
            view["sho"], view["str"] = st["shot"], st["phys"]
        return view

    def card_lvl(self, card):
        p = self.prog(card["id"])
        return card_level(p["xp"] if p else 0)

    def xp_to(self, card, level):
        """XP still missing to reach `level`."""
        p = self.prog(card["id"])
        have = int(p["xp"]) if p else 0
        return max(0, sum(LEVEL_XP[:max(1, min(MAX_LEVEL, level)) - 1]) - have)

    def tp_for(self, card, level):
        return -(-self.xp_to(card, level) // XP_PER_TP)

    def train(self, card, levels=1):
        """Spend training points: `levels` more levels, or as many as you can pay for (None)."""
        card = self.cards.get(card["id"], card)
        if not self.owns(card):
            return False
        lvl = self.card_lvl(card)[0]
        if lvl >= MAX_LEVEL:
            self.toast("ALREADY LEVEL %d" % MAX_LEVEL, (200, 210, 230))
            return False
        tp = int(self.save.get("training_coins", 0))
        if levels is None:
            target = lvl
            while target < MAX_LEVEL and self.tp_for(card, target + 1) <= tp:
                target += 1
        else:
            target = min(MAX_LEVEL, lvl + levels)
        cost = self.tp_for(card, target)
        if target <= lvl or cost > tp:
            self.toast("NOT ENOUGH TRAINING POINTS", (255, 140, 120))
            return False
        need = self.xp_to(card, target)
        self.save["training_coins"] = tp - cost
        self.prog(card["id"], True)["xp"] += need
        self.toast("%s  -  LEVEL %d" % (card["name"].upper(), target), (140, 220, 255))
        self.write_save()
        return True

    def feed_list(self, target):
        """[(card, copies that can go)] - squad players and the card being trained keep one."""
        out = []
        squad = self.save["squad"]
        for cid, n in self.save["owned"].items():
            c = self.cards.get(cid)
            if c is None or not self.can_exchange(c):
                continue
            keep = 1 if (cid in squad or cid == target["id"]) else 0
            if n - keep > 0:
                out.append((c, n - keep))
        return sorted(out, key=lambda e: (e[0]["rating"], e[0]["name"]))

    def feed_value(self, donor, target):
        xp = feed_xp(donor)
        if donor["id"] != target["id"] and self.save["owned"].get(donor["id"], 0) == 1:
            p = self.prog(donor["id"])
            if p:
                xp += int(int(p.get("xp", 0)) * FEED_KEEP)
        return xp

    def feed(self, target, donor):
        """Use up one copy of `donor` for XP on `target`. Returns the XP given."""
        target = self.cards.get(target["id"], target)
        donor = self.cards.get(donor["id"], donor)
        if not self.owns(target) or self.card_lvl(target)[0] >= MAX_LEVEL:
            return 0
        if donor["id"] not in [c["id"] for c, _n in self.feed_list(target)]:
            return 0
        xp = self.feed_value(donor, target)
        owned = self.save["owned"]
        owned[donor["id"]] -= 1
        if owned[donor["id"]] <= 0:
            del owned[donor["id"]]
            self.save["stamina"].pop(donor["id"], None)
            self.save.get("prog", {}).pop(donor["id"], None)
        p = self.prog(target["id"], True)
        p["xp"] = min(sum(LEVEL_XP), int(p["xp"]) + xp)
        self.toast("+%d XP  -  %s IS LEVEL %d" % (xp, target["name"].upper(), self.card_lvl(target)[0]),
                   (140, 220, 255))
        self.write_save()
        return xp

    def rank_up(self, card):
        card = self.cards.get(card["id"], card)
        if not self.owns(card):
            return False
        p = self.prog(card["id"], True)
        r = int(p["rank"])
        if r >= len(RANK_COST):
            self.toast("THE GEM IS ALREADY GOLD", PROG_GOLD)
            return False
        cost, pz = RANK_COST[r], int(self.save.get("puzzle_points", 0))
        if pz < cost:
            self.toast("NOT ENOUGH PUZZLE POINTS (%d / %d)" % (pz, cost), (255, 140, 120))
            return False
        self.save["puzzle_points"] = pz - cost
        p["rank"] = r + 1
        name, col = RANKS[r + 1]
        self.toast("%s GEM  -  +1 OVR, +1 SKILL POINT" % name, col)
        self.burst_fireworks(WIDTH // 2, HEIGHT // 2, col, 30)
        self.write_save()
        return True

    def skill_left(self, card):
        p = self.prog(card["id"])
        if not p:
            return 0
        return int(p["rank"]) - sum(int(v) for v in (p.get("skill") or {}).values())

    def skill_up(self, card, key):
        card = self.cards.get(card["id"], card)
        if not self.owns(card) or key not in STAT_KEYS or self.skill_left(card) <= 0:
            return False
        skill = self.prog(card["id"], True).setdefault("skill", {})
        if int(skill.get(key, 0)) >= SKILL_MAX:
            return False
        skill[key] = int(skill.get(key, 0)) + 1
        self.write_save()
        return True

    # ---- the gem at the foot of the card, in its colour
    def draw_rank_gem(self, surf, card, rect):
        rank = int(card.get("gem_rank", 0) or 0)
        if rank <= 0:
            return
        col = RANKS[min(rank, len(RANKS) - 1)][1]
        r = max(5, int(rect.w * 0.072))
        cx, cy = rect.centerx, rect.bottom - int(rect.h * 0.004)
        pts = [(cx + math.cos(math.pi / 6 + k * math.pi / 3) * r, cy + math.sin(math.pi / 6 + k * math.pi / 3) * r)
               for k in range(6)]
        pygame.draw.polygon(surf, (24, 22, 32), [(cx + (x - cx) * 1.18, cy + (y - cy) * 1.18) for x, y in pts])
        pygame.draw.polygon(surf, col, pts)
        inner = [(cx + (x - cx) * 0.6, cy + (y - cy) * 0.6) for x, y in pts]
        pygame.draw.polygon(surf, _shade(col, 1.35), [inner[3], inner[4], (cx, cy)])
        pygame.draw.polygon(surf, _shade(col, 0.6), [inner[0], inner[1], (cx, cy)])
        pygame.draw.polygon(surf, (250, 250, 255), pts, max(1, r // 6))

    def draw_gem_icon(self, w, cx, cy, r, col, on=True):
        pts = [(cx + math.cos(math.pi / 6 + k * math.pi / 3) * r, cy + math.sin(math.pi / 6 + k * math.pi / 3) * r)
               for k in range(6)]
        pygame.draw.polygon(w, col if on else (46, 52, 68), pts)
        if on:
            inner = [(cx + (x - cx) * 0.6, cy + (y - cy) * 0.6) for x, y in pts]
            pygame.draw.polygon(w, _shade(col, 1.35), [inner[3], inner[4], (cx, cy)])
            pygame.draw.polygon(w, _shade(col, 0.6), [inner[0], inner[1], (cx, cy)])
        pygame.draw.polygon(w, (236, 240, 250) if on else (80, 88, 108), pts, 3)

    # ---- tab 5: upgrade
    def upgrade_layout(self, panel):
        L = {}
        left = pygame.Rect(panel.x + 26, panel.y + 24, 560, panel.h - 48)
        right = pygame.Rect(left.right + 26, left.y, panel.right - 26 - left.right - 26, left.h)
        L["left"], L["right"] = left, right
        L["bar"] = pygame.Rect(left.x + 24, left.y + 150, left.w - 48, 26)
        L["one"] = pygame.Rect(left.x + 24, left.y + 300, left.w - 48, 76)
        L["max"] = pygame.Rect(left.x + 24, left.y + 392, left.w - 48, 76)
        L["feed"] = pygame.Rect(left.x + 24, left.y + 484, left.w - 48, 76)
        L["rank"] = pygame.Rect(right.x + 24, right.y + 152, right.w - 48, 70)
        L["skills"] = []
        for i, key in enumerate(STAT_KEYS):
            row = pygame.Rect(right.x + 24, right.y + 290 + i * 56, right.w - 48, 50)
            L["skills"].append((key, row, pygame.Rect(row.right - 70, row.y + 2, 66, 46)))
        # the feed picker, over the whole panel
        L["cards"] = []
        for i in range(12):
            col, row = i % 6, i // 6
            L["cards"].append(pygame.Rect(panel.x + 52 + col * 200, panel.y + 70 + row * 290, 150, 208))
        L["prev"] = pygame.Rect(panel.x + 26, panel.bottom - 74, 120, 58)
        L["next"] = pygame.Rect(panel.right - 146, panel.bottom - 74, 120, 58)
        L["cancel"] = pygame.Rect(panel.centerx - 130, panel.bottom - 74, 260, 58)
        L["yes"] = pygame.Rect(panel.centerx - 290, panel.centery + 60, 260, 76)
        L["no"] = pygame.Rect(panel.centerx + 30, panel.centery + 60, 260, 76)
        return L

    def prog_button(self, w, r, text, sub, on, col=(70, 190, 120)):
        hov = r.collidepoint(pygame.mouse.get_pos())
        pygame.draw.rect(w, _shade(col, 1.15 if hov else 1.0) if on else (44, 50, 64), r, border_radius=14)
        pygame.draw.rect(w, (230, 236, 248) if on else (70, 78, 96), r, 3, border_radius=14)
        sw = 0
        if sub:                                            # the price first, the label gets what is left
            s2 = self.fit_text(sub, self.font_s, WHITE if on else (130, 138, 156), r.w * 0.36, r.h * 0.5)
            w.blit(s2, s2.get_rect(midright=(r.right - 22, r.centery)))
            sw = s2.get_width() + 30
        t = self.fit_text(text, self.font_m, WHITE if on else (140, 148, 166), r.w - 44 - sw, r.h * 0.6)
        w.blit(t, t.get_rect(midleft=(r.x + 22, r.centery)))

    def cv_upgrade(self, w, card, panel):
        base = self.cards.get(card["id"], card)
        L = self.upgrade_layout(panel)
        if not self.owns(base) or card.get("boosted"):
            self.centre_in(w, "NOT IN YOUR CLUB", pygame.Rect(panel.x, panel.y + 220, panel.w, 60), self.font_l)
            self.centre_in(w, "Sign this player to level him up and upgrade his gem.",
                           pygame.Rect(panel.x, panel.y + 300, panel.w, 44), self.font_s, (168, 184, 208))
            return
        if getattr(self, "feed_ui", None):
            return self.draw_feed(w, base, panel, L)
        p = self.prog(base["id"]) or {"xp": 0, "rank": 0, "skill": {}}
        lvl, into, need = card_level(p["xp"])
        tp, pz = int(self.save.get("training_coins", 0)), int(self.save.get("puzzle_points", 0))
        # ---- left: the level
        left = L["left"]
        pygame.draw.rect(w, (22, 28, 44), left, border_radius=14)
        w.blit(self.font_s.render("TRAINING", True, (140, 220, 255)), (left.x + 24, left.y + 20))
        big = self.fit_text("LEVEL %d" % lvl, self.font_xl, WHITE, left.w - 150, 84)
        w.blit(big, (left.x + 24, left.y + 52))
        of = self.font_s.render("/ %d" % MAX_LEVEL, True, (150, 164, 188))
        w.blit(of, (left.x + 34 + big.get_width(), left.y + 100))
        bar = L["bar"]
        pygame.draw.rect(w, (38, 46, 66), bar, border_radius=12)
        frac = 1.0 if lvl >= MAX_LEVEL else into / float(max(1, need))
        if frac > 0:
            pygame.draw.rect(w, (90, 190, 255), (bar.x, bar.y, max(10, int(bar.w * frac)), bar.h), border_radius=12)
        xpt = "MAX" if lvl >= MAX_LEVEL else "%d / %d XP" % (into, need)
        xpi = self.fit_text(xpt, self.font_s, WHITE, bar.w - 20, bar.h + 10, (10, 14, 30))
        w.blit(xpi, xpi.get_rect(center=bar.center))
        gain = self.fit_text("+%d TO EVERY STAT  (+%d AT LEVEL %d)" % (level_stat_bonus(lvl), LEVEL_STAT_MAX, MAX_LEVEL),
                             self.font_s, (150, 236, 190), left.w - 48, 32)
        w.blit(gain, (left.x + 24, left.y + 196))
        have = self.fit_text("TRAINING POINTS:  %s" % self.fmt(tp), self.font_s, (200, 210, 230), left.w - 48, 32)
        w.blit(have, (left.x + 24, left.y + 242))
        top = lvl >= MAX_LEVEL
        one = self.tp_for(base, lvl + 1) if not top else 0
        mx = lvl
        while mx < MAX_LEVEL and self.tp_for(base, mx + 1) <= tp:
            mx += 1
        self.prog_button(w, L["one"], "+1 LEVEL", "%s TP" % self.fmt(one) if not top else "MAX",
                         not top and one <= tp, (52, 140, 220))
        self.prog_button(w, L["max"], "TO LEVEL %d" % mx if mx > lvl else "AS FAR AS I CAN",
                         "%s TP" % self.fmt(self.tp_for(base, mx)) if mx > lvl else "-", mx > lvl, (52, 140, 220))
        self.prog_button(w, L["feed"], "FEED A PLAYER", "%d CAN GO" % len(self.feed_list(base)),
                         not top and bool(self.feed_list(base)), (196, 110, 40))
        # ---- right: the gem
        right = L["right"]
        pygame.draw.rect(w, (22, 28, 44), right, border_radius=14)
        rank = int(p.get("rank", 0))
        w.blit(self.font_s.render("GEM RANK", True, RANKS[rank][1]), (right.x + 24, right.y + 20))
        have = self.fit_text("PUZZLE POINTS:  %s" % self.fmt(pz), self.font_s, (200, 210, 230), 300, 30)
        w.blit(have, (right.x + 24, right.y + 56))
        nm = self.fit_text(RANKS[rank][0], self.font_l, RANKS[rank][1], 260, 60)
        w.blit(nm, nm.get_rect(topright=(right.right - 24, right.y + 14)))
        step = (right.w - 48) // len(RANKS)
        for i, (gname, gcol) in enumerate(RANKS):
            cx = right.x + 24 + step * i + step // 2
            self.draw_gem_icon(w, cx, right.y + 108, 26 if i == rank else 20, gcol, i <= rank)
        if rank < len(RANK_COST):
            self.prog_button(w, L["rank"], "UPGRADE TO %s" % RANKS[rank + 1][0],
                             "%d PUZZLE" % RANK_COST[rank], pz >= RANK_COST[rank], RANKS[rank + 1][1])
        else:
            self.prog_button(w, L["rank"], "GOLD - FULLY UPGRADED", "", False)
        left_pts = self.skill_left(base)
        pts = self.fit_text("SKILL POINTS:  %d     (+1 OVR AND +1 POINT A STEP)" % left_pts, self.font_s,
                            PROG_GOLD if left_pts else (176, 192, 214), right.w - 48, 32)
        w.blit(pts, (right.x + 24, right.y + 242))
        skill = p.get("skill") or {}
        for key, row, plus in L["skills"]:
            pygame.draw.rect(w, (30, 38, 58), row, border_radius=10)
            lab = self.fit_text(STAT_NAMES[key], self.font_s, WHITE, 190, 30)
            w.blit(lab, lab.get_rect(midleft=(row.x + 16, row.centery)))
            n = int(skill.get(key, 0))
            for k in range(SKILL_MAX):
                pip = pygame.Rect(row.x + 230 + k * 44, row.y + 13, 36, 24)
                pygame.draw.rect(w, PROG_GOLD if k < n else (52, 60, 80), pip, border_radius=6)
            val = self.fit_text("+%d" % (n * SKILL_STEP), self.font_s, PROG_GOLD if n else (120, 130, 150), 80, 30)
            w.blit(val, val.get_rect(midleft=(row.x + 230 + SKILL_MAX * 44 + 10, row.centery)))
            ok = left_pts > 0 and n < SKILL_MAX
            pygame.draw.rect(w, (64, 170, 100) if ok else (44, 50, 64), plus, border_radius=10)
            self.centre_in(w, "+", plus, self.font_m, WHITE if ok else (110, 118, 136))

    def draw_feed(self, w, target, panel, L):
        f = self.feed_ui
        items = self.feed_list(target)
        pages = max(1, (len(items) + 11) // 12)
        f["page"] = max(0, min(f.get("page", 0), pages - 1))
        head = self.fit_text("FEED A PLAYER INTO %s  -  THE ONE YOU PICK IS USED UP" % target["name"].upper(),
                             self.font_s, WHITE, panel.w - 60, 34)
        w.blit(head, (panel.x + 30, panel.y + 22))
        page = items[f["page"] * 12:(f["page"] + 1) * 12]
        for (c, n), r in zip(page, L["cards"]):
            self.blit_card(w, c, r)
            xp = self.fit_text("+%d XP" % self.feed_value(c, target), self.font_s, (140, 220, 255), r.w, 30)
            w.blit(xp, xp.get_rect(midtop=(r.centerx, r.bottom + 8)))
            if n > 1:
                cnt = self.fit_text("x%d" % n, self.font_s, (200, 210, 230), 60, 26)
                w.blit(cnt, cnt.get_rect(topright=(r.right, r.bottom + 40)))
        if not items:
            self.centre_in(w, "NOBODY TO FEED - SPARE PLAYERS AND DUPLICATES SHOW UP HERE",
                           pygame.Rect(panel.x, panel.y + 260, panel.w, 50), self.font_s, (168, 184, 208))
        for key, label, on in (("prev", "<", f["page"] > 0), ("next", ">", f["page"] < pages - 1),
                               ("cancel", "CANCEL", True)):
            r = L[key]
            pygame.draw.rect(w, (40, 52, 78) if on else (30, 34, 46), r, border_radius=12)
            self.centre_in(w, label, r, self.font_m, WHITE if on else (90, 98, 116))
        pick = f.get("pick")
        if pick is not None:
            box = pygame.Rect(panel.x + 180, panel.y + 150, panel.w - 360, 360)
            wash(w, (6, 8, 16, 170), panel)
            pygame.draw.rect(w, (20, 26, 42), box, border_radius=18)
            pygame.draw.rect(w, (196, 110, 40), box, 3, border_radius=18)
            self.centre_in(w, "FEED %s INTO %s?" % (pick["name"].upper(), target["name"].upper()),
                           pygame.Rect(box.x, box.y + 40, box.w, 50), self.font_m, WHITE)
            gain = self.feed_value(pick, target)
            lvl0 = self.card_lvl(target)[0]
            p = self.prog(target["id"]) or {"xp": 0}
            lvl1 = card_level(min(sum(LEVEL_XP), int(p["xp"]) + gain))[0]
            self.centre_in(w, "+%d XP  -  LEVEL %d -> %d.  %s IS USED UP." % (gain, lvl0, lvl1, pick["name"].upper()),
                           pygame.Rect(box.x, box.y + 110, box.w, 40), self.font_s, (200, 210, 230))
            for key, label, col in (("yes", "FEED", (196, 110, 40)), ("no", "CANCEL", (60, 70, 92))):
                pygame.draw.rect(w, col, L[key], border_radius=14)
                self.centre_in(w, label, L[key], self.font_m, WHITE)

    def upgrade_click(self, pos):
        base = self.cards.get(self.card_detail["id"], self.card_detail)
        if not self.owns(base) or self.card_detail.get("boosted"):
            return
        L = self.upgrade_layout(self.CV_PANEL)
        hit = lambda r: r.collidepoint(pos.x, pos.y)
        f = getattr(self, "feed_ui", None)
        if f:
            if f.get("pick") is not None:
                if hit(L["yes"]):
                    self.feed(base, f["pick"])
                    f["pick"] = None
                    if not self.feed_list(base) or self.card_lvl(base)[0] >= MAX_LEVEL:
                        self.feed_ui = None
                elif hit(L["no"]):
                    f["pick"] = None
                return
            items = self.feed_list(base)
            page = items[f.get("page", 0) * 12:(f.get("page", 0) + 1) * 12]
            for (c, _n), r in zip(page, L["cards"]):
                if hit(r):
                    f["pick"] = c
                    return
            if hit(L["prev"]):
                f["page"] = max(0, f.get("page", 0) - 1)
            elif hit(L["next"]):
                f["page"] = f.get("page", 0) + 1
            elif hit(L["cancel"]):
                self.feed_ui = None
            return
        if hit(L["one"]):
            self.train(base, 1)
        elif hit(L["max"]):
            self.train(base, None)
        elif hit(L["feed"]):
            if self.feed_list(base) and self.card_lvl(base)[0] < MAX_LEVEL:
                self.feed_ui = {"page": 0, "pick": None}
        elif hit(L["rank"]):
            self.rank_up(base)
        else:
            for key, _row, plus in L["skills"]:
                if hit(plus):
                    self.skill_up(base, key)
                    return

    def can_exchange(self, card):
        return card["kind"] not in ("star", "wg") and card["id"] not in NO_EXCHANGE

    def exchange_list(self, dupes_only=None):
        """[(card, copies you can exchange)] - squad players always keep one copy."""
        dupes_only = self.exchange_dupes if dupes_only is None else dupes_only
        out = []
        squad = self.save["squad"]
        for cid, n in self.save["owned"].items():
            c = self.cards.get(cid)
            if c is None or not self.can_exchange(c):
                continue
            spare = n - 1 if (dupes_only or cid in squad) else n
            if spare > 0:
                out.append((c, spare))
        return sorted(out, key=lambda e: (-e[0]["rating"], e[0]["name"]))

    def exchange_pages(self):
        return max(1, math.ceil(len(self.exchange_list()) / EXCHANGE_PER_PAGE))

    def open_exchange(self):
        self.store_confirm = None
        self.exchange_page = 0
        self.state = EXCHANGE

    def exchange_layout(self):
        L = {"all": pygame.Rect(290, 172, 300, 64), "dupes": pygame.Rect(606, 172, 360, 64),
             "bulk": pygame.Rect(1150, 172, 480, 64), "prev": pygame.Rect(110, 540, 110, 110),
             "next": pygame.Rect(1700, 540, 110, 110), "grid": []}
        items = self.exchange_list()
        pages = max(1, math.ceil(len(items) / EXCHANGE_PER_PAGE))
        self.exchange_page %= pages
        page = items[self.exchange_page * EXCHANGE_PER_PAGE:(self.exchange_page + 1) * EXCHANGE_PER_PAGE]
        for i, (c, n) in enumerate(page):
            r, k = divmod(i, 8)
            L["grid"].append((c, n, pygame.Rect(290 + k * 170, 258 + r * 256, 150, 208)))
        return L

    def dupes_total(self):
        dupes = self.exchange_list(True)
        return sum(n for _c, n in dupes), sum(n * star_points_for(c["rating"]) for c, n in dupes)

    def exchange_click(self, pos):
        if self.store_confirm is not None:
            self.store_confirm_click(pos)
            return
        L = self.exchange_layout()
        if pygame.Rect(40, 30, 200, 70).collidepoint(pos.x, pos.y):
            self.open_store()
            return
        if L["all"].collidepoint(pos.x, pos.y) or L["dupes"].collidepoint(pos.x, pos.y):
            self.exchange_dupes = L["dupes"].collidepoint(pos.x, pos.y)
            self.exchange_page = 0
            return
        if L["prev"].collidepoint(pos.x, pos.y):
            self.turn_page(-1)
            return
        if L["next"].collidepoint(pos.x, pos.y):
            self.turn_page(1)
            return
        if L["bulk"].collidepoint(pos.x, pos.y):
            n, sp = self.dupes_total()
            if n == 0:
                self.toast("NO DUPLICATES TO EXCHANGE", (220, 210, 240))
                return
            self.store_confirm = {"card": None, "title": "EXCHANGE ALL DUPLICATES?", "ok": "EXCHANGE",
                                  "lines": ["%d CARDS  ->  +%s STAR POINTS" % (n, self.fmt(sp)),
                                            "YOU KEEP ONE COPY OF EVERY PLAYER"],
                                  "action": self.exchange_all_dupes}
            return
        for c, n, r in L["grid"]:
            if r.collidepoint(pos.x, pos.y):
                self.card_click(c, lambda card=c: self.ask_exchange(card))
                return

    def ask_exchange(self, card):
        if self.state != EXCHANGE or not self.can_exchange(card):
            return
        n = self.save["owned"].get(card["id"], 0)
        if n <= 0 or (n <= 1 and card["id"] in self.save["squad"]):
            return
        left = n - 1
        self.store_confirm = {"card": card, "title": "EXCHANGE %s?" % card["name"].upper(), "ok": "EXCHANGE",
                              "lines": ["+%s STAR POINTS" % self.fmt(star_points_for(card["rating"])),
                                        "YOU'LL HAVE %d LEFT" % left if left else "LAST COPY - HE LEAVES YOUR CLUB"],
                              "action": lambda c=card: self.exchange_card(c)}

    def exchange_card(self, card, copies=1, save=True):
        """Swap copies of a card for Star Points. Returns the points earned."""
        cid = card["id"]
        owned = self.save["owned"]
        n = owned.get(cid, 0)
        keep = 1 if cid in self.save["squad"] else 0
        copies = min(copies, n - keep)
        if copies <= 0 or not self.can_exchange(card):
            return 0
        owned[cid] = n - copies
        if owned[cid] <= 0:
            del owned[cid]
            self.save["stamina"].pop(cid, None)
            self.save.get("prog", {}).pop(cid, None)
        sp = copies * star_points_for(card["rating"])
        self.save["star_points"] = self.star_points() + sp
        if save:
            self.toast("+%s STAR POINTS" % self.fmt(sp), STAR_LILAC)
            self.burst_fireworks(WIDTH // 2, HEIGHT // 2, STAR_LILAC, 30)
            self.write_save()
        return sp

    def exchange_all_dupes(self):
        total = 0
        for c, n in self.exchange_list(True):
            total += self.exchange_card(c, n, save=False)
        if total:
            self.toast("+%s STAR POINTS" % self.fmt(total), STAR_LILAC)
            self.burst_fireworks(WIDTH // 2, HEIGHT // 2, STAR_LILAC, 60)
        self.write_save()
        return total

    def draw_exchange(self, w):
        self.draw_purple_bg(w)
        wash(w, (8, 4, 20, 110))
        self.draw_back_button(w)
        self.draw_coins(w)
        self.draw_star_points(w)
        head = self.outlined("EXCHANGE", self.font_l, WHITE, 0.9, (60, 14, 110), 5)
        w.blit(head, head.get_rect(center=(WIDTH // 2, 64)))
        hint = self.label("CLICK A PLAYER TO EXCHANGE HIM  -  DOUBLE-CLICK FOR STATS", 900, (210, 200, 235))
        w.blit(hint, hint.get_rect(center=(WIDTH // 2 - 60, 132)))
        L = self.exchange_layout()
        mouse = pygame.mouse.get_pos()
        for key, txt, on in (("all", "ALL PLAYERS", not self.exchange_dupes),
                             ("dupes", "DUPLICATES ONLY", self.exchange_dupes)):
            r = L[key]
            pygame.draw.rect(w, (126, 52, 220) if on else (46, 24, 80), r, border_radius=14)
            pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else (226, 228, 240), r, 3, border_radius=14)
            lab = self.label(txt, r.w - 30, WHITE)
            w.blit(lab, lab.get_rect(center=r.center))
        n, sp = self.dupes_total()
        r = L["bulk"]
        pygame.draw.rect(w, (30, 110, 70) if n else (40, 40, 56), r, border_radius=14)
        pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) and n else (226, 228, 240), r, 3, border_radius=14)
        lab = self.label("EXCHANGE ALL DUPES  +%s SP" % self.fmt(sp) if n else "NO DUPLICATES", r.w - 30, WHITE)
        w.blit(lab, lab.get_rect(center=r.center))
        if not L["grid"]:
            self.centre_text(w, "NOTHING TO EXCHANGE" if not self.exchange_dupes else "NO DUPLICATES YET",
                             self.font_m, WHITE, 480)
            self.centre_text(w, "OPEN PACKS TO GET MORE PLAYERS", self.font_s, (210, 200, 235), 570)
        for c, copies, r in L["grid"]:
            hover = r.collidepoint(mouse)
            self.blit_card(w, c, r, count=copies, glow=hover)
            tag = pygame.Rect(r.x, r.bottom + 8, r.w, 34)
            pygame.draw.rect(w, (40, 14, 76), tag, border_radius=10)
            pygame.draw.rect(w, STAR_LILAC if hover else (120, 80, 170), tag, 2, border_radius=10)
            self.draw_sp_icon(w, (tag.x + 18, tag.centery), 12)
            txt = self.label("+%s" % self.fmt(star_points_for(c["rating"])), tag.w - 44, WHITE)
            w.blit(txt, txt.get_rect(center=(tag.centerx + 12, tag.centery)))
        pages = self.exchange_pages()
        if pages > 1:
            for key, txt in (("prev", "<"), ("next", ">")):
                pygame.draw.rect(w, (90, 36, 160), L[key], border_radius=14)
                pygame.draw.rect(w, YELLOW if L[key].collidepoint(mouse) else WHITE, L[key], 3, border_radius=14)
                self.centre_in(w, txt, L[key], self.font_m)
        pg = self.label("%d / %d" % (self.exchange_page + 1, pages), 170, WHITE, self.font_m)
        w.blit(pg, pg.get_rect(center=(1058, 204)))
        rule = self.label("SQUAD PLAYERS ALWAYS KEEP ONE COPY  -  NEYMAR JR AND STAR SIGNINGS "
                          "CAN'T BE EXCHANGED", WIDTH - 160, (190, 180, 220))
        w.blit(rule, rule.get_rect(center=(WIDTH // 2, 1050)))
        self.draw_fx(w, 1.0 / FPS)
        if self.store_confirm is not None:
            self.draw_store_confirm(w)

    # ---- yes / no popup ------------------------------------------------------------
    def store_confirm_layout(self):
        panel = pygame.Rect(420, 230, 1080, 600)
        return panel, pygame.Rect(880, 690, 300, 96), pygame.Rect(1200, 690, 260, 96)

    def store_confirm_click(self, pos):
        panel, ok, cancel = self.store_confirm_layout()
        pc = self.store_confirm
        if ok.collidepoint(pos.x, pos.y):
            self.store_confirm = None
            pc["action"]()
        elif cancel.collidepoint(pos.x, pos.y) or not panel.collidepoint(pos.x, pos.y):
            self.store_confirm = None

    def draw_store_confirm(self, w):
        pc = self.store_confirm
        ess = pc.get("theme") == "essence"                 # the Essence shop asks in its own colours
        edge = ESSENCE_HOT if ess else STAR_LILAC
        wash(w, (14, 4, 6, 200) if ess else (6, 2, 14, 200))
        panel, ok, cancel = self.store_confirm_layout()
        pygame.draw.rect(w, (52, 14, 18) if ess else (36, 14, 66), panel, border_radius=26)
        pygame.draw.rect(w, edge, panel, 5, border_radius=26)
        x = 900
        if pc["card"] is not None:
            keep = w.get_clip()
            w.set_clip(pygame.Rect(panel.x + 8, panel.y + 8, 880 - panel.x - 8, panel.h - 16))
            self.draw_card(w, pc["card"], pygame.Rect(480, 290, 340, 472), glow=True)
            w.set_clip(keep)
        elif pc.get("icon") == "star_points":
            self.draw_sp_icon(w, (650, 520), 120)
        elif pc.get("icon") in ("coins", "training_coins"):
            self.draw_reward_icon(w, "coins" if pc["icon"] == "coins" else "training", (650, 520), 2.8)
        elif ess:
            self.draw_essence_icon(w, (650, 510), 120)
        else:
            self.draw_sp_icon(w, (650, 520), 120)
        title = self.label(pc["title"], panel.right - x - 40, WHITE, self.font_m)
        w.blit(title, (x, 300))
        for i, line in enumerate(pc["lines"]):
            col = edge if i == 0 else ((236, 220, 214) if ess else (220, 214, 236))
            img = self.label(line, panel.right - x - 40, col, self.font_m if i == 0 else None)
            if i == 0:
                if ess:
                    self.draw_essence_icon(w, (x + 22, 414), 22)
                else:
                    self.draw_sp_icon(w, (x + 22, 420), 22)
                w.blit(img, (x + 56, 392))
            else:
                w.blit(img, (x, 440 + i * 60))
        mouse = pygame.mouse.get_pos()
        for r, txt, col in ((ok, pc["ok"], (186, 44, 48) if ess else (126, 52, 220)),
                            (cancel, "CANCEL", (78, 58, 60) if ess else (70, 60, 90))):
            pygame.draw.rect(w, col, r, border_radius=18)
            pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else WHITE, r, 5, border_radius=18)
            lab = self.label(txt, r.w - 36, WHITE, self.font_m)
            w.blit(lab, lab.get_rect(center=r.center))

    # ================================================================ ESSENCE SHOP
    # Essence only comes out of Impossible Mode. It buys two kinds of thing: a lot of an
    # ordinary currency at once (ESSENCE_BUNDLES), or the World's Game player sitting in the
    # one slot today (WG_PRICE). The slot turns at local midnight, in table order.
    def open_essence(self, came_from=None):
        self.store_confirm = None
        if came_from is not None:
            self.essence_from = came_from
        elif self.state == TITLE:
            self.essence_from = "play"                     # BACK returns to the Impossible tab
        elif self.state == STORE:
            self.essence_from = "store"
        self.state = ESSENCE

    def leave_essence(self):
        if getattr(self, "essence_from", "store") == "play":
            self.state = TITLE
            self.menu_page = "play"
        else:
            self.open_store()

    def wg_pool(self):
        return [self.cards[c] for c in self.wg_ids if c in self.cards]

    def wg_today(self, days_ahead=0):
        """The World's Game player in the slot (today, or `days_ahead` from now). None if there are none yet."""
        pool = self.wg_pool()
        if not pool:
            return None
        return pool[(today_number() + days_ahead) % len(pool)]

    def essence_layout(self):
        slot = pygame.Rect(70, 196, 760, 824)
        card = pygame.Rect(0, 0, 340, 472)                 # the size the players were drawn for
        card.midtop = (slot.centerx, slot.y + 146)
        sign = pygame.Rect(slot.x + 70, slot.bottom - 118, slot.w - 140, 94)
        n = len(ESSENCE_BUNDLES)
        gap = 18
        h = (slot.h - gap * (n - 1)) // n
        rows = []
        for i in range(n):
            r = pygame.Rect(slot.right + 40, slot.y + i * (h + gap), WIDTH - 70 - slot.right - 40, h)
            rows.append((r, pygame.Rect(r.right - 322, r.centery - 52, 288, 104)))
        return {"slot": slot, "card": card, "sign": sign, "rows": rows}

    def essence_click(self, pos):
        if self.store_confirm is not None:
            self.store_confirm_click(pos)
            return
        L = self.essence_layout()
        if L["sign"].collidepoint(pos.x, pos.y):
            self.ask_wg()
            return
        card = self.wg_today()
        if card is not None and L["card"].collidepoint(pos.x, pos.y):
            self.card_detail = card                        # look before you spend an hour's worth
            self.card_tab = 0
            return
        for i, (_row, btn) in enumerate(L["rows"]):
            if btn.collidepoint(pos.x, pos.y):
                self.ask_bundle(i)
                return

    def short_of_essence(self, cost):
        need = cost - self.essence()
        if need > 0:
            self.toast("NOT ENOUGH ESSENCE  -  %s MORE NEEDED" % self.fmt(need), (255, 140, 140))
        return need > 0

    def ask_bundle(self, i):
        key, name, amount, cost = ESSENCE_BUNDLES[i]
        if self.short_of_essence(cost):
            return
        self.store_confirm = {"card": None, "theme": "essence", "icon": key, "ok": "BUY",
                              "title": "%s %s?" % (self.fmt(amount), name),
                              "lines": ["%s ESSENCE" % self.fmt(cost),
                                        "YOU'LL HAVE %s ESSENCE LEFT" % self.fmt(self.essence() - cost)],
                              "action": lambda n=i: self.buy_bundle(n)}

    def buy_bundle(self, i):
        key, name, amount, cost = ESSENCE_BUNDLES[i]
        if self.essence() < cost:
            return False
        self.save["essence"] = self.essence() - cost
        self.save[key] = int(self.save.get(key, 0)) + amount
        self.write_save()
        self.toast("+%s %s" % (self.fmt(amount), name), YELLOW)
        return True

    def ask_wg(self):
        card = self.wg_today()
        if card is None:
            self.toast("THE FIRST WORLD'S GAME PLAYERS ARE ON THEIR WAY", ESSENCE_HOT)
            return
        if card["id"] in self.save["owned"]:
            self.toast("%s IS ALREADY AT YOUR CLUB" % card["name"].upper(), ESSENCE_HOT)
            return
        if self.short_of_essence(WG_PRICE):
            return
        self.store_confirm = {"card": card, "theme": "essence", "ok": "SIGN",
                              "title": "SIGN %s?" % card["name"].upper(),
                              "lines": ["%s ESSENCE" % self.fmt(WG_PRICE),
                                        "YOU'LL HAVE %s ESSENCE LEFT" % self.fmt(self.essence() - WG_PRICE),
                                        "WORLD'S GAME PLAYERS CAN'T BE EXCHANGED"],
                              "action": lambda c=card: self.sign_wg(c)}

    def sign_wg(self, card):
        today = self.wg_today()
        if today is None or today["id"] != card["id"]:     # the box sat open past midnight
            self.toast("THE SLOT HAS CHANGED  -  LOOK AGAIN", ESSENCE_HOT)
            return False
        if card["id"] in self.save["owned"] or self.essence() < WG_PRICE:
            return False
        self.save["essence"] = self.essence() - WG_PRICE
        count = self.give_card(card)
        self.pack_reveal = {"card": card, "t": 0.0, "count": count, "pack": 0, "tier": self.card_pool(card),
                            "opened": False, "back": "essence", "art": self.wg_pack or self.star_pack}
        self.fx = []
        self.state = PACK_OPEN
        self.write_save()
        return True

    @staticmethod
    def clock_words(seconds):
        h, m = int(seconds) // 3600, int(seconds) % 3600 // 60
        return "%dH %02dM" % (h, m) if h else "%d MIN" % max(1, m)

    def draw_essence_shop(self, w):
        if self.essence_bg is not None:
            w.blit(self.essence_bg, (0, 0))
        else:
            w.fill((26, 8, 12))
        mouse = pygame.mouse.get_pos() if self.store_confirm is None else (-1, -1)
        self.draw_back_button(w)
        self.draw_coins(w)
        self.draw_star_points(w)
        head = self.outlined("ESSENCE SHOP", self.font_l, WHITE, 0.82, (70, 14, 18), 5)
        w.blit(head, head.get_rect(center=(WIDTH // 2, 92)))
        # what you have to spend, next to the BACK button
        have = self.label("%s ESSENCE" % self.fmt(self.essence()), 360, ESSENCE_HOT, self.font_m)
        self.draw_essence_icon(w, (300, 62), 26)
        w.blit(have, have.get_rect(midleft=(336, 66)))
        L = self.essence_layout()
        # ---- the single slot
        slot = L["slot"]
        pygame.draw.rect(w, (26, 12, 56), slot, border_radius=24)
        pygame.draw.rect(w, WG_SILVER, slot, 5, border_radius=24)
        name = self.outlined("THE WORLD'S GAME", self.font_m, WG_SILVER, 1.0, (40, 16, 90), 4)
        w.blit(name, name.get_rect(center=(slot.centerx, slot.y + 46)))
        card = self.wg_today()
        pool = self.wg_pool()
        if card is None:
            sub = "ONE PLAYER A DAY  -  THE FIRST ARE ON THEIR WAY"
        elif len(pool) > 1:
            sub = "TODAY'S PLAYER  -  CHANGES IN %s" % self.clock_words(seconds_to_midnight())
        else:
            sub = "TODAY'S PLAYER"
        img = self.label(sub, slot.w - 60, (226, 216, 244), self.font_s)
        w.blit(img, img.get_rect(center=(slot.centerx, slot.y + 96)))
        cr = L["card"]
        owned = card is not None and card["id"] in self.save["owned"]
        if card is not None:
            hover = cr.collidepoint(mouse)
            keep = w.get_clip()
            w.set_clip(slot.inflate(-12, -12))
            self.draw_card(w, card, cr.move(0, -6) if hover else cr)
            w.set_clip(keep)
            if owned:
                tag = pygame.Rect(0, 0, 260, 64)
                tag.center = cr.center
                pygame.draw.rect(w, (18, 60, 32), tag, border_radius=14)
                pygame.draw.rect(w, WHITE, tag, 4, border_radius=14)
                self.centre_in(w, "SIGNED", tag)
        else:
            if self.card_back is not None:
                back = scaled(self.card_back, cr.size)
                w.blit(back, cr)
                wash(w, (26, 12, 56, 205), cr)
            pygame.draw.rect(w, WG_SILVER, cr, 4, border_radius=14)
            q = self.outlined("?", self.font_xl, WG_SILVER, 1.0, (40, 16, 90), 5)
            w.blit(q, q.get_rect(center=cr.center))
        if len(pool) > 1:
            nxt = self.wg_today(1)
            line = self.label("TOMORROW:  %s" % nxt["name"].upper(), slot.w - 60, (196, 184, 224), self.font_s)
            w.blit(line, line.get_rect(center=(slot.centerx, cr.bottom + 56)))
        elif card is None:
            line = self.label("THE PLAYERS WILL TAKE TURNS HERE", slot.w - 60, (196, 184, 224), self.font_s)
            w.blit(line, line.get_rect(center=(slot.centerx, cr.bottom + 56)))
        sb = L["sign"]
        need = WG_PRICE - self.essence()
        can = card is not None and not owned and need <= 0
        if card is None:
            words = "COMING SOON"
        elif owned:
            words = "ALREADY AT YOUR CLUB"
        elif need > 0:
            words = "%s MORE ESSENCE TO SIGN" % self.fmt(need)
        else:
            words = "SIGN FOR %s" % self.fmt(WG_PRICE)
        hov = can and sb.collidepoint(mouse)
        r = sb.move(0, -4) if hov else sb
        pygame.draw.rect(w, (186, 44, 48) if can else (62, 50, 52), r, border_radius=20)
        pygame.draw.rect(w, YELLOW if hov else (WHITE if can else (140, 124, 126)), r, 5, border_radius=20)
        lab = self.label(words, r.w - (120 if can else 50), WHITE if can else (190, 176, 178), self.font_m)
        pos = lab.get_rect(center=(r.centerx - (24 if can else 0), r.centery))
        w.blit(lab, pos)
        if can:
            self.draw_essence_icon(w, (pos.right + 34, r.centery - 2), 24)
        # ---- the bundles
        hints = {"star_points": "TOWARDS A STAR SIGNING", "training_coins": "LEVELS UP YOUR PLAYERS"}
        for (key, title, amount, cost), (row, btn) in zip(ESSENCE_BUNDLES, L["rows"]):
            hov = btn.collidepoint(mouse)
            pygame.draw.rect(w, (40, 12, 16), row, border_radius=22)
            pygame.draw.rect(w, _shade(ESSENCE_RED, 0.62), row, 4, border_radius=22)
            ic = (row.x + 124, row.centery)
            pygame.draw.circle(w, (26, 8, 10), ic, 92)
            if key == "star_points":
                self.draw_sp_icon(w, ic, 60)
            else:
                self.draw_reward_icon(w, "coins" if key == "coins" else "training", ic, 1.5)
            big = self.fit_text(self.fmt(amount), self.font_l, WHITE, 380, 96, (40, 12, 8))
            w.blit(big, (row.x + 250, row.y + 44))
            lab = self.label(title, 380, YELLOW, self.font_s)
            w.blit(lab, (row.x + 252, row.y + 150))
            hint = "%d PACKS' WORTH" % (amount // PACK_PRICE) if key == "coins" else hints.get(key, "")
            small = self.label(hint, 380, (200, 180, 174), self.font_s)
            w.blit(scaled_text(small, 0.8), (row.x + 252, row.y + 196))
            afford = self.essence() >= cost
            r = btn.move(0, -4) if hov and afford else btn
            pygame.draw.rect(w, (186, 44, 48) if afford else (62, 50, 52), r, border_radius=18)
            pygame.draw.rect(w, YELLOW if hov and afford else (WHITE if afford else (140, 124, 126)), r, 5,
                             border_radius=18)
            price = self.font_m.render(self.fmt(cost), True, WHITE if afford else (190, 176, 178))
            px = r.centerx - (price.get_width() + 56) // 2
            self.draw_essence_icon(w, (px + 20, r.centery - 2), 24)
            w.blit(price, (px + 56, r.centery - price.get_height() // 2))
        if self.store_confirm is not None:
            self.draw_store_confirm(w)

    # ================================================================ THE SIGNATURE ARCHIVE (1 Nov)
    # Every Game Box player, signed for SIGNATURE TOKENS. Tokens come only from the archive's quests: one
    # opens every ARCHIVE_EVERY levels (ARCHIVE_QUESTS - one so far, at level 10), each a handful of hard,
    # specific tasks. A task counts only once its quest is open; each pays ARCHIVE_TASK_TOKENS when you
    # claim it, and all of a quest's tasks ARCHIVE_BONUS_TOKENS more - one quest is one Signature card.
    def archive(self):
        A = self.save.setdefault("archive", {})
        for k, v in (("tokens", 0), ("done", {}), ("claimed", {}), ("bonus", {})):
            A.setdefault(k, v)
        return A

    def sig_tokens(self):
        return int(self.archive()["tokens"])

    def player_level(self):
        return level_from_xp(self.save.get("xp", 0))[0]

    def archive_quest_open(self, q):
        return self.player_level() >= q[1]

    def archive_next_quest(self):
        """The first quest not finished yet (None when all are)."""
        A = self.archive()
        for q in ARCHIVE_QUESTS:
            if not A["bonus"].get(q[0]):
                return q
        return None

    def archive_event(self, task):
        """One of the archive's tasks just happened in a match (the hooks in the game)."""
        A = self.archive()
        for q in ARCHIVE_QUESTS:
            for key, text in q[3]:
                if key == task and not A["done"].get(key) and self.archive_quest_open(q):
                    A["done"][key] = True
                    self.toast("SIGNATURE ARCHIVE  -  TASK DONE: %s" % text, SIG_GOLD, 5.0)
                    self.sfx.play("cheer", 0.6)
                    return True
        return False

    def archive_claim(self, key):
        A = self.archive()
        if not A["done"].get(key) or A["claimed"].get(key):
            return False
        A["claimed"][key] = True
        A["tokens"] = self.sig_tokens() + ARCHIVE_TASK_TOKENS
        self.toast("+%d SIGNATURE TOKEN" % ARCHIVE_TASK_TOKENS, SIG_GOLD, 2.4)
        self.sfx.play("cheer", 0.5)
        self.write_save()
        return True

    def archive_bonus_ready(self, q):
        A = self.archive()
        return not A["bonus"].get(q[0]) and all(A["claimed"].get(k) for k, _t in q[3])

    def archive_claim_bonus(self, q):
        if not self.archive_bonus_ready(q):
            return False
        A = self.archive()
        A["bonus"][q[0]] = True
        A["tokens"] = self.sig_tokens() + ARCHIVE_BONUS_TOKENS
        self.toast("%s COMPLETE  -  +%d SIGNATURE TOKENS" % (q[2], ARCHIVE_BONUS_TOKENS), SIG_GOLD, 3.0)
        self.burst_fireworks(WIDTH // 2, HEIGHT // 2, SIG_GOLD, 60)
        self.sfx.play("cheer", 0.8)
        self.write_save()
        return True

    def archive_sign(self, cid):
        card = self.cards.get(cid)
        if card is None or cid not in ARCHIVE_CARDS or self.owns(card) or self.sig_tokens() < SIG_TOKEN_PRICE:
            return False
        A = self.archive()
        A["tokens"] = self.sig_tokens() - SIG_TOKEN_PRICE
        count = self.give_card(card)
        self.pack_reveal = {"card": card, "t": 0.0, "count": count, "pack": 0, "tier": self.card_pool(card),
                            "opened": False, "back": "archive", "art": self.box_art_for(cid)}
        self.fx = []
        self.state = PACK_OPEN
        self.write_save()
        return True

    def open_archive(self):
        self.store_confirm = None
        self.state = ARCHIVE
        self.dragging = False

    def archive_layout(self):
        L = {"cards": [], "tasks": [], "bonus": None, "tokens": pygame.Rect(1176, 40, 340, 52)}
        for i, cid in enumerate(ARCHIVE_CARDS):
            x = 70 + i * 430
            L["cards"].append((cid, pygame.Rect(x + 52, 236, 306, 424), pygame.Rect(x, 856, 410, 84)))
        q = self.archive_next_quest() or ARCHIVE_QUESTS[-1]
        for k in range(len(q[3])):
            L["tasks"].append(pygame.Rect(1000, 330 + k * 150, 860, 136))
        L["claims"] = [pygame.Rect(r.right - 200, r.centery - 32, 176, 64) for r in L["tasks"]]
        L["bonus"] = pygame.Rect(1000, 330 + len(q[3]) * 150, 860, 110)
        L["bonus_btn"] = pygame.Rect(L["bonus"].right - 200, L["bonus"].centery - 32, 176, 64)
        return L

    def archive_click(self, pos):
        if self.store_confirm is not None:
            self.store_confirm_click(pos)
            return
        x, y = pos.x, pos.y
        if self.BACK_RECT.collidepoint(x, y):
            self.open_store()
            return
        L = self.archive_layout()
        q = self.archive_next_quest() or ARCHIVE_QUESTS[-1]
        for (key, _t), b in zip(q[3], L["claims"]):
            if b.collidepoint(x, y):
                self.archive_claim(key)
                return
        if L["bonus_btn"].collidepoint(x, y):
            self.archive_claim_bonus(q)
            return
        for cid, cr, btn in L["cards"]:
            card = self.cards[cid]
            if btn.collidepoint(x, y):
                self.ask_archive(card)
                return
            if cr.collidepoint(x, y):
                self.card_detail = card
                self.card_tab = 0
                return

    def ask_archive(self, card):
        if self.owns(card):
            self.toast("%s IS ALREADY AT YOUR CLUB" % card["name"].upper(), SIG_GOLD)
            return
        need = SIG_TOKEN_PRICE - self.sig_tokens()
        if need > 0:
            self.toast("%d MORE SIGNATURE TOKEN%s NEEDED - FINISH ARCHIVE QUESTS" % (need, "" if need == 1 else "S"),
                       (255, 150, 140))
            return
        self.store_confirm = {"card": card, "title": "SIGN %s?" % card["name"].upper(), "ok": "SIGN",
                              "lines": ["%d SIGNATURE TOKENS" % SIG_TOKEN_PRICE,
                                        "YOU'LL HAVE %d LEFT" % (self.sig_tokens() - SIG_TOKEN_PRICE),
                                        "%d OVR  -  SIGNATURE" % card["rating"]],
                              "action": lambda c=card: self.archive_sign(c["id"])}

    def draw_sig_token(self, w, centre, r=20):
        """A Signature Token: a gold coin with an autograph's loop across it."""
        x, y = int(centre[0]), int(centre[1])
        pygame.draw.circle(w, (120, 80, 14), (x, y + max(1, r // 10)), r)
        pygame.draw.circle(w, SIG_GOLD, (x, y), r)
        pygame.draw.circle(w, (255, 240, 190), (x, y), r, max(2, r // 7))
        pygame.draw.circle(w, (196, 140, 40), (x, y), int(r * 0.72), max(1, r // 12))
        pts = [(x - r * 0.5 + i * r / 14.0, y + math.sin(i * 0.9) * r * 0.22 - (i - 7) * r * 0.02) for i in range(15)]
        pygame.draw.lines(w, (90, 54, 8), False, pts, max(2, r // 8))

    def draw_archive(self, w):
        mouse = pygame.mouse.get_pos()
        w.blit(tinted(self.home_bg(), (30, 18, 0, 70), "archive"), (0, 0))
        self.draw_glass(w, pygame.Rect(24, 20, WIDTH - 48, 92), radius=24, alpha=120)
        self.draw_glass_back(w, mouse)
        title = self.home_gold("SIGNATURE ARCHIVE", 52)
        w.blit(title, title.get_rect(midleft=(272, 66)))
        self.draw_status(w, mouse)
        L = self.archive_layout()
        tk = L["tokens"]
        self.draw_glass(w, tk, radius=26, alpha=170, edge=SIG_GOLD)
        self.draw_sig_token(w, (tk.x + 32, tk.centery), 18)
        n = self.sig_tokens()
        self.home_text(w, "%d TOKEN%s" % (n, "" if n == 1 else "S"), (tk.centerx + 16, tk.centery), 30, SIG_GOLD,
                       anchor="center", shadow=False)
        # ---- left: the Signature cards
        left = pygame.Rect(40, 136, 900, 830)
        self.draw_glass(w, left, radius=30, alpha=150, edge=SIG_GOLD)
        self.home_text(w, "SIGNATURE CARDS", (left.x + 34, left.y + 34), 30, (255, 226, 150), shadow=False)
        for cid, cr, btn in L["cards"]:
            card = self.cards[cid]
            owned = self.owns(card)
            g = self.home_glow((cr.w + 160, cr.h + 120), (255, 200, 90), 60)
            w.blit(g, g.get_rect(center=cr.center))
            self.blit_card(w, card, cr, dim=False)
            self.home_text(w, card["name"].upper(), (btn.centerx, cr.bottom + 52), 34, WHITE, anchor="center",
                           max_w=btn.w)
            self.home_text(w, "%d OVR  -  %s" % (card["rating"], card["pos"]), (btn.centerx, cr.bottom + 96), 24,
                           self.HOME_MUTED, anchor="center", shadow=False)
            can = not owned and n >= SIG_TOKEN_PRICE
            hov = btn.collidepoint(mouse)
            if can:
                img = self.home_button(btn.size, hov, top=(255, 214, 110), bottom=(200, 140, 40), lip=(110, 70, 10))
                w.blit(img, (btn.x, btn.y - (3 if hov else 0)))
            else:
                self.draw_glass(w, btn, radius=btn.h // 2, alpha=150, edge=(140, 120, 80))
            txt = "AT YOUR CLUB" if owned else "SIGN  -  %d TOKENS" % SIG_TOKEN_PRICE
            col = (60, 34, 4) if can else ((150, 230, 160) if owned else (200, 190, 170))
            self.home_text(w, txt, (btn.centerx, btn.centery - (3 if can and hov else 0)), 28, col, anchor="center",
                           shadow=False, max_w=btn.w - 30)
        # ---- right: the quest
        right = pygame.Rect(980, 136, 900, 830)
        self.draw_glass(w, right, radius=30, alpha=150, edge=SIG_GOLD)
        q = self.archive_next_quest()
        done_all = q is None
        q = q or ARCHIVE_QUESTS[-1]
        is_open = self.archive_quest_open(q)
        A = self.archive()
        self.home_text(w, "ARCHIVE QUEST  -  LEVEL %d" % q[1], (right.x + 34, right.y + 34), 26, self.HOME_MUTED,
                       shadow=False)
        self.home_text(w, q[2], (right.x + 34, right.y + 96), 52, (255, 226, 150))
        sub = ("ALL DONE  -  A NEW QUEST OPENS EVERY %d LEVELS" % ARCHIVE_EVERY) if done_all else \
            ("EACH TASK +%d TOKEN  -  ALL %d +%d MORE  -  ONE QUEST IS ONE SIGNATURE CARD"
             % (ARCHIVE_TASK_TOKENS, len(q[3]), ARCHIVE_BONUS_TOKENS)) if is_open else \
            ("OPENS AT LEVEL %d  -  YOU'RE LEVEL %d" % (q[1], self.player_level()))
        self.home_text(w, sub, (right.x + 34, right.y + 152), 22, SIG_GOLD if is_open else (255, 160, 150),
                       shadow=False, max_w=right.w - 68)
        for (key, text), r, b in zip(q[3], L["tasks"], L["claims"]):
            done, claimed = A["done"].get(key), A["claimed"].get(key)
            self.draw_glass(w, r, radius=22, alpha=170 if is_open else 90,
                            edge=(120, 230, 140) if done and not claimed else ((90, 110, 150) if claimed else
                                                                                (110, 130, 190)))
            box = pygame.Rect(r.x + 24, r.centery - 24, 48, 48)
            pygame.draw.rect(w, (8, 12, 24), box, border_radius=10)
            pygame.draw.rect(w, (120, 230, 140) if done else (110, 120, 150), box, 3, border_radius=10)
            if done:
                pygame.draw.lines(w, (120, 230, 140), False, [(box.x + 10, box.centery), (box.x + 20, box.bottom - 12),
                                                              (box.right - 9, box.y + 11)], 6)
            if not is_open:                                      # a padlock over the box
                pygame.draw.rect(w, (150, 140, 120), (box.x + 12, box.y + 20, 24, 18))
                pygame.draw.arc(w, (150, 140, 120), (box.x + 15, box.y + 8, 18, 24), 0, math.pi, 4)
            words = self.wrap_lines(text, self.font_s, r.w - 320)
            top = r.centery - len(words[:3]) * 21
            for k, ln in enumerate(words[:3]):
                w.blit(ln, (r.x + 96, top + k * 42))
            if done and not claimed:
                self.draw_quest_button(w, b, "CLAIM", mouse)
            else:
                self.home_text(w, "CLAIMED" if claimed else "+%d TOKEN" % ARCHIVE_TASK_TOKENS, b.center, 26,
                               (120, 220, 150) if claimed else SIG_GOLD, anchor="center", shadow=False)
        br = L["bonus"]
        ready = self.archive_bonus_ready(q)
        self.draw_glass(w, br, radius=22, alpha=170, edge=SIG_GOLD if ready else (110, 130, 190))
        self.draw_sig_token(w, (br.x + 48, br.centery), 26)
        self.home_text(w, "ALL %d TASKS: +%d SIGNATURE TOKENS" % (len(q[3]), ARCHIVE_BONUS_TOKENS),
                       (br.x + 96, br.centery), 28, WHITE, shadow=False, max_w=br.w - 330)
        if ready:
            self.draw_quest_button(w, L["bonus_btn"], "CLAIM", mouse)
        else:
            self.home_text(w, "CLAIMED" if A["bonus"].get(q[0]) else "+%d TOKENS" % ARCHIVE_BONUS_TOKENS,
                           L["bonus_btn"].center, 26, (120, 220, 150) if A["bonus"].get(q[0]) else SIG_GOLD,
                           anchor="center", shadow=False)
        nxt = (q[1] // ARCHIVE_EVERY + 1) * ARCHIVE_EVERY
        self.home_text(w, "NEXT QUEST: LEVEL %d" % nxt, (right.centerx, right.bottom - 40), 24, self.HOME_MUTED,
                       anchor="center", shadow=False)
        self.draw_fx(w, 1.0 / FPS)
        if self.store_confirm is not None:
            self.draw_store_confirm(w)

    # ================================================================ THE GAME BOXES (Neymar Jr, Mario Kempes)
    def box_entry(self):
        """The Game Box on screen (GAME_BOXES row). One box now (4 Nov): Mario Kempes's."""
        key = getattr(self, "box_key", GAME_BOXES[0][0])
        return next((b for b in GAME_BOXES if b[0] == key), GAME_BOXES[0])

    def box_card(self):
        return self.cards[self.box_entry()[1]]

    def box_art_for(self, cid):
        arts = self.__dict__.setdefault("_box_arts", {})
        name = next((b[4] for b in GAME_BOXES if b[1] == cid), "box_neymar")
        if name not in arts:
            arts[name] = load_pixel(name, (330, 462), fit=True, quiet=True) or self.box_art
        return arts[name]

    def event_state(self):
        ev = self.save.setdefault(self.box_entry()[2], {})
        if ev.get("v") != BOX_VERSION:                     # the box was rebalanced: fresh start
            ev.clear()
            ev.update({"v": BOX_VERSION, "claimed": [], "players": []})
        if len(ev["players"]) < 5:
            normal = [c for c in self.cards.values() if c["design"] not in ("icon", "signature")
                      and c["kind"] in ("wc", "club")]

            def pick(lo, hi, n=1, taken=()):
                pool = [c["id"] for c in normal if lo <= c["rating"] <= hi and c["id"] not in taken]
                return random.sample(pool, min(n, len(pool)))
            chosen = pick(55, 71) + pick(72, 89) + pick(90, 98)           # bad, alright, good
            chosen += pick(99, 112, 2, chosen)                            # two pool A jackpots
            ev["players"] = chosen
            self.write_save()
        return ev

    def event_price(self):
        n = len(self.event_state()["claimed"])
        return NEYMAR_PRICES[n] if n < len(NEYMAR_PRICES) else None

    def open_event(self, box=None):
        if box is not None:
            self.box_key = box
        self.event_state()
        self.event_spin = None
        self.event_popup = None
        self.state = EVENT

    def event_layout(self):
        tiles = [pygame.Rect(470 + (i % 4) * 218, 180 + (i // 4) * 188, 200, 170) for i in range(12)]
        return {"tiles": tiles, "prize": pygame.Rect(1370, 160, 380, 560),
                "buy": pygame.Rect(1370, 800, 420, 110), "back": pygame.Rect(40, 30, 200, 70),
                "boxes": [(b[0], pygame.Rect(470 + i * 330, 930, 310, 80)) for i, b in enumerate(GAME_BOXES)]
                if len(GAME_BOXES) > 1 else []}

    def event_reward_card(self, i):
        kind, val = NEYMAR_REWARDS[i]
        if kind == "neymar":                               # (the box's Signature card - either box)
            return self.box_card()
        if kind in ("player", "jackpot_player"):
            ids = self.event_state()["players"]
            return self.cards.get(ids[val]) if val < len(ids) else None
        return None

    def box_odds(self, left):
        """Chance of each unclaimed reward on the next draw."""
        ney = len(NEYMAR_REWARDS) - 1
        if left == [ney]:
            return {ney: 1.0}                              # pity: the last draw is Neymar
        odds = {}
        jack = [i for i in left if NEYMAR_REWARDS[i][0].startswith("jackpot")]
        filler = [i for i in left if i != ney and i not in jack]
        if ney in left:
            odds[ney] = NEYMAR_ODDS
        rest = 1.0 - sum(odds.values())
        if filler:
            for i in jack:
                odds[i] = JACKPOT_ODDS
            rest -= JACKPOT_ODDS * len(jack)
            for i in filler:
                odds[i] = rest / len(filler)
        else:
            for i in jack:
                odds[i] = rest / len(jack)
        return odds

    def event_click(self, pos):
        L = self.event_layout()
        if self.event_popup is not None:
            self.event_popup = None
            return
        if self.event_spin is not None:
            return
        if L["back"].collidepoint(pos.x, pos.y):
            self.open_store()
            return
        if L["buy"].collidepoint(pos.x, pos.y):
            self.event_draw()
            return
        for key, r in L["boxes"]:                          # the other Game Box
            if r.collidepoint(pos.x, pos.y):
                self.open_event(key)
                return
        for i, r in enumerate(L["tiles"]):
            card = self.event_reward_card(i)
            if card is not None and r.collidepoint(pos.x, pos.y):
                self.card_click(card, lambda: None)            # double-click = stats
        if L["prize"].collidepoint(pos.x, pos.y):
            self.card_click(self.box_card(), lambda: None)

    def event_draw(self):
        price = self.event_price()
        if price is None:
            return False
        if self.save["coins"] < price:
            self.toast("NOT ENOUGH COINS - NEED %d" % price, (255, 120, 120))
            return False
        self.save["coins"] -= price
        ev = self.event_state()
        left = [i for i in range(len(NEYMAR_REWARDS)) if i not in ev["claimed"]]
        odds = self.box_odds(left)
        target = random.choices(list(odds), weights=list(odds.values()))[0]
        hops = []
        for _ in range(16 if len(left) > 1 else 1):
            hops.append(random.choice([i for i in left if not hops or i != hops[-1]] or left))
        hops.append(target)
        self.event_spin = {"hops": hops, "step": 0, "timer": 0.0, "interval": 0.07}
        self.write_save()
        return True

    def update_event(self, dt):
        sp = self.event_spin
        if sp is None:
            return
        sp["timer"] += dt
        if sp["timer"] < sp["interval"]:
            return
        sp["timer"] = 0.0
        if sp["step"] < len(sp["hops"]) - 1:
            sp["step"] += 1
            sp["interval"] *= 1.14
            return
        self.event_spin = None
        self.event_grant(sp["hops"][-1])

    def event_grant(self, i):
        ev = self.event_state()
        if i in ev["claimed"]:
            return
        ev["claimed"].append(i)
        kind, val = NEYMAR_REWARDS[i]
        if kind in ("coins", "jackpot_coins"):
            self.save["coins"] += val
            jack = kind == "jackpot_coins"
            self.event_popup = {"title": "+%d COINS" % val, "sub": "JACKPOT!" if jack else "", "kind": "coins"}
        elif kind == "training":
            self.save["training_coins"] = self.save.get("training_coins", 0) + val
            self.event_popup = {"title": "+%d TRAINING POINTS" % val, "sub": "LEVEL UP A PLAYER", "kind": kind}
        elif kind == "puzzle":
            self.save["puzzle_points"] = self.save.get("puzzle_points", 0) + val
            self.event_popup = {"title": "+%d PUZZLE POINTS" % val, "sub": "UPGRADE A PLAYER'S GEM", "kind": kind}
        else:
            card = self.event_reward_card(i)
            count = self.give_card(card)
            self.pack_reveal = {"card": card, "t": 0.0, "count": count, "pack": 0,
                                "tier": self.card_pool(card), "opened": True, "back": "event",
                                "art": self.box_art_for(self.box_card()["id"])}
            self.fx = []
            self.state = PACK_OPEN
        self.write_save()

    def draw_reward_icon(self, w, kind, centre, size=1.0):
        x, y = centre
        s = size
        if kind == "coins":
            for j in range(3):
                r = pygame.Rect(0, 0, int(80 * s), int(34 * s))
                r.center = (x + (j - 1) * int(18 * s), y + int(14 * s) - j * int(16 * s))
                pygame.draw.ellipse(w, (190, 140, 20), r.move(0, int(6 * s)))
                pygame.draw.ellipse(w, YELLOW, r)
                pygame.draw.ellipse(w, (255, 244, 170), r.inflate(-int(40 * s), -int(16 * s)))
        elif kind == "training":
            pygame.draw.circle(w, (30, 90, 200), (x, y), int(40 * s))
            pygame.draw.circle(w, (140, 200, 255), (x, y), int(40 * s), max(2, int(6 * s)))
            t = self.font_m.render("T", True, WHITE)
            t = pygame.transform.smoothscale(t, (int(t.get_width() * s), int(t.get_height() * s)))
            w.blit(t, t.get_rect(center=(x, y)))
        elif kind == "puzzle":
            c = (170, 70, 220)
            pygame.draw.rect(w, c, (x - int(34 * s), y - int(26 * s), int(68 * s), int(60 * s)), border_radius=6)
            pygame.draw.circle(w, c, (x, y - int(30 * s)), int(15 * s))
            pygame.draw.circle(w, c, (x + int(38 * s), y + int(4 * s)), int(15 * s))
            pygame.draw.rect(w, (230, 180, 255), (x - int(34 * s), y - int(26 * s), int(68 * s), int(60 * s)),
                             max(2, int(4 * s)), border_radius=6)

    def draw_event(self, w):
        bgs = self.__dict__.setdefault("_box_bgs", {})
        key = self.box_entry()[0]
        if key not in bgs:                                 # each box its own flag (1 Nov)
            bgs[key] = opaque(load_pixel("event_bg_" + key, (WIDTH, HEIGHT), quiet=True) if key != "neymar" else None) \
                or self.event_bg
        if bgs[key] is not None:
            w.blit(bgs[key], (0, 0))
        else:
            w.fill((0, 110, 52))
        L = self.event_layout()
        ev = self.event_state()
        mouse = pygame.mouse.get_pos()
        self.draw_back_button(w)
        t = self.outlined(self.box_entry()[3], self.font_m, WHITE, 1.0, width=4)
        w.blit(t, (270, 36))
        # currencies, top right
        self.draw_coins(w)
        cur = "%d TRAINING   %d PUZZLE" % (self.save.get("training_coins", 0), self.save.get("puzzle_points", 0))
        img = self.font_s.render(cur, True, (220, 236, 255))
        w.blit(img, img.get_rect(topright=(WIDTH - 60, 104)))
        # left: the box's Signature player (his bust, or his card figure)
        sig = self.box_card()
        face = self.icon_faces.get(sig["id"])
        if face is not None:
            big = pygame.transform.scale(face, (384, 384))
            w.blit(big, (48, 196))
        elif self.card_faces.get(sig["id"]) is not None:
            fig = self.card_faces[sig["id"]]
            k = 384.0 / fig.get_height()
            big = pygame.transform.scale(fig, (int(fig.get_width() * k), 384))
            w.blit(big, big.get_rect(midbottom=(240, 600)))
        pts = []
        for i in range(40):
            tt = i / 39.0
            pts.append((70 + tt * 300, 560 + math.sin(tt * 13.0) * 26 * (1 - tt * 0.5) - tt * 40))
        pygame.draw.lines(w, (255, 230, 130), False, pts, 6)
        plate = pygame.Rect(40, 610, 400, 120)
        veil = pygame.Surface(plate.size, pygame.SRCALPHA)
        veil.fill((0, 30, 16, 200))
        w.blit(veil, plate.topleft)
        for txt, y, col, font in ((sig["name"].upper(), plate.y + 38, WHITE, self.font_m),
                                  ("%d OVR  -  SIGNATURE" % sig["rating"], plate.y + 90, (255, 226, 120), None)):
            img = self.label(txt, plate.w - 30, col, font)
            w.blit(img, img.get_rect(center=(plate.centerx, y)))
        # reward tiles
        sp = self.event_spin
        lit = sp["hops"][sp["step"]] if sp else None
        for i, r in enumerate(L["tiles"]):
            kind, val = NEYMAR_REWARDS[i]
            claimed = i in ev["claimed"]
            jack = kind.startswith("jackpot")
            face = (255, 222, 120) if jack else (246, 242, 226)
            pygame.draw.rect(w, face if not claimed else (120, 124, 120), r, border_radius=10)
            if jack:
                tag = self.fit_text("JACKPOT", self.font_s, (150, 40, 20), r.w * 0.7, 24)
                w.blit(tag, tag.get_rect(center=(r.centerx, r.y + 18)))
            if kind == "jackpot_coins":
                kind = "coins"
            if kind in ("coins", "training", "puzzle"):
                self.draw_reward_icon(w, kind, (r.centerx, r.y + 66), 0.8)
                amt = self.label("x%d" % val, r.w - 30, INK, self.font_m)
                w.blit(amt, amt.get_rect(center=(r.centerx, r.bottom - 32)))
                if kind != "coins":
                    tag = self.font_s.render("LATER UPDATE", True, (120, 80, 160))
                    k = min(1.0, (r.w - 24) / tag.get_width(), 22 / tag.get_height())
                    tag = pygame.transform.smoothscale(tag, (int(tag.get_width() * k), int(tag.get_height() * k)))
                    w.blit(tag, tag.get_rect(center=(r.centerx, r.y + 18)))
            else:
                card = self.event_reward_card(i)
                if card is not None:
                    cr = pygame.Rect(0, 0, 92, 128)
                    cr.center = (r.centerx, r.centery + (8 if jack else 0))
                    self.draw_card(w, card, cr)
            if claimed:
                veil = pygame.Surface(r.size, pygame.SRCALPHA)
                veil.fill((0, 0, 0, 120))
                w.blit(veil, r.topleft)
                pygame.draw.lines(w, (90, 230, 110), False, [(r.centerx - 40, r.centery), (r.centerx - 10, r.centery + 30),
                                                             (r.centerx + 46, r.centery - 36)], 12)
            border = YELLOW if lit == i else (WHITE if r.collidepoint(mouse) else (30, 60, 34))
            pygame.draw.rect(w, border, r, 8 if lit == i else 3, border_radius=10)
        # the prize
        pr = L["prize"]
        claimed = (len(NEYMAR_REWARDS) - 1) in ev["claimed"]
        pygame.draw.rect(w, (250, 238, 200), pr, border_radius=14)
        cr = pygame.Rect(0, 0, 320, 444)
        cr.center = (pr.centerx, pr.centery - 10)
        self.draw_card(w, sig, cr, dim=claimed)
        if claimed:
            self.centre_text_at(w, "CLAIMED", pr.centerx, pr.bottom - 30, (40, 140, 60), self.font_m)
        pygame.draw.rect(w, YELLOW if lit == len(NEYMAR_REWARDS) - 1 else (190, 150, 50), pr,
                         10 if lit == len(NEYMAR_REWARDS) - 1 else 5, border_radius=14)
        # bottom bar
        bar = pygame.Rect(470, 800, 854, 110)
        veil = pygame.Surface(bar.size, pygame.SRCALPHA)
        veil.fill((250, 238, 200, 230))
        w.blit(veil, bar.topleft)
        for txt, y, col in (("EACH REWARD ONCE  -  JACKPOTS 1%% EACH  -  %s 0.05%% (SURE ON THE LAST DRAW)"
                             % sig["name"].upper(),
                             bar.y + 36, INK),
                            ("DRAW %d OF %d" % (min(len(ev["claimed"]) + 1, len(NEYMAR_REWARDS)),
                                                len(NEYMAR_REWARDS)), bar.y + 80, (90, 90, 90))):
            img = self.font_s.render(txt, True, col)
            k = min(1.0, (bar.w - 40) / img.get_width())
            img = pygame.transform.smoothscale(img, (int(img.get_width() * k), int(img.get_height() * k)))
            w.blit(img, img.get_rect(center=(bar.centerx, y)))
        for key, r in L["boxes"]:                          # 1 Nov: a tab for each Game Box
            entry = next(b for b in GAME_BOXES if b[0] == key)
            on = entry == self.box_entry()
            pygame.draw.rect(w, (250, 238, 200) if on else (20, 70, 40), r, border_radius=20)
            pygame.draw.rect(w, YELLOW if r.collidepoint(mouse) else (WHITE if on else (120, 170, 130)), r, 4,
                             border_radius=20)
            lab = self.label(self.cards[entry[1]]["name"].upper(), r.w - 30, INK if on else WHITE)
            w.blit(lab, lab.get_rect(center=r.center))
        price = self.event_price()
        b = L["buy"]
        afford = price is not None and self.save["coins"] >= price
        col = (40, 170, 70) if afford else (90, 100, 92)
        pygame.draw.rect(w, col, b, border_radius=50)
        pygame.draw.rect(w, YELLOW if b.collidepoint(mouse) and afford else WHITE, b, 6, border_radius=50)
        label = "SOLD OUT" if price is None else ("FREE" if price == 0 else "%d COINS" % price)
        lab = self.label(label, b.w - 40, WHITE, self.font_m)
        w.blit(lab, lab.get_rect(center=b.center))
        # reward popup
        if self.event_popup is not None:
            wash(w, (0, 0, 0, 170))
            box = pygame.Rect(0, 0, 900, 420)
            box.center = (WIDTH // 2, HEIGHT // 2)
            pygame.draw.rect(w, (250, 238, 200), box, border_radius=20)
            pygame.draw.rect(w, YELLOW, box, 8, border_radius=20)
            self.draw_reward_icon(w, self.event_popup["kind"], (box.centerx, box.y + 120), 1.8)
            self.centre_text_at(w, self.event_popup["title"], box.centerx, box.y + 250, INK, self.font_l)
            if self.event_popup["sub"]:
                self.centre_text_at(w, self.event_popup["sub"], box.centerx, box.y + 320, (110, 90, 140))
            self.centre_text_at(w, "CLICK TO CONTINUE", box.centerx, box.bottom - 40, (90, 90, 90))

    # ---- main menu (like the sketch: art carousel | title + buttons) -----------------
    MENU_ITEMS = ("PLAY", "STORE", "TEAM", "MAIL", "QUIT")
    SLIDE_SECONDS = 10.0

    def menu_items(self):
        return self.MENU_ITEMS                    # PLAY opens the tabbed screen further down

    def menu_layout(self):
        n = len(self.menu_items())
        step = 128 if n <= 5 else 108
        y0 = 330 + (5 - n) * 64 + (24 if n > 5 else 0)     # 4 buttons sit centred where 5 would
        return [pygame.Rect(1180, y0 + i * step, 600, 104 if n <= 5 else 92) for i in range(n)]

    def slide_rect(self):
        return pygame.Rect(210, 170, 560, 680)

    def slide_controls(self):
        n = max(1, len(self.slides))
        dots = [pygame.Rect(0, 0, 30, 30) for _ in range(n)]
        x0 = 490 - (n - 1) * 26 - 110
        for i, r in enumerate(dots):
            r.center = (x0 + i * 52, 905)
        nxt = pygame.Rect(0, 0, 170, 58)
        nxt.center = (x0 + (n - 1) * 52 + 150, 905)
        return dots, nxt

    def current_slide(self):
        now = pygame.time.get_ticks() / 1000.0
        if not hasattr(self, "slide_t0"):
            self.slide_t0, self.slide = now, 0
        if now - self.slide_t0 >= self.SLIDE_SECONDS:     # every 10 s the art changes
            self.slide = (self.slide + 1) % max(1, len(self.slides))
            self.slide_t0 = now
        return self.slide

    def set_slide(self, i):
        self.slide = i % max(1, len(self.slides))
        self.slide_t0 = pygame.time.get_ticks() / 1000.0

    def title_click(self, pos):
        if getattr(self, "menu_page", "main") == "play":
            self.play_click(pos)
            return
        if HOME_V2:
            self.home_click(pos)
            return
        dots, nxt = self.slide_controls()
        if nxt.collidepoint(pos.x, pos.y):
            self.set_slide(self.current_slide() + 1)
            return
        for i, r in enumerate(dots):
            if r.collidepoint(pos.x, pos.y):
                self.set_slide(i)
                return
        if self.slide_rect().collidepoint(pos.x, pos.y):
            s = self.current_slide()
            if s == 0:
                self.menu_page = "play"                    # PLAY NOW
            elif s == 1:
                self.menu_item("WORLD CUP")               # the champions art -> World Cup
            elif s == 2:
                self.open_pack_view(0)                     # World Cup pack
            elif s == 3:
                self.open_event()                          # the Game Box (Mario Kempes)
            elif s == 4:
                self.open_stars()                          # Star Signing
            return
        for item, rect in zip(self.menu_items(), self.menu_layout()):
            if rect.collidepoint(pos.x, pos.y):
                self.menu_item(item)
                return

    def menu_item(self, item):
        if item == "PLAY":
            self.menu_page = "play"
        elif item == "BACK":
            self.menu_page = "main"
        elif item == "WORLD CUP":                          # the champions slide on the front page
            self.enter_world_cup()
        elif item == "STORE":
            self.open_store()
        elif item == "TEAM":
            self.state = MYCLUB
        elif item == "MAIL":
            self.open_mail()
        elif item == "PROFILE":
            self.open_profile()
        elif item == "QUESTS":
            self.open_quests()
        elif item == "QUIT":
            self.quit_requested = True

    # ---- PLAY: one tab per way to play -------------------------------------------------
    # (key, what the tab says, the two lines under the title, what it pays, the button)
    # The order here is the order on screen. Each key is started by play_go().
    PLAY_TABS = (
        ("wc", "WORLD CUP",
         ("PICK A NATION AND WIN SEVEN ROUNDS.", "LOSE ONCE AND THE RUN IS OVER."),
         "COINS + XP EVERY MATCH   -   +%d XP FOR THE TROPHY" % XP_TROPHY, "PLAY"),
        ("club", "CLUB FOOTBALL",
         ("A LEAGUE SEASON WITH YOUR OWN FIVE,", "IN YOUR KIT, UNDER YOUR NAME."),
         "COINS + XP EVERY MATCH   -   +%d XP FOR THE TITLE" % XP_TROPHY, "PLAY"),
        ("practice", "PRACTICE",
         ("NO CLOCK AND NO SCORE. ADD ROBOTS,", "TRY THROWS, LEARN HOW THE BALL MOVES."),
         "NOTHING TO WIN, NOTHING TO LOSE", "START"),
        ("free", "FREE MODE",
         ("ANY PLAYER YOU OWN AGAINST ANY OTHER.", "YOU PICK BOTH SIDES AND THE DIFFICULTY."),
         "%d TO %d COINS A MATCH   -   NO XP" % FREE_REWARD, "PLAY"),
        ("h2h", "HEAD TO HEAD",
         ("A RANKED MATCH AGAINST A REAL PLAYER.", "YOUR BEST SQUAD CARD GOES OUT FOR YOU."),
         "RANK POINTS ON THE LADDER", "FIND A MATCH"),
        ("impossible", "IMPOSSIBLE MODE",
         ("THE WORLD CUP WITH EVERYTHING TURNED UP:", "OPPONENTS +%d, NO HESITATION, TWICE AS QUICK." % IMPOSSIBLE_BOOST),
         "%dX COINS   +   ESSENCE:  WIN %d,  LOSS %d,  TROPHY +%d" % (
             IMPOSSIBLE_COINS, ESSENCE_REWARD["win"], ESSENCE_REWARD["loss"], ESSENCE_TROPHY), "PLAY"),
        ("gauntlet", "THE GAUNTLET",
         ("TEN OPPONENTS, EACH ONE HARDER. LOSE ONCE", "AND IT'S OVER. NUMBER 10 IS THE MACHINE."),
         "UP TO %s COINS  +  A POOL A CARD  +  A TROPHY" % "{:,}".format(sum(r[6] for r in GT_RUNGS) + GT_WIN_COINS),
         "PLAY"),
    )
    PLAY_GREEN = ((20, 46, 27), (13, 30, 18), (226, 232, 226))      # panel, a resting tab, the edge
    PLAY_RED = ((64, 14, 20), (40, 12, 16), (255, 120, 110))
    PLAY_IRON = ((34, 18, 30), (24, 12, 20), (255, 150, 110))

    def play_pal(self, key):
        return {"impossible": self.PLAY_RED, "gauntlet": self.PLAY_IRON}.get(key, self.PLAY_GREEN)

    def play_layout(self):
        n = len(self.PLAY_TABS)
        gap, x0, x1 = 12, 60, WIDTH - 60
        tw = (x1 - x0 - gap * (n - 1)) / float(n)
        tabs = [pygame.Rect(int(round(x0 + i * (tw + gap))), 196, int(tw), 96) for i in range(n)]
        panel = pygame.Rect(x0, 288, x1 - x0, 732)
        art = pygame.Rect(panel.x + 34, panel.y + 34, 720, panel.h - 68)
        go = pygame.Rect(art.right + 50, panel.bottom - 34 - 124, 520, 124)
        shop = pygame.Rect(go.right + 30, go.y, panel.right - 34 - go.right - 30, 124)
        return {"tabs": tabs, "panel": panel, "art": art, "go": go, "shop": shop}

    def play_status(self, key):
        """(the line above the button, its colour, whether the button does anything)."""
        calm, warn = (204, 224, 206), (255, 160, 150)
        if key in ("wc", "impossible"):
            if key == "impossible" and not self.impossible_unlocked():
                return ("YOU ARE LEVEL %d  -  IT OPENS AT LEVEL %d" % (self.level(), IMPOSSIBLE_LEVEL), warn, False)
            run = self.run_of("normal" if key == "wc" else "impossible")
            team, rnd = run.get("team"), run.get("round", 0)
            if team is None or not self.teams:
                return ("NO RUN YET  -  PICK A NATION", calm, True)
            code = self.teams[team]["name"]
            name = NATION_NAMES.get(code, code)
            if rnd >= len(ROUNDS):
                return ("%s WON IT  -  PICK A NATION TO GO AGAIN" % name, YELLOW, True)
            if run.get("opponents"):
                return ("RUN IN PROGRESS:  %s,  ROUND %d OF %d" % (name, rnd + 1, len(ROUNDS)), YELLOW, True)
            return ("%s PICKED  -  NOT STARTED YET" % name, calm, True)
        if key == "club":
            if len(self.save["squad"]) < SQUAD_SIZE:
                return ("NEEDS %d PLAYERS  -  PICK THEM IN TEAM" % SQUAD_SIZE, warn, True)
            if self.season_running() and self.club_round < CLUB_ROUNDS:
                return ("SEASON IN PROGRESS:  ROUND %d OF %d" % (self.club_round + 1, CLUB_ROUNDS), YELLOW, True)
            return ("A NEW SEASON IS READY", calm, True)
        if key == "practice":
            return ("YOU PLAY AS THE FIRST PLAYER IN YOUR SQUAD", calm, True)
        if key == "gauntlet":
            run = self.gt_run()
            if run is not None:
                return ("RUN LIVE:  RUNG %d OF %d" % (run["rung"] + 1, GT_LEN), YELLOW, True)
            if len(self.save["squad"]) < SQUAD_SIZE:
                return ("NEEDS %d PLAYERS  -  PICK THEM IN TEAM" % SQUAD_SIZE, warn, True)
            return ("BEST: %d / %d  -  A NEW RUN IS READY" % (int(self.gt().get("best", 0)), GT_LEN), calm, True)
        owned = self.owned_cards()
        if key == "free":
            if not owned:
                return ("YOU DON'T OWN ANY PLAYERS YET", warn, False)
            return ("%d PLAYERS TO CHOOSE FROM" % len(owned), calm, True)
        if key == "h2h":
            if not self.net.on:
                return ("ONLINE ONLY  -  PLAY ON THE WEBSITE", warn, False)
            if not owned:
                return ("YOU DON'T OWN ANY PLAYERS YET", warn, False)
            if self.searching:
                return ("LOOKING FOR AN OPPONENT...", CYAN, False)
            return ("RANKED  -  WIN AND YOU CLIMB, LOSE AND YOU DROP", CYAN, True)
        return ("", calm, True)

    def play_go(self, key):
        if key == "wc":
            self.enter_world_cup()
        elif key == "club":
            self.mode = "club"
            self.go_to_club()
        elif key == "practice":
            self.start_practice()
        elif key == "free":
            self.open_freeplay()
        elif key == "h2h":
            self.find_online()                 # says so itself when there is no website behind it
        elif key == "impossible":
            self.enter_impossible()            # ...and so does this, below level 5
        elif key == "gauntlet":
            self.enter_gauntlet()

    def play_click(self, pos):
        L = self.play_layout()
        for i, r in enumerate(L["tabs"]):
            if r.collidepoint(pos.x, pos.y):
                self.play_tab = i
                return
        key = self.PLAY_TABS[self.play_tab % len(self.PLAY_TABS)][0]
        if L["go"].collidepoint(pos.x, pos.y):
            self.play_go(key)
        elif key == "impossible" and L["shop"].collidepoint(pos.x, pos.y):
            self.open_essence()

    def draw_padlock(self, w, centre, s, col):
        x, y = int(centre[0]), int(centre[1])
        pygame.draw.circle(w, col, (x, y - int(s * 0.30)), int(s * 0.42), max(3, int(s * 0.16)))
        body = pygame.Rect(0, 0, int(s * 1.16), int(s * 0.86))
        body.midtop = (x, y - int(s * 0.22))
        pygame.draw.rect(w, col, body, border_radius=max(2, int(s * 0.10)))
        pygame.draw.circle(w, (30, 26, 30), (x, body.centery - int(s * 0.04)), max(2, int(s * 0.12)))
        pygame.draw.rect(w, (30, 26, 30), (x - max(1, int(s * 0.05)), body.centery, max(2, int(s * 0.10)),
                                           int(s * 0.24)))

    def draw_play_art(self, w, key, box, t):
        """The picture on the left of a tab's panel - put together from sprites the game already has."""
        cx = box.centerx
        if key == "wc":
            if self.wc_badge is not None:
                b = fit_flag(self.wc_badge, 300, 330)
                w.blit(b, b.get_rect(center=(cx, box.y + 200)))
            flags = [tm["flag"] for tm in self.teams if tm.get("flag") is not None]
            for i, f in enumerate(flags[:12]):
                r_, c = divmod(i, 6)
                img = fit_flag(f, 96, 60)
                w.blit(img, img.get_rect(center=(box.x + 80 + c * 112, box.y + 452 + r_ * 96)))
        elif key == "club":
            name = self.label(self.save["team"]["name"].upper(), box.w - 60, YELLOW, self.font_m)
            w.blit(name, name.get_rect(center=(cx, box.y + 70)))
            rivals = self.clubs[:len(CLUBS)]                     # everyone but your own club
            sub = self.label("AGAINST %d CLUBS" % len(rivals), box.w - 60, (204, 224, 206), self.font_s)
            w.blit(sub, sub.get_rect(center=(cx, box.y + 130)))
            cols = 7
            rows = max(1, math.ceil(len(rivals) / float(cols)))
            step_y = min(140, (box.h - 210) / float(rows))
            for i, c in enumerate(rivals):
                if c["badge"] is None:
                    continue
                r_, k = divmod(i, cols)
                img = fit_flag(c["badge"], 78, 90)
                w.blit(img, img.get_rect(center=(box.x + 72 + k * 96, int(box.y + 240 + r_ * step_y))))
        elif key == "practice":
            for i, mode in enumerate(("EASY", "MEDIUM", "HARD")):
                x = box.x + 140 + i * 220
                look = self.robot_look(mode)
                if any(look.values()):
                    self.draw_look_preview(w, look, (x, box.y + 300))
                self.centre_text_at(w, mode, x, box.y + 560, (204, 224, 206))
            self.centre_text_at(w, "PRACTICE ROBOTS", cx, box.y + 60, YELLOW)
        elif key in ("free", "h2h"):
            owned = self.owned_cards()
            squad = [c for c in owned if c["id"] in self.save["squad"]] or owned
            mine = max(squad, key=lambda c: c["rating"]) if squad else None
            other = next((c for c in owned if mine is not None and c["id"] != mine["id"]), None)
            if key == "free":
                for card, x in ((mine, box.x + 180), (other, box.x + 540)):
                    r = pygame.Rect(0, 0, 250, 347)
                    r.center = (x, box.y + 300)
                    if card is not None:
                        self.blit_card(w, card, r)
                    elif self.card_back is not None:
                        w.blit(scaled(self.card_back, r.size), r)
                self.centre_text_at(w, "YOU PICK BOTH", cx, box.y + 560, (204, 224, 206))
            else:
                for card, x, flip in ((mine, box.x + 190, False), (other or mine, box.x + 530, True)):
                    look = self.card_original_look(card) if card is not None else None
                    if look and any(look.values()):
                        self.draw_look_preview(w, look, (x, box.y + 300))
                self.centre_text_at(w, "RANKED ONLINE", cx, box.y + 60, CYAN)
                who = "%s GOES OUT FOR YOU" % mine["name"].upper() if mine is not None else ""
                lab = self.label(who, box.w - 60, (204, 224, 206), self.font_s)
                w.blit(lab, lab.get_rect(center=(cx, box.y + 560)))
            vs = self.outlined("VS", self.font_l, YELLOW, 0.8, width=4)
            w.blit(vs, vs.get_rect(center=(cx, box.y + 300)))
        elif key == "gauntlet":
            self.draw_gt_play_art(w, box, t)
        elif key == "impossible":
            open_ = self.impossible_unlocked()
            pulse = 0.5 + 0.5 * math.sin(t * 2.4)
            for k in range(3):                                   # rings breathing behind it
                rad = int(150 + k * 44 + pulse * 10)
                pygame.draw.circle(w, _shade(self.PLAY_RED[0], 1.5 - k * 0.22), (cx, box.y + 232), rad)
            if open_:
                self.draw_essence_icon(w, (cx, box.y + 226), 104)
                self.centre_text_at(w, "ESSENCE", cx, box.y + 60, ESSENCE_HOT)
                rows = (("WIN", ESSENCE_REWARD["win"]), ("LOSS", ESSENCE_REWARD["loss"]), ("TROPHY", ESSENCE_TROPHY))
                for i, (name, val) in enumerate(rows):
                    chip = pygame.Rect(0, 0, 204, 132)
                    chip.center = (box.x + 132 + i * 228, box.y + 540)
                    pygame.draw.rect(w, (34, 10, 14), chip, border_radius=14)
                    pygame.draw.rect(w, self.PLAY_RED[2], chip, 3, border_radius=14)
                    self.centre_text_at(w, name, chip.centerx, chip.y + 36, (236, 214, 210))
                    self.centre_text_at(w, "+%d" % val, chip.centerx, chip.y + 88, ESSENCE_HOT, self.font_m)
            else:
                self.draw_padlock(w, (cx, box.y + 240), 150, (214, 200, 200))
                self.centre_text_at(w, "LOCKED", cx, box.y + 60, (236, 214, 210))
                lv, into, need = level_from_xp(self.save.get("xp", 0))
                bar = pygame.Rect(box.x + 90, box.y + 520, box.w - 180, 40)
                done = clamp((lv - 1 + into / float(max(1, need))) / float(IMPOSSIBLE_LEVEL - 1), 0.0, 1.0)
                pygame.draw.rect(w, (26, 10, 14), bar, border_radius=10)
                pygame.draw.rect(w, self.PLAY_RED[2], (bar.x, bar.y, int(bar.w * done), bar.h), border_radius=10)
                pygame.draw.rect(w, WHITE, bar, 3, border_radius=10)
                self.centre_text_at(w, "LEVEL %d OF %d" % (lv, IMPOSSIBLE_LEVEL), cx, bar.bottom + 40, (236, 214, 210))

    def draw_play(self, w):
        w.blit(self.select_bg, (0, 0))
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        L = self.play_layout()
        self.draw_back_button(w)
        head = self.outlined("PLAY", self.font_l, WHITE, 0.9, width=4)
        w.blit(head, head.get_rect(center=(WIDTH // 2, 92)))
        self.draw_level(w, 290, 44, 420)
        self.draw_coins(w)
        self.draw_essence_count(w)
        cur = self.play_tab % len(self.PLAY_TABS)
        key, title, lines, pays, button = self.PLAY_TABS[cur]
        open_ = self.impossible_unlocked()
        pal = self.play_pal(key)
        panel = L["panel"]
        pygame.draw.rect(w, pal[0], panel)
        pygame.draw.rect(w, pal[2], panel, 5)
        # the tabs, drawn after the panel so the chosen one can sit on its top edge
        for i, (tab, rect) in enumerate(zip(self.PLAY_TABS, L["tabs"])):
            red = tab[0] == "impossible"
            tp = self.play_pal(tab[0])
            locked = red and not open_
            chosen = i == cur
            hover = rect.collidepoint(mouse) and not chosen
            if chosen:
                body = pygame.Rect(rect.x, rect.y, rect.w, rect.h + 4)          # runs into the panel
                pygame.draw.rect(w, tp[0], body)
                pygame.draw.lines(w, tp[2], False, [(body.x + 2, body.bottom - 5), (body.x + 2, body.y + 2),
                                                    (body.right - 3, body.y + 2), (body.right - 3, body.bottom - 5)], 5)
                pygame.draw.rect(w, YELLOW, (rect.x + 5, rect.y + 5, rect.w - 10, 7))
            else:
                r = rect.inflate(0, -12).move(0, 6)
                pygame.draw.rect(w, (34, 30, 32) if locked else tp[1], r)
                pygame.draw.rect(w, WHITE if hover else _shade(tp[2], 0.55), r, 3)
            col = YELLOW if chosen else ((150, 142, 146) if locked else WHITE)
            if locked:                                           # the tab itself says what opens it
                small = self.label(tab[1], rect.w - 36, (128, 120, 124), self.font_s)
                small = scaled_text(small, 0.62)
                w.blit(small, small.get_rect(center=(rect.centerx, rect.y + 28)))
                lab = self.label("LVL %d UNLOCK" % IMPOSSIBLE_LEVEL, rect.w - 76, YELLOW if chosen else (214, 200, 200),
                                 self.font_s)
                pos = lab.get_rect(center=(rect.centerx + 18, rect.y + 62))
                w.blit(lab, pos)
                self.draw_padlock(w, (pos.x - 22, pos.centery + 2), 20, (214, 200, 200))
            else:
                lab = self.label(tab[1], rect.w - 28, col, self.font_s)
                w.blit(lab, lab.get_rect(center=(rect.centerx, rect.centery + (3 if chosen else 0))))
        # the picture
        art = L["art"]
        pygame.draw.rect(w, _shade(pal[0], 0.62), art, border_radius=16)
        self.draw_play_art(w, key, art, t)
        pygame.draw.rect(w, _shade(pal[2], 0.7), art, 3, border_radius=16)
        # the words
        x = art.right + 50
        room = panel.right - 34 - x
        big = self.outlined("LVL %d UNLOCK" % IMPOSSIBLE_LEVEL if key == "impossible" and not open_ else title,
                            self.font_l, WHITE, 1.0, width=4)
        if big.get_width() > room:
            k = room / float(big.get_width())
            big = pygame.transform.smoothscale(big, (int(big.get_width() * k), int(big.get_height() * k)))
        w.blit(big, (x - 4, panel.y + 40))
        if key == "impossible" and not open_:
            sub = self.label("IMPOSSIBLE MODE", room, self.PLAY_RED[2], self.font_s)
            w.blit(sub, (x, panel.y + 150))
        for i, line in enumerate(lines):
            img = self.label(line, room, (226, 234, 226), self.font_s)
            w.blit(img, (x, panel.y + 206 + i * 52))
        status, scol, can = self.play_status(key)
        strip = pygame.Rect(x, panel.y + 340, room, 70)
        pygame.draw.rect(w, _shade(pal[0], 0.62), strip, border_radius=12)
        img = self.label(status, room - 40, scol, self.font_s)
        w.blit(img, img.get_rect(midleft=(strip.x + 20, strip.centery)))
        cap = self.label("YOU EARN", room, _shade(pal[2], 0.8), self.font_s)
        w.blit(cap, (x, panel.y + 444))
        img = self.label(pays, room, YELLOW, self.font_s)
        w.blit(img, (x, panel.y + 492))
        # the button(s)
        go = L["go"]
        hov = can and go.collidepoint(mouse)
        fill = ((170, 36, 44) if key in ("impossible", "gauntlet") else SELECT_GREEN) if can else (62, 66, 64)
        r = go.move(0, -4) if hov else go
        pygame.draw.rect(w, fill, r, border_radius=20)
        pygame.draw.rect(w, YELLOW if hov else (WHITE if can else (130, 134, 132)), r, 6, border_radius=20)
        words = "LVL %d UNLOCK" % IMPOSSIBLE_LEVEL if key == "impossible" and not open_ else button
        lab = self.label(words, r.w - 40, WHITE if can else (170, 174, 172), self.font_m)
        w.blit(lab, lab.get_rect(center=r.center))
        if key == "impossible":                                  # the shop is always open: look before you earn
            sb = L["shop"]
            hov = sb.collidepoint(mouse)
            r = sb.move(0, -4) if hov else sb
            pygame.draw.rect(w, (34, 10, 14), r, border_radius=20)
            pygame.draw.rect(w, YELLOW if hov else ESSENCE_HOT, r, 5, border_radius=20)
            lab = self.label("ESSENCE SHOP", r.w - 110, ESSENCE_HOT, self.font_m)
            pos = lab.get_rect(center=(r.centerx + 26, r.centery))
            w.blit(lab, pos)
            self.draw_essence_icon(w, (pos.x - 34, r.centery), 24)

    # ==================================================================================
    # HOME (28 Oct) - Hubi: "this is fire, add it to the game". The main menu as a stage:
    # the night stadium out of focus and lit (floodlight beams, bokeh, camera flashes), a hero
    # player in front with rim lights, and frosted-glass panels over it all. Everything heavy is
    # built once and kept (background, glass, hero, gold titles, buttons); per frame it is a
    # handful of blits plus the twinkles, so the browser stays smooth.
    # ==================================================================================
    HOME_TABS = ("HOME", "PLAY", "STORE", "TEAM", "QUESTS", "MAIL", "PROFILE")     # QUESTS: 1 Nov
    HOME_EDGE = (150, 180, 255)
    HOME_GOLD_EDGE = (255, 210, 110)
    HOME_TINT = (16, 26, 64)
    HOME_MUTED = (190, 204, 240)
    HOME_HERO_SCALE = 6
    HOME_FALLBACK_HERO = "WC_ARG_messi"

    def home_layout(self):
        L = {"bar": pygame.Rect(24, 20, WIDTH - 48, 92),
             "tabs": [(t, pygame.Rect(566 + i * 128, 34, 122, 64)) for i, t in enumerate(self.HOME_TABS)],
             "level": pygame.Rect(1468, 34, 64, 64),
             "coins": pygame.Rect(1550, 40, 230, 52),
             "quit": pygame.Rect(1796, 34, 76, 64),
             "feature": pygame.Rect(1140, 150, 720, 540),
             "play": pygame.Rect(1180, 540, 420, 110),
             "change": pygame.Rect(1620, 548, 220, 46),
             "plate": pygame.Rect(60, 840, 580, 160),
             "pack": pygame.Rect(1140, 720, 350, 280),
             "event": pygame.Rect(1510, 720, 350, 280)}
        L["pack_open"] = pygame.Rect(L["pack"].x + 200, L["pack"].bottom - 80, 130, 50)
        L["event_open"] = pygame.Rect(L["event"].x + 200, L["event"].bottom - 80, 130, 50)
        return L

    # ---- the building blocks (all cached) ----------------------------------------------
    @staticmethod
    def home_soft(surf, k):
        """A cheap blur: down by k and back up, twice (smoothscale averages)."""
        w, h = surf.get_size()
        small = pygame.transform.smoothscale(surf, (max(1, w // k), max(1, h // k)))
        small = pygame.transform.smoothscale(small, (max(1, w // (k // 2 or 1)), max(1, h // (k // 2 or 1))))
        return pygame.transform.smoothscale(small, (w, h))

    @staticmethod
    def home_vgrad(size, top, bottom):
        g = pygame.Surface(size, pygame.SRCALPHA)
        h = max(1, size[1] - 1)
        for y in range(size[1]):
            t = y / float(h)
            g.fill(tuple(int(top[i] + (bottom[i] - top[i]) * t) for i in range(4)), (0, y, size[0], 1))
        return g

    @staticmethod
    def home_glow(size, colour, alpha):
        """A soft round glow (an ellipse filling `size`), drawn small and blown up."""
        s = pygame.Surface((64, 64), pygame.SRCALPHA)
        for k in range(32, 0, -1):
            a = int(alpha * (1.0 - k / 32.0) ** 1.6)
            pygame.draw.circle(s, colour + (a,), (32, 32), k)
        return pygame.transform.smoothscale(s, (max(2, int(size[0])), max(2, int(size[1]))))

    def home_bg(self):
        hit = self.__dict__.get("_home_bg")
        if hit is not None:
            return hit
        rnd = random.Random(7)
        night = self.stadiums[2] if len(self.stadiums) > 2 else (self.stadiums[0] if self.stadiums else None)
        bg = pygame.Surface((WIDTH, HEIGHT)).convert()
        bg.fill((10, 16, 40))
        if night is not None:
            k = HEIGHT / float(night.get_height())
            big = pygame.transform.smoothscale(night, (int(night.get_width() * k), HEIGHT))
            bg.blit(big, ((WIDTH - big.get_width()) // 2, 0))
            bg = self.home_soft(bg, 10)                                      # out of focus: depth
            bg.fill((232, 232, 236), special_flags=pygame.BLEND_RGB_MULT)
        bg.blit(self.home_vgrad((WIDTH, HEIGHT), (14, 28, 80, 80), (6, 10, 30, 160)), (0, 0))   # the grade
        g = self.home_glow((1640, 1300), (40, 110, 255), 130)               # cool light behind the hero
        bg.blit(g, g.get_rect(center=(640, 600)))
        g = self.home_glow((1240, 700), (255, 190, 90), 70)                 # warm light from below
        bg.blit(g, g.get_rect(center=(700, 900)))
        beams = pygame.Surface((WIDTH // 8, HEIGHT // 8), pygame.SRCALPHA)  # floodlight beams, soft
        for sx, tx in ((250, 760), (1680, 1100)):
            pygame.draw.polygon(beams, (170, 200, 255, 40), [((sx - 30) / 8, 0), ((sx + 30) / 8, 0),
                                                             ((tx + 260) / 8, HEIGHT / 8), ((tx - 260) / 8, HEIGHT / 8)])
        bg.blit(pygame.transform.smoothscale(beams, (WIDTH, HEIGHT)), (0, 0))
        for sx in (250, 1680):
            g = self.home_glow((340, 300), (220, 235, 255), 220)
            bg.blit(g, g.get_rect(center=(sx, 30)))
        bok = pygame.Surface((WIDTH // 2, HEIGHT // 2), pygame.SRCALPHA)    # bokeh
        for _ in range(70):
            x, y = rnd.uniform(0, WIDTH / 2), rnd.uniform(30, HEIGHT * 0.35)
            r = rnd.choice((3, 4, 6, 8, 11, 15, 20))
            col = rnd.choice(((255, 214, 150), (150, 200, 255), (255, 255, 255)))
            pygame.draw.circle(bok, col + (rnd.randint(20, 70),), (int(x), int(y)), r)
            pygame.draw.circle(bok, col + (90,), (int(x), int(y)), r, 1)
        bg.blit(pygame.transform.smoothscale(bok, (WIDTH, HEIGHT)), (0, 0))
        vig = pygame.Surface((96, 54), pygame.SRCALPHA)                     # vignette
        for k in range(16):
            pygame.draw.rect(vig, (2, 4, 14, int(150 * (1 - k / 16.0) ** 2.2)), (k * 2, k, 96 - k * 4, 54 - k * 2), 2)
        bg.blit(pygame.transform.smoothscale(vig, (WIDTH, HEIGHT)), (0, 0))
        bg.blit(self.home_vgrad((WIDTH, 340), (4, 8, 24, 0), (4, 8, 24, 235)), (0, HEIGHT - 340))   # the floor
        bg = opaque(bg)                                 # whatever smoothscale handed back: a straight copy to draw
        self._home_bg = bg
        self._home_flashes = [(rnd.uniform(0, WIDTH), rnd.uniform(280, 700), rnd.uniform(6, 14), rnd.uniform(0, 6.3))
                              for _ in range(30)]
        return bg

    def home_glass(self, rect, radius=26, alpha=150, edge=None, hot=False):
        """A frosted panel: the background behind it, blurred and tinted, with a lit top edge."""
        edge = edge or self.HOME_EDGE
        cache = self.__dict__.setdefault("_home_glass", {})
        key = (tuple(rect), radius, alpha, edge, hot)
        hit = cache.get(key)
        if hit is not None:
            return hit
        bg = self.home_bg()
        area = rect.clip(bg.get_rect())
        pad = 40
        out = pygame.Surface((rect.w + pad * 2, rect.h + pad * 2), pygame.SRCALPHA)
        sh = pygame.Surface((rect.w // 4 + 20, rect.h // 4 + 20), pygame.SRCALPHA)   # its shadow
        pygame.draw.rect(sh, (0, 0, 0, 150), (10, 13, rect.w // 4, rect.h // 4), border_radius=max(1, radius // 4))
        out.blit(pygame.transform.smoothscale(sh, (rect.w + 80, rect.h + 80)), (0, 0))
        body = pygame.Surface(rect.size, pygame.SRCALPHA)
        if area.w and area.h:
            crop = bg.subsurface(area).copy()
            body.blit(self.home_soft(crop, 16), (area.x - rect.x, area.y - rect.y))
        body.blit(tint(rect.size, self.HOME_TINT + (alpha,)), (0, 0))
        body.blit(self.home_vgrad(rect.size, (255, 255, 255, 26), (255, 255, 255, 0)), (0, 0))
        mask = pygame.Surface(rect.size, pygame.SRCALPHA)
        pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(), border_radius=radius)
        body.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        out.blit(body, (pad, pad))
        r = pygame.Rect(pad, pad, rect.w, rect.h)
        pygame.draw.rect(out, edge + (150,), r, 2, border_radius=radius)
        pygame.draw.rect(out, (255, 255, 255, 40), r.inflate(-4, -4), 1, border_radius=max(1, radius - 2))
        if hot:
            pygame.draw.rect(out, self.HOME_GOLD_EDGE + (210,), r.inflate(6, 6), 3, border_radius=radius + 3)
        if len(cache) > 60:
            cache.clear()
        cache[key] = out
        return out

    def draw_glass(self, w, rect, **kw):
        g = self.home_glass(rect, **kw)
        if WEB_BUILD:                       # the browser: only the panel and the inner edge of its shadow
            m = 14
            w.blit(g, (rect.x - m, rect.y - m), pygame.Rect(40 - m, 40 - m, rect.w + 2 * m, rect.h + 2 * m))
            return
        w.blit(g, (rect.x - 40, rect.y - 40))

    def home_gold(self, text, height):
        """Text in a gold gradient with a soft dark shadow (cached)."""
        cache = self.__dict__.setdefault("_home_gold", {})
        key = (text, int(height))
        hit = cache.get(key)
        if hit is not None:
            return hit
        white = self.font_xl.render(text, True, (255, 255, 255))
        k = height / float(max(1, white.get_height()))
        white = pygame.transform.smoothscale(white, (max(1, int(white.get_width() * k)), int(height)))
        grad = self.home_vgrad(white.get_size(), (255, 246, 200, 255), (214, 150, 40, 255))
        grad.blit(white, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        dark = self.font_xl.render(text, True, (40, 20, 0))
        dark = pygame.transform.smoothscale(dark, white.get_size())
        out = pygame.Surface((white.get_width() + 14, white.get_height() + 14), pygame.SRCALPHA)
        out.blit(self.home_soft(dark, 4), (6, 9))
        out.blit(grad, (3, 3))
        if len(cache) > 40:
            cache.clear()
        cache[key] = out
        return out

    def home_text(self, w, text, pos, size, colour=WHITE, anchor="midleft", shadow=True, max_w=None):
        cache = self.__dict__.setdefault("_home_txt", {})
        key = (text, int(size), tuple(colour), shadow, max_w)
        img = cache.get(key)
        if img is None:
            font = self.font_s if size <= 30 else (self.font_m if size <= 50 else self.font_l)
            t = font.render(text, True, colour)
            k = size / float(max(1, t.get_height()))
            if max_w and t.get_width() * k > max_w:
                k = max_w / float(t.get_width())
            t = pygame.transform.smoothscale(t, (max(1, int(t.get_width() * k)), max(1, int(t.get_height() * k))))
            img = pygame.Surface((t.get_width() + 4, t.get_height() + 5), pygame.SRCALPHA)
            if shadow:
                s = font.render(text, True, (0, 0, 0))
                s = pygame.transform.smoothscale(s, t.get_size())
                s.set_alpha(140)
                img.blit(s, (3, 4))
            img.blit(t, (0, 0))
            if len(cache) > 200:
                cache.clear()
            cache[key] = img
        r = img.get_rect(**{anchor: (int(pos[0]), int(pos[1]))})
        w.blit(img, r)
        return r

    def home_button(self, size, hover, top=(80, 225, 120), bottom=(24, 150, 70), lip=(10, 70, 34)):
        """The big glossy button with a solid lip under it (it reads as pressable)."""
        cache = self.__dict__.setdefault("_home_btn", {})
        key = (size, hover, top)
        hit = cache.get(key)
        if hit is not None:
            return hit
        w, h = size
        if hover:
            top = tuple(min(255, c + 22) for c in top)
            bottom = tuple(min(255, c + 22) for c in bottom)
        out = pygame.Surface((w, h + 10), pygame.SRCALPHA)
        pygame.draw.rect(out, lip + (255,), (0, 10, w, h), border_radius=22)
        face = self.home_vgrad((w, h), top + (255,), bottom + (255,))
        face.blit(self.home_vgrad((w, h // 2), (255, 255, 255, 80), (255, 255, 255, 10)), (0, 0))
        mask = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(), border_radius=22)
        face.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
        out.blit(face, (0, 0))
        pygame.draw.rect(out, (200, 255, 210, 230), (0, 0, w, h), 3, border_radius=22)
        cache[key] = out
        return out

    # ---- the hero ------------------------------------------------------------------------
    def home_base_web(self, card):
        """Browser only: home_bg + the watermark + the hero (still, no bob) as one cached surface."""
        key = card["id"] if card is not None else None
        hit = self.__dict__.get("_home_base_web")
        if hit is not None and hit[0] == key:
            return hit[1]
        base = self.home_bg().copy()
        if card is not None:
            base.blit(self.home_watermark(card), (70, 160))
            hero = self.home_hero(card)
            if hero is not None:
                big, shadow = hero
                fx, fy = 330, HEIGHT - big.get_height() + 40
                base.blit(shadow, (fx + 30, fy + 26))
                base.blit(big, (fx, fy))
        self._home_base_web = (key, base)
        return base

    def home_watermark(self, card):
        """His surname, huge and faint, behind him (cached)."""
        cache = self.__dict__.setdefault("_home_wm", {})
        name = card["name"].split()[-1].upper()
        img = cache.get(name)
        if img is None:
            t = self.font_xl.render(name, True, (255, 255, 255))
            k = 330.0 / t.get_height()
            if t.get_width() * k > 1000:
                k = 1000.0 / t.get_width()
            img = pygame.transform.smoothscale(t, (int(t.get_width() * k), int(t.get_height() * k)))
            img.set_alpha(24)
            cache[name] = img
        return img

    def home_hero_card(self):
        figs = getattr(self, "card_figs", set())
        owned = [c for c in self.owned_cards() if c["id"] in figs]
        if owned:
            return self.upgraded(owned[0])
        return self.cards.get(self.HOME_FALLBACK_HERO)

    def home_hero(self, card):
        """His figure at 6x, a cool rim light on the left edge, a warm one on the right, and a soft
        shadow (cached per card)."""
        cache = self.__dict__.setdefault("_home_hero", {})
        hit = cache.get(card["id"])
        if hit is not None:
            return hit
        fig = self.card_faces.get(card["id"])
        if fig is None:
            cache[card["id"]] = None
            return None
        box = fig.get_bounding_rect()
        fig = fig.subsurface(box).copy() if box.w and box.h else fig.copy()
        w, h = fig.get_size()
        lit = fig.copy()
        for y in range(h):
            for x in range(w):
                c = fig.get_at((x, y))
                if c[3] < 128:
                    continue
                left = x == 0 or fig.get_at((x - 1, y))[3] < 128
                right = x == w - 1 or fig.get_at((x + 1, y))[3] < 128
                if left:
                    lit.set_at((x, y), (min(255, (c[0] + 120 * 2) // 3), min(255, (c[1] + 220 * 2) // 3),
                                        min(255, (c[2] + 255 * 2) // 3), c[3]))
                elif right:
                    lit.set_at((x, y), (min(255, (c[0] + 255 * 2) // 3), min(255, (c[1] + 210 * 2) // 3),
                                        min(255, (c[2] + 130 * 2) // 3), c[3]))
        S = self.HOME_HERO_SCALE
        big = pygame.transform.scale(lit, (w * S, h * S))
        shadow = pygame.transform.scale(fig, (w * S // 4, h * S // 4))
        shadow.fill((0, 0, 0, 150), special_flags=pygame.BLEND_RGBA_MULT)
        shadow = pygame.transform.smoothscale(shadow, (w * S, h * S))
        cache[card["id"]] = (big, shadow)
        return cache[card["id"]]

    # ---- the screen ----------------------------------------------------------------------
    def featured_tab(self):
        return self.PLAY_TABS[self.play_tab % len(self.PLAY_TABS)]

    FEATURE_TITLE = {"wc": "WORLD CUP 2026", "club": "CLUB FOOTBALL", "practice": "PRACTICE",
                     "free": "FREEPLAY", "h2h": "HEAD TO HEAD", "impossible": "IMPOSSIBLE",
                     "gauntlet": "THE GAUNTLET"}
    FEATURE_SUB = {"wc": "Pick a nation. Win 7 rounds. Lose once, it's over.",
                   "club": "A league season with your own five, in your kit.",
                   "practice": "No clock, no score. Learn how the ball moves.",
                   "free": "Any player you own against any other.",
                   "h2h": "Ranked, against a real player. Website only.",
                   "impossible": "The World Cup with everything turned up.",
                   "gauntlet": "Ten in a row. The last one is the best there is."}

    def draw_home(self, w):
        L = self.home_layout()
        mouse = pygame.mouse.get_pos()
        t = pygame.time.get_ticks() * 0.001
        card = self.home_hero_card()
        if WEB_BUILD:
            # the browser: the stadium, the name behind the hero and the hero himself are one picture,
            # built once - three full-screen-sized blits a frame were most of the home screen's cost
            w.blit(self.home_base_web(card), (0, 0))
        else:
            w.blit(self.home_bg(), (0, 0))
        for x, y, s, ph in (() if WEB_BUILD else self.__dict__.get("_home_flashes", ())):   # camera flashes
            a = 0.5 + 0.5 * math.sin(t * 1.7 + ph * 3.0)
            if a > 0.82:
                self.draw_glint(w, x, y, s * (a - 0.82) / 0.18 * 1.3)
        # the hero, a faint name behind him
        if card is not None and not WEB_BUILD:
            w.blit(self.home_watermark(card), (70, 160))
            hero = self.home_hero(card)
            if hero is not None:
                big, shadow = hero
                bob = int(round(math.sin(t * 1.3) * 1.5)) * PIXEL
                fx, fy = 330, HEIGHT - big.get_height() + 40 + bob
                w.blit(shadow, (fx + 30, fy + 26))
                w.blit(big, (fx, fy))
        # the top bar
        self.draw_glass(w, L["bar"], radius=24, alpha=120)
        logo = self.home_gold("A SMALL WORLD CUP", 46)
        w.blit(logo, logo.get_rect(midleft=(64, L["bar"].centery)))
        for tab, r in L["tabs"]:
            on = tab == "HOME"
            hov = r.collidepoint(mouse) and not on
            col = (255, 226, 150) if on else (YELLOW if hov else self.HOME_MUTED)
            self.home_text(w, tab, r.center, 28, col, anchor="center", shadow=False, max_w=r.w - 4)
            if on:
                pygame.draw.rect(w, (255, 206, 90), (r.centerx - 46, r.bottom - 6, 92, 6), border_radius=3)
            if tab in ("MAIL", "QUESTS"):
                n = self.unread_mail() if tab == "MAIL" else self.quest_claimable()
                if n:
                    c = (r.right + 2, r.y + 6)
                    pygame.draw.circle(w, (236, 70, 70), c, 15)
                    self.home_text(w, str(min(n, 9)), c, 22, WHITE, anchor="center", shadow=False)
        level, into, need = level_from_xp(self.save.get("xp", 0))
        lr = L["level"]
        pygame.draw.circle(w, (40, 60, 120), lr.center, 32, 7)
        k = into / float(max(1, need))
        if k > 0:
            pygame.draw.arc(w, (90, 220, 255), lr, math.pi / 2 - math.tau * k, math.pi / 2, 7)
        self.home_text(w, str(level), lr.center, 30, WHITE, anchor="center", shadow=False)
        self.draw_glass(w, L["coins"], radius=26, alpha=170, edge=(255, 200, 90))
        cr = L["coins"]
        pygame.draw.circle(w, (250, 200, 70), (cr.x + 30, cr.centery), 16)
        pygame.draw.circle(w, (150, 100, 10), (cr.x + 30, cr.centery), 16, 3)
        self.home_text(w, self.fmt(self.save["coins"]), (cr.centerx + 18, cr.centery), 32, (255, 226, 150),
                       anchor="center", shadow=False)
        q = L["quit"]                                                    # quit: a power symbol
        hq = q.collidepoint(mouse)
        self.draw_glass(w, q, radius=20, alpha=150, edge=(255, 140, 140) if hq else self.HOME_EDGE)
        col = (255, 150, 150) if hq else self.HOME_MUTED
        pygame.draw.arc(w, col, q.inflate(-38, -26), math.radians(120), math.radians(420), 5)
        pygame.draw.line(w, col, (q.centerx, q.y + 12), (q.centerx, q.centery), 5)
        # the hero's nameplate
        if card is not None:
            pl = L["plate"]
            self.draw_glass(w, pl, radius=26, alpha=150)
            flag = self.card_flag(card)
            if flag is not None:
                fl = fit_flag(flag, 96, 64)
                w.blit(fl, fl.get_rect(center=(pl.x + 78, pl.y + 62)))
            self.home_text(w, card["name"].upper(), (pl.x + 150, pl.y + 56), 44, WHITE, max_w=pl.w - 170)
            pool = self.card_pool(card)
            self.home_text(w, "%d  %s  -  POOL %s" % (card["rating"], card["pos"], pool), (pl.x + 150, pl.y + 112),
                           26, self.HOME_MUTED, shadow=False)
            for i, (ps, lvl) in enumerate(card.get("ps", ())[:2]):
                ic = self.ps_icon(ps["key"], 54, lvl)
                if ic is not None:
                    w.blit(ic, (pl.right - 140 + i * 62, pl.y + 84))
        # the featured mode
        key, _tab, lines, pays, go = self.featured_tab()
        f = L["feature"]
        self.draw_glass(w, f, radius=30, alpha=150, hot=True)
        chip = pygame.Rect(f.x + 40, f.y + 30, 240, 48)
        self.draw_glass(w, chip, radius=24, alpha=190, edge=self.HOME_GOLD_EDGE)
        self.home_text(w, "FEATURED", chip.center, 24, (255, 226, 150), anchor="center", shadow=False)
        title = self.home_gold(self.FEATURE_TITLE.get(key, "PLAY"), 76)
        if title.get_width() > f.w - 70:
            title = pygame.transform.smoothscale(title, (f.w - 70, int(title.get_height() * (f.w - 70) / title.get_width())))
        w.blit(title, title.get_rect(midleft=(f.x + 34, f.y + 150)))
        sub = self.FEATURE_SUB.get(key, " ".join(lines).capitalize())
        self.home_text(w, sub, (f.x + 42, f.y + 222), 27, (205, 216, 245), shadow=False, max_w=f.w - 80)
        self.draw_home_progress(w, key, f, pays)
        pr = L["play"]
        hov = pr.collidepoint(mouse)
        btn = self.home_button(pr.size, hov)
        w.blit(btn, (pr.x, pr.y - (3 if hov else 0)))
        cx, cy = pr.centerx, pr.centery - (3 if hov else 0)
        pygame.draw.polygon(w, WHITE, [(cx - 150, cy - 26), (cx - 150, cy + 26), (cx - 106, cy)])
        self.home_text(w, go, (cx + 20, cy), 64 if len(go) <= 5 else 44, WHITE, anchor="center",
                       max_w=pr.w - 200)
        ch = L["change"]
        hc = ch.collidepoint(mouse)
        self.draw_glass(w, ch, radius=23, alpha=170 if hc else 120,
                        edge=self.HOME_GOLD_EDGE if hc else (130, 160, 240))
        self.home_text(w, "CHANGE MODE", ch.center, 25, (255, 226, 150) if hc else (215, 226, 255),
                       anchor="center", shadow=False)
        self.home_text(w, "%d MODES" % len(self.PLAY_TABS), (ch.centerx, ch.bottom + 34), 24, self.HOME_MUTED,
                       anchor="center", shadow=False)
        # the newest pack
        self.draw_home_tiles(w, L, mouse)

    def draw_home_progress(self, w, key, f, pays=""):
        y = f.y + 300
        if key in ("wc", "impossible"):
            run = self.run_of("impossible" if key == "impossible" else "normal")
            live = bool(run.get("opponents")) and run.get("round", 0) < len(ROUNDS)
            done = min(len(ROUNDS) - 1, len(run.get("results") or ())) if live else 0
            for i, rnd_name in enumerate(ROUNDS):
                x = f.x + 64 + i * 98
                if i < len(ROUNDS) - 1:
                    pygame.draw.line(w, (255, 206, 90) if i < done else (70, 90, 150), (x + 24, y), (x + 74, y), 6)
                if i < done:
                    pygame.draw.circle(w, (40, 170, 90), (x, y), 24)
                    pygame.draw.circle(w, (170, 255, 190), (x, y), 24, 3)
                    pygame.draw.lines(w, WHITE, False, [(x - 10, y), (x - 2, y + 9), (x + 12, y - 9)], 5)
                elif i == done:
                    pygame.draw.circle(w, (60, 46, 10), (x, y), 30)
                    pygame.draw.circle(w, (255, 206, 90), (x, y), 30, 5)
                    self.home_text(w, "?", (x, y), 30, (255, 226, 150), anchor="center", shadow=False)
                else:
                    pygame.draw.circle(w, (16, 24, 56), (x, y), 22)
                    pygame.draw.circle(w, (80, 100, 160), (x, y), 22, 3)
                lab = {"DAY1": "D1", "DAY2": "D2", "DAY3": "D3", "R 16": "R16", "QRTR": "QF", "SEMI": "SF",
                       "FINL": "F"}.get(rnd_name, rnd_name)
                self.home_text(w, lab, (x, y + 52), 22, (255, 226, 150) if i == done else (170, 186, 225),
                               anchor="center", shadow=False)
        elif key == "gauntlet":
            run = self.gt_run()
            done = run["rung"] if run else 0
            for i in range(GT_LEN):
                x = f.x + 64 + i * 66
                last = i == GT_LEN - 1
                if i < GT_LEN - 1:
                    pygame.draw.line(w, (255, 206, 90) if i < done else (90, 60, 110), (x + 20, y), (x + 46, y), 5)
                if i < done:
                    pygame.draw.circle(w, (40, 170, 90), (x, y), 20)
                    pygame.draw.circle(w, (170, 255, 190), (x, y), 20, 3)
                elif last:
                    bi = self.gt_machine_badge(56)
                    w.blit(bi, bi.get_rect(center=(x, y)))
                else:
                    on = run is not None and i == done
                    pygame.draw.circle(w, (60, 46, 10) if on else (24, 16, 40), (x, y), 24 if on else 20)
                    pygame.draw.circle(w, (255, 206, 90) if on else (110, 90, 150), (x, y), 24 if on else 20, 4 if on else 3)
                self.home_text(w, str(i + 1), (x, y + 46), 22, (255, 120, 110) if last else (200, 196, 230),
                               anchor="center", shadow=False)
        elif key == "club":
            running = self.season_running() if hasattr(self, "season_running") else False
            n = getattr(self, "club_round", 0) if running else 0
            self.home_text(w, ("ROUND %d OF %d" % (n + 1, CLUB_ROUNDS)) if running else "A NEW SEASON",
                           (f.x + 42, y - 18), 28, WHITE, shadow=False)
            bar = pygame.Rect(f.x + 42, y + 22, f.w - 84, 18)
            pygame.draw.rect(w, (6, 10, 28), bar, border_radius=9)
            if n:
                pygame.draw.rect(w, (90, 220, 255), (bar.x, bar.y, max(18, int(bar.w * n / float(CLUB_ROUNDS))), bar.h),
                                 border_radius=9)
        else:
            self.home_text(w, pays, (f.x + 42, y), 26, (255, 226, 150), shadow=False, max_w=f.w - 84)

    def draw_home_tiles(self, w, L, mouse):
        newest = self.shown_pack(len(PACK_NAMES) - 1)       # (the Limit Breakers draft that's in)
        r = L["pack"]
        hot = r.collidepoint(mouse)
        self.draw_glass(w, r, radius=26, alpha=150, edge=(255, 130, 150) if hot else None)
        art = self.pack_art[newest] if newest < len(self.pack_art) else None
        if art is not None:
            a = scaled(art, (int(art.get_width() * 220 / art.get_height()), 220))
            a = pygame.transform.rotate(a, -6)
            w.blit(a, (r.x + 20, r.y + 26))
        self.home_text(w, "NEW", (r.x + 200, r.y + 50), 24, (255, 120, 140), shadow=False)
        words = PACK_NAMES[newest].split()
        for i, word in enumerate(words[:2]):
            self.home_text(w, word, (r.x + 200, r.y + 92 + i * 40), 34 if len(word) <= 6 else 28, WHITE,
                           max_w=r.right - r.x - 214)
        b = L["pack_open"]
        self.draw_glass(w, b, radius=25, alpha=190, edge=(255, 130, 150))
        self.home_text(w, "OPEN", b.center, 26, WHITE, anchor="center", shadow=False)
        r = L["event"]
        hot = r.collidepoint(mouse)
        self.draw_glass(w, r, radius=26, alpha=150, edge=self.HOME_GOLD_EDGE if hot else None)
        sig = self.cards.get(KEMPES_CARD)                  # (1 Nov: the newest Game Box)
        if sig is not None:
            self.blit_card(w, sig, pygame.Rect(r.x + 40, r.y + 44, 146, 182))
        self.home_text(w, "EVENT", (r.x + 200, r.y + 50), 24, (90, 220, 255), shadow=False)
        self.home_text(w, "GAME", (r.x + 200, r.y + 92), 34, WHITE)
        self.home_text(w, "BOX", (r.x + 200, r.y + 132), 34, WHITE)
        b = L["event_open"]
        self.draw_glass(w, b, radius=25, alpha=190, edge=self.HOME_GOLD_EDGE)
        self.home_text(w, "OPEN", b.center, 26, WHITE, anchor="center", shadow=False)

    def home_click(self, pos):
        L = self.home_layout()
        p = (pos[0], pos[1])
        for tab, r in L["tabs"]:
            if r.collidepoint(p):
                if tab == "PLAY":
                    self.menu_page = "play"
                elif tab != "HOME":
                    self.menu_item(tab)
                return
        if L["quit"].collidepoint(p):
            self.menu_item("QUIT")
        elif L["level"].collidepoint(p):
            self.open_profile()
        elif L["play"].collidepoint(p):
            self.play_go(self.featured_tab()[0])
        elif L["change"].collidepoint(p):
            self.menu_page = "play"
        elif L["pack"].collidepoint(p) or L["pack_open"].collidepoint(p):
            self.open_packs(self.shown_pack(len(PACK_NAMES) - 1))
        elif L["event"].collidepoint(p) or L["event_open"].collidepoint(p):
            self.open_event("kempes")
        elif L["plate"].collidepoint(p):
            card = self.home_hero_card()
            if card is not None:
                self.card_detail = card
                self.card_tab = 0

    def draw_title(self, w):
        if getattr(self, "menu_page", "main") == "play":
            self.draw_play(w)
            return
        if HOME_V2:
            self.draw_home(w)
            return
        w.blit(self.select_bg, (0, 0))
        mouse = pygame.mouse.get_pos()
        # left: PLAY NOW + the art carousel
        head = self.outlined("PLAY NOW", self.font_l, WHITE, 0.9, width=4)
        w.blit(head, head.get_rect(center=(490, 110)))
        sr = self.slide_rect()
        i = self.current_slide()
        hover = sr.collidepoint(mouse)
        r = sr.move(0, -6) if hover else sr
        pygame.draw.rect(w, (10, 14, 12), r.inflate(22, 22), border_radius=16)
        img = self.slides[i] if self.slides else None
        if img is not None:
            w.blit(pygame.transform.scale(img, r.size), r)
        else:
            pygame.draw.rect(w, (40, 60, 44), r)
        pygame.draw.rect(w, YELLOW if hover else (236, 196, 90), r.inflate(10, 10), 6, border_radius=12)
        left = self.SLIDE_SECONDS - (pygame.time.get_ticks() / 1000.0 - self.slide_t0)
        prog = pygame.Rect(r.x, r.bottom + 14, int(r.w * clamp(1 - left / self.SLIDE_SECONDS, 0, 1)), 6)
        pygame.draw.rect(w, (236, 196, 90), prog)
        dots, nxt = self.slide_controls()
        for k, d in enumerate(dots):
            pygame.draw.circle(w, WHITE, d.center, 13 if k == i else 9, 0 if k == i else 3)
        pygame.draw.rect(w, SELECT_GREEN, nxt, border_radius=28)
        pygame.draw.rect(w, YELLOW if nxt.collidepoint(mouse) else WHITE, nxt, 4, border_radius=28)
        self.centre_in(w, "NEXT >", nxt)
        # the diagonal divider
        pygame.draw.line(w, (230, 236, 230), (1110, -10), (880, HEIGHT + 10), 7)
        # right: title, level, buttons
        title = self.outlined("A SMALL WORLD CUP", self.font_xl, (255, 214, 40), 1.0, width=5)
        if title.get_width() > 760:
            k = 760 / title.get_width()
            title = pygame.transform.smoothscale(title, (int(title.get_width() * k), int(title.get_height() * k)))
        w.blit(title, title.get_rect(center=(1480, 150)))
        self.draw_coins(w)
        self.draw_level(w, 1180, 226, 600)
        for item, rect in zip(self.menu_items(), self.menu_layout()):
            soon = item == "SOON"
            hov = rect.collidepoint(mouse) and not soon
            col = (120, 140, 124) if soon else (YELLOW if hov else WHITE)
            lab = self.outlined(item, self.font_l, col, 1.0, width=4)
            if lab.get_width() > rect.w:
                k = rect.w / lab.get_width()
                lab = pygame.transform.smoothscale(lab, (int(lab.get_width() * k), int(lab.get_height() * k)))
            w.blit(lab, lab.get_rect(center=rect.center))
            if item == "MAIL":
                n = self.unread_mail()
                if n:
                    dot = pygame.Rect(0, 0, 54, 54)
                    dot.center = (lab.get_rect(center=rect.center).right + 42, rect.centery - 6)
                    pygame.draw.circle(w, (220, 60, 60), dot.center, 27)
                    pygame.draw.circle(w, WHITE, dot.center, 27, 3)
                    self.centre_in(w, str(min(n, 9)), dot)
            if hov:
                for sx in (-1, 1):
                    x = rect.centerx + sx * (lab.get_width() // 2 + 40)
                    pygame.draw.polygon(w, YELLOW, [(x - sx * 14, rect.centery - 18), (x + sx * 8, rect.centery),
                                                    (x - sx * 14, rect.centery + 18)])

    def draw_shadow(self, surface, x, bottom_y, width):
        height_above = max(0.0, GROUND_Y - bottom_y)
        k = clamp(1.0 - height_above / 600.0, 0.25, 1.0)
        sw, sh = int(width * 2 * k), max(2, int(12 * k))
        sh_surf = pygame.Surface((sw, sh), pygame.SRCALPHA)
        pygame.draw.ellipse(sh_surf, (0, 0, 0, int(90 * k)), (0, 0, sw, sh))
        surface.blit(sh_surf, (int(x - sw / 2), GROUND_Y - sh // 2 + 2))

    def draw_aim(self, surface):
        """Arrow toward the mouse: longer = more power (strength lets you pull
        it further), and it wobbles for players with low shooting."""
        if not self.dragging:
            return
        p = self.player
        mouse = Vector2(pygame.mouse.get_pos())
        launch = mouse - p.pos
        if launch.length() < 14.0:
            return
        rng = p.drag_range()
        charge = clamp(launch.length() / rng, 0.0, 1.0)
        n = rot(launch.normalize(), p.aim_wobble(pygame.time.get_ticks() * 0.001))
        fill, edge = (250, 248, 236), INK
        if charge >= 0.999:
            fill = (255, 128, 56)                          # maxed out
        side = perp(n)
        tail = p.pos + n * 60.0
        tip = tail + n * (70.0 + ARROW_STRETCH * (rng / THROW_DRAG_RANGE) * charge)
        head_len, hw = 34.0, 5.0
        neck = tip - n * head_len
        pts = [tail + side * hw, neck + side * hw, neck + side * hw * 3.4, tip,
               neck - side * hw * 3.4, neck - side * hw, tail - side * hw]
        pygame.draw.polygon(surface, fill, [(int(q.x), int(q.y)) for q in pts])
        pygame.draw.polygon(surface, edge, [(int(q.x), int(q.y)) for q in pts], 4)

    def draw_clock(self, surface):
        if self.half == 3:
            label, col = "GOLDEN GOAL", YELLOW
        else:
            left = max(0.0, HALF_SECONDS * self.half - self.match_time)
            label = "%s  0:%02d" % ("1ST" if self.half == 1 else "2ND", int(math.ceil(left)))
            col = (255, 120, 120) if left < 5 else WHITE
        img = self.font_m.render(label, True, col)
        pad = tint((img.get_width() + 40, img.get_height() + 16), (10, 14, 24, 150))
        surface.blit(pad, pad.get_rect(midtop=(WIDTH // 2, 24)))
        surface.blit(img, img.get_rect(midtop=(WIDTH // 2, 32)))

    # ---- online: searching, names and chat ------------------------
    def draw_searching(self, w):
        if not self.searching:
            return
        wash(w, (4, 10, 8, 205))
        t = self.searching["t"]
        self.centre_text(w, "LOOKING FOR AN OPPONENT", self.font_l, WHITE, 360)
